            if (TryLoadVerifiedLrcFromDiskCache(song, out diskLines, out diskProv, out diskScore))
            {
                song.SyncedLines = diskLines;
                lyricsSyncSourceLabel = diskProv;
                currentLyricMatchScore = diskScore;
                return;
