            else if (lowTitle.Contains("excuses"))
            {
                raw = "[00:02.50]Mere dil naal laare ni tu laun waliye\n" +
                      "[00:07.20]Dil tera jado tutuga tan pata laguga\n" +
                      "[00:12.00]Dil naal laare ni tu laun waliye\n" +
