        private string GetQueryParamFromUri(string rawUri, string paramName)
        {
            if (string.IsNullOrEmpty(rawUri) || string.IsNullOrEmpty(paramName)) return "";
            try
            {
                int qIdx = rawUri.IndexOf('?');
                string query = (qIdx >= 0) ? rawUri.Substring(qIdx + 1) : rawUri;
                string[] parts = query.Split(new char[] { '&' }, StringSplitOptions.RemoveEmptyEntries);
                foreach (string p in parts)
                {
                    int eq = p.IndexOf('=');
                    if (eq > 0)
                    {
                        string k = p.Substring(0, eq).Trim();
                        string v = Uri.UnescapeDataString(p.Substring(eq + 1).Replace("+", " ").Trim());
                        if (string.Equals(k, paramName, StringComparison.OrdinalIgnoreCase)) return v;
                    }
                }
            }
            catch { }
            return "";
        }

        private void CheckAndExecuteIncomingShareCommand()
        {
            try
            {
                if (string.IsNullOrEmpty(incomingShareCmdFile))
                {
                    incomingShareCmdFile = Path.Combine(leoLocalDataRoot, "incoming_share.cmd");
                }
                if (!File.Exists(incomingShareCmdFile)) return;
                string rawCmd = File.ReadAllText(incomingShareCmdFile, Encoding.UTF8).Trim();
                try { File.Delete(incomingShareCmdFile); } catch { }
                if (string.IsNullOrEmpty(rawCmd)) return;

                if (this.WindowState == FormWindowState.Minimized) this.WindowState = FormWindowState.Normal;
                this.Activate();
                this.BringToFront();

                string sharedId = GetQueryParamFromUri(rawCmd, "id");
                string sharedTitle = GetQueryParamFromUri(rawCmd, "title");
                string sharedArtist = GetQueryParamFromUri(rawCmd, "artist");

                // 1. Check if song is already in catalog, queueSongs, or downloadedSongs
                List<SongItem> allKnown = new List<SongItem>();
                allKnown.AddRange(queueSongs);
                allKnown.AddRange(catalog);
                allKnown.AddRange(downloadedSongs);
                foreach (SongItem s in allKnown)
                {
                    if ((!string.IsNullOrEmpty(sharedId) && string.Equals(s.Id, sharedId, StringComparison.OrdinalIgnoreCase)) ||
                        (!string.IsNullOrEmpty(sharedTitle) && IsSameSongTitleOrVariant(s.Title, sharedTitle)))
                    {
                        PlaySong(s, false);
                        ShowToast("\u266B Playing Shared Track: " + s.Title);
                        return;
                    }
                }

                // 2. Otherwise search JioSaavn live for the shared title & artist and play immediately!
                if (!string.IsNullOrEmpty(sharedTitle))
                {
                    string q = sharedTitle + " " + sharedArtist;
                    ShowToast("\u266B Opening Shared Song: " + sharedTitle + "...");
                    Thread shThread = new Thread(() =>
                    {
                        try
                        {
                            string url = "https://www.jiosaavn.com/api.php?__call=search.getResults&_format=json&n=8&p=1&_marker=0&ctx=android&q=" + Uri.EscapeDataString(q.Trim());
                            using (WebClient wc = new WebClient())
                            {
                                wc.Encoding = Encoding.UTF8;
                                wc.Headers.Add("User-Agent", "Mozilla/5.0 (Linux; Android 14)");
                                string json = wc.DownloadString(url);
                                List<SongItem> found = ParseOfficialJioSaavnJson(json);
                                if (found.Count > 0)
                                {
                                    this.BeginInvoke((MethodInvoker)delegate
                                    {
                                        PlaySong(found[0], false);
                                        ShowToast("\u266B Playing Shared Song: " + found[0].Title);
                                    });
                                }
                            }
                        }
                        catch { }
                    });
                    shThread.IsBackground = true;
                    shThread.Start();
                }
            }
            catch { }
        }

