        private void ShowWindowsNowPlayingNotification(SongItem song)
        {
            if (song == null) return;
            try
            {
                string cleanTitle = CleanSongDisplayTitle(song.Title);
                string cleanArtist = GetPrimaryArtistName(song.Artist);
                this.Text = "\u25B6 " + cleanTitle + " \u2014 " + cleanArtist + " | LEO Music Studio";

                if (trayNotifyIcon == null)
                {
                    trayNotifyIcon = new NotifyIcon();
                    trayNotifyIcon.Icon = customAppIcon ?? SystemIcons.Application;
                    trayNotifyIcon.Visible = true;
                    trayNotifyIcon.BalloonTipClicked += (bs, bev) =>
                    {
                        try
                        {
                            this.Show();
                            if (this.WindowState == FormWindowState.Minimized) this.WindowState = FormWindowState.Normal;
                            this.Activate();
                            isFullPlayerExpanded = true;
                            this.Invalidate();
                        }
                        catch { }
                    };
                }
