        private void ApplyLyricCandidateToSong(SongItem song, LyricCandidateItem sel)
        {
            if (song == null || sel == null) return;
            song.SyncedLines = sel.ParsedLines;
            currentLyricsAreExactLrc = sel.IsTimeSynced;
            lyricsSyncSourceLabel = sel.ProviderName + " (" + sel.ConfidenceScore + "% Match)";
            currentLyricMatchScore = sel.ConfidenceScore;
            double durToUse = currentDurSec > 20 ? currentDurSec : song.Duration;
            AutoCalibrateLyricsToDuration(song, durToUse);
            cachedLyricWrapKey = "";
        }

