        private void CopyCurrentSongLyricsToClipboard()
        {
            if (currentSong == null) return;
            EnsureSyncedLyricsParsed(currentSong);
            if (currentSong.SyncedLines == null || currentSong.SyncedLines.Count == 0)
            {
                ShowToast("No lyrics available to copy");
                return;
            }
            StringBuilder sb = new StringBuilder();
            sb.AppendLine(CleanSongDisplayTitle(currentSong.Title) + " - " + GetPrimaryArtistName(currentSong.Artist));
            sb.AppendLine();
            for (int i = 0; i < currentSong.SyncedLines.Count; i++)
            {
                sb.AppendLine(FormatLyricTextForActiveProvider(currentSong.SyncedLines[i].Text));
            }
            try
            {
                Clipboard.SetText(sb.ToString());
                ShowToast("\u2713 Full Lyrics Copied to Clipboard!");
            }
            catch { }
        }

