        private void PaintUniversalThreeDotPopupMenu(Graphics g, int w, int h, float anim, StringFormat sfCenter, StringFormat sfLeftEllipsis)
        {
            if (!isUniversalDotMenuOpen && anim <= 0.01f) return;
            int popW = 262;
            int popH = 316;
            int px = Math.Max(16, Math.Min(w - popW - 16, universalDotMenuPt.X));
            int py = Math.Max(50, Math.Min(h - popH - 84, universalDotMenuPt.Y));
            Rectangle popRect = new Rectangle(px, py, popW, popH);

            using (SolidBrush shB = new SolidBrush(Color.FromArgb((int)(165 * anim), 3, 2, 10)))
            {
                FillRoundRect(g, shB, new Rectangle(popRect.X + 4, popRect.Y + 8, popRect.Width, popRect.Height), 18);
            }
            DrawGlassCard(g, popRect, 18, Color.FromArgb(24, 16, 46), true, false);

            string hdrTitle = "QUICK STUDIO ACTIONS";
            string[] items;
            if (universalDotMenuType == "playlist" && universalDotMenuPlaylistIdx >= 0 && universalDotMenuPlaylistIdx < userPlaylists.Count)
            {
                UserPlaylistItem pl = userPlaylists[universalDotMenuPlaylistIdx];
                hdrTitle = "PLAYLIST: " + pl.Name.ToUpperInvariant();
                items = new string[]
                {
                    "\u25B6  Play Entire Playlist Now",
                    "\uD83D\uDD00  Shuffle Play Playlist",
                    "\u2795  Add Playlist to Up Next Queue",
                    "\u2728  Auto-Fill with Trending Songs",
                    "\u270E  Rename Playlist",
                    "\u2795  Create New Custom Playlist",
                    pl.IsLeoAutoMood ? "\u21BB  Refresh Auto-Mood Tracks" : "\uD83D\uDDD1  Delete Custom Playlist"
                };
            }
            else
            {
                SongItem s = universalDotMenuSong ?? currentSong;
                bool isLiked = (s != null && likedIds.Contains(s.Id));
                bool isCustomPlView = (activeTab == 5 && selectedPlaylistIdx >= 1);
                hdrTitle = s != null ? FormatMinimalCardTitle(s.Title).ToUpperInvariant() : "SONG OPTIONS";
                items = new string[]
                {
                    "\u25B6  Play Track Now (320kbps)",
                    "\u23ED  Play Next in Queue",
                    "\u2795  Add to Up Next Queue",
                    isLiked ? "\u2665  Remove from Favorites" : "\u2661  Add to Favorites",
                    isCustomPlView ? "\u2715  Remove from This Playlist" : "\uD83D\uDCC1  Add to Active Playlist",
                    "\u2193  Download 320kbps Offline",
                    "\uD83D\uDD17  Share Smart Link (leomusic://)"
                };
            }

            using (SolidBrush ab = new SolidBrush(Color.FromArgb(225, 180, 255)))
            {
                g.DrawString(hdrTitle, fontSmallBold, ab, new RectangleF(popRect.X + 14, popRect.Y + 10, popRect.Width - 28, 18), sfLeftEllipsis);
            }

            int rowStart = popRect.Y + 34;
            Point relMouse = this.PointToClient(Cursor.Position);
            for (int i = 0; i < items.Length; i++)
            {
                Rectangle itemR = new Rectangle(popRect.X + 10, rowStart + i * 39, popRect.Width - 20, 35);
                bool hov = itemR.Contains(relMouse);
                DrawGlassCard(g, itemR, 10, bgCard, i == 0 || hov, hov);
                g.DrawString(items[i], fontSmallBold, Brushes.White, new RectangleF(itemR.X + 12, itemR.Y + 7, itemR.Width - 20, 20), sfLeftEllipsis);
            }
        }

        private bool HandleUniversalThreeDotPopupClick(Point pt)
        {
            if (!isUniversalDotMenuOpen) return false;
            int w = this.ClientSize.Width;
            int h = this.ClientSize.Height;
            int popW = 262, popH = 316;
            int px = Math.Max(16, Math.Min(w - popW - 16, universalDotMenuPt.X));
            int py = Math.Max(50, Math.Min(h - popH - 84, universalDotMenuPt.Y));
            Rectangle popRect = new Rectangle(px, py, popW, popH);

            if (!popRect.Contains(pt))
            {
                isUniversalDotMenuOpen = false;
                this.Invalidate();
                return true;
            }

            int idx = (pt.Y - (popRect.Y + 34)) / 39;
            isUniversalDotMenuOpen = false;

            if (universalDotMenuType == "playlist")
            {
                int plIdx = Math.Max(0, Math.Min(userPlaylists.Count - 1, universalDotMenuPlaylistIdx));
                UserPlaylistItem pl = userPlaylists[plIdx];
                selectedPlaylistIdx = plIdx;
                if (idx == 0) PlayEntirePlaylist(pl, false);
                else if (idx == 1) { isShuffle = true; PlayEntirePlaylist(pl, true); }
                else if (idx == 2)
                {
                    int added = 0;
                    foreach (SongItem s in pl.Songs) { if (!ContainsSongByTitleOrId(queueSongs, s)) { queueSongs.Add(s); added++; } }
                    ShowToast("\u2795 Added " + added + " tracks from " + pl.Name + " to Queue");
                }
                else if (idx == 3)
                {
                    int added = 0;
                    foreach (SongItem ts in trendingSongs) { if (!ContainsSongByTitleOrId(pl.Songs, ts)) { pl.Songs.Add(ts); added++; } }
                    SavePersistentSettings();
                    ShowToast("\u2728 Auto-filled " + pl.Name + " with " + added + " trending tracks");
                }
                else if (idx == 4 || idx == 5)
                {
                    activeTab = 5;
                    int centerX = 198;
                    int rightW = Math.Max(0, (int)Math.Round(rightPanelWidthAnim));
                    int centerW = Math.Max(320, w - centerX - rightW);
                    ShowPlaylistNameBox(centerX + 26 + centerW - 52 - 292, 31, 180);
                    if (idx == 4 && playlistNameBox != null) playlistNameBox.Text = pl.Name;
                }
                else if (idx == 6)
                {
                    if (pl.IsLeoAutoMood)
                    {
                        SyncLeoSmartPlaylistWithMood(true);
                        ShowToast("\u21BB Refreshed Leo Smart Playlist");
                    }
                    else if (plIdx >= 1 && userPlaylists.Count > 1)
                    {
                        string delName = pl.Name;
                        userPlaylists.RemoveAt(plIdx);
                        selectedPlaylistIdx = 0;
                        SavePersistentSettings();
                        ShowToast("Deleted Playlist: " + delName);
                    }
                }
            }
            else
            {
                SongItem s = universalDotMenuSong ?? currentSong;
                if (s != null)
                {
                    if (idx == 0) PlaySong(s, false);
                    else if (idx == 1)
                    {
                        for (int i = queueSongs.Count - 1; i >= 0; i--) { if (queueSongs[i].Id == s.Id && i != currentQueueIndex) queueSongs.RemoveAt(i); }
                        int insPos = Math.Min(queueSongs.Count, currentQueueIndex + 1);
                        queueSongs.Insert(insPos, s);
                        ShowToast("\u23ED Playing Next: " + CleanSongDisplayTitle(s.Title));
                    }
                    else if (idx == 2) AddToQueue(s);
                    else if (idx == 3)
                    {
                        if (likedIds.Contains(s.Id)) likedIds.Remove(s.Id);
                        else likedIds.Add(s.Id);
                        SavePersistentSettings();
                        ShowToast(likedIds.Contains(s.Id) ? "\u2665 Added to Favorites" : "Removed from Favorites");
                    }
                    else if (idx == 4)
                    {
                        if (activeTab == 5 && selectedPlaylistIdx >= 1 && selectedPlaylistIdx < userPlaylists.Count)
                        {
                            UserPlaylistItem cpl = userPlaylists[selectedPlaylistIdx];
                            for (int i = cpl.Songs.Count - 1; i >= 0; i--) { if (cpl.Songs[i].Id == s.Id) cpl.Songs.RemoveAt(i); }
                            SavePersistentSettings();
                            ShowToast("Removed from " + cpl.Name);
                        }
                        else AddSongToActiveUserPlaylist(s);
                    }
                    else if (idx == 5) DownloadSongDirectly(s);
                    else if (idx == 6) { currentSong = s; CopyShareTrackCardToClipboard(); }
                }
            }
            this.Invalidate();
            return true;
        }

        private string TransliterateDevanagariToRoman(string input)
        {
            if (string.IsNullOrEmpty(input)) return "";
            bool hasDevanagari = false;
            for (int i = 0; i < input.Length; i++)
            {
                if (input[i] >= '\u0900' && input[i] <= '\u097F') { hasDevanagari = true; break; }
            }
            if (!hasDevanagari) return input;

            Dictionary<char, string> map = new Dictionary<char, string>()
            {
                {'\u0905',"a"}, {'\u0906',"aa"}, {'\u0907',"i"}, {'\u0908',"ee"}, {'\u0909',"u"}, {'\u090A',"oo"},
                {'\u090F',"e"}, {'\u0910',"ai"}, {'\u0913',"o"}, {'\u0914',"au"},
                {'\u0915',"k"}, {'\u0916',"kh"}, {'\u0917',"g"}, {'\u0918',"gh"}, {'\u091A',"ch"}, {'\u091B',"chh"},
                {'\u091C',"j"}, {'\u091D',"jh"}, {'\u091F',"t"}, {'\u0920',"th"}, {'\u0921',"d"}, {'\u0922',"dh"},
                {'\u0923',"n"}, {'\u0924',"t"}, {'\u0925',"th"}, {'\u0926',"d"}, {'\u0927',"dh"}, {'\u0928',"n"},
                {'\u092A',"p"}, {'\u092B',"ph"}, {'\u092C',"b"}, {'\u092D',"bh"}, {'\u092E',"m"},
                {'\u092F',"y"}, {'\u0930',"r"}, {'\u0932',"l"}, {'\u0935',"v"}, {'\u0936',"sh"}, {'\u0937',"sh"},
                {'\u0938',"s"}, {'\u0939',"h"}, {'\u095C',"r"}, {'\u095D',"rh"},
                {'\u093E',"aa"}, {'\u093F',"i"}, {'\u0940',"ee"}, {'\u0941',"u"}, {'\u0942',"oo"},
                {'\u0947',"e"}, {'\u0948',"ai"}, {'\u094B',"o"}, {'\u094C',"au"},
                {'\u0902',"n"}, {'\u0901',"n"}, {'\u0903',"h"}, {'\u094D',""}, {'\u093C',""}, {'\u0964',"."}, {'\u0965',""}
            };

            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < input.Length; i++)
            {
                char c = input[i];
                if (map.ContainsKey(c))
                {
                    sb.Append(map[c]);
                    bool isConsonant = (c >= '\u0915' && c <= '\u0939') || c == '\u095C' || c == '\u095D';
                    if (isConsonant)
                    {
                        char next = (i + 1 < input.Length) ? input[i + 1] : ' ';
                        bool nextIsMatraOrHalant = (next >= '\u093E' && next <= '\u094D') || next == '\u093C' || next == ' ' || next == ',' || next == ')';
                        if (!nextIsMatraOrHalant) sb.Append("a");
                    }
                }
                else sb.Append(c);
            }
            string res = sb.ToString();
            if (res.Length > 1) res = char.ToUpperInvariant(res[0]) + res.Substring(1);
            return res;
        }

        private string FormatLyricTextForActiveProvider(string rawText)
        {
            if (string.IsNullOrEmpty(rawText)) return "";
            if (activeLyricsProviderIdx == 3) return TransliterateDevanagariToRoman(rawText);
            if (activeLyricsProviderIdx == 4)
            {
                string rom = TransliterateDevanagariToRoman(rawText);
                if (!string.Equals(rom, rawText, StringComparison.OrdinalIgnoreCase))
                    return rawText + "  \u2022  " + rom;
            }
            return rawText;
        }

        private void CycleLyricsProviderMode()
        {
            activeLyricsProviderIdx = (activeLyricsProviderIdx + 1) % lyricsProviderNames.Length;
            if (activeLyricsProviderIdx == 1 && currentSongLyricCandidates != null && currentSongLyricCandidates.Count > 1 && currentSong != null)
