                activeLyricCandidateIdx = (activeLyricCandidateIdx + 1) % currentSongLyricCandidates.Count;
                ApplyLyricCandidateToSong(currentSong, currentSongLyricCandidates[activeLyricCandidateIdx]);
            }
            SavePersistentSettings();
            ShowToast("\u2726 Lyrics Engine: " + lyricsProviderNames[activeLyricsProviderIdx] + " (" + currentLyricMatchScore + "% Accuracy)");
            this.Invalidate();
        }

        private void CopyShareTrackCardToClipboard()
        {
            if (currentSong == null) return;
            try
            {
                RegisterLeoMusicProtocolHandler();
                string cleanTitle = CleanSongDisplayTitle(currentSong.Title);
                string cleanArtist = GetPrimaryArtistName(currentSong.Artist);
                lastGeneratedDeepLinkUri = "leomusic://play?id=" + Uri.EscapeDataString(currentSong.Id) +
                    "&title=" + Uri.EscapeDataString(cleanTitle) +
                    "&artist=" + Uri.EscapeDataString(cleanArtist);

                string webRedirectUrl = "https://umas8549.github.io/leo-music-updates/share.html?id=" + Uri.EscapeDataString(currentSong.Id) +
                    "&title=" + Uri.EscapeDataString(cleanTitle) +
                    "&artist=" + Uri.EscapeDataString(cleanArtist);
                string downloadFallbackUrl = DEFAULT_GITHUB_RELEASE_URL;

                lastGeneratedSmartShareUrl = webRedirectUrl;
                GenerateLocalSmartShareHtmlPage(currentSong, lastGeneratedDeepLinkUri, downloadFallbackUrl);

                string shareClipboardText =
                    "\uD83C\uDFB5 Listen to \"" + cleanTitle + "\" by " + cleanArtist + " on Leo Music!\r\n" +
                    "\u25B6 Smart Link (Opens in Leo Music or Downloads App): " + webRedirectUrl + "\r\n" +
