        {
            isMuted = !isMuted;
            ApplyEffectiveDspAndVolume();
            QueueSavePersistentSettings();
            ShowToast(isMuted ? "Muted" : ("Volume: " + volumePercent + "%"));
            this.Invalidate();
        }

        private void ApplyEqPreset(string presetName)
        {
            activeEqPreset = presetName;
            eqEnabled = true;
            if (presetName == "Flat")
            {
                eqBands = new float[] { 0f, 0f, 0f, 0f, 0f };
                bassBoostPct = 0; virtualizerPct = 0; loudnessGainPct = 0;
            }
            else if (presetName == "Bass Boost")
            {
                eqBands = new float[] { 8.5f, 5.5f, 0.5f, 2.0f, 3.5f };
                bassBoostPct = 85; virtualizerPct = 35; loudnessGainPct = 65;
            }
            else if (presetName == "Club")
            {
                eqBands = new float[] { 6.5f, 4.5f, 3.5f, 4.5f, 4.0f };
                bassBoostPct = 75; virtualizerPct = 65; loudnessGainPct = 75;
            }
            else if (presetName == "Hip Hop")
            {
                eqBands = new float[] { 8.0f, 5.0f, -1.0f, 3.0f, 5.0f };
                bassBoostPct = 80; virtualizerPct = 45; loudnessGainPct = 60;
            }
            else if (presetName == "Rock")
            {
                eqBands = new float[] { 6.0f, -1.0f, 2.5f, 5.5f, 6.5f };
                bassBoostPct = 55; virtualizerPct = 50; loudnessGainPct = 65;
            }
            else if (presetName == "Pop")
            {
                eqBands = new float[] { 1.5f, 3.5f, 6.0f, 4.5f, 2.0f };
                bassBoostPct = 40; virtualizerPct = 40; loudnessGainPct = 55;
            }
            else if (presetName == "Vocal Boost")
            {
                eqBands = new float[] { -3.5f, 1.5f, 7.5f, 6.0f, 3.0f };
                bassBoostPct = 15; virtualizerPct = 20; loudnessGainPct = 50;
            }
            else if (presetName == "Acoustic")
            {
                eqBands = new float[] { 4.0f, 3.0f, 2.5f, 5.0f, 5.5f };
                bassBoostPct = 35; virtualizerPct = 30; loudnessGainPct = 45;
            }
            else if (presetName == "Electronic")
            {
                eqBands = new float[] { 7.5f, 4.0f, 0.0f, 5.0f, 7.0f };
                bassBoostPct = 78; virtualizerPct = 80; loudnessGainPct = 70;
            }
            ApplyEffectiveDspAndVolume();
            SavePersistentSettings();
            ShowToast("\u266B EQ Applied: " + presetName + " (Bass " + bassBoostPct + "% \u2022 Loudness " + loudnessGainPct + "%)");
            this.Invalidate();
        }

        private void SeekRelative(double deltaSec)
        {
            if (wmpControls == null) return;
            double target = Math.Max(0.0, Math.Min(currentDurSec, currentPosSec + deltaSec));
            SeekToAbsolute(target);
        }

        private void SeekToAbsolute(double targetSec)
        {
            if (wmpControls == null) return;
            double target = Math.Max(0.0, Math.Min(currentDurSec, targetSec));
            currentPosSec = target;
            smoothPosSec = target;
            // v10.4.4 Smooth Micro-Fade on Seek to prevent digital audio pop/click
            if (smoothMicroFadeEnabled && isPlaying)
            {
                microFadeMultiplier = 0.32f;
                ApplyEffectiveDspAndVolume();
            }
            // v10.3.6 Fix: Immediately silence outgoing crossfade Deck B when user scrubs the timeline
            if (deckBVolume > 0 && wmpControlsB != null)
            {
                deckBVolume = 0;
                deckAFadeInProgress = 100;
                try { wmpControlsB.GetType().InvokeMember("stop", BindingFlags.InvokeMethod, null, wmpControlsB, null); } catch { }
            }
            try
            {
                wmpControls.GetType().InvokeMember("currentPosition", BindingFlags.SetProperty, null, wmpControls, new object[] { target });
                // v10.5.0 Single-Stream Seek (Zero secondary echo)
            }
            catch { }
            this.Invalidate();
        }

        private void StopCrossfadeDeckBImmediately()
        {
            deckBVolume = 0;
            deckBCrossfadeVolFloat = 0.0;
            deckAFadeInProgress = 100;
            deckAFadeInFloat = 100.0;
            if (wmpControlsB != null)
            {
                try { wmpControlsB.GetType().InvokeMember("stop", BindingFlags.InvokeMethod, null, wmpControlsB, null); } catch { }
            }
            ApplyEffectiveDspAndVolume();
        }

        private void HandOffToCrossfadeDeckB()
        {
            if (!crossfadeEnabled || crossfadeSeconds <= 0 || !isPlaying || wmpPlayer == null || wmpDeckB == null)
            {
                deckAFadeInProgress = 100;
                deckAFadeInFloat = 100.0;
                return;
            }
            try
            {
                string curUrl = !string.IsNullOrEmpty(activePlayTargetUrlOrFile)
                    ? activePlayTargetUrlOrFile
                    : Convert.ToString(wmpType.InvokeMember("URL", BindingFlags.GetProperty, null, wmpPlayer, null));
                if (currentSong != null)
                {
                    string localF = GetLocalDownloadedFilePath(currentSong);
                    if (!string.IsNullOrEmpty(localF) && File.Exists(localF)) curUrl = localF;
                }
                if (!string.IsNullOrEmpty(curUrl) && currentPosSec > 1.0)
                {
                    deckBVolume = ComputeTargetEffectiveVolume();
                    deckBCrossfadeVolFloat = deckBVolume;
                    if (wmpSettingsB != null)
                    {
                        wmpSettingsB.GetType().InvokeMember("mute", BindingFlags.SetProperty, null, wmpSettingsB, new object[] { isMuted });
                        wmpSettingsB.GetType().InvokeMember("volume", BindingFlags.SetProperty, null, wmpSettingsB, new object[] { deckBVolume });
                    }
                    wmpType.InvokeMember("URL", BindingFlags.SetProperty, null, wmpDeckB, new object[] { curUrl });
                    if (wmpControlsB != null)
                    {
                        wmpControlsB.GetType().InvokeMember("currentPosition", BindingFlags.SetProperty, null, wmpControlsB, new object[] { currentPosSec });
                        wmpControlsB.GetType().InvokeMember("play", BindingFlags.InvokeMethod, null, wmpControlsB, null);
                    }
                    deckAFadeInFloat = 12.0;
                    deckAFadeInProgress = 12;
                    return;
                }
            }
            catch { }
            deckAFadeInProgress = 100;
            deckAFadeInFloat = 100.0;
        }

        private void PlaySong(SongItem song)
        {
            PlaySong(song, false);
        }

        private void PlaySong(SongItem song, bool isQueueStep)
        {
            if (song == null) return;

            if (string.IsNullOrEmpty(song.Mood) || song.Mood == "All")
            {
                song.Mood = InferSongMood(song.Title, song.Artist, song.Album, song.Duration);
            }

            // v10.3.6 Fix: Only hand off to Deck B if track was playing for >2.5s; if user rapidly spam-skips tracks, stop Deck B cleanly
            if (currentSong != null && currentSong.Id != song.Id && isPlaying && crossfadeEnabled && currentPosSec > 2.5)
            {
                HandOffToCrossfadeDeckB();
            }
            else
            {
                deckAFadeInProgress = 100;
                deckBVolume = 0;
                if (wmpControlsB != null)
                {
                    try { wmpControlsB.GetType().InvokeMember("stop", BindingFlags.InvokeMethod, null, wmpControlsB, null); } catch { }
                }
            }

            currentSong = song;
            hasResolvedWmpDurationForCurrentSong = false;
            ShowWindowsNowPlayingNotification(song);
            currentPosSec = 0;
            smoothPosSec = 0;
            lyricSyncOffsetSec = 0.0;
            abLoopStartSec = -1.0;
            abLoopEndSec = -1.0;
            streamStallWatchdogTicks = 0;
            lastWatchdogPosSec = -1.0;
            currentDurSec = song.Duration > 0 ? song.Duration : 210;
            isPlaying = true;
            isAutoEndCrossfadeTriggered = false;
            lyricsSmoothScrollY = 0f;
            microFadeMultiplier = smoothMicroFadeEnabled ? 0.22f : 1.0f;
            TriggerButtonBounce("play");
            playShockwaveAnim = 1.0f;
            ApplySmartAutoEqForSong(song);
            ApplyEffectiveDspAndVolume();
            int myPlayVer = ++playRequestVersion;

            // Parse & fetch BetterLyrics time-synced lines + update ambient backdrop color!
            EnsureSyncedLyricsParsed(song);
            FetchBetterLyricsAsync(song);
            UpdateTargetAmbientColorFromSong(song);
            RebuildCurrentSongBgSlideshow(song, true);

            // Record play for Quick Play unlocking & personalization!
            RecordSongPlayForQuickPlay(song);
            cachedHomeShelvesKey = "";

            if (!isQueueStep)
            {
                BuildSmartSimilarQueueForSeed(song);
            }
            else
            {
                // Always enforce unique titles in queue even when stepping
                EnforceUniqueQueueTitlesInPlace();
                int qIdx = -1;
                for (int i = 0; i < queueSongs.Count; i++)
                {
                    if (queueSongs[i].Id == song.Id) { qIdx = i; break; }
                }
                if (qIdx == -1)
                {
                    queueSongs.Insert(0, song);
                    currentQueueIndex = 0;
                }
                else
                {
                    currentQueueIndex = qIdx;
                }
                QueueSavePersistentSettings();
            }

            PrefetchSingleThumbnail(song.ThumbUrl);

            string safeId = Regex.Replace(song.Id, "[^a-zA-Z0-9_-]", "_");
            string cachedFile = Path.Combine(cacheFolder, safeId + "_320hq.m4a");

            // v10.6.0 Offline-First Local Download Check: If the song exists in Leo_Music_Local_Data\Downloads or AudioCache, play immediately from disk!
            string localDlFile = GetLocalDownloadedFilePath(song);
            if (!string.IsNullOrEmpty(localDlFile) && File.Exists(localDlFile) && new FileInfo(localDlFile).Length > 15000L)
            {
                isBuffering = false;
                SyncNativeWmpHardwareDspRegistry();
                StartWmpFileOrUrl(localDlFile);
                if (autoPreBufferNextEnabled) PreBufferNextQueueSongAsync();
                this.Invalidate();
                return;
            }

            string resolvedLosslessUrl = ResolveActiveLosslessStreamUrl(song);
            long minValidCacheBytes = string.Equals(activeStreamQuality, "320kbps", StringComparison.OrdinalIgnoreCase) ? 1200000L : 150000L;
            if (File.Exists(cachedFile) && new FileInfo(cachedFile).Length >= minValidCacheBytes)
            {
                isBuffering = false;
                SyncNativeWmpHardwareDspRegistry();
                StartWmpFileOrUrl(cachedFile);
                if (autoPreBufferNextEnabled) PreBufferNextQueueSongAsync();
                this.Invalidate();
                return;
            }

            isBuffering = true;
            SyncNativeWmpHardwareDspRegistry();
            StartWmpFileOrUrl(resolvedLosslessUrl);
            this.Invalidate();

            // v10.4.9 Double Pipeline (Alpha + Beta) 24-Bit Lossless Stream Verification, SSD Cache & 3D Spatial Deck Lock
            Thread cacheThread = new Thread(() =>
            {
                int swStart = Environment.TickCount;
                // Give WMP Deck A immediate network priority for 1.4s so 24-Bit audio starts with 0ms stutter
                Thread.Sleep(6500);
                if (playRequestVersion != myPlayVer) return;

                string[] candidates = new string[] { resolvedLosslessUrl, song.AudioUrl, song.FallbackUrl, song.FallbackUrl96 };
                string tempFile = cachedFile + "." + myPlayVer + ".tmp";

                foreach (string candidateUrl in candidates)
                {
                    if (string.IsNullOrEmpty(candidateUrl)) continue;
                    try
                    {
                        using (WebClient wc = new WebClient())
                        {
                            wc.Headers.Add("User-Agent", "Mozilla/5.0 (Windows NT 10.0; Win64; x64)");
                            wc.DownloadFile(candidateUrl, tempFile);
                        }
                        if (File.Exists(tempFile) && new FileInfo(tempFile).Length > 10000)
                        {
                            try
                            {
                                if (File.Exists(cachedFile)) File.Delete(cachedFile);
                                File.Move(tempFile, cachedFile);
                            }
                            catch { }
                            jioSaavnPingMs = Math.Max(14, Math.Min(95, (Environment.TickCount - swStart) / 25));
                            break;
                        }
                    }
                    catch
                    {
                        try { if (File.Exists(tempFile)) File.Delete(tempFile); } catch { }
                    }
                }

                this.BeginInvoke((MethodInvoker)delegate
                {
                    if (playRequestVersion == myPlayVer)
                    {
                        isBuffering = false;
                        if (File.Exists(cachedFile) && new FileInfo(cachedFile).Length > 100000)
                        {
                            activePlayTargetUrlOrFile = cachedFile;
                            SyncSpatial3DHeadphoneDeckNow(true);
                        }
                        if (autoPreBufferNextEnabled) PreBufferNextQueueSongAsync();
                        this.Invalidate();
                    }
                });
            });
            cacheThread.IsBackground = true;
            cacheThread.Start();
        }

        private void StartWmpFileOrUrl(string target)
        {
            activePlayTargetUrlOrFile = target ?? "";
            try
            {
                if (!crossfadeEnabled && wmpControlsB != null)
                {
                    deckBVolume = 0;
                    try { wmpControlsB.GetType().InvokeMember("stop", BindingFlags.InvokeMethod, null, wmpControlsB, null); } catch { }
                }
                if (wmpPlayer != null)
                {
                    if (wmpControls != null)
                    {
                        try { wmpControls.GetType().InvokeMember("stop", BindingFlags.InvokeMethod, null, wmpControls, null); } catch { }
                    }
                    wmpType.InvokeMember("URL", BindingFlags.SetProperty, null, wmpPlayer, new object[] { target });
                    if (wmpControls != null)
                    {
                        wmpControls.GetType().InvokeMember("play", BindingFlags.InvokeMethod, null, wmpControls, null);
                        if (skipSilence)
                        {
                            try { wmpControls.GetType().InvokeMember("currentPosition", BindingFlags.SetProperty, null, wmpControls, new object[] { 0.8 }); } catch { }
                        }
                    }
                }

                // v10.5.0 Zero-Echo Fix: Ensure secondary spatial deck is always stopped so only 1 stream plays with zero 200ms echo!
                if (wmpSpatialControls != null)
                {
                    try { wmpSpatialControls.GetType().InvokeMember("stop", BindingFlags.InvokeMethod, null, wmpSpatialControls, null); } catch { }
                }
                ApplyEffectiveDspAndVolume();
            }
            catch { }
        }

        private void TogglePlayPause()
        {
            TriggerButtonBounce("play");
            if (wmpPlayer == null || wmpControls == null) return;
            try
            {
                string currentUrl = "";
                try { currentUrl = Convert.ToString(wmpType.InvokeMember("URL", BindingFlags.GetProperty, null, wmpPlayer, null)); } catch { }
                if (string.IsNullOrEmpty(currentUrl) || string.IsNullOrEmpty(activePlayTargetUrlOrFile))
                {
                    if (currentSong == null && catalog.Count > 0) currentSong = catalog[0];
                    PlaySong(currentSong, true);
                    return;
                }
                if (isPlaying)
                {
                    wmpControls.GetType().InvokeMember("pause", BindingFlags.InvokeMethod, null, wmpControls, null);
                    if (wmpSpatialControls != null) { try { wmpSpatialControls.GetType().InvokeMember("pause", BindingFlags.InvokeMethod, null, wmpSpatialControls, null); } catch { } }
                    if (wmpControlsB != null)
                    {
                        try { wmpControlsB.GetType().InvokeMember("stop", BindingFlags.InvokeMethod, null, wmpControlsB, null); } catch { }
                        deckBVolume = 0;
                    }
                    isPlaying = false;
                }
                else
                {
                    if (smoothMicroFadeEnabled)
                    {
                        microFadeMultiplier = 0.35f;
                        ApplyEffectiveDspAndVolume();
                    }
                    wmpControls.GetType().InvokeMember("play", BindingFlags.InvokeMethod, null, wmpControls, null);
                    isPlaying = true;
                    if (currentSong != null) ShowWindowsNowPlayingNotification(currentSong);
                }
                this.Invalidate();
            }
            catch { }
        }

        private void PreBufferNextQueueSongAsync()
        {
            if (!autoPreBufferNextEnabled || queueSongs.Count <= 1) return;
            try
            {
                int nextIdx = (currentQueueIndex + 1) % queueSongs.Count;
                SongItem nextSong = queueSongs[nextIdx];
                if (nextSong == null || string.IsNullOrEmpty(nextSong.Id) || nextSong.Id == lastPreBufferedSongId) return;
                lastPreBufferedSongId = nextSong.Id;
                PrefetchSingleThumbnail(nextSong.ThumbUrl);

                string safeId = Regex.Replace(nextSong.Id, "[^a-zA-Z0-9_-]", "_");
                string nextCachedFile = Path.Combine(cacheFolder, safeId + ".m4a");
                if (File.Exists(nextCachedFile) && new FileInfo(nextCachedFile).Length > 10000) return;

                Thread preThread = new Thread(() =>
                {
                    try
                    {
                        Thread.Sleep(900);
                        string url = nextSong.AudioUrl;
                        if (string.IsNullOrEmpty(url)) return;
                        string tmp = nextCachedFile + ".pre.tmp";
                        using (WebClient wc = new WebClient())
                        {
                            wc.Headers.Add("User-Agent", "Mozilla/5.0 (Windows NT 10.0; Win64; x64)");
                            wc.DownloadFile(url, tmp);
                        }
                        if (File.Exists(tmp) && new FileInfo(tmp).Length > 10000)
                        {
                            if (!File.Exists(nextCachedFile)) File.Move(tmp, nextCachedFile);
                            else File.Delete(tmp);
                        }
                    }
                    catch { }
                });
                preThread.IsBackground = true;
                preThread.Start();
            }
            catch { }
        }

        private void NextTrack()
        {
            TriggerButtonBounce("next");
            if (queueSongs.Count == 0) return;
            EnforceUniqueQueueTitlesInPlace();
            if (isShuffle && queueSongs.Count > 1)
            {
                Random rnd = new Random();
                int nextIdx = rnd.Next(0, queueSongs.Count);
                if (nextIdx == currentQueueIndex) nextIdx = (nextIdx + 1) % queueSongs.Count;
                currentQueueIndex = nextIdx;
            }
            else
            {
                currentQueueIndex = (currentQueueIndex + 1) % queueSongs.Count;
            }
            PlaySong(queueSongs[currentQueueIndex], true);
        }

        private void PrevTrack()
        {
            TriggerButtonBounce("prev");
            if (queueSongs.Count == 0) return;
            EnforceUniqueQueueTitlesInPlace();
            currentQueueIndex = (currentQueueIndex - 1 + queueSongs.Count) % queueSongs.Count;
            PlaySong(queueSongs[currentQueueIndex], true);
        }

        private void AddToQueue(SongItem song)
        {
            if (song == null) return;
            if (string.IsNullOrEmpty(song.Mood) || song.Mood == "All")
            {
                song.Mood = InferSongMood(song.Title, song.Artist, song.Album, song.Duration);
            }
            manualQueuedIds.Add(song.Id);
            if (!ContainsSongByTitleOrId(queueSongs, song))
            {
                int insertPos = Math.Min(queueSongs.Count, currentQueueIndex + 1);
                queueSongs.Insert(insertPos, song);
            }
            rightPanelMode = 0;
            SavePersistentSettings();
            ShowToast("Added Next in Queue: " + song.Title);
            this.Invalidate();
        }

        private string GetSafeLocalSongFileName(SongItem song)
        {
            if (song == null) return "Track.m4a";
            string safeId = Regex.Replace(song.Id ?? "track", "[^a-zA-Z0-9_-]", "_");
            string safeTitle = CleanSongDisplayTitle(song.Title) + " - " + GetPrimaryArtistName(song.Artist) + " [" + safeId + "] (320kbps).m4a";
            foreach (char c in Path.GetInvalidFileNameChars())
            {
                safeTitle = safeTitle.Replace(c.ToString(), "");
            }
            return safeTitle;
        }

        private string GetLocalDownloadedFilePath(SongItem song)
        {
            if (song == null) return "";
            try
            {
                // 1. If AudioUrl or FallbackUrl is already a local file on disk
                if (!string.IsNullOrEmpty(song.AudioUrl) && File.Exists(song.AudioUrl)) return song.AudioUrl;
                if (!string.IsNullOrEmpty(song.FallbackUrl) && File.Exists(song.FallbackUrl)) return song.FallbackUrl;

                string safeId = Regex.Replace(song.Id ?? "", "[^a-zA-Z0-9_-]", "_");
                string newName = GetSafeLocalSongFileName(song);
                string legacyName = CleanSongDisplayTitle(song.Title) + " - " + GetPrimaryArtistName(song.Artist) + " (320kbps).m4a";
                foreach (char c in Path.GetInvalidFileNameChars()) legacyName = legacyName.Replace(c.ToString(), "");

                string[] checkDirs = new string[]
                {
                    downloadsFolder,
                    secondaryUserDownloadsFolder,
                    Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), "Downloads")
                };
                foreach (string dir in checkDirs)
                {
                    if (string.IsNullOrEmpty(dir) || !Directory.Exists(dir)) continue;
                    string p1 = Path.Combine(dir, newName);
                    if (File.Exists(p1) && new FileInfo(p1).Length > 15000L) return p1;
                    string p2 = Path.Combine(dir, legacyName);
                    if (File.Exists(p2) && new FileInfo(p2).Length > 15000L) return p2;
                }
            }
            catch { }
            return "";
        }

        private void SaveLocalDownloadsDatabase()
        {
            try
            {
                if (string.IsNullOrEmpty(localDownloadsDbPath)) return;
                List<string> lines = new List<string>();
                foreach (SongItem s in downloadedSongs)
                {
                    if (s == null) continue;
                    lines.Add(EncodeSongRecord(s));
                }
                File.WriteAllLines(localDownloadsDbPath, lines.ToArray(), Encoding.UTF8);
            }
            catch { }
        }

        private void ScanAndRestoreLocalDownloads(bool showToast)
        {
            try
            {
                // 1. Load from local downloads_catalog.db
                if (!string.IsNullOrEmpty(localDownloadsDbPath) && File.Exists(localDownloadsDbPath))
                {
                    string[] dbLines = File.ReadAllLines(localDownloadsDbPath, Encoding.UTF8);
                    foreach (string line in dbLines)
                    {
                        SongItem ds = DecodeSongRecord(line);
                        if (ds != null && !ContainsSongByTitleOrId(downloadedSongs, ds))
                        {
                            downloadedSongs.Add(ds);
                            if (!ContainsSongByTitleOrId(catalog, ds)) catalog.Add(ds);
                        }
                    }
                }

                // 2. Scan local Downloads folders (`Leo_Music_Local_Data\Downloads`, `Downloads\Leo_Music_Downloads`, `UserProfile\Downloads`)
                string[] scanDirs = new string[]
                {
                    downloadsFolder,
                    secondaryUserDownloadsFolder,
                    Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), "Downloads")
                };
                string[] validExts = new string[] { ".m4a", ".mp3", ".wav", ".flac", ".aac", ".wma" };

                for (int dIdx = 0; dIdx < scanDirs.Length; dIdx++)
                {
                    string dir = scanDirs[dIdx];
                    if (string.IsNullOrEmpty(dir) || !Directory.Exists(dir)) continue;
                    string[] files = Directory.GetFiles(dir);
                    foreach (string file in files)
                    {
                        try
                        {
                            string ext = (Path.GetExtension(file) ?? "").ToLowerInvariant();
                            bool extOk = false;
                            foreach (string ve in validExts) { if (ext == ve) { extOk = true; break; } }
                            if (!extOk) continue;

                            FileInfo fi = new FileInfo(file);
                            if (fi.Length < 15000L) continue;

                            string fnameNoExt = Path.GetFileNameWithoutExtension(file);
                            // In general UserProfile\Downloads (dIdx == 2), only auto-import files that look like Leo Music downloads (`(320kbps)` or `[`) unless in dedicated Leo folders
                            if (dIdx == 2 && !fnameNoExt.Contains("(320kbps)") && !fnameNoExt.Contains("[")) continue;

                            // Copy into primary `Leo_Music_Local_Data\Downloads` if it was only in UserProfile\Downloads
                            string localCopyPath = Path.Combine(downloadsFolder, Path.GetFileName(file));
                            if (dIdx > 0 && !File.Exists(localCopyPath))
                            {
                                try { File.Copy(file, localCopyPath, false); } catch { localCopyPath = file; }
                            }
                            else if (!File.Exists(localCopyPath))
                            {
                                localCopyPath = file;
                            }

                            // Check if already in downloadedSongs
                            bool alreadyMatched = false;
                            foreach (SongItem existing in downloadedSongs)
                            {
                                if (string.Equals(existing.AudioUrl, localCopyPath, StringComparison.OrdinalIgnoreCase) ||
                                    string.Equals(existing.FallbackUrl, localCopyPath, StringComparison.OrdinalIgnoreCase) ||
                                    fnameNoExt.IndexOf(CleanSongDisplayTitle(existing.Title), StringComparison.OrdinalIgnoreCase) >= 0)
                                {
                                    if (string.IsNullOrEmpty(existing.FallbackUrl) || !File.Exists(existing.FallbackUrl))
                                    {
                                        existing.FallbackUrl = localCopyPath;
                                    }
                                    alreadyMatched = true;
                                    break;
                                }
                            }
                            if (alreadyMatched) continue;

                            // Parse Title & Artist from filename: `Title - Artist [id] (320kbps)`
                            string cleanLabel = fnameNoExt.Replace("(320kbps)", "").Trim();
                            string extractedId = "local_" + Math.Abs(cleanLabel.GetHashCode());
                            int brkStart = cleanLabel.IndexOf('[');
                            int brkEnd = cleanLabel.IndexOf(']');
                            if (brkStart >= 0 && brkEnd > brkStart + 1)
                            {
                                extractedId = cleanLabel.Substring(brkStart + 1, brkEnd - brkStart - 1).Trim();
                                cleanLabel = (cleanLabel.Substring(0, brkStart) + cleanLabel.Substring(brkEnd + 1)).Trim();
                            }

                            string parsedTitle = cleanLabel;
                            string parsedArtist = "Local Studio Track";
                            int dashIdx = cleanLabel.IndexOf(" - ");
                            if (dashIdx > 0)
                            {
                                parsedTitle = cleanLabel.Substring(0, dashIdx).Trim();
                                parsedArtist = cleanLabel.Substring(dashIdx + 3).Trim();
                            }

                            // Check if catalog has richer metadata for this ID or Title
                            SongItem matchedCat = null;
                            foreach (SongItem csItem in catalog)
                            {
                                if (csItem.Id == extractedId || string.Equals(CleanSongDisplayTitle(csItem.Title), parsedTitle, StringComparison.OrdinalIgnoreCase))
                                {
                                    matchedCat = csItem;
                                    break;
                                }
                            }

                            SongItem restored = matchedCat != null
                                ? new SongItem(matchedCat.Id, matchedCat.Title, matchedCat.Artist, matchedCat.Album, matchedCat.Duration, matchedCat.Mood, matchedCat.ThumbUrl, localCopyPath, localCopyPath, matchedCat.Lyrics)
                                : new SongItem(extractedId, parsedTitle, parsedArtist, "Local Offline Download", 215, InferSongMood(parsedTitle, parsedArtist, "", 215), "", localCopyPath, localCopyPath, "");

                            if (!ContainsSongByTitleOrId(downloadedSongs, restored))
                            {
                                downloadedSongs.Add(restored);
                            }
                            if (!ContainsSongByTitleOrId(catalog, restored))
                            {
                                catalog.Insert(0, restored);
                            }
                        }
                        catch { }
                    }
                }

                SaveLocalDownloadsDatabase();
                if (showToast)
                {
                    ShowToast("\u2726 Scanned Local Downloads Folder: " + downloadedSongs.Count + " Songs Ready Offline");
                }
                if (activeTab == 3) FilterDisplaySongs();
            }
            catch { }
        }

        private void ImportLocalAudioFilesFromPc()
        {
            try
            {
                using (OpenFileDialog ofd = new OpenFileDialog())
                {
                    ofd.Title = "Import Songs from Your PC/Laptop into Leo Music Offline Downloads";
                    ofd.Filter = "Audio Files (*.mp3;*.m4a;*.wav;*.flac;*.aac;*.wma)|*.mp3;*.m4a;*.wav;*.flac;*.aac;*.wma|All Files (*.*)|*.*";
                    ofd.Multiselect = true;
                    if (ofd.ShowDialog(this) == DialogResult.OK && ofd.FileNames != null && ofd.FileNames.Length > 0)
                    {
                        int added = 0;
                        foreach (string src in ofd.FileNames)
                        {
                            try
                            {
                                if (!File.Exists(src)) continue;
                                string dest = Path.Combine(downloadsFolder, Path.GetFileName(src));
                                if (!string.Equals(src, dest, StringComparison.OrdinalIgnoreCase))
                                {
                                    File.Copy(src, dest, true);
                                }
                                added++;
                            }
                            catch { }
                        }
                        ScanAndRestoreLocalDownloads(false);
                        SavePersistentSettings();
                        FilterDisplaySongs();
                        ShowToast("\u2726 Imported " + added + " Song(s) into Local Downloads (" + downloadedSongs.Count + " Total)");
                        this.Invalidate();
                    }
                }
            }
            catch { }
        }

        private void DownloadSongDirectly(SongItem song)
        {
            if (song == null || !string.IsNullOrEmpty(downloadingSongId)) return;
            TriggerButtonBounce("download");

            string safeTitle = GetSafeLocalSongFileName(song);
            string destFile = Path.Combine(downloadsFolder, safeTitle);
            string secondaryDest = Path.Combine(secondaryUserDownloadsFolder, safeTitle);

            string safeId = Regex.Replace(song.Id, "[^a-zA-Z0-9_-]", "_");
            string cachedFile = Path.Combine(cacheFolder, safeId + ".m4a");
            if (File.Exists(cachedFile) && new FileInfo(cachedFile).Length > 10000)
            {
                try
                {
                    File.Copy(cachedFile, destFile, true);
                    try { File.Copy(cachedFile, secondaryDest, true); } catch { }
                    song.FallbackUrl = destFile;
                    AddSongToDownloadedList(song);
                    ShowToast("\u2726 Saved to Local Downloads: " + CleanSongDisplayTitle(song.Title));
                    this.Invalidate();
                    return;
                }
                catch { }
            }

            downloadingSongId = song.Id;
            downloadProgress = 15;
            ShowToast("Downloading to Local Folder: " + song.Title + "...");

            Thread dlThread = new Thread(() =>
            {
                string resolvedUrl = ResolveActiveLosslessStreamUrl(song);
                string[] candidates = new string[] { resolvedUrl, song.AudioUrl, song.FallbackUrl, song.FallbackUrl96 };
                bool ok = false;
                foreach (string url in candidates)
                {
                    if (string.IsNullOrEmpty(url) || File.Exists(url)) continue;
                    try
                    {
                        using (WebClient wc = new WebClient())
                        {
                            wc.Headers.Add("User-Agent", "Mozilla/5.0 (Windows NT 10.0; Win64; x64)");
                            wc.DownloadFile(url, destFile);
                        }
                        if (File.Exists(destFile) && new FileInfo(destFile).Length > 10000)
                        {
                            try { File.Copy(destFile, secondaryDest, true); } catch { }
                            try { if (!File.Exists(cachedFile)) File.Copy(destFile, cachedFile, true); } catch { }
                            ok = true;
                            break;
                        }
                    }
                    catch { }
                }

                // Also cache cover art locally for 100% offline display
                if (!string.IsNullOrEmpty(song.ThumbUrl))
                {
                    PrefetchSingleThumbnail(song.ThumbUrl);
                }

                this.BeginInvoke((MethodInvoker)delegate
                {
                    downloadingSongId = "";
                    downloadProgress = 0;
                    if (ok)
                    {
                        song.FallbackUrl = destFile;
                        AddSongToDownloadedList(song);
                        ShowToast("\u2726 Downloaded Offline: " + CleanSongDisplayTitle(song.Title));
                    }
                    else
                    {
                        ShowToast("Download failed (Check connection)");
                    }
                    this.Invalidate();
                });
            });
            dlThread.IsBackground = true;
            dlThread.Start();
        }

        private void AddSongToDownloadedList(SongItem song)
        {
            if (song == null) return;
            bool exists = false;
            foreach (SongItem item in downloadedSongs)
            {
                if (item.Id == song.Id || string.Equals(CleanSongDisplayTitle(item.Title), CleanSongDisplayTitle(song.Title), StringComparison.OrdinalIgnoreCase))
                {
                    exists = true;
                    break;
                }
            }
            if (!exists) downloadedSongs.Insert(0, song);
            if (!ContainsSongByTitleOrId(catalog, song)) catalog.Insert(0, song);
            SaveLocalDownloadsDatabase();
            SavePersistentSettings();
            if (activeTab == 3) FilterDisplaySongs();
        }

        private string GetAudioCacheSizeText()
        {
            try
            {
                if (!Directory.Exists(cacheFolder)) return "0.0 MB";
                long bytes = 0;
                foreach (string f in Directory.GetFiles(cacheFolder))
                {
                    bytes += new FileInfo(f).Length;
                }
                double mb = bytes / (1024.0 * 1024.0);
                return mb.ToString("0.0") + " MB";
            }
            catch { return "0.0 MB"; }
        }

        private void ClearAudioCache()
        {
            try
            {
                if (Directory.Exists(cacheFolder))
                {
                    foreach (string f in Directory.GetFiles(cacheFolder))
                    {
                        try { File.Delete(f); } catch { }
                    }
                }
                ShowToast("Audio Cache Cleared");
                this.Invalidate();
            }
            catch { }
        }

