        private void DrawExpandIcon(Graphics g, Color color, float cx, float cy)
        {
            using (Pen p = new Pen(color, 1.6f))
            {
                p.StartCap = LineCap.Round;
                p.EndCap = LineCap.Round;
                g.DrawLine(p, cx - 5f, cy + 5f, cx + 5f, cy - 5f);
                g.DrawLine(p, cx + 1f, cy - 5f, cx + 5f, cy - 5f);
                g.DrawLine(p, cx + 5f, cy - 1f, cx + 5f, cy - 5f);
                g.DrawLine(p, cx - 5f, cy + 1f, cx - 5f, cy + 5f);
                g.DrawLine(p, cx - 1f, cy + 5f, cx - 5f, cy + 5f);
            }
        }

        private void DrawHeartIcon(Graphics g, Color color, float cx, float cy, bool filled)
        {
            // Larger, fuller Bezier Heart Icon (22x19px) with glowing halo when liked
            if (filled)
            {
                using (SolidBrush glowB = new SolidBrush(Color.FromArgb(58, 255, 56, 148)))
                {
                    g.FillEllipse(glowB, cx - 14f, cy - 14f, 28f, 28f);
                }
            }
            using (GraphicsPath path = new GraphicsPath())
            {
                path.AddBezier(cx, cy - 3.2f, cx - 5.2f, cy - 9.2f, cx - 10.8f, cy - 1.5f, cx, cy + 8.0f);
                path.AddBezier(cx, cy + 8.0f, cx + 10.8f, cy - 1.5f, cx + 5.2f, cy - 9.2f, cx, cy - 3.2f);
                path.CloseFigure();
                if (filled)
                {
                    RectangleF bounds = new RectangleF(cx - 12f, cy - 10f, 24f, 20f);
                    using (LinearGradientBrush hb = new LinearGradientBrush(
                        bounds,
                        Color.FromArgb(255, 255, 62, 152),
                        Color.FromArgb(255, 168, 85, 247),
                        LinearGradientMode.Vertical))
                    using (Pen rimP = new Pen(Color.FromArgb(220, 255, 195, 230), 1.2f))
                    {
                        g.FillPath(hb, path);
                        g.DrawPath(rimP, path);
                    }
                }
                else
                {
                    using (Pen p = new Pen(color, 1.9f))
                    {
                        p.LineJoin = LineJoin.Round;
                        g.DrawPath(p, path);
                    }
                }
            }
        }

        private void DrawToggleSwitch(Graphics g, Rectangle rect, bool isOn)
        {
            using (SolidBrush b = new SolidBrush(isOn ? accentColor : Color.FromArgb(40, 45, 62)))
            {
                FillRoundRect(g, b, rect, rect.Height / 2);
            }
            int knobSz = rect.Height - 6;
            int kx = isOn ? (rect.Right - knobSz - 3) : (rect.X + 3);
            using (SolidBrush kb = new SolidBrush(isOn ? Color.Black : Color.White))
            {
                g.FillEllipse(kb, kx, rect.Y + 3, knobSz, knobSz);
            }
        }

        private void DrawEqResponsiveVisualizer(Graphics g, int startX, int baseY, int numBars, int spacing, float barW, float maxH)
        {
            if (visualizerStyleIdx == 1)
            {
                // Style 1: Smooth Dual Neon Wave
                List<PointF> wave1 = new List<PointF>();
                List<PointF> wave2 = new List<PointF>();
                for (int i = 0; i < numBars; i++)
                {
                    float x = startX + i * spacing + barW / 2f;
                    float amp = isPlaying ? (maxH * 0.85f) : 2.5f;
                    float y1 = baseY - maxH * 0.45f + (float)Math.Sin(wavePhase * 1.3f + i * 0.45f) * amp * 0.55f;
                    float y2 = baseY - maxH * 0.45f + (float)Math.Cos(wavePhase * 1.05f - i * 0.38f) * amp * 0.42f;
                    wave1.Add(new PointF(x, y1));
                    wave2.Add(new PointF(x, y2));
                }
                if (wave1.Count > 1)
                {
                    using (Pen p2 = new Pen(Color.FromArgb(110, accentColor), 2.2f))
                    using (Pen p1 = new Pen(accentColor, 2.8f))
                    {
                        g.DrawCurve(p2, wave2.ToArray());
                        g.DrawCurve(p1, wave1.ToArray());
                    }
                }
                return;
            }

            using (SolidBrush vb = new SolidBrush(accentColor))
            using (SolidBrush glowB = new SolidBrush(Color.FromArgb(95, accentColor)))
            {
                float midY = baseY - maxH * 0.5f;
                for (int i = 0; i < numBars; i++)
                {
                    float bandPos = (float)i / Math.Max(1, numBars - 1) * 4f;
                    int b0 = Math.Min(4, (int)bandPos);
                    int b1 = Math.Min(4, b0 + 1);
                    float frac = bandPos - b0;
                    float dbGain = eqEnabled ? (eqBands[b0] * (1f - frac) + eqBands[b1] * frac) : 0f;
                    if (b0 <= 1 && eqEnabled) dbGain += (bassBoostPct * 0.05f);

                    float eqMult = Math.Max(0.28f, Math.Min(1.75f, 1.0f + dbGain * 0.065f));
                    float bh = isPlaying ? (4f + (float)Math.Abs(Math.Sin(wavePhase * 1.25f + i * 0.52f)) * maxH * eqMult) : 4f;
                    bh = Math.Min(maxH * 1.45f, bh);

                    float x = startX + i * spacing;
                    if (visualizerStyleIdx == 2)
                    {
                        // Style 2: Center-Mirrored Soundwave
                        g.FillRectangle(vb, x, midY - bh * 0.55f, barW, bh * 1.1f);
                    }
                    else if (visualizerStyleIdx == 3)
                    {
                        // Style 3: Glowing Harmonic Orbs
                        float oy = baseY - bh;
                        g.FillEllipse(glowB, x - 1.5f, oy - 1.5f, barW + 3f, barW + 3f);
                        g.FillEllipse(vb, x, oy, barW, barW);
                        g.FillRectangle(glowB, x + barW * 0.25f, oy + barW, barW * 0.5f, Math.Max(2f, bh - barW));
                    }
                    else
                    {
                        // Style 0: Classic Studio Bars
                        g.FillRectangle(vb, x, baseY - bh, barW, bh);
                    }
                }
            }
        }

        // =========================================================================
        // UPGRADED BETTERLYRICS KARAOKE REAL-TIME AUTO-SYNC RENDERER
        // Uses sub-frame smoothPosSec clock for 35-FPS continuous syllable fill,
        // active-line soft glow, intro spinner, and instant sync controls!
        // =========================================================================

        private Font GetCustomLyricFont(bool isActive, bool isFullScreenStyle)
        {
            int fIdx = Math.Max(0, Math.Min(3, lyricFontStyleIdx));
            int sIdx = Math.Max(0, Math.Min(3, lyricTextSizeIdx));
            if (!isFullScreenStyle)
            {
                return isActive ? fontLyricsSideActiveZoom : fontLyricsSideIdle;
            }
            if (lyricFontTableFull[fIdx, sIdx] == null)
            {
                string[] famNames = new string[] { "Georgia", "Segoe UI", "Georgia", "Segoe UI" };
                FontStyle[] fStyles = new FontStyle[] { FontStyle.Bold, FontStyle.Bold, FontStyle.Bold | FontStyle.Italic, FontStyle.Bold };
                float[] actSizes = new float[] { 18.5f, 22.0f, 25.5f, 29.0f };
                float[] idlSizes = new float[] { 15.5f, 18.0f, 20.5f, 23.0f };
                lyricFontTableFull[fIdx, sIdx] = new Font(famNames[fIdx], actSizes[sIdx], fStyles[fIdx]);
                lyricFontTableIdle[fIdx, sIdx] = new Font(famNames[fIdx], idlSizes[sIdx], fStyles[fIdx]);
            }
            return isActive ? lyricFontTableFull[fIdx, sIdx] : lyricFontTableIdle[fIdx, sIdx];
        }

        private void PaintBetterLyricsCanvas(Graphics g, Rectangle bounds, bool isFullScreenStyle, StringFormat sfCenter)
        {
            if (currentSong == null) return;
            EnsureSyncedLyricsParsed(currentSong);
            List<LyricLine> lines = currentSong.SyncedLines;

            Region oldClip = g.Clip;
            g.SetClip(bounds);

            if (isFullScreenStyle && lyricBgArtModeIdx == 0)
            {
                int wmSz = 160;
                Rectangle wmRect = new Rectangle(bounds.Right - wmSz - 28, bounds.Bottom - wmSz - 64, wmSz, wmSz);
                DrawStaticAlbumArt(g, currentSong.ThumbUrl, wmRect, 24);
                using (SolidBrush dimB = new SolidBrush(Color.FromArgb(195, 12, 9, 24)))
                {
                    FillRoundRect(g, dimB, wmRect, 24);
                }
            }
            else if (isFullScreenStyle && lyricBgArtModeIdx == 2)
            {
                int wmSz = 180;
                Rectangle wmRect = new Rectangle(bounds.Right - wmSz - 24, bounds.Bottom - wmSz - 60, wmSz, wmSz);
                using (Pen vp = new Pen(Color.FromArgb(28, 215, 175, 255), 1.4f))
                {
                    g.DrawEllipse(vp, wmRect);
                    g.DrawEllipse(vp, wmRect.X + 24, wmRect.Y + 24, wmRect.Width - 48, wmRect.Height - 48);
                    g.DrawEllipse(vp, wmRect.X + 48, wmRect.Y + 48, wmRect.Width - 96, wmRect.Height - 96);
                }
            }

            // 1. Top Accuracy % Badge + Interactive Customization Toolbar
            int headerY = bounds.Y + 6;
            bool isExact = (lines != null && lines.Count > 0 && lines[0].IsExactLrcTimestamp) || currentLyricsAreExactLrc;
            int dispAcc = Math.Max(88, Math.Min(99, currentLyricMatchScore > 0 ? currentLyricMatchScore : (isExact ? 99 : 92)));

            Rectangle accBadge = new Rectangle(bounds.X + 12, headerY - 1, isFullScreenStyle ? 226 : 148, 24);
            Color accCol = isExact ? Color.FromArgb(34, 197, 94) : Color.FromArgb(168, 85, 247);
            using (SolidBrush ab = new SolidBrush(Color.FromArgb(55, accCol.R, accCol.G, accCol.B)))
            using (Pen ap = new Pen(Color.FromArgb(185, accCol.R, accCol.G, accCol.B), 1.1f))
            {
                FillRoundRect(g, ab, accBadge, 12);
                DrawRoundRect(g, ap, accBadge, 12);
            }
            string accTxt = isFullScreenStyle
                ? ("\u2713 " + dispAcc + "% Accuracy \u2022 " + (isExact ? "Exact LRC Sync" : "Smart Sync"))
                : ("\u2713 " + dispAcc + "% Sync Accuracy");
            using (SolidBrush atb = new SolidBrush(isExact ? Color.FromArgb(145, 255, 190) : Color.FromArgb(235, 200, 255)))
            {
                g.DrawString(accTxt, fontSmallBold, atb, accBadge, sfCenter);
            }

            if (isFullScreenStyle)
            {
                syncSwitchMatchBtnRect = new Rectangle(bounds.Right - 604, headerY - 1, 108, 24);
                syncBoxlessBtnRect     = new Rectangle(bounds.Right - 490, headerY - 1, 62, 24);
                syncGlowBtnRect        = new Rectangle(bounds.Right - 422, headerY - 1, 52, 24);
                syncFontBtnRect        = new Rectangle(bounds.Right - 364, headerY - 1, 52, 24);
                syncSizeBtnRect        = new Rectangle(bounds.Right - 306, headerY - 1, 48, 24);
                syncBgArtBtnRect       = new Rectangle(bounds.Right - 252, headerY - 1, 46, 24);
                syncCopyBtnRect        = new Rectangle(bounds.Right - 200, headerY - 1, 44, 24);
                syncRefetchBtnRect     = new Rectangle(bounds.Right - 150, headerY - 1, 46, 24);
                syncMinusBtnRect       = new Rectangle(bounds.Right - 98,  headerY - 1, 32, 24);
                syncResetBtnRect       = new Rectangle(bounds.Right - 62,  headerY - 1, 30, 24);
                syncPlusBtnRect        = new Rectangle(bounds.Right - 28,  headerY - 1, 32, 24);

                Rectangle[] pillRects = new Rectangle[]
                {
                    syncSwitchMatchBtnRect, syncBoxlessBtnRect, syncGlowBtnRect, syncFontBtnRect, syncSizeBtnRect,
                    syncBgArtBtnRect, syncCopyBtnRect, syncRefetchBtnRect, syncMinusBtnRect, syncResetBtnRect, syncPlusBtnRect
                };
                string[] pillTexts = new string[]
                {
                    "\u21C4 " + lyricsProviderNames[activeLyricsProviderIdx],
                    lyricStageStyleNames[lyricStageStyleIdx].Split(' ')[0],
                    "Glow",
                    "Font",
                    "Size",
                    "Art",
                    "Copy",
                    "\u21BB LRC",
                    "-0.2",
                    lyricSyncOffsetSec == 0 ? "0s" : lyricSyncOffsetSec.ToString("+0.0;-0.0"),
                    "+0.2"
                };

                Point relM = this.PointToClient(Cursor.Position);
                for (int pi = 0; pi < pillRects.Length; pi++)
                {
                    bool hov = pillRects[pi].Contains(relM);
                    using (SolidBrush pb = new SolidBrush((pi == 0 || hov) ? Color.FromArgb(155, accentColor.R, accentColor.G, accentColor.B) : Color.FromArgb(135, 24, 18, 46)))
                    using (Pen pp = new Pen(Color.FromArgb(hov ? 235 : 105, 215, 175, 255), 1f))
                    {
                        FillRoundRect(g, pb, pillRects[pi], 10);
                        DrawRoundRect(g, pp, pillRects[pi], 10);
                    }
                    g.DrawString(pillTexts[pi], fontSmallBold, Brushes.White, pillRects[pi], sfCenter);
                }
            }
            else
            {
                syncSwitchMatchBtnRect = new Rectangle(bounds.Right - 104, headerY - 1, 96, 24);
                using (SolidBrush pb = new SolidBrush(Color.FromArgb(145, accentColor.R, accentColor.G, accentColor.B)))
                {
                    FillRoundRect(g, pb, syncSwitchMatchBtnRect, 11);
                }
                g.DrawString("\u21C4 " + lyricsProviderNames[activeLyricsProviderIdx], fontSmallBold, Brushes.White, syncSwitchMatchBtnRect, sfCenter);
            }

            if (lines == null || lines.Count == 0)
            {
                g.Clip = oldClip;
                return;
            }

            // Tight Vocal-Onset Phase Lock (+0.04s syllable anticipation)
            double syncClock = Math.Max(0.0, smoothPosSec + lyricSyncOffsetSec + 0.04);
            int activeIdx = 0;
            for (int i = 0; i < lines.Count; i++)
            {
                if (syncClock >= lines[i].StartSec && syncClock <= lines[i].EndSec) { activeIdx = i; break; }
                if (syncClock >= lines[i].StartSec) activeIdx = i;
            }

            float sizeScale = (lyricTextSizeIdx == 0) ? 0.86f : ((lyricTextSizeIdx == 2) ? 1.16f : 1.0f);
            int lineSpacing = (int)((isFullScreenStyle ? 56 : 44) * sizeScale);
            targetLyricsScrollY = activeIdx * lineSpacing;

            int centerStageY = bounds.Y + (int)(bounds.Height * 0.44f);
            activeLyricHitRects.Clear();
            activeLyricHitTimes.Clear();

            string fontFam = "Segoe UI";
            if (lyricFontStyleIdx == 1) fontFam = "Georgia";
            else if (lyricFontStyleIdx == 2) fontFam = "Trebuchet MS";
            else if (lyricFontStyleIdx == 3) fontFam = "Consolas";

            float activeFontPt = (isFullScreenStyle ? 22f : 14.5f) * sizeScale;
            float nearFontPt   = (isFullScreenStyle ? 16.5f : 11.5f) * sizeScale;
            float farFontPt    = (isFullScreenStyle ? 14.0f : 10.2f) * sizeScale;

            using (Font fActive = new Font(fontFam, activeFontPt, FontStyle.Bold))
            using (Font fNear   = new Font(fontFam, nearFontPt, FontStyle.Bold))
            using (Font fFar    = new Font(fontFam, farFontPt, FontStyle.Regular))
            {
                StringFormat sfLine = new StringFormat();
                sfLine.Alignment = isFullScreenStyle ? StringAlignment.Near : StringAlignment.Center;
                sfLine.LineAlignment = StringAlignment.Center;
                sfLine.Trimming = StringTrimming.EllipsisWord;

                for (int i = 0; i < lines.Count; i++)
                {
                    float drawY = centerStageY + (i * lineSpacing) - lyricsSmoothScrollY;
                    if (drawY < bounds.Y + 30 || drawY > bounds.Bottom - 24) continue;

                    int dist = Math.Abs(i - activeIdx);
                    if (lyricFadeModeIdx == 3 && dist > 1) continue;
                    if (lyricFadeModeIdx == 2 && dist > 3) continue;

                    LyricLine ln = lines[i];
                    string displayLine = FormatLyricTextForActiveProvider(ln.Text);
                    bool isActive = (i == activeIdx);

                    int rowH = isActive ? (int)((isFullScreenStyle ? 58 : 44) * sizeScale) : (int)((isFullScreenStyle ? 42 : 32) * sizeScale);
                    Rectangle lineRect = new Rectangle(bounds.X + (isFullScreenStyle ? 28 : 8), (int)drawY - rowH / 2, bounds.Width - (isFullScreenStyle ? 56 : 16), rowH);

                    activeLyricHitRects.Add(lineRect);
                    activeLyricHitTimes.Add(ln.StartSec);

                    if (isActive)
                    {
                        if (lyricStageStyleIdx == 0)
                        {
                            using (LinearGradientBrush haloB = new LinearGradientBrush(
                                lineRect,
                                Color.FromArgb(85, accentColor.R, accentColor.G, accentColor.B),
                                Color.FromArgb(0, accentColor.R, accentColor.G, accentColor.B),
                                LinearGradientMode.Horizontal))
                            {
                                FillRoundRect(g, haloB, lineRect, 14);
                            }
                        }
                        else if (lyricStageStyleIdx == 2)
                        {
                            using (SolidBrush cb = new SolidBrush(Color.FromArgb(165, 88, 38, 175)))
                            using (Pen cp = new Pen(Color.FromArgb(225, 225, 175, 255), 1.4f))
                            {
                                FillRoundRect(g, cb, lineRect, 14);
                                DrawRoundRect(g, cp, lineRect, 14);
                            }
                        }

                        double dur = Math.Max(0.25, ln.EndSec - ln.StartSec);
                        float prog = (float)Math.Max(0.0, Math.Min(1.0, (syncClock - ln.StartSec) / dur));

                        if (lyricGlowModeIdx == 0 || activeLyricsProviderIdx == 0)
                        {
                            using (SolidBrush baseB = new SolidBrush(Color.FromArgb(145, 225, 215, 245)))
                            {
                                g.DrawString(displayLine, fActive, baseB, lineRect, sfLine);
                            }
                            SizeF fullSz = g.MeasureString(displayLine, fActive, lineRect.Width, sfLine);
                            int glowW = Math.Max(12, (int)(Math.Min(lineRect.Width, fullSz.Width + 24) * prog));
                            Region prevC = g.Clip;
                            g.SetClip(new Rectangle(lineRect.X, lineRect.Y, glowW, lineRect.Height), CombineMode.Intersect);
                            g.DrawString(displayLine, fActive, Brushes.White, lineRect, sfLine);
                            g.Clip = prevC;
                        }
                        else
                        {
                            Color actCol = (lyricGlowModeIdx == 1) ? Color.FromArgb(255, 235, 195, 255) : Color.White;
                            using (SolidBrush ab = new SolidBrush(actCol))
                            {
                                g.DrawString(displayLine, fActive, ab, lineRect, sfLine);
                            }
                        }
                    }
                    else
                    {
                        int alpha = (dist == 1) ? 175 : Math.Max(48, 148 - dist * 28);
                        Font fUse = (dist == 1) ? fNear : fFar;
                        using (SolidBrush ib = new SolidBrush(Color.FromArgb(alpha, 225, 218, 245)))
                        {
                            g.DrawString(displayLine, fUse, ib, lineRect, sfLine);
                        }
                    }
                }
            }

            g.Clip = oldClip;
        }

        private List<string> WrapLyricTextToRows(Graphics g, string text, Font font, int maxWidth)
        {
            List<string> rows = new List<string>();
            if (string.IsNullOrEmpty(text))
            {
                rows.Add("");
                return rows;
            }
            string[] words = text.Split(new char[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
            StringBuilder current = new StringBuilder();
            foreach (string w in words)
            {
                string test = current.Length == 0 ? w : (current.ToString() + " " + w);
                SizeF sz = g.MeasureString(test, font);
                if (sz.Width > maxWidth && current.Length > 0)
                {
                    rows.Add(current.ToString());
                    current = new StringBuilder(w);
                }
                else
                {
                    current = new StringBuilder(test);
                }
            }
            if (current.Length > 0) rows.Add(current.ToString());
            return rows;
        }

        // =========================================================================
        // v10.4.0 ZERO-STUTTER OFFSCREEN AURORA MESH ENGINE
        // Renders the 3 breathing aurora spheres into a lightweight 240x140 buffer
        // and composites it with bilinear smoothing for 10x faster 120Hz frame rate!
        // =========================================================================

        private void PaintLiveMeshAuroraBackdrop(Graphics g, int w, int h)
        {
            if (!glassEffectEnabled || oledPureBlack || w <= 10 || h <= 10) return;
            try
            {
                int bufW = 240;
                int bufH = 140;
                auroraCacheFrameCounter++;
                if (cachedAuroraBitmap == null || auroraCacheFrameCounter >= 3)
                {
                    auroraCacheFrameCounter = 0;
                    if (cachedAuroraBitmap == null)
                    {
                        cachedAuroraBitmap = new Bitmap(bufW, bufH);
                    }
                    using (Graphics bg = Graphics.FromImage(cachedAuroraBitmap))
                    {
                        bg.Clear(Color.Transparent);
                        bg.SmoothingMode = SmoothingMode.HighSpeed;

                        float t1 = wavePhase * 0.16f;
                        float t2 = morphPhase * 0.42f;

                        int r1 = 115;
                        int cx1 = (int)(bufW * 0.36f + Math.Sin(t1) * (bufW * 0.14f));
                        int cy1 = (int)(bufH * 0.28f + Math.Cos(t2 * 0.8f) * (bufH * 0.12f));

                        int r2 = 105;
                        int cx2 = (int)(bufW * 0.72f + Math.Cos(t1 * 0.75f) * (bufW * 0.12f));
                        int cy2 = (int)(bufH * 0.62f + Math.Sin(t2) * (bufH * 0.14f));

                        int r3 = 92;
                        int cx3 = (int)(bufW * 0.24f + Math.Cos(t2 * 1.1f) * (bufW * 0.10f));
                        int cy3 = (int)(bufH * 0.76f + Math.Sin(t1 * 0.9f) * (bufH * 0.10f));

                        int acR = (int)accentColor.R;
                        int acG = (int)accentColor.G;
                        int acB = (int)accentColor.B;
                        Color cOrb1 = Color.FromArgb(56, acR, acG, acB);
                        Color cOrb2 = Color.FromArgb(44,
                            Math.Min(255, (acB + 90) % 255),
                            Math.Min(255, (acR + 60) % 255),
                            Math.Min(255, Math.Max(110, acG)));
                        Color cOrb3 = Color.FromArgb(38,
                            Math.Min(255, Math.Max(80, acG)),
                            Math.Min(255, (acB + 70) % 255),
                            Math.Min(255, (acR + 110) % 255));

                        DrawSoftMeshOrb(bg, cx1, cy1, r1, cOrb1);
                        DrawSoftMeshOrb(bg, cx2, cy2, r2, cOrb2);
                        DrawSoftMeshOrb(bg, cx3, cy3, r3, cOrb3);
                    }
                }
                g.DrawImage(cachedAuroraBitmap, new Rectangle(0, 0, w, h));
            }
            catch { }
        }

        private void DrawSoftMeshOrb(Graphics g, int cx, int cy, int radius, Color centerColor)
        {
            if (radius < 20) return;
            Rectangle bounds = new Rectangle(cx - radius, cy - radius, radius * 2, radius * 2);
            using (GraphicsPath gp = new GraphicsPath())
            {
                gp.AddEllipse(bounds);
                using (PathGradientBrush pgb = new PathGradientBrush(gp))
                {
                    pgb.CenterPoint = new PointF(cx, cy);
                    pgb.CenterColor = centerColor;
                    pgb.SurroundColors = new Color[] { Color.FromArgb(0, centerColor.R, centerColor.G, centerColor.B) };
                    g.FillPath(pgb, gp);
                }
            }
        }

        // =========================================================================
        // v10.6.4 SPATIAL UI 3D GLASS MATERIAL & SPECULAR LIGHTING ENGINE
        // =========================================================================
        private void DrawGlassCard(Graphics g, Rectangle rect, int radius, Color fallbackCardColor, bool isSelected, bool isHovered)
        {
            if (rect.Width <= 4 || rect.Height <= 4) return;
            if (oledPureBlack)
            {
                using (SolidBrush b = new SolidBrush(Color.FromArgb(14, 12, 24)))
                using (Pen p = new Pen(isSelected ? accentColor : Color.FromArgb(85, accentColor.R, accentColor.G, accentColor.B), isSelected ? 1.8f : 1.1f))
                {
                    FillRoundRect(g, b, rect, radius);
                    DrawRoundRect(g, p, rect, radius);
                }
                return;
            }

            if (rect.Height >= 34)
            {
                Rectangle shadowR = new Rectangle(rect.X + 2, rect.Y + 5, rect.Width, rect.Height);
                using (SolidBrush shB = new SolidBrush(Color.FromArgb(isHovered ? 135 : 95, 3, 2, 10)))
                {
                    FillRoundRect(g, shB, shadowR, radius);
                }
            }

            Color topFill = isSelected
                ? Color.FromArgb(225, Math.Min(255, 44 + accentColor.R / 4), Math.Min(255, 28 + accentColor.G / 5), Math.Min(255, 78 + accentColor.B / 4))
                : (isHovered ? Color.FromArgb(215, 36, 26, 66) : Color.FromArgb(202, 24, 17, 46));
            Color botFill = isSelected
                ? Color.FromArgb(235, 22, 14, 44)
                : (isHovered ? Color.FromArgb(225, 20, 14, 38) : Color.FromArgb(215, 14, 10, 28));

            using (LinearGradientBrush glassGrad = new LinearGradientBrush(rect, topFill, botFill, LinearGradientMode.Vertical))
            {
                FillRoundRect(g, glassGrad, rect, radius);
            }

            if (curved3DGlassEnabled && rect.Height >= 28)
            {
                int lensH = Math.Max(8, Math.Min(rect.Height / 3, 32));
                Rectangle topLens = new Rectangle(rect.X + 2, rect.Y + 1, Math.Max(4, rect.Width - 4), lensH);
                using (LinearGradientBrush specB = new LinearGradientBrush(
                    topLens,
                    Color.FromArgb(isHovered ? 48 : 30, 235, 205, 255),
                    Color.FromArgb(0, 168, 85, 247),
                    LinearGradientMode.Vertical))
                {
                    FillRoundRect(g, specB, topLens, Math.Max(4, radius - 2));
                }
            }

            Color rimCol = isSelected
                ? Color.FromArgb(245, Math.Min(255, accentColor.R + 30), Math.Min(255, accentColor.G + 20), Math.Min(255, accentColor.B + 15))
                : (isHovered ? Color.FromArgb(195, 215, 165, 255) : Color.FromArgb(95, 185, 140, 250));
            using (Pen rimPen = new Pen(rimCol, isSelected ? 1.8f : 1.15f))
            {
                DrawRoundRect(g, rimPen, rect, radius);
            }

            if ((isSelected || isHovered) && rect.Width > 60)
            {
                int glowW = Math.Min(rect.Width - radius * 2, 150);
                if (glowW > 20)
                {
                    int gx = rect.X + (rect.Width - glowW) / 2;
                    using (Pen glowP = new Pen(Color.FromArgb(isSelected ? 235 : 145, 225, 165, 255), 2.2f))
                    {
                        g.DrawLine(glowP, gx, rect.Bottom, gx + glowW, rect.Bottom);
                    }
                }
            }
        }

        private void PaintSpatialEnvironmentBackdrop(Graphics g, int w, int h)
        {
            if (oledPureBlack || w <= 100 || h <= 100) return;

            // When in Full-Screen Player with Song Cover Art Background ON, keep the blurred bokeh backdrop clean!
            if (isFullPlayerExpanded && songBgImageEnabled)
            {
                return;
            }

            // Fast Cached Vivid Environment Bitmap for Homepage & Tabs
            if (cachedEnvBackdropBmp == null || cachedEnvW != w || cachedEnvH != h || cachedEnvStyle != homeEffectStyleIdx)
            {
                if (cachedEnvBackdropBmp != null) { try { cachedEnvBackdropBmp.Dispose(); } catch { } }
                cachedEnvW = w;
                cachedEnvH = h;
                cachedEnvStyle = homeEffectStyleIdx;
                cachedEnvBackdropBmp = new Bitmap(w, h, System.Drawing.Imaging.PixelFormat.Format32bppPArgb);

                using (Graphics bg = Graphics.FromImage(cachedEnvBackdropBmp))
                {
                    bg.SmoothingMode = SmoothingMode.AntiAlias;
                    bg.Clear(Color.Transparent);

                    if (homeEffectStyleIdx == 0) // Style 0: Vivid Cosmic Mountain Aurora (1:1 Reference Hero!)
                    {
                        int skyH = Math.Min(h, 480);
                        using (LinearGradientBrush skyB = new LinearGradientBrush(
                            new Rectangle(0, 0, w, skyH),
                            Color.FromArgb(215, 28, 14, 58),
                            Color.FromArgb(0, 10, 8, 20),
                            LinearGradientMode.Vertical))
                        {
                            bg.FillRectangle(skyB, 0, 0, w, skyH);
                        }

                        // Vibrant Radial Aurora Glow behind the mountains
                        DrawSoftMeshOrb(bg, (int)(w * 0.62f), 165, 340, Color.FromArgb(115, 168, 85, 247));
                        DrawSoftMeshOrb(bg, (int)(w * 0.52f), 210, 260, Color.FromArgb(95, 236, 72, 153));

                        if (heroMountainAuroraBmp != null)
                        {
                            int mtnW = Math.Min(680, Math.Max(460, (int)(w * 0.50f)));
                            int mtnH = (int)(mtnW * 0.51f);
                            int rightOff = isRightPanelVisible ? 295 : 20;
                            int mtnX = Math.Max(330, w - rightOff - mtnW + 30);
                            int mtnY = 44;
                            bg.DrawImage(heroMountainAuroraBmp, new Rectangle(mtnX, mtnY, mtnW, mtnH));
                        }

                        // Electric Sweeping Pink-Violet Aurora Laser Arc across the sky
                        using (GraphicsPath arcPath = new GraphicsPath())
                        {
                            arcPath.AddBezier(
                                new PointF(w * 0.42f, 290),
                                new PointF(w * 0.56f, 128),
                                new PointF(w * 0.75f, 38),
                                new PointF(w * 0.96f, 14));
                            for (int gl = 4; gl >= 1; gl--)
                            {
                                using (Pen glowPen = new Pen(Color.FromArgb(24 * (5 - gl), 236, 115, 255), gl * 5.5f))
                                {
                                    bg.DrawPath(glowPen, arcPath);
                                }
                            }
                            using (Pen corePen = new Pen(Color.FromArgb(245, 255, 225, 255), 2.4f))
                            {
                                bg.DrawPath(corePen, arcPath);
                            }
                        }
                    }
                    else if (homeEffectStyleIdx == 1) // Style 1: Crimson Golden Horizon
                    {
                        int skyH = Math.Min(h, 480);
                        using (LinearGradientBrush skyB = new LinearGradientBrush(
                            new Rectangle(0, 0, w, skyH),
                            Color.FromArgb(215, 88, 24, 54),
                            Color.FromArgb(0, 10, 8, 20),
                            LinearGradientMode.Vertical))
                        {
                            bg.FillRectangle(skyB, 0, 0, w, skyH);
                        }
                        int sunCx = (int)(w * 0.62f);
                        int sunCy = 155;
                        DrawSoftMeshOrb(bg, sunCx, sunCy, 340, Color.FromArgb(145, 255, 115, 55));
                        DrawSoftMeshOrb(bg, sunCx, sunCy, 190, Color.FromArgb(185, 255, 205, 85));

                        for (int wave = 0; wave < 3; wave++)
                        {
                            using (GraphicsPath wp = new GraphicsPath())
                            {
                                int wy = 190 + wave * 34;
                                wp.AddBezier(
                                    new PointF(w * 0.25f, wy + 45),
                                    new PointF(w * 0.48f, wy - 35),
                                    new PointF(w * 0.70f, wy + 25),
                                    new PointF(w * 0.95f, wy - 20));
                                using (Pen p = new Pen(Color.FromArgb(110 - wave * 25, 255, 175 - wave * 30, 95), 8f - wave * 2f))
                                {
                                    bg.DrawPath(p, wp);
                                }
                            }
                        }
                    }
                    else if (homeEffectStyleIdx == 2) // Style 2: Cyber Synthwave Matrix
                    {
                        int skyH = Math.Min(h, 480);
                        using (LinearGradientBrush skyB = new LinearGradientBrush(
                            new Rectangle(0, 0, w, skyH),
                            Color.FromArgb(215, 10, 34, 68),
                            Color.FromArgb(0, 10, 8, 20),
                            LinearGradientMode.Vertical))
                        {
                            bg.FillRectangle(skyB, 0, 0, w, skyH);
                        }
                        DrawSoftMeshOrb(bg, (int)(w * 0.58f), 190, 290, Color.FromArgb(130, 6, 182, 212));
                        DrawSoftMeshOrb(bg, (int)(w * 0.74f), 160, 240, Color.FromArgb(125, 236, 72, 153));

                        int horY = 265;
                        using (Pen gridP = new Pen(Color.FromArgb(85, 0, 235, 255), 1.3f))
                        using (Pen horP = new Pen(Color.FromArgb(210, 236, 72, 153), 2.2f))
                        {
                            bg.DrawLine(horP, w * 0.22f, horY, w * 0.95f, horY);
                            int vanishX = (int)(w * 0.60f);
                            for (int i = -6; i <= 6; i++) bg.DrawLine(gridP, vanishX + i * 24, horY, vanishX + i * 95, horY + 115);
                            for (int r = 1; r <= 5; r++)
                            {
                                int gy = horY + r * r * 4 + 6;
                                bg.DrawLine(gridP, w * 0.22f, gy, w * 0.95f, gy);
                            }
                        }
                    }
                    else // Style 3: Emerald Borealis Ribbons
                    {
                        int skyH = Math.Min(h, 480);
                        using (LinearGradientBrush skyB = new LinearGradientBrush(
                            new Rectangle(0, 0, w, skyH),
                            Color.FromArgb(215, 8, 46, 42),
                            Color.FromArgb(0, 10, 8, 20),
                            LinearGradientMode.Vertical))
                        {
                            bg.FillRectangle(skyB, 0, 0, w, skyH);
                        }
                        DrawSoftMeshOrb(bg, (int)(w * 0.54f), 160, 280, Color.FromArgb(135, 16, 215, 135));
                        DrawSoftMeshOrb(bg, (int)(w * 0.72f), 145, 250, Color.FromArgb(115, 38, 195, 235));

                        for (int band = 0; band < 3; band++)
                        {
                            using (GraphicsPath aurP = new GraphicsPath())
                            {
                                int by = 95 + band * 36;
                                aurP.AddBezier(
                                    new PointF(w * 0.30f, by + 40),
                                    new PointF(w * 0.48f, by - 35),
                                    new PointF(w * 0.68f, by + 35),
                                    new PointF(w * 0.92f, by - 20));
                                using (Pen ap = new Pen(Color.FromArgb(115 - band * 25, 52, 245, 168), 14f - band * 3f))
                                {
                                    bg.DrawPath(ap, aurP);
                                }
                            }
                        }
                    }
                }
            }

            if (cachedEnvBackdropBmp != null)
            {
                g.DrawImageUnscaled(cachedEnvBackdropBmp, 0, 0);
            }
        }

        private int GetNextAllowedBgSlideIndex(int curIdx, int totalCount)
        {
            if (totalCount <= 1) return 0;
            for (int step = 1; step <= totalCount; step++)
            {
                int cand = (curIdx + step) % totalCount;
                if (songBgStyleIdx == 1 && cand > 1 && cand < 5) continue;
                if (songBgStyleIdx == 2 && cand != 2 && cand != 3 && cand < 5) continue;
                if (songBgStyleIdx == 3 && cand != 4 && cand < 5) continue;
                return cand;
            }
            return (curIdx + 1) % totalCount;
        }

        private void RebuildCurrentSongBgSlideshow(SongItem song, bool fetchOnlineGallery)
        {
            if (song == null) return;
            if (isBuildingBgSlidesAsync && cachedBgSlidesSongId == song.Id) return;
            try
            {
                string jpgUrl = (song.ThumbUrl ?? "").Replace(".webp", ".jpg");
                Image srcImg = null;
                lock (imageCache)
                {
                    if (imageCache.ContainsKey(jpgUrl)) srcImg = imageCache[jpgUrl];
                }
                if (srcImg == null)
                {
                    PrefetchSingleThumbnail(jpgUrl);
                    return;
                }

                cachedBgSlidesSongId = song.Id;
                isBuildingBgSlidesAsync = true;

                Bitmap srcClone = null;
                try { srcClone = new Bitmap(srcImg); } catch { isBuildingBgSlidesAsync = false; return; }
                string targetSongId = song.Id;

                ThreadPool.QueueUserWorkItem(_ =>
                {
                    try
                    {
                        List<Bitmap> newSlides = new List<Bitmap>();
                        List<string> newLabels = new List<string>();

                        newSlides.Add(CreateEditedWidescreenSlide(srcClone, 0));
                        newLabels.Add("Original Cinema Wide");

                        newSlides.Add(CreateEditedWidescreenSlide(srcClone, 1));
                        newLabels.Add("Edited Neon Grade");

                        newSlides.Add(CreateEditedWidescreenSlide(srcClone, 2));
                        newLabels.Add("Edited Concert Stage");

                        newSlides.Add(CreateEditedWidescreenSlide(srcClone, 3));
                        newLabels.Add("Edited Cyber Duotone");

                        srcClone.Dispose();

                        this.BeginInvoke((MethodInvoker)delegate
                        {
                            if (currentSong != null && currentSong.Id == targetSongId)
                            {
                                currentSongBgSlides = newSlides;
                                currentSongBgSlideLabels = newLabels;
                                if (songBgCurrentSlideIdx >= currentSongBgSlides.Count) songBgCurrentSlideIdx = 0;
                                songBgNextSlideIdx = GetNextAllowedBgSlideIndex(songBgCurrentSlideIdx, currentSongBgSlides.Count);
                                compositeBackdropFrameCounter = 99;
                                this.Invalidate();
                            }
                            isBuildingBgSlidesAsync = false;
                        });

                        if (fetchOnlineGallery)
                        {
                            FetchAdditionalArtistGallerySlidesAsync(song);
                        }
                    }
                    catch
                    {
                        try { if (srcClone != null) srcClone.Dispose(); } catch { }
                        isBuildingBgSlidesAsync = false;
                    }
                });
            }
            catch { isBuildingBgSlidesAsync = false; }
        }

        private Bitmap CreateEditedWidescreenSlide(Image src, int styleVariant)
        {
            int bw = 480;
            int bh = 270;
            Bitmap bmp = new Bitmap(bw, bh);
            try
            {
                // Multi-pass downscale + upscale Gaussian-style bokeh blur so album cover text NEVER clashes with UI text!
                using (Bitmap tiny = new Bitmap(44, 25))
                {
                    using (Graphics tg = Graphics.FromImage(tiny))
                    {
                        tg.InterpolationMode = InterpolationMode.HighQualityBicubic;
                        tg.DrawImage(src, new Rectangle(0, 0, 44, 25), new Rectangle(0, 0, src.Width, src.Height), GraphicsUnit.Pixel);
                    }
                    using (Graphics g = Graphics.FromImage(bmp))
                    {
                        g.SmoothingMode = SmoothingMode.AntiAlias;
                        g.InterpolationMode = InterpolationMode.HighQualityBicubic;
                        using (ImageAttributes ia = new ImageAttributes())
                        {
                            ColorMatrix cm = new ColorMatrix(new float[][] {
                                new float[] { 1.28f, 0.04f, 0.04f, 0f, 0f },
                                new float[] { 0.04f, 1.22f, 0.04f, 0f, 0f },
                                new float[] { 0.06f, 0.04f, 1.34f, 0f, 0f },
                                new float[] { 0.00f, 0.00f, 0.00f, 1f, 0f },
                                new float[] { -0.04f, -0.04f, -0.02f, 0f, 1f }
                            });
                            ia.SetColorMatrix(cm);
                            g.DrawImage(tiny, new Rectangle(-16, -12, bw + 32, bh + 24), 0, 0, 44, 25, GraphicsUnit.Pixel, ia);
                        }
                    }
                }
            }
            catch { }
            return bmp;
        }

        private void FetchAdditionalArtistGallerySlidesAsync(SongItem song)
        {
            if (song == null) return;
            int myVer = ++bgGalleryFetchVer;
            string primArtist = GetPrimaryArtistName(song.Artist);
            string baseThumb = (song.ThumbUrl ?? "").Replace(".webp", ".jpg");

            Thread t = new Thread(() =>
            {
                List<Bitmap> extraSlides = new List<Bitmap>();
                try
                {
                    string q = primArtist + " top songs";
                    string url = "https://www.jiosaavn.com/api.php?__call=search.getResults&_format=json&n=10&p=1&_marker=0&ctx=android&q=" + Uri.EscapeDataString(q);
                    using (WebClient wc = new WebClient())
                    {
                        wc.Encoding = Encoding.UTF8;
                        wc.Headers.Add("User-Agent", "Mozilla/5.0 (Linux; Android 14)");
                        string json = wc.DownloadString(url);
                        List<SongItem> items = ParseOfficialJioSaavnJson(json);
                        HashSet<string> usedUrls = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                        usedUrls.Add(baseThumb);

                        foreach (SongItem item in items)
                        {
                            if (extraSlides.Count >= 2) break;
                            string u = (item.ThumbUrl ?? "").Replace(".webp", ".jpg");
                            if (string.IsNullOrEmpty(u) || usedUrls.Contains(u)) continue;
                            usedUrls.Add(u);

                            try
                            {
                                byte[] data = wc.DownloadData(u);
                                using (MemoryStream ms = new MemoryStream(data))
                                {
                                    Image dlImg = Image.FromStream(ms);
                                    Bitmap slide = CreateEditedWidescreenSlide(dlImg, extraSlides.Count == 0 ? 1 : 2);
                                    extraSlides.Add(slide);
                                }
                            }
                            catch { }
                        }
                    }
                }
                catch { }

                if (extraSlides.Count > 0)
                {
                    this.BeginInvoke((MethodInvoker)delegate
                    {
                        if (myVer != bgGalleryFetchVer || currentSong == null || currentSong.Id != song.Id) return;
                        for (int i = 0; i < extraSlides.Count; i++)
                        {
                            if (currentSongBgSlides.Count < 8)
                            {
                                currentSongBgSlides.Add(extraSlides[i]);
                                currentSongBgSlideLabels.Add("Live Artist Still #" + (i + 1));
                            }
                        }
                    });
                }
            });
            t.IsBackground = true;
            t.Start();
        }

        private void DrawSingleBgSlideWithMotion(Graphics g, Bitmap slide, int w, int h, float phaseOffset, float alpha, int animMode)
        {
            if (slide == null || alpha <= 0.01f) return;

            // Smooth Ken Burns zoom & pan so the background feels alive while the song plays!
            float zoom = 1.08f + 0.06f * (float)Math.Sin(phaseOffset * 0.55f);
            if (animMode == 3) zoom += 0.03f * (float)Math.Sin(wavePhase * 1.4f); // Pulse Morph beat zoom

            int drawW = (int)(w * zoom);
            int drawH = (int)(h * zoom);
            int panX = (int)(Math.Sin(phaseOffset * 0.42f) * (w * 0.03f));
            int panY = (int)(Math.Cos(phaseOffset * 0.36f) * (h * 0.025f));

            if (animMode == 2 && alpha < 0.99f)
            {
                // Slide + Fade horizontal motion during transition
                panX += (int)((1.0f - alpha) * 48f);
            }

            Rectangle destRect = new Rectangle((w - drawW) / 2 + panX, (h - drawH) / 2 + panY, drawW, drawH);

            if (alpha >= 0.99f)
            {
                g.DrawImage(slide, destRect);
            }
            else
            {
                using (ImageAttributes ia = new ImageAttributes())
                {
                    ColorMatrix cm = new ColorMatrix();
                    cm.Matrix33 = Math.Max(0f, Math.Min(1f, alpha));
                    ia.SetColorMatrix(cm);
                    g.DrawImage(slide, destRect, 0, 0, slide.Width, slide.Height, GraphicsUnit.Pixel, ia);
                }
            }
        }

        private void PaintAtmosphericSongBackdrop(Graphics g, int w, int h, float intensity)
        {
            if (oledPureBlack || !songBgImageEnabled || currentSong == null || w <= 10 || h <= 10) return;
            try
            {
                if (currentSongBgSlides.Count == 0 || cachedBgSlidesSongId != currentSong.Id)
                {
                    RebuildCurrentSongBgSlideshow(currentSong, false);
                }

                // v10.4.4 ZERO-LAG TURBO COMPOSITOR:
                // Render the multi-image slide motion, ColorMatrix crossfade, scrim & gradients into a fast 384x216 Format32bppPArgb
                // offscreen surface (throttled every 2 ticks when steady) and blit in ONE pass! Cuts CPU time from ~22ms to <0.4ms!
                if (uiTurboCacheEnabled)
                {
                    int cw = 384;
                    int ch = 216;
                    compositeBackdropFrameCounter++;
                    bool needRebuild = (cachedCompositeBackdropBmp == null)
                        || (lastCompositeSlideIdx != songBgCurrentSlideIdx)
                        || isSongBgTransitioning
                        || (compositeBackdropFrameCounter >= 5);

                    if (needRebuild)
                    {
                        compositeBackdropFrameCounter = 0;
                        lastCompositeSlideIdx = songBgCurrentSlideIdx;
                        lastCompositeNextSlideIdx = songBgNextSlideIdx;
                        if (cachedCompositeBackdropBmp == null)
                        {
                            cachedCompositeBackdropBmp = new Bitmap(cw, ch, System.Drawing.Imaging.PixelFormat.Format32bppPArgb);
                        }
                        using (Graphics bg = Graphics.FromImage(cachedCompositeBackdropBmp))
                        {
                            bg.SmoothingMode = SmoothingMode.HighSpeed;
                            bg.InterpolationMode = InterpolationMode.Bilinear;
                            bg.CompositingQuality = CompositingQuality.HighSpeed;
                            bg.Clear(Color.FromArgb(255, 8, 6, 10));

                            if (currentSongBgSlides.Count > 0)
                            {
                                int curIdx = Math.Max(0, Math.Min(currentSongBgSlides.Count - 1, songBgCurrentSlideIdx));
                                Bitmap curSlide = currentSongBgSlides[curIdx];
                                DrawSingleBgSlideWithMotion(bg, curSlide, cw, ch, songBgKenBurnsPhase + curIdx * 1.7f, 1.0f, songBgAnimModeIdx);

                                if (isSongBgTransitioning && currentSongBgSlides.Count > 1)
                                {
                                    int nxtIdx = Math.Max(0, Math.Min(currentSongBgSlides.Count - 1, songBgNextSlideIdx));
                                    Bitmap nxtSlide = currentSongBgSlides[nxtIdx];
                                    float smoothAlpha = (float)((1.0 - Math.Cos(songBgCrossfadeAlpha * Math.PI)) * 0.5);
                                    DrawSingleBgSlideWithMotion(bg, nxtSlide, cw, ch, songBgKenBurnsPhase + nxtIdx * 1.7f, smoothAlpha, songBgAnimModeIdx);
                                }
                            }
                            else
                            {
                                string jpgUrl = (currentSong.ThumbUrl ?? "").Replace(".webp", ".jpg");
                                Image bgImg = null;
                                lock (imageCache)
                                {
                                    if (imageCache.ContainsKey(jpgUrl)) bgImg = imageCache[jpgUrl];
                                }
                                if (bgImg != null)
                                {
                                    int drawSz = Math.Max(cw, ch + 40);
                                    bg.DrawImage(bgImg, new Rectangle((cw - drawSz) / 2 + 16, (ch - drawSz) / 2 - 6, drawSz, drawSz));
                                }
                            }

                            int baseDarkAlpha = (int)Math.Max(115, Math.Min(195, 168 - intensity * 26));
                            using (SolidBrush darkScrim = new SolidBrush(Color.FromArgb(baseDarkAlpha, 8, 6, 10)))
                            {
                                bg.FillRectangle(darkScrim, 0, 0, cw, ch);
                            }

                            Color tintTop = Color.FromArgb((int)(64 * intensity), Math.Min(255, (int)(accentColor.R * 0.90f)), Math.Min(255, (int)(accentColor.G * 0.35f)), Math.Min(255, (int)(accentColor.B * 0.40f)));
                            Color tintBot = Color.FromArgb(220, 6, 5, 9);
                            using (LinearGradientBrush vGrad = new LinearGradientBrush(new Rectangle(0, 0, cw, ch), tintTop, tintBot, LinearGradientMode.Vertical))
                            {
                                bg.FillRectangle(vGrad, 0, 0, cw, ch);
                            }

                            Rectangle leftFadeRect = new Rectangle(0, 0, Math.Max(64, cw / 3), ch);
                            using (LinearGradientBrush lGrad = new LinearGradientBrush(
                                leftFadeRect,
                                Color.FromArgb(195, 6, 6, 9),
                                Color.FromArgb(0, 6, 6, 9),
                                LinearGradientMode.Horizontal))
                            {
                                bg.FillRectangle(lGrad, leftFadeRect);
                            }
                        }
                    }

                    InterpolationMode prevInterp = g.InterpolationMode;
                    g.InterpolationMode = InterpolationMode.Bilinear;
                    g.DrawImage(cachedCompositeBackdropBmp, new Rectangle(0, 0, w, h));
                    g.InterpolationMode = prevInterp;
                    return;
                }

                if (currentSongBgSlides.Count > 0)
                {
                    int curIdx = Math.Max(0, Math.Min(currentSongBgSlides.Count - 1, songBgCurrentSlideIdx));
                    Bitmap curSlide = currentSongBgSlides[curIdx];
                    DrawSingleBgSlideWithMotion(g, curSlide, w, h, songBgKenBurnsPhase + curIdx * 1.7f, 1.0f, songBgAnimModeIdx);

                    if (isSongBgTransitioning && currentSongBgSlides.Count > 1)
                    {
                        int nxtIdx = Math.Max(0, Math.Min(currentSongBgSlides.Count - 1, songBgNextSlideIdx));
                        Bitmap nxtSlide = currentSongBgSlides[nxtIdx];
                        float smoothAlpha = (float)((1.0 - Math.Cos(songBgCrossfadeAlpha * Math.PI)) * 0.5);
                        DrawSingleBgSlideWithMotion(g, nxtSlide, w, h, songBgKenBurnsPhase + nxtIdx * 1.7f, smoothAlpha, songBgAnimModeIdx);
                    }
                }

                int baseDarkAlphaFallback = (int)Math.Max(115, Math.Min(195, 168 - intensity * 26));
                using (SolidBrush darkScrim = new SolidBrush(Color.FromArgb(baseDarkAlphaFallback, 8, 6, 10)))
                {
                    g.FillRectangle(darkScrim, 0, 0, w, h);
                }
            }
            catch { }
        }

        private void DrawBrandMusicNoteLogo(Graphics g, int x, int y)
        {
            int[] barOffsets = new int[] { 0, 6, 12, 18, 24 };
            int[] barHeights = new int[] { 8, 16, 24, 15, 8 };
            int cy = y + 12;

            using (SolidBrush glowB = new SolidBrush(Color.FromArgb(68, accentColor.R, accentColor.G, accentColor.B)))
            {
                g.FillEllipse(glowB, x - 4, y - 2, 36, 28);
            }

            for (int i = 0; i < 5; i++)
            {
                int bh = barHeights[i];
                Rectangle barR = new Rectangle(x + barOffsets[i], cy - bh / 2, 3, bh);
                using (LinearGradientBrush bb = new LinearGradientBrush(
                    new Rectangle(barR.X, barR.Y - 1, 4, barR.Height + 2),
                    Color.FromArgb(255, 225, 165, 255),
                    accentColor,
                    LinearGradientMode.Vertical))
                {
                    FillRoundRect(g, bb, barR, 2);
                }
            }

            using (Font fLeo = new Font("Segoe UI", 13.5f, FontStyle.Bold))
            using (Font fMusic = new Font("Segoe UI", 13.5f, FontStyle.Regular))
            {
                g.DrawString("LEO", fLeo, Brushes.White, x + 32, y - 1);
                g.DrawString("Music", fMusic, Brushes.White, x + 72, y - 1);
            }
        }

        private void DrawSidebarNavIcon(Graphics g, int iconType, float cx, float cy, Color col)
        {
            using (Pen p = new Pen(col, 1.7f))
            using (SolidBrush b = new SolidBrush(col))
            {
                p.StartCap = LineCap.Round;
                p.EndCap = LineCap.Round;
                if (iconType == 0)
                {
                    PointF[] roof = new PointF[] { new PointF(cx - 6.5f, cy - 0.5f), new PointF(cx, cy - 6.5f), new PointF(cx + 6.5f, cy - 0.5f) };
                    g.DrawLines(p, roof);
                    g.DrawRectangle(p, cx - 4.5f, cy - 0.5f, 9f, 6.5f);
                }
                else if (iconType == 1)
                {
                    g.DrawEllipse(p, cx - 6.5f, cy - 6.5f, 13f, 13f);
                    PointF[] needle = new PointF[]
                    {
                        new PointF(cx + 2.8f, cy - 2.8f),
                        new PointF(cx + 1.0f, cy + 1.0f),
                        new PointF(cx - 2.8f, cy + 2.8f),
                        new PointF(cx - 1.0f, cy - 1.0f)
                    };
                    g.DrawPolygon(p, needle);
                }
                else if (iconType == 2)
                {
                    g.DrawRectangle(p, cx - 6.0f, cy - 5.5f, 2.8f, 11f);
                    g.DrawRectangle(p, cx - 1.8f, cy - 5.5f, 2.8f, 11f);
                    g.DrawLine(p, cx + 2.5f, cy - 5.0f, cx + 5.8f, cy + 5.5f);
                    g.DrawLine(p, cx + 4.5f, cy - 5.5f, cx + 7.5f, cy + 5.0f);
                }
                else if (iconType == 3)
                {
                    DrawHeartIcon(g, col, cx, cy - 0.5f, false);
                }
                else if (iconType == 4)
                {
                    g.DrawLine(p, cx - 6.0f, cy - 4.0f, cx + 1.5f, cy - 4.0f);
                    g.DrawLine(p, cx - 6.0f, cy,        cx + 1.5f, cy);
                    g.DrawLine(p, cx - 6.0f, cy + 4.0f, cx - 0.5f, cy + 4.0f);
                    g.FillEllipse(b, cx + 1.5f, cy + 1.5f, 4.2f, 3.6f);
                    g.DrawLine(p, cx + 5.2f, cy + 3.0f, cx + 5.2f, cy - 5.0f);
                    g.DrawLine(p, cx + 5.2f, cy - 5.0f, cx + 7.5f, cy - 3.5f);
                }
                else if (iconType == 5)
                {
                    DrawDownloadArrow(g, col, cx, cy);
                }
                else if (iconType == 6)
                {
                    g.DrawEllipse(p, cx - 3.5f, cy - 3.5f, 7f, 7f);
                    for (int k = 0; k < 8; k++)
                    {
                        double ang = k * Math.PI / 4.0;
                        float x1 = cx + 4.2f * (float)Math.Cos(ang);
                        float y1 = cy + 4.2f * (float)Math.Sin(ang);
                        float x2 = cx + 6.2f * (float)Math.Cos(ang);
                        float y2 = cy + 6.2f * (float)Math.Sin(ang);
                        g.DrawLine(p, x1, y1, x2, y2);
                    }
                }
            }
        }

        private void DrawShuffleVectorIcon(Graphics g, Color col, float cx, float cy)
        {
            using (Pen p = new Pen(col, 1.6f))
            {
                p.StartCap = LineCap.Round;
                p.EndCap = LineCap.Round;
                g.DrawLine(p, cx - 6.5f, cy - 4.0f, cx - 2.0f, cy - 4.0f);
                g.DrawLine(p, cx - 2.0f, cy - 4.0f, cx + 2.5f, cy + 4.0f);
                g.DrawLine(p, cx + 2.5f, cy + 4.0f, cx + 6.5f, cy + 4.0f);

                g.DrawLine(p, cx - 6.5f, cy + 4.0f, cx - 2.0f, cy + 4.0f);
                g.DrawLine(p, cx - 2.0f, cy + 4.0f, cx + 2.5f, cy - 4.0f);
                g.DrawLine(p, cx + 2.5f, cy - 4.0f, cx + 6.5f, cy - 4.0f);

                g.DrawLine(p, cx + 4.2f, cy - 6.2f, cx + 6.8f, cy - 4.0f);
                g.DrawLine(p, cx + 4.2f, cy - 1.8f, cx + 6.8f, cy - 4.0f);
                g.DrawLine(p, cx + 4.2f, cy + 1.8f, cx + 6.8f, cy + 4.0f);
                g.DrawLine(p, cx + 4.2f, cy + 6.2f, cx + 6.8f, cy + 4.0f);
            }
        }

        private void DrawRepeatVectorIcon(Graphics g, Color col, float cx, float cy)
        {
            using (Pen p = new Pen(col, 1.6f))
            {
                p.StartCap = LineCap.Round;
                p.EndCap = LineCap.Round;
                g.DrawArc(p, cx - 6.5f, cy - 4.5f, 13f, 9f, 200f, 145f);
