            }
        }

        private void DrawGlowingNeonPlayButton(Graphics g, Rectangle circleRect, bool playing)
        {
            for (int r = 4; r >= 1; r--)
            {
                int expand = r * 3;
                Rectangle haloR = new Rectangle(circleRect.X - expand, circleRect.Y - expand, circleRect.Width + expand * 2, circleRect.Height + expand * 2);
                using (SolidBrush haloB = new SolidBrush(Color.FromArgb(18 * (5 - r), accentColor.R, accentColor.G, accentColor.B)))
                {
                    g.FillEllipse(haloB, haloR);
                }
            }

            Color cTop = Color.FromArgb(255, Math.Min(255, accentColor.R + 42), Math.Min(255, accentColor.G + 36), Math.Min(255, accentColor.B + 10));
            Color cBot = Color.FromArgb(255, Math.Max(0, accentColor.R - 38), Math.Max(0, accentColor.G - 28), Math.Max(0, accentColor.B - 18));
            using (LinearGradientBrush coreB = new LinearGradientBrush(circleRect, cTop, cBot, LinearGradientMode.Vertical))
            {
                g.FillEllipse(coreB, circleRect);
            }

            using (Pen neonRim = new Pen(Color.FromArgb(225, 235, 200, 255), 1.8f))
            {
                g.DrawEllipse(neonRim, circleRect);
            }

            float cx = circleRect.X + circleRect.Width / 2f;
            float cy = circleRect.Y + circleRect.Height / 2f;
            float scale = circleRect.Width / 44f;
            if (playing)
            {
                DrawPauseBars(g, Brushes.White, cx, cy, 3.6f * scale, 13.5f * scale, 4.2f * scale);
            }
            else
            {
                DrawPlayTriangle(g, Brushes.White, cx + 1.2f * scale, cy, 10.0f * scale);
            }
        }

