        private void PaintShareSongPopupModal(Graphics g, int w, int h, float anim, StringFormat sfCenter, StringFormat sfLeftEllipsis)
        {
            if (currentSong == null) return;
            using (SolidBrush scrim = new SolidBrush(Color.FromArgb((int)(190 * anim), 5, 3, 12)))
            {
                g.FillRectangle(scrim, 0, 0, w, h);
            }

            int mw = 500, mh = 320;
            int mx = (w - mw) / 2;
            int my = (h - mh) / 2;
            Rectangle modal = new Rectangle(mx, my, mw, mh);
            DrawGlassCard(g, modal, 24, bgCard, true, false);

            using (Font fHdr = new Font("Segoe UI", 14f, FontStyle.Bold))
            using (SolidBrush purpB = new SolidBrush(Color.FromArgb(220, 175, 255)))
            {
                g.DrawString("\uD83D\uDD17 Share Song Smart Deep-Link", fHdr, Brushes.White, mx + 24, my + 20);
                g.DrawString("If the recipient has Leo Music installed, clicking opens Leo Music & plays immediately. Otherwise it downloads Leo Music!", fontSubReg, purpB, new RectangleF(mx + 24, my + 50, mw - 48, 36));
            }

            Rectangle songBox = new Rectangle(mx + 24, my + 92, mw - 48, 64);
            DrawGlassCard(g, songBox, 16, bgCard, false, false);
            DrawStaticAlbumArt(g, currentSong.ThumbUrl, new Rectangle(songBox.X + 10, songBox.Y + 8, 48, 48), 10);
            g.DrawString(CleanSongDisplayTitle(currentSong.Title), fontTitleBold, Brushes.White, new RectangleF(songBox.X + 68, songBox.Y + 12, songBox.Width - 80, 22), sfLeftEllipsis);
            g.DrawString(GetPrimaryArtistName(currentSong.Artist) + "  \u2022  leomusic://play?id=" + currentSong.Id, fontSubReg, Brushes.LightGray, new RectangleF(songBox.X + 68, songBox.Y + 34, songBox.Width - 80, 20), sfLeftEllipsis);

            Rectangle linkBox = new Rectangle(mx + 24, my + 168, mw - 48, 36);
            using (SolidBrush lb = new SolidBrush(Color.FromArgb(200, 12, 9, 26)))
            using (Pen lp = new Pen(Color.FromArgb(90, accentColor), 1f))
            {
                FillRoundRect(g, lb, linkBox, 10);
                DrawRoundRect(g, lp, linkBox, 10);
            }
            g.DrawString(lastGeneratedSmartShareUrl, fontSmallBold, new SolidBrush(Color.FromArgb(180, 240, 205)), new RectangleF(linkBox.X + 12, linkBox.Y + 8, linkBox.Width - 24, 20), sfLeftEllipsis);

            int btnY = my + mh - 62;
            Rectangle btnCopy = new Rectangle(mx + 24, btnY, 146, 40);
            Rectangle btnWa   = new Rectangle(mx + 180, btnY, 156, 40);
            Rectangle btnTest = new Rectangle(mx + 346, btnY, 74, 40);
            Rectangle btnClose = new Rectangle(mx + 428, btnY, 48, 40);

            FillRoundRect(g, new SolidBrush(accentColor), btnCopy, 14);
            FillRoundRect(g, new SolidBrush(Color.FromArgb(34, 197, 94)), btnWa, 14);
            DrawGlassCard(g, btnTest, 14, bgCard, false, false);
            DrawGlassCard(g, btnClose, 14, bgCard, false, false);

            g.DrawString("\uD83D\uDCCB Copy Link", fontSmallBold, Brushes.White, btnCopy, sfCenter);
            g.DrawString("\uD83D\uDCAC WhatsApp Share", fontSmallBold, Brushes.White, btnWa, sfCenter);
            g.DrawString("Preview", fontSmallBold, Brushes.White, btnTest, sfCenter);
            g.DrawString("\u2715", fontSmallBold, Brushes.White, btnClose, sfCenter);
        }

        protected override void OnPaint(PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            g.TextRenderingHint = TextRenderingHint.ClearTypeGridFit;

            int w = this.ClientSize.Width;
            int h = this.ClientSize.Height;
            int sidebarW = 198;
            int rightW = Math.Max(0, (int)Math.Round(rightPanelWidthAnim));
            int playerH = 82;
            int mainH = h - playerH;

            Color curBgMain = oledPureBlack ? Color.Black : Color.FromArgb(10, 8, 20);
            Color curBgSide = oledPureBlack ? Color.FromArgb(8, 7, 14) : Color.FromArgb(16, 12, 32);
            Color curBgCard = oledPureBlack ? Color.FromArgb(14, 12, 24) : Color.FromArgb(24, 18, 44);

            using (SolidBrush mainB = new SolidBrush(curBgMain))
            {
                g.FillRectangle(mainB, 0, 0, w, h);
            }

            StringFormat sfCenter = new StringFormat();
            sfCenter.Alignment = StringAlignment.Center;
            sfCenter.LineAlignment = StringAlignment.Center;
            sfCenter.Trimming = StringTrimming.EllipsisCharacter;
            sfCenter.FormatFlags = StringFormatFlags.NoWrap;

            StringFormat sfLeftEllipsis = new StringFormat();
            sfLeftEllipsis.Alignment = StringAlignment.Near;
            sfLeftEllipsis.LineAlignment = StringAlignment.Center;
            sfLeftEllipsis.Trimming = StringTrimming.EllipsisCharacter;
            sfLeftEllipsis.FormatFlags = StringFormatFlags.NoWrap;

            if (isDynamicBarMode)
            {
                PaintFloatingDynamicBarOverlay(g, w, h, sfCenter, sfLeftEllipsis);
                return;
            }

            if (isMiniPlayerMode)
            {
                PaintFloatingMiniPlayer(g, w, h, sfCenter, sfLeftEllipsis);
                return;
            }

            if (fullPlayerAnim < 0.15f)
            {
                if (songBgImageEnabled && activeTab != 0)
                {
                    PaintAtmosphericSongBackdrop(g, w, h, 0.85f);
                }
                PaintLiveMeshAuroraBackdrop(g, w, h);
                PaintSpatialEnvironmentBackdrop(g, w, h);
            }

            if (fullPlayerAnim < 0.15f)
            {
                DrawBrandMusicNoteLogo(g, 24, 20);

                Rectangle sideCardRect = new Rectangle(12, 62, sidebarW - 18, h - 74);
                DrawGlassCard(g, sideCardRect, 22, curBgSide, false, false);

                Region oldSideClip = g.Clip;
                g.SetClip(sideCardRect);
                using (GraphicsPath wavePath = new GraphicsPath())
                {
                    int wy = h - 145;
                    wavePath.AddBezier(
                        new PointF(sideCardRect.X - 10, wy + 70),
                        new PointF(sideCardRect.X + 55, wy + 25),
                        new PointF(sideCardRect.X + 115, wy + 5),
                        new PointF(sideCardRect.Right + 15, wy - 45));
                    for (int wg = 3; wg >= 1; wg--)
                    {
                        using (Pen wp = new Pen(Color.FromArgb(46 * (4 - wg), accentColor.R, accentColor.G, accentColor.B), wg * 5.5f))
                        {
                            g.DrawPath(wp, wavePath);
                        }
                    }
                    using (Pen wc = new Pen(Color.FromArgb(175, 215, 145, 255), 1.8f))
                    {
                        g.DrawPath(wc, wavePath);
                    }
                }
                g.Clip = oldSideClip;

                string[] navLabels = new string[] { "Home", "Explore", "Library", "Playlists", "Downloads", "Favorites" };
                int[] navTabIds    = new int[] { 0, 1, 6, 5, 3, 2 };
                int[] navIcons     = new int[] { 0, 1, 2, 4, 5, 3 };

                for (int i = 0; i < navLabels.Length; i++)
                {
                    int tabId = navTabIds[i];
                    string btnKey = "nav_" + tabId;
                    Rectangle baseNavRect = new Rectangle(20, 82 + i * 44, sidebarW - 34, 38);
                    Rectangle navRect = ScaleRectCentered(baseNavRect, GetButtonScale(btnKey));
                    bool isSel = (activeTab == tabId);
                    bool isHov = (hoveredNavIndex == i);

                    if (isSel)
                    {
                        using (LinearGradientBrush selGrad = new LinearGradientBrush(
                            navRect,
                            Color.FromArgb(240, Math.Min(255, accentColor.R + 20), Math.Min(255, accentColor.G + 15), (int)accentColor.B),
                            Color.FromArgb(215, Math.Max(0, accentColor.R - 45), Math.Max(0, accentColor.G - 35), Math.Max(0, accentColor.B - 20)),
                            LinearGradientMode.Horizontal))
                        {
                            FillRoundRect(g, selGrad, navRect, 14);
                        }
                        using (Pen selRim = new Pen(Color.FromArgb(210, 235, 195, 255), 1.2f))
                        {
                            DrawRoundRect(g, selRim, navRect, 14);
                        }
                        using (Pen botBloom = new Pen(Color.FromArgb(230, 235, 160, 255), 2.2f))
                        {
                            g.DrawLine(botBloom, navRect.X + 16, navRect.Bottom, navRect.Right - 16, navRect.Bottom);
                        }
                    }
                    else if (isHov)
                    {
                        using (SolidBrush b = new SolidBrush(Color.FromArgb(35, 195, 150, 255)))
                        {
                            FillRoundRect(g, b, navRect, 14);
                        }
                    }

                    Color iconCol = isSel ? Color.White : (isHov ? textWhite : Color.FromArgb(205, 200, 220));
                    DrawSidebarNavIcon(g, navIcons[i], navRect.X + 20f, navRect.Y + 19f, iconCol);

                    using (Font fNav = new Font("Segoe UI", 10.0f, isSel ? FontStyle.Bold : FontStyle.Regular))
                    using (SolidBrush tb = new SolidBrush(iconCol))
                    {
                        g.DrawString(navLabels[i], fNav, tb, navRect.X + 42, navRect.Y + 9);
                    }
                }

                int divY = 356;
                using (Pen divPen = new Pen(Color.FromArgb(35, 200, 175, 255), 1f))
                {
                    g.DrawLine(divPen, 24, divY, sidebarW - 20, divY);
                }

                Rectangle newPlBtnRect = new Rectangle(20, divY + 14, sidebarW - 34, 36);
                Rectangle plusBoxRect = new Rectangle(newPlBtnRect.X + 8, newPlBtnRect.Y + 6, 24, 24);
                using (SolidBrush pb = new SolidBrush(Color.FromArgb(55, accentColor.R, accentColor.G, accentColor.B)))
                using (Pen pp = new Pen(Color.FromArgb(120, accentColor.R, accentColor.G, accentColor.B), 1f))
                {
                    FillRoundRect(g, pb, plusBoxRect, 7);
                    DrawRoundRect(g, pp, plusBoxRect, 7);
                }
                using (Font fPlus = new Font("Segoe UI", 11f, FontStyle.Bold))
                using (Font fNewPl = new Font("Segoe UI", 9.8f, FontStyle.Regular))
                using (SolidBrush nb = new SolidBrush(Color.FromArgb(220, 215, 235)))
                {
                    g.DrawString("+", fPlus, Brushes.White, plusBoxRect, sfCenter);
                    g.DrawString("New Playlist", fNewPl, nb, newPlBtnRect.X + 42, newPlBtnRect.Y + 8);
                }

                int bottomSettingsY = h - 62;
                Rectangle settingsNavRect = new Rectangle(20, bottomSettingsY, sidebarW - 34, 38);
                bool isSetSel = (activeTab == 4);
                if (isSetSel)
                {
                    using (LinearGradientBrush setGrad = new LinearGradientBrush(
                        settingsNavRect,
                        Color.FromArgb(240, Math.Min(255, accentColor.R + 20), Math.Min(255, accentColor.G + 15), (int)accentColor.B),
                        Color.FromArgb(215, Math.Max(0, accentColor.R - 45), Math.Max(0, accentColor.G - 35), Math.Max(0, accentColor.B - 20)),
                        LinearGradientMode.Horizontal))
                    {
                        FillRoundRect(g, setGrad, settingsNavRect, 14);
                    }
                    using (Pen setRim = new Pen(Color.FromArgb(210, 235, 195, 255), 1.2f))
                    {
                        DrawRoundRect(g, setRim, settingsNavRect, 14);
                    }
                }
                Color setCol = isSetSel ? Color.White : Color.FromArgb(205, 200, 220);
                DrawSidebarNavIcon(g, 6, settingsNavRect.X + 20f, settingsNavRect.Y + 19f, setCol);
                using (Font fSet = new Font("Segoe UI", 10.0f, isSetSel ? FontStyle.Bold : FontStyle.Regular))
                using (SolidBrush stb = new SolidBrush(setCol))
                {
                    g.DrawString("Settings", fSet, stb, settingsNavRect.X + 42, settingsNavRect.Y + 9);
                }

                int centerX = sidebarW;
                int centerW = Math.Max(320, w - sidebarW - rightW);
                float tabSpring = (uiAnimStyleIdx == 0) ? (float)(Math.Sin((1.0f - tabFadeAnim) * Math.PI * 1.5f) * 12f) : ((1.0f - tabFadeAnim) * 10f);
                int slideOffsetY = (int)tabSpring;

                GraphicsState centerState = g.Save();
                g.TranslateTransform(0, slideOffsetY);
                if (activeTab == 4)
                {
                    PaintSettingsAndEqualizerScreen(g, centerX, w - sidebarW, h, curBgCard, sfCenter, sfLeftEllipsis);
                }
                else if (activeTab == 5)
                {
                    PaintPlaylistsStudioScreen(g, centerX, centerW, mainH, curBgCard, sfCenter, sfLeftEllipsis);
                }
                else
                {
                    PaintCenterSongStage(g, centerX, centerW, mainH, curBgCard, sfCenter, sfLeftEllipsis);
                }
                g.Restore(centerState);

                if (rightW > 24 && activeTab != 4)
                {
                    int rightX = w - rightW;
                    Region prevClipR = g.Clip;
                    g.SetClip(new Rectangle(rightX, 60, rightW, mainH - 60));
                    PaintRightDockedPanel(g, rightX, 315, mainH, curBgSide, curBgCard, sfCenter, sfLeftEllipsis);
                    g.Clip = prevClipR;
                }

                if (activeTab != 4)
                {
                    PaintBottomPlayerBar(g, w, h, playerH, sfCenter, sfLeftEllipsis);
                }
            }

            if (fullPlayerAnim > 0.01f && currentSong != null)
            {
                GraphicsState fullState = g.Save();
                float slideY = (1.0f - fullPlayerAnim) * (h * 0.14f);
                g.TranslateTransform(0, slideY);
                PaintFullNowPlayingPanel(g, w, h, fullPlayerAnim, sfCenter, sfLeftEllipsis);
                g.Restore(fullState);
            }

            if (volumeControllerPopupAnim > 0.01f)
            {
                PaintStudioVolumeControllerPopup(g, w, h, volumeControllerPopupAnim, sfCenter, sfLeftEllipsis);
            }

            if (backendHubPopupAnim > 0.01f)
            {
                PaintBackendAndLyricsSyncHubPopup(g, w, h, backendHubPopupAnim, sfCenter, sfLeftEllipsis);
            }

            if (universalDotMenuAnim > 0.01f)
            {
                PaintUniversalThreeDotPopupMenu(g, w, h, universalDotMenuAnim, sfCenter, sfLeftEllipsis);
            }
            if (shareModalAnim > 0.01f)
            {
                PaintShareSongPopupModal(g, w, h, shareModalAnim, sfCenter, sfLeftEllipsis);
            }

            using (Pen winPen = new Pen(Color.FromArgb(200, 225, 220, 240), 1.5f))
            {
                g.DrawLine(winPen, w - 94, 26, w - 84, 26);
                g.DrawRectangle(winPen, w - 62, 20, 10, 10);
                g.DrawLine(winPen, w - 32, 20, w - 22, 30);
                g.DrawLine(winPen, w - 22, 20, w - 32, 30);
            }

            if (updatePopupAnim > 0.01f)
            {
                PaintUpdatePopupModal(g, w, h, updatePopupAnim, sfCenter, sfLeftEllipsis);
            }

            if (languageSetupAnim > 0.01f)
            {
                PaintLanguageSetupScreen(g, w, h, languageSetupAnim, sfCenter, sfLeftEllipsis);
            }

            if (clickRippleAnim > 0.01f && !clickRipplePt.IsEmpty)
            {
                float rpProg = 1.0f - clickRippleAnim;
                int rpRad = 6 + (int)(rpProg * 34f);
                int rpAlpha = (int)(clickRippleAnim * 165f);
                using (Pen rpPen = new Pen(Color.FromArgb(Math.Max(0, Math.Min(255, rpAlpha)), accentColor.R, accentColor.G, accentColor.B), 2.0f))
                {
                    g.DrawEllipse(rpPen, clickRipplePt.X - rpRad, clickRipplePt.Y - rpRad, rpRad * 2, rpRad * 2);
                }
            }

            if (statusTick > 0 && !string.IsNullOrEmpty(statusMessage))
            {
                int midX = w / 2;
                Rectangle toastRect = new Rectangle(midX - 210, h - playerH - 46, 420, 34);
                using (SolidBrush tb = new SolidBrush(Color.FromArgb(240, 20, 14, 38)))
                using (Pen tp = new Pen(accentColor, 1.5f))
                {
                    FillRoundRect(g, tb, toastRect, 17);
                    DrawRoundRect(g, tp, toastRect, 17);
                }
                using (Font fToast = new Font("Segoe UI", 9.2f, FontStyle.Bold))
                {
                    g.DrawString(statusMessage, fToast, Brushes.White, toastRect, sfCenter);
                }
            }
        }

        private void PaintFloatingDynamicBarOverlay(Graphics g, int w, int h, StringFormat sfCenter, StringFormat sfLeftEllipsis)
        {
            int cornerR = isDynamicBarExpanded ? 22 : (h / 2 - 1);

            if (dynamicBarStyleIdx == 0)
            {
                using (SolidBrush blkB = new SolidBrush(Color.FromArgb(255, 6, 7, 11)))
                {
                    g.FillRectangle(blkB, 0, 0, w, h);
                }
                using (Pen subRim = new Pen(Color.FromArgb(52, 255, 255, 255), 1.0f))
                {
                    DrawRoundRect(g, subRim, new Rectangle(1, 1, w - 3, h - 3), cornerR);
                }
            }
            else
            {
                Color cTop = Color.FromArgb(255, (int)Math.Min(255, ambR * 0.42f + 8), (int)Math.Min(255, ambG * 0.40f + 10), (int)Math.Min(255, ambB * 0.45f + 16));
                Color cBot = Color.FromArgb(255, 6, 8, 14);
                using (LinearGradientBrush bg = new LinearGradientBrush(new Rectangle(0, 0, w, h), cTop, cBot, LinearGradientMode.Horizontal))
                {
                    g.FillRectangle(bg, 0, 0, w, h);
                }
                PaintLiveMeshAuroraBackdrop(g, w, h);
                using (Pen meshRim = new Pen(Color.FromArgb(85, accentColor), 1.0f))
                {
                    DrawRoundRect(g, meshRim, new Rectangle(1, 1, w - 3, h - 3), cornerR);
                }
            }

            if (!isDynamicBarExpanded)
            {
                int cy = h / 2;
                Rectangle logoCircle = new Rectangle(7, cy - 11, 22, 22);
                using (SolidBrush lb = new SolidBrush(Color.FromArgb(38, accentColor.R, accentColor.G, accentColor.B)))
                using (Pen lp = new Pen(Color.FromArgb(180, accentColor), 1.2f))
                {
                    g.FillEllipse(lb, logoCircle);
                    g.DrawEllipse(lp, logoCircle);
                }
                using (SolidBrush barB = new SolidBrush(accentColor))
                {
                    g.FillRectangle(barB, logoCircle.X + 5.5f, logoCircle.Y + 8f, 2.0f, 6f);
                    g.FillRectangle(barB, logoCircle.X + 10.0f, logoCircle.Y + 5f, 2.0f, 12f);
                    g.FillRectangle(barB, logoCircle.X + 14.5f, logoCircle.Y + 7f, 2.0f, 8f);
                }

                string titleStr = currentSong != null
                    ? (FormatMinimalCardTitle(currentSong.Title) + " \u2022 " + GetPrimaryArtistName(currentSong.Artist))
                    : "Leo Music Studio";
                using (SolidBrush wb = new SolidBrush(Color.FromArgb(245, 255, 255, 255)))
                {
                    g.DrawString(titleStr, fontSmallBold, wb, new RectangleF(35, cy - 9, w - 76, 18), sfLeftEllipsis);
                }

                DrawEqResponsiveVisualizer(g, w - 34, cy + 6, 4, 5, 2.2f, 7.5f);

                float fracC = (float)Math.Max(0.0, Math.Min(1.0, smoothPosSec / Math.Max(1.0, currentDurSec)));
                int progW = (int)((w - 40) * fracC);
                if (progW > 2)
                {
                    using (Pen pp = new Pen(Color.FromArgb(150, accentColor), 1.5f))
                    {
                        g.DrawLine(pp, 20, h - 2, 20 + progW, h - 2);
                    }
                }
                return;
            }

            if (currentSong != null)
            {
                Rectangle podArt = new Rectangle(12, 12, 46, 46);
                DrawAnimatedStudioArtwork(g, currentSong.ThumbUrl, podArt, artworkShapeMode);

                int tx = 66;
                int tw = w - tx - 146;
                using (SolidBrush wb = new SolidBrush(Color.White))
                using (SolidBrush sb = new SolidBrush(textSub))
                {
                    g.DrawString(FormatMinimalCardTitle(currentSong.Title), fontSmallBold, wb, new RectangleF(tx, 12, tw, 18), sfLeftEllipsis);
                    g.DrawString(GetPrimaryArtistName(currentSong.Artist), fontSubReg, sb, new RectangleF(tx, 30, tw, 16), sfLeftEllipsis);
                }
            }

            Rectangle btnFull  = new Rectangle(w - 44, 10, 36, 20);
            Rectangle btnMini  = new Rectangle(btnFull.X - 38, 10, 35, 20);
            Rectangle btnStyle = new Rectangle(btnMini.X - 44, 10, 41, 20);
            Rectangle btnComp  = new Rectangle(btnStyle.X - 26, 10, 23, 20);

            using (SolidBrush pb = new SolidBrush(Color.FromArgb(65, 255, 255, 255)))
            using (SolidBrush db = new SolidBrush(Color.FromArgb(40, 255, 255, 255)))
            {
                FillRoundRect(g, db, btnComp, 8);
                FillRoundRect(g, db, btnStyle, 8);
                FillRoundRect(g, db, btnMini, 8);
                FillRoundRect(g, pb, btnFull, 8);
            }
            g.DrawString("\u25B4", fontSmallBold, Brushes.White, btnComp, sfCenter);
            g.DrawString(dynamicBarStyleIdx == 0 ? "Black" : "Mesh", fontSmallBold, Brushes.White, btnStyle, sfCenter);
            g.DrawString("Mini", fontSmallBold, Brushes.White, btnMini, sfCenter);
            g.DrawString("Full", fontSmallBold, Brushes.Black, btnFull, sfCenter);

            int cyPod = 74;
            Rectangle prevR = new Rectangle(14, cyPod - 11, 22, 22);
            Rectangle playR = new Rectangle(40, cyPod - 13, 26, 26);
            Rectangle nextR = new Rectangle(70, cyPod - 11, 22, 22);

            using (SolidBrush cb = new SolidBrush(Color.FromArgb(55, 255, 255, 255)))
            using (SolidBrush ab = new SolidBrush(accentColor))
            {
                g.FillEllipse(cb, prevR);
                g.FillEllipse(ab, playR);
                g.FillEllipse(cb, nextR);
            }
            DrawSkipPrevIcon(g, Brushes.White, prevR.X + 11f, cyPod);
            if (isPlaying) DrawPauseBars(g, Brushes.Black, playR.X + 13f, cyPod, 3.0f, 9.5f, 3.2f);
            else DrawPlayTriangle(g, Brushes.Black, playR.X + 13f, cyPod, 7.0f);
            DrawSkipNextIcon(g, Brushes.White, nextR.X + 11f, cyPod);

            int barX = 104;
            int barW = w - barX - 46;
            int barY = cyPod;
            float frac = (float)Math.Max(0.0, Math.Min(1.0, smoothPosSec / Math.Max(1.0, currentDurSec)));
            int actX = barX + (int)(barW * frac);
            using (Pen ip = new Pen(Color.FromArgb(55, 255, 255, 255), 2.8f))
            using (Pen ap = new Pen(accentColor, 3.0f))
            {
                g.DrawLine(ip, barX, barY, barX + barW, barY);
                if (actX > barX + 2) g.DrawLine(ap, barX, barY, actX, barY);
            }
            g.FillEllipse(Brushes.White, actX - 3.5f, barY - 3.5f, 7f, 7f);
            using (SolidBrush tb = new SolidBrush(textSub))
            {
                g.DrawString(FormatSec((int)currentPosSec), fontSmallBold, tb, w - 38, barY - 7);
            }
        }

        private void PaintFloatingMiniPlayer(Graphics g, int w, int h, StringFormat sfCenter, StringFormat sfLeftEllipsis)
        {
            Color cTop = Color.FromArgb(255, (int)Math.Min(255, ambR * 0.55f + 14), (int)Math.Min(255, ambG * 0.52f + 16), (int)Math.Min(255, ambB * 0.58f + 24));
            Color cBot = Color.FromArgb(255, 10, 13, 22);
            using (LinearGradientBrush bg = new LinearGradientBrush(new Rectangle(0, 0, w, h), cTop, cBot, LinearGradientMode.ForwardDiagonal))
            {
                g.FillRectangle(bg, 0, 0, w, h);
            }

            PaintLiveMeshAuroraBackdrop(g, w, h);

            if (miniPlayerStyleIdx == 3)
            {
                using (Pen rimPen = new Pen(Color.FromArgb(190, accentColor), 2.5f))
                {
                    g.DrawEllipse(rimPen, 2, 2, w - 5, h - 5);
                }

                if (currentSong != null)
                {
                    Rectangle orbArt = new Rectangle((w - 116) / 2, 18, 116, 116);
                    DrawAnimatedStudioArtwork(g, currentSong.ThumbUrl, orbArt, artworkShapeMode);

                    using (SolidBrush wb = new SolidBrush(Color.White))
                    using (SolidBrush sb = new SolidBrush(textSub))
                    {
                        g.DrawString(FormatMinimalCardTitle(currentSong.Title), fontSmallBold, wb, new RectangleF(24, 140, w - 48, 18), sfCenter);
                        g.DrawString(GetPrimaryArtistName(currentSong.Artist), fontSubReg, sb, new RectangleF(28, 157, w - 56, 16), sfCenter);
                    }
                }

                int cyOrb = 194;
                int midOrb = w / 2;
                Rectangle prevOrb = new Rectangle(midOrb - 54, cyOrb - 13, 26, 26);
                Rectangle playOrb = new Rectangle(midOrb - 16, cyOrb - 16, 32, 32);
                Rectangle nextOrb = new Rectangle(midOrb + 28, cyOrb - 13, 26, 26);
                using (SolidBrush cb = new SolidBrush(Color.FromArgb(95, 0, 0, 0)))
                using (SolidBrush ab = new SolidBrush(accentColor))
                {
                    g.FillEllipse(cb, prevOrb);
                    g.FillEllipse(ab, playOrb);
                    g.FillEllipse(cb, nextOrb);
                }
                DrawSkipPrevIcon(g, Brushes.White, prevOrb.X + 13f, cyOrb);
                if (isPlaying) DrawPauseBars(g, Brushes.Black, playOrb.X + 16f, cyOrb, 3.5f, 11f, 3.8f);
                else DrawPlayTriangle(g, Brushes.Black, playOrb.X + 16f, cyOrb, 8.5f);
                DrawSkipNextIcon(g, Brushes.White, nextOrb.X + 13f, cyOrb);

                Rectangle shapeOrbBtn = new Rectangle(midOrb - 68, 220, 62, 22);
                Rectangle fullOrbBtn = new Rectangle(midOrb + 6, 220, 62, 22);
                DrawGlassCard(g, shapeOrbBtn, 11, bgCard, false, false);
                DrawGlassCard(g, fullOrbBtn, 11, bgCard, true, false);
                g.DrawString("Shape", fontSmallBold, Brushes.White, shapeOrbBtn, sfCenter);
                g.DrawString("Full UI", fontSmallBold, Brushes.White, fullOrbBtn, sfCenter);
                return;
            }

            int cornerRad = (miniPlayerStyleIdx == 1) ? (h / 2 - 2) : ((miniPlayerStyleIdx == 2) ? 10 : 28);
            DrawGlassCard(g, new Rectangle(1, 1, w - 3, h - 3), cornerRad, bgCard, false, false);

            int artLeft = (miniPlayerStyleIdx == 1) ? 22 : 14;
            if (currentSong != null)
            {
                Rectangle miniArt = new Rectangle(artLeft, (h - 90) / 2 - 6, 88, 88);
                DrawAnimatedStudioArtwork(g, currentSong.ThumbUrl, miniArt, artworkShapeMode);

                int textLeft = miniArt.Right + 12;
                int textW = w - textLeft - 154;
                using (SolidBrush wb = new SolidBrush(Color.White))
                using (SolidBrush sb = new SolidBrush(Color.FromArgb(215, 235, 240, 248)))
                {
                    g.DrawString(FormatMinimalCardTitle(currentSong.Title), fontTitleBold, wb, new RectangleF(textLeft, 14, textW, 22), sfLeftEllipsis);
                    g.DrawString(GetPrimaryArtistName(currentSong.Artist), fontSubReg, sb, new RectangleF(textLeft, 35, textW, 18), sfLeftEllipsis);
                }

                EnsureSyncedLyricsParsed(currentSong);
                string activeLyricText = "\u266A " + currentSong.Title;
                double syncClock = Math.Max(0.0, smoothPosSec + lyricSyncOffsetSec);
                if (currentSong.SyncedLines != null)
                {
                    for (int i = 0; i < currentSong.SyncedLines.Count; i++)
                    {
                        if (syncClock >= currentSong.SyncedLines[i].StartSec)
                        {
                            activeLyricText = "\u266A " + currentSong.SyncedLines[i].Text;
                        }
                    }
                }
                using (SolidBrush lyrB = new SolidBrush(accentColor))
                {
                    g.DrawString(activeLyricText, fontSmallBold, lyrB, new RectangleF(textLeft, 56, w - textLeft - 24, 20), sfLeftEllipsis);
                }
            }

            int rightMargin = (miniPlayerStyleIdx == 1) ? 24 : 14;
            Rectangle expandDesktopBtn = new Rectangle(w - rightMargin - 64, 12, 64, 24);
            Rectangle miniShapeBtn = new Rectangle(expandDesktopBtn.X - 66, 12, 62, 24);
            Rectangle miniDynBarBtn = new Rectangle(miniShapeBtn.X - 66, 12, 62, 24);
            DrawGlassCard(g, miniDynBarBtn, 12, bgCard, false, false);
            DrawGlassCard(g, miniShapeBtn, 12, bgCard, false, false);
            DrawGlassCard(g, expandDesktopBtn, 12, bgCard, true, false);
            g.DrawString("Dyn Bar", fontSmallBold, Brushes.White, miniDynBarBtn, sfCenter);
            g.DrawString(miniPlayerStyleNames[miniPlayerStyleIdx], fontSmallBold, Brushes.White, miniShapeBtn, sfCenter);
            g.DrawString("\u2922 Full UI", fontSmallBold, Brushes.White, expandDesktopBtn, sfCenter);

            int tLeft = artLeft + 100;
            int cy = 96;
            Rectangle prevR = new Rectangle(tLeft, cy - 13, 26, 26);
            Rectangle playR = new Rectangle(tLeft + 34, cy - 16, 32, 32);
            Rectangle nextR = new Rectangle(tLeft + 74, cy - 13, 26, 26);
            Rectangle speedR = new Rectangle(tLeft + 112, cy - 12, 92, 24);

            using (SolidBrush cb = new SolidBrush(Color.FromArgb(75, 0, 0, 0)))
            using (SolidBrush ab = new SolidBrush(accentColor))
            {
                g.FillEllipse(cb, prevR);
                g.FillEllipse(ab, playR);
                g.FillEllipse(cb, nextR);
                FillRoundRect(g, cb, speedR, 12);
            }
            DrawSkipPrevIcon(g, Brushes.White, prevR.X + 13f, cy);
            if (isPlaying) DrawPauseBars(g, Brushes.Black, playR.X + 16f, cy, 3.5f, 11f, 3.8f);
            else DrawPlayTriangle(g, Brushes.Black, playR.X + 16f, cy, 8.5f);
            DrawSkipNextIcon(g, Brushes.White, nextR.X + 13f, cy);

            using (SolidBrush spTxt = new SolidBrush(playbackSpeedIdx == 0 ? textSub : accentColor))
            {
                g.DrawString(playbackSpeedNames[playbackSpeedIdx], fontSmallBold, spTxt, speedR, sfCenter);
            }

            int barX = (miniPlayerStyleIdx == 1) ? 42 : 20;
            int barW = w - barX * 2;
            int barY = h - 18;
            float frac = (float)Math.Max(0.0, Math.Min(1.0, smoothPosSec / Math.Max(1.0, currentDurSec)));
            int actX = barX + (int)(barW * frac);
            using (Pen ip = new Pen(Color.FromArgb(60, 255, 255, 255), 3f))
            using (Pen ap = new Pen(accentColor, 3.2f))
            {
                g.DrawLine(ip, barX, barY, barX + barW, barY);
                if (actX > barX + 2) g.DrawLine(ap, barX, barY, actX, barY);
            }
            g.FillEllipse(Brushes.White, actX - 4, barY - 4, 8, 8);
        }

        private void DrawPadlockIcon(Graphics g, Color col, float cx, float cy, bool unlocked)
        {
            using (Pen p = new Pen(col, 1.6f))
            using (SolidBrush b = new SolidBrush(col))
            {
                RectangleF body = new RectangleF(cx - 5f, cy - 1f, 10f, 8f);
                g.FillRectangle(b, body);
                if (unlocked)
                {
                    g.DrawArc(p, cx - 3.5f, cy - 6.5f, 7f, 6f, 180f, 130f);
                }
                else
                {
                    g.DrawArc(p, cx - 3.5f, cy - 6.5f, 7f, 7f, 180f, 180f);
                }
            }
        }

        private void PaintLanguageSetupScreen(Graphics g, int w, int h, float anim, StringFormat sfCenter, StringFormat sfLeftEllipsis)
        {
            int bgAlpha = (int)(anim * 248);
            using (SolidBrush bgB = new SolidBrush(Color.FromArgb(bgAlpha, 8, 10, 16)))
            {
                g.FillRectangle(bgB, 0, 0, w, h);
            }

            int mw = Math.Min(820, w - 64);
            int mh = Math.Min(560, h - 64);
            int mx = (w - mw) / 2;
            int my = (h - mh) / 2;
            Rectangle modalBox = new Rectangle(mx, my, mw, mh);

            using (SolidBrush mb = new SolidBrush(Color.FromArgb(245, 16, 20, 30)))
            using (Pen mp = new Pen(Color.FromArgb(160, accentColor), 1.8f))
            {
                FillRoundRect(g, mb, modalBox, 22);
                DrawRoundRect(g, mp, modalBox, 22);
            }

            Rectangle badgeRect = new Rectangle(mx + (mw - 220) / 2, my + 24, 220, 26);
            using (SolidBrush bb = new SolidBrush(Color.FromArgb(40, accentColor.R, accentColor.G, accentColor.B)))
            {
                FillRoundRect(g, bb, badgeRect, 13);
            }
            using (SolidBrush bt = new SolidBrush(accentColor))
            {
                g.DrawString("\u2605 PERSONALIZE YOUR MUSIC", fontSmallBold, bt, badgeRect, sfCenter);
            }

            using (Font fLangTitle = new Font("Segoe UI", 15f, FontStyle.Bold))
            {
                g.DrawString("Welcome! Choose Your Name, Country & Music Languages", fLangTitle, Brushes.White,
                    new RectangleF(mx + 20, my + 52, mw - 40, 28), sfCenter);
            }

            // Row 1: User Name Pill + Upload Photo from PC Button + Active Country Badge (`my + 84`)
            Rectangle nameEditPill = new Rectangle(mx + 24, my + 84, 240, 32);
            using (SolidBrush nb = new SolidBrush(Color.FromArgb(32, 38, 56)))
            using (Pen np = new Pen(accentColor, 1.3f))
            {
                FillRoundRect(g, nb, nameEditPill, 10);
                DrawRoundRect(g, np, nameEditPill, 10);
            }
            if (!isEditingUserName)
            {
                g.DrawString("\u2605 Name: " + userName + "  \u270E", fontSmallBold, Brushes.White, nameEditPill, sfCenter);
            }

            Rectangle welcomePhotoBtn = new Rectangle(mx + 272, my + 84, 132, 32);
            using (SolidBrush pb = new SolidBrush(Color.FromArgb(42, 0, 242, 254)))
            using (Pen pp = new Pen(Color.FromArgb(120, 0, 242, 254), 1f))
            {
                FillRoundRect(g, pb, welcomePhotoBtn, 10);
                DrawRoundRect(g, pp, welcomePhotoBtn, 10);
            }
            g.DrawString("+ Profile Photo (PC)", fontSmallBold, Brushes.White, welcomePhotoBtn, sfCenter);

            using (SolidBrush cb = new SolidBrush(Color.FromArgb(180, 16, 185, 129)))
            {
                g.DrawString("\u25C9 Country: " + selectedCountry + " (Filters Homepage & Queue)",
                    fontSmallBold, cb, new RectangleF(mx + 414, my + 90, mw - 434, 22), sfLeftEllipsis);
            }

            // Row 2: 14 Country Selector Chips (`2 rows of 7 at my + 124`)
            int cCols = 7;
            int cGap = 8;
            int cW = (mw - 48 - (cCols - 1) * cGap) / cCols;
            int cH = 30;
            for (int i = 0; i < availableCountries.Length; i++)
            {
                int r = i / cCols;
                int c = i % cCols;
                Rectangle cr = new Rectangle(mx + 24 + c * (cW + cGap), my + 124 + r * (cH + 6), cW, cH);
                bool isCountrySel = string.Equals(selectedCountry, availableCountries[i], StringComparison.OrdinalIgnoreCase);
                using (SolidBrush b = new SolidBrush(isCountrySel ? accentColor : Color.FromArgb(24, 28, 42)))
                using (Pen p = new Pen(isCountrySel ? Color.White : Color.FromArgb(50, 60, 82), isCountrySel ? 1.5f : 1f))
                {
                    FillRoundRect(g, b, cr, 8);
                    DrawRoundRect(g, p, cr, 8);
                }
                g.DrawString(availableCountries[i], fontSmallBold, isCountrySel ? Brushes.White : Brushes.LightGray, cr, sfCenter);
            }

            int gridTop = my + 202;
            int cols = 7;
            int cardGap = 10;
            int cardW = (mw - 48 - (cols - 1) * cardGap) / cols;
            int cardH = 68;

            for (int i = 0; i < availableLanguages.Count; i++)
            {
                int r = i / cols;
                int c = i % cols;
                int cx = mx + 24 + c * (cardW + cardGap);
                int cy = gridTop + r * (cardH + 12);

                MusicLanguageItem item = availableLanguages[i];
                bool isSel = userSelectedLanguages.Contains(item.Name);
                Rectangle cardRect = new Rectangle(cx, cy, cardW, cardH);

                using (SolidBrush cb = new SolidBrush(isSel ? Color.FromArgb(45, accentColor.R, accentColor.G, accentColor.B) : Color.FromArgb(24, 28, 42)))
                {
                    FillRoundRect(g, cb, cardRect, 12);
                }
                using (Pen cp = new Pen(isSel ? accentColor : Color.FromArgb(45, 50, 70), isSel ? 1.8f : 1f))
                {
                    DrawRoundRect(g, cp, cardRect, 12);
                }

                if (isSel)
                {
                    Rectangle chkDot = new Rectangle(cardRect.Right - 20, cardRect.Y + 6, 14, 14);
                    using (SolidBrush chkB = new SolidBrush(accentColor))
                    {
                        g.FillEllipse(chkB, chkDot);
                    }
                    g.DrawString("\u2713", fontSmallBold, Brushes.Black, chkDot, sfCenter);
                }

                using (Font fLangName = new Font("Segoe UI", 10.5f, FontStyle.Bold))
                using (Font fNative = new Font("Segoe UI", 9f, FontStyle.Regular))
                using (SolidBrush wb = new SolidBrush(isSel ? accentColor : textWhite))
                using (SolidBrush nb = new SolidBrush(isSel ? textWhite : textSub))
                {
                    g.DrawString(item.Name, fLangName, wb, new RectangleF(cardRect.X + 6, cardRect.Y + 12, cardRect.Width - 12, 22), sfCenter);
                    g.DrawString(item.NativeScript, fNative, nb, new RectangleF(cardRect.X + 6, cardRect.Y + 36, cardRect.Width - 12, 20), sfCenter);
                }
            }

            int bottomY = my + mh - 72;
            int selCount = userSelectedLanguages.Count;
            string selSummary = (selCount == 0)
                ? "Please select at least 1 language to continue."
                : (selCount + " Language" + (selCount > 1 ? "s" : "") + " Selected: " + string.Join(", ", new List<string>(userSelectedLanguages).ToArray()));

            using (SolidBrush sumB = new SolidBrush(selCount == 0 ? Color.FromArgb(255, 120, 120) : accentColor))
            {
                g.DrawString(selSummary, fontSmallBold, sumB, new RectangleF(mx + 30, bottomY - 26, mw - 60, 20), sfCenter);
            }

            int btnW = Math.Min(320, mw - 80);
            langContinueBtnRect = new Rectangle(mx + (mw - btnW) / 2, bottomY, btnW, 44);
            using (SolidBrush cbb = new SolidBrush(selCount > 0 ? accentColor : Color.FromArgb(40, 45, 60)))
            {
                FillRoundRect(g, cbb, langContinueBtnRect, 14);
            }
            string btnLabel = selCount > 0
                ? ("Continue to Leo Music (" + selCount + " Selected) \u2192")
                : "Select at least 1 language";
            using (SolidBrush cbt = new SolidBrush(selCount > 0 ? Color.Black : textMuted))
            {
                g.DrawString(btnLabel, fontTitleBold, cbt, langContinueBtnRect, sfCenter);
            }
        }

        private void PaintUpdatePopupModal(Graphics g, int w, int h, float anim, StringFormat sfCenter, StringFormat sfLeftEllipsis)
        {
            int scrimAlpha = (int)(anim * 195);
            using (SolidBrush scrim = new SolidBrush(Color.FromArgb(scrimAlpha, 5, 3, 12)))
            {
                g.FillRectangle(scrim, 0, 0, w, h);
            }

            int mw = (int)(520 * (0.90f + 0.10f * anim));
            int mh = (int)(360 * (0.90f + 0.10f * anim));
            int mx = (w - mw) / 2;
            int my = (h - mh) / 2;
            Rectangle modalRect = new Rectangle(mx, my, mw, mh);

            DrawGlassCard(g, modalRect, 24, Color.FromArgb(24, 16, 46), true, false);

            bool hasNewer = IsRemoteVersionNewer(latestRemoteVersion, CURRENT_APP_VERSION);
            Rectangle badgeRect = new Rectangle(mx + 24, my + 20, 215, 26);
            using (SolidBrush bb = new SolidBrush(hasNewer ? Color.FromArgb(75, 155, 81, 245) : Color.FromArgb(55, 34, 197, 94)))
            using (Pen bp = new Pen(hasNewer ? accentColor : Color.FromArgb(34, 197, 94), 1.2f))
            {
                FillRoundRect(g, bb, badgeRect, 13);
                DrawRoundRect(g, bp, badgeRect, 13);
            }
            using (SolidBrush bt = new SolidBrush(hasNewer ? Color.FromArgb(225, 185, 255) : Color.FromArgb(110, 245, 160)))
            {
                string statusTxt = hasNewer ? ("\u26A1 UPDATE AVAILABLE: v" + latestRemoteVersion) : ("\u2713 UP TO DATE (v" + CURRENT_APP_VERSION + ")");
                g.DrawString(statusTxt, fontSmallBold, bt, badgeRect, sfCenter);
            }

            using (SolidBrush verB = new SolidBrush(Color.FromArgb(200, 195, 220)))
            {
                g.DrawString("Current: v" + CURRENT_APP_VERSION + "  \u2022  Remote: v" + latestRemoteVersion, fontSmallBold, verB, mx + 252, my + 25);
            }

            using (Font fModalTitle = new Font("Segoe UI", 13.5f, FontStyle.Bold))
            {
                g.DrawString(latestUpdateTitle, fModalTitle, Brushes.White, new RectangleF(mx + 24, my + 56, mw - 48, 28), sfLeftEllipsis);
            }

            Rectangle notesBox = new Rectangle(mx + 24, my + 90, mw - 48, 138);
            using (SolidBrush nb = new SolidBrush(Color.FromArgb(210, 12, 9, 26)))
            using (Pen np = new Pen(Color.FromArgb(65, 185, 135, 255), 1f))
            {
                FillRoundRect(g, nb, notesBox, 14);
                DrawRoundRect(g, np, notesBox, 14);
            }

            using (SolidBrush ab = new SolidBrush(Color.FromArgb(215, 165, 255)))
            {
                g.DrawString("WHAT'S NEW IN LEO MUSIC v" + latestRemoteVersion + ":", fontSmallBold, ab, notesBox.X + 14, notesBox.Y + 10);
            }

            string[] noteLines = (latestUpdateNotes ?? "").Split(new char[] { '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries);
            int ny = notesBox.Y + 32;
            using (SolidBrush ntb = new SolidBrush(Color.FromArgb(235, 232, 248)))
            {
                for (int i = 0; i < noteLines.Length; i++)
                {
                    if (ny + 18 > notesBox.Bottom - 6) break;
                    g.DrawString(noteLines[i], fontSubReg, ntb, new RectangleF(notesBox.X + 14, ny, notesBox.Width - 28, 20), sfLeftEllipsis);
                    ny += 23;
                }
            }

            using (SolidBrush hintB = new SolidBrush(Color.FromArgb(80, 235, 155)))
            {
                string modeDesc = autoCheckUpdatesEnabled
                    ? "\u2713 Background Auto-Check Active (Only pops up on startup when a newer version is released)"
                    : "\u2022 Manual Update Check Mode (Enable Auto-Check in Settings \u2192 General)";
                g.DrawString(modeDesc, fontSmallBold, hintB, mx + 26, my + 240);
            }

            int btnY = my + mh - 58;
            updateInstallBtnRect = new Rectangle(mx + 24, btnY, 260, 40);
            updateEditUrlBtnRect = new Rectangle(mx + 294, btnY, 112, 40);
            updateLaterBtnRect = new Rectangle(mx + 416, btnY, 80, 40);

            using (LinearGradientBrush ib = new LinearGradientBrush(
                updateInstallBtnRect,
                Color.FromArgb(255, Math.Min(255, accentColor.R + 25), Math.Min(255, accentColor.G + 15), (int)accentColor.B),
                Color.FromArgb(255, Math.Max(0, accentColor.R - 35), Math.Max(0, accentColor.G - 25), Math.Max(0, accentColor.B - 15)),
                LinearGradientMode.Horizontal))
            {
                FillRoundRect(g, ib, updateInstallBtnRect, 14);
            }
            string installBtnTxt = isInstallingUpdate ? "Updating..." : (hasNewer ? "\u26A1 Install Update & Restart" : "\u26A1 Reinstall / Sync Latest Build");
            g.DrawString(installBtnTxt, fontSmallBold, Brushes.White, updateInstallBtnRect, sfCenter);

            using (SolidBrush cb = new SolidBrush(Color.FromArgb(45, 165, 115, 255)))
            using (Pen cp = new Pen(Color.FromArgb(120, 195, 145, 255), 1f))
            {
                FillRoundRect(g, cb, updateEditUrlBtnRect, 14);
                DrawRoundRect(g, cp, updateEditUrlBtnRect, 14);
            }
            g.DrawString(isCheckingUpdate ? "Checking..." : "\u21BB Check Now", fontSmallBold, Brushes.White, updateEditUrlBtnRect, sfCenter);

            using (SolidBrush lb = new SolidBrush(Color.FromArgb(32, 26, 56)))
            {
                FillRoundRect(g, lb, updateLaterBtnRect, 14);
            }
            g.DrawString("Close", fontSmallBold, Brushes.White, updateLaterBtnRect, sfCenter);
        }

        private int GetCenterSongListTopY()
        {
            return 70;
        }

        private void PaintCosmicTopBar(Graphics g, int w, StringFormat sfCenter, StringFormat sfLeftEllipsis)
        {
            int searchW = Math.Min(520, Math.Max(280, w - 540));
            int searchX = Math.Max(214, (w - searchW) / 2 - 20);
            Rectangle searchPill = new Rectangle(searchX, 14, searchW, 40);

            using (SolidBrush spBg = new SolidBrush(Color.FromArgb(255, 22, 16, 42)))
            using (Pen spRim = new Pen(isSearchEditing ? accentColor : Color.FromArgb(110, 175, 135, 245), isSearchEditing ? 1.8f : 1.1f))
            {
                FillRoundRect(g, spBg, searchPill, 20);
                DrawRoundRect(g, spRim, searchPill, 20);
            }

            using (Pen mp = new Pen(isSearchEditing ? accentColor : Color.FromArgb(205, 200, 225), 1.8f))
            {
                g.DrawEllipse(mp, searchPill.X + 15, searchPill.Y + 12, 12, 12);
                g.DrawLine(mp, searchPill.X + 25, searchPill.Y + 22, searchPill.X + 29, searchPill.Y + 26);
            }

            if (!isSearchEditing)
            {
                using (Font fPh = new Font("Segoe UI", 9.5f))
                using (SolidBrush pb = new SolidBrush(string.IsNullOrEmpty(searchQueryText) ? Color.FromArgb(165, 190, 185, 215) : textWhite))
                {
                    string displayStr = string.IsNullOrEmpty(searchQueryText) ? "Search songs, artists, albums..." : searchQueryText;
                    g.DrawString(displayStr, fPh, pb, new RectangleF(searchPill.X + 38, searchPill.Y + 10, searchPill.Width - 112, 20), sfLeftEllipsis);
                }
            }

            Rectangle ctrlKBadge = new Rectangle(searchPill.Right - 68, searchPill.Y + 7, 58, 26);
            using (SolidBrush ckB = new SolidBrush(Color.FromArgb(65, 145, 110, 220)))
            using (Pen ckP = new Pen(Color.FromArgb(85, 195, 165, 255), 1f))
            {
                FillRoundRect(g, ckB, ctrlKBadge, 10);
                DrawRoundRect(g, ckP, ctrlKBadge, 10);
            }
            using (Font fCk = new Font("Segoe UI", 8.0f, FontStyle.Regular))
            using (SolidBrush ckT = new SolidBrush(Color.FromArgb(225, 220, 240)))
            {
                g.DrawString(string.IsNullOrEmpty(searchQueryText) ? "Ctrl + K" : "Clear \u2715", fCk, ckT, ctrlKBadge, sfCenter);
            }

            int avatarX = w - 156;
            Rectangle avatarRect = new Rectangle(avatarX, 15, 38, 38);
            DrawUserProfileAvatar(g, avatarRect, 19);
            using (Pen avRim = new Pen(Color.FromArgb(210, 195, 145, 255), 1.6f))
            {
                g.DrawEllipse(avRim, avatarRect);
            }
            topFilterHitZones.Add(new HomeHitZone(new Rectangle(avatarX - 2, 13, 42, 42), "open_account_settings", null, "avatar_top", ""));

            Rectangle bellCircle = ScaleRectCentered(new Rectangle(avatarX - 48, 16, 36, 36), GetButtonScale("bell_top"));
            using (SolidBrush bb = new SolidBrush(Color.FromArgb(145, 26, 20, 48)))
            using (Pen bp = new Pen(Color.FromArgb(75, 185, 145, 255), 1f))
            {
                g.FillEllipse(bb, bellCircle);
                g.DrawEllipse(bp, bellCircle);
            }
            DrawNotificationBellIcon(g, bellCircle.X + 18f, bellCircle.Y + 18f, Color.FromArgb(230, 225, 245), true);
            topFilterHitZones.Add(new HomeHitZone(bellCircle, "check_updates_top", null, "bell_top", ""));

            if (bellCircle.X - 88 > searchPill.Right + 10)
            {
                Rectangle manUpdBtn = ScaleRectCentered(new Rectangle(bellCircle.X - 86, 20, 78, 28), GetButtonScale("update_top"));
                using (SolidBrush ub = new SolidBrush(Color.FromArgb(65, accentColor.R, accentColor.G, accentColor.B)))
                using (Pen up = new Pen(Color.FromArgb(140, accentColor.R, accentColor.G, accentColor.B), 1f))
                {
                    FillRoundRect(g, ub, manUpdBtn, 14);
                    DrawRoundRect(g, up, manUpdBtn, 14);
                }
                g.DrawString(isCheckingUpdate ? "Checking.." : "\u21BB Update", fontSmallBold, Brushes.White, manUpdBtn, sfCenter);
                topFilterHitZones.Add(new HomeHitZone(manUpdBtn, "check_updates_top", null, "update_top", ""));
            }
        }

        private void PaintCenterSongStage(Graphics g, int centerX, int centerW, int mainH, Color curBgCard, StringFormat sfCenter, StringFormat sfLeftEllipsis)
        {
            topFilterHitZones.Clear();
            homeHitZones.Clear();

            int w = this.ClientSize.Width;
            PaintCosmicTopBar(g, w, sfCenter, sfLeftEllipsis);

            int viewportTop = 64;
            int viewportH = mainH - viewportTop - 4;
            Rectangle stageViewport = new Rectangle(centerX, viewportTop, centerW, viewportH);

            if (!string.IsNullOrEmpty(searchQueryText) || activeTab == 1)
            {
                PaintExploreAndSearchScreen(g, stageViewport, curBgCard, sfCenter, sfLeftEllipsis);
                return;
            }

            if (activeTab == 0)
            {
                PaintScrollableHomeDashboard(g, stageViewport, curBgCard, sfCenter, sfLeftEllipsis);
                return;
            }

            if (activeTab == 6 || activeTab == 2)
            {
                PaintLibraryScreenV1070(g, stageViewport, curBgCard, sfCenter, sfLeftEllipsis);
                return;
            }

            if (activeTab == 3)
            {
                PaintDownloadsScreenV1070(g, stageViewport, curBgCard, sfCenter, sfLeftEllipsis);
                return;
            }

            PaintScrollableHomeDashboard(g, stageViewport, curBgCard, sfCenter, sfLeftEllipsis);
        }

        private void PaintLibraryScreenV1070(Graphics g, Rectangle vp, Color curBgCard, StringFormat sfCenter, StringFormat sfLeftEllipsis)
        {
            Region oldClip = g.Clip;
            g.SetClip(vp);

            int padX = vp.X + 20;
            int contentW = vp.Width - 40;
            int curY = vp.Y + 6 - scrollOffset;

            if (curY + 64 >= vp.Y && curY <= vp.Bottom)
            {
                DrawSoftMeshOrb(g, padX + 26, curY + 28, 42, Color.FromArgb(110, accentColor.R, accentColor.G, accentColor.B));
                using (Pen bkPen = new Pen(Color.FromArgb(245, 225, 175, 255), 2.8f))
                {
                    FillRoundRect(g, new SolidBrush(Color.FromArgb(180, accentColor)), new Rectangle(padX + 6, curY + 8, 9, 36), 3);
                    FillRoundRect(g, new SolidBrush(Color.FromArgb(210, 195, 125, 255)), new Rectangle(padX + 19, curY + 8, 9, 36), 3);
                    g.DrawRectangle(bkPen, padX + 6, curY + 8, 9, 36);
                    g.DrawRectangle(bkPen, padX + 19, curY + 8, 9, 36);
                    PointF[] tiltedBook = new PointF[]
                    {
                        new PointF(padX + 33, curY + 10),
                        new PointF(padX + 42, curY + 7),
                        new PointF(padX + 51, curY + 41),
                        new PointF(padX + 42, curY + 44)
                    };
                    g.DrawPolygon(bkPen, tiltedBook);
                }

                using (Font fLibTitle = new Font("Segoe UI", 22f, FontStyle.Bold))
                using (Font fLibSub = new Font("Segoe UI", 10.0f, FontStyle.Regular))
                using (SolidBrush sb = new SolidBrush(Color.FromArgb(205, 198, 225)))
                {
                    g.DrawString(activeTab == 2 ? "Your Favorites" : "Your Library", fLibTitle, Brushes.White, padX + 64, curY - 2);
                    g.DrawString("All your music, in one place", fLibSub, sb, padX + 66, curY + 38);
                }
            }
            curY += 68;

            int sumGap = 14;
            int sumW = (contentW - 3 * sumGap) / 4;
            int sumH = 82;
            if (curY + sumH >= vp.Y && curY <= vp.Bottom)
            {
                string[] sumTitles = new string[] { "Liked Songs", "Your Playlists", "Albums", "Artists" };
                string[] sumSubs = new string[]
                {
                    likedIds.Count + " liked songs",
                    userPlaylists.Count + " playlists",
                    catalog.Count + " studio tracks",
                    "18 artists"
                };
                Color[] sumWaveCols = new Color[]
                {
                    Color.FromArgb(185, 85, 255),
                    Color.FromArgb(75, 135, 255),
                    Color.FromArgb(55, 175, 255),
                    Color.FromArgb(205, 75, 245)
                };

                for (int i = 0; i < 4; i++)
                {
                    int cx = padX + i * (sumW + sumGap);
                    string hKey = "lib_sum_" + i;
                    Rectangle cRect = ScaleRectCentered(new Rectangle(cx, curY, sumW, sumH), GetButtonScale(hKey));
                    DrawGlassCard(g, cRect, 18, curBgCard, (activeTab == 2 && i == 0), currentHoveredBtnKey == hKey);

                    using (SolidBrush wb = new SolidBrush(Color.FromArgb(42, sumWaveCols[i].R, sumWaveCols[i].G, sumWaveCols[i].B)))
                    {
                        g.FillEllipse(wb, cRect.Right - 95, cRect.Bottom - 34, 110, 50);
                    }
                    using (Pen wp = new Pen(Color.FromArgb(145, sumWaveCols[i].R, sumWaveCols[i].G, sumWaveCols[i].B), 2.0f))
                    {
                        g.DrawLine(wp, cRect.X + cRect.Width / 2, cRect.Bottom - 1, cRect.Right - 14, cRect.Bottom - 1);
                    }

                    Rectangle iconBox = new Rectangle(cRect.X + 14, cRect.Y + 17, 48, 48);
                    using (LinearGradientBrush ib = new LinearGradientBrush(
                        iconBox,
                        Color.FromArgb(120, sumWaveCols[i].R, sumWaveCols[i].G, sumWaveCols[i].B),
                        Color.FromArgb(45, 20, 14, 42),
                        LinearGradientMode.ForwardDiagonal))
                    using (Pen ip = new Pen(Color.FromArgb(145, sumWaveCols[i].R, sumWaveCols[i].G, sumWaveCols[i].B), 1.2f))
                    {
                        FillRoundRect(g, ib, iconBox, 13);
                        DrawRoundRect(g, ip, iconBox, 13);
                    }

                    float icx = iconBox.X + 24f;
                    float icy = iconBox.Y + 24f;
                    if (i == 0) DrawHeartIcon(g, Color.FromArgb(235, 165, 255), icx, icy, true);
                    else if (i == 1) DrawSidebarNavIcon(g, 4, icx, icy, Color.FromArgb(175, 210, 255));
                    else if (i == 2)
                    {
                        using (Pen dp = new Pen(Color.FromArgb(195, 220, 255), 2.0f))
                        {
                            g.DrawEllipse(dp, icx - 10f, icy - 10f, 20f, 20f);
                            g.DrawEllipse(dp, icx - 3f, icy - 3f, 6f, 6f);
                        }
                    }
                    else
                    {
                        using (Pen up = new Pen(Color.FromArgb(235, 185, 255), 2.0f))
                        {
                            g.DrawEllipse(up, icx - 5f, icy - 9f, 10f, 10f);
                            g.DrawArc(up, icx - 9f, icy + 2f, 18f, 12f, 180f, 180f);
                        }
                    }

                    using (Font fSt = new Font("Segoe UI", 11.0f, FontStyle.Bold))
                    using (Font fSs = new Font("Segoe UI", 8.8f, FontStyle.Regular))
                    using (SolidBrush subB = new SolidBrush(Color.FromArgb(185, 180, 210)))
                    {
                        g.DrawString(sumTitles[i], fSt, Brushes.White, cRect.X + 74, cRect.Y + 20);
                        g.DrawString(sumSubs[i], fSs, subB, cRect.X + 74, cRect.Y + 43);
                    }

                    Rectangle playCirc = new Rectangle(cRect.Right - 38, cRect.Bottom - 36, 26, 26);
                    using (SolidBrush pcb = new SolidBrush(Color.FromArgb(95, sumWaveCols[i].R, sumWaveCols[i].G, sumWaveCols[i].B)))
                    using (Pen pcp = new Pen(Color.FromArgb(150, 255, 255, 255), 1f))
                    {
                        g.FillEllipse(pcb, playCirc);
                        g.DrawEllipse(pcp, playCirc);
                    }
                    DrawPlayTriangle(g, Brushes.White, playCirc.X + 14f, playCirc.Y + 13f, 5.5f);

                    string sumAction = (i == 0) ? "lib_card_liked" : ((i == 1) ? "lib_card_playlists" : ((i == 2) ? "lib_card_albums" : "lib_card_artists"));
                    homeHitZones.Add(new HomeHitZone(cRect, sumAction, null, hKey));
                }
            }
            curY += sumH + 22;

            if (curY + 32 >= vp.Y && curY <= vp.Bottom)
            {
                FillRoundRect(g, new SolidBrush(accentColor), new Rectangle(padX, curY + 4, 5, 20), 2);
                using (Font fSec = new Font("Segoe UI", 13.5f, FontStyle.Bold))
                {
                    g.DrawString("Playlists", fSec, Brushes.White, padX + 12, curY);
                }

                Rectangle sortPill = new Rectangle(padX + contentW - 224, curY, 146, 28);
                DrawGlassCard(g, sortPill, 14, curBgCard, false, false);
                g.DrawString("Sort: " + librarySortNames[librarySortIdx] + " \u2304", fontSmallBold, Brushes.White, sortPill, sfCenter);
                homeHitZones.Add(new HomeHitZone(sortPill, "cycle_lib_sort", null, "lib_sort"));

                Rectangle gridToggle = new Rectangle(padX + contentW - 68, curY, 68, 28);
                DrawGlassCard(g, gridToggle, 14, curBgCard, false, false);
                Rectangle gridHalf = new Rectangle(gridToggle.X + 2, gridToggle.Y + 2, 32, 24);
                Rectangle listHalf = new Rectangle(gridToggle.X + 34, gridToggle.Y + 2, 32, 24);
                FillRoundRect(g, new SolidBrush(accentColor), isGridViewMode ? gridHalf : listHalf, 11);
                g.DrawString("\u229E", fontSmallBold, Brushes.White, gridHalf, sfCenter);
                g.DrawString("\u2630", fontSmallBold, Brushes.White, listHalf, sfCenter);
                homeHitZones.Add(new HomeHitZone(gridToggle, "toggle_grid_list", null, "lib_grid_tog"));
            }
            curY += 38;

            if (userPlaylists.Count < 6) InitDefaultPlaylists();
            int numPlCards = 6;
            int plGap = 14;
            int plCardW = (contentW - (numPlCards - 1) * plGap) / numPlCards;
            int plArtSz = Math.Max(96, Math.Min(148, plCardW));
            int plRowH = plArtSz + 46;

            string[] plCoverUris = new string[]
            {
                "local://pl_favorites",
                "local://pl_chill",
                "local://pl_workout",
                "local://pl_hindi",
                "local://pl_lofi",
                "local://pl_latenight"
            };
            string[] plCountLabels = new string[] { "76 songs", "42 songs", "28 songs", "65 songs", "54 songs", "31 songs" };

            if (curY + plRowH >= vp.Y && curY <= vp.Bottom)
            {
                for (int i = 0; i < numPlCards && i < userPlaylists.Count; i++)
                {
                    UserPlaylistItem pl = userPlaylists[i];
                    int cx = padX + i * (plCardW + plGap);
                    string hKey = "lib_pl_" + i;
                    Rectangle artRect = ScaleRectCentered(new Rectangle(cx, curY, plArtSz, plArtSz), GetButtonScale(hKey));

                    DrawStaticAlbumArt(g, plCoverUris[i % plCoverUris.Length], artRect, 16);
                    using (Pen rimP = new Pen(Color.FromArgb(currentHoveredBtnKey == hKey ? 200 : 75, 205, 165, 255), 1.2f))
                    {
                        DrawRoundRect(g, rimP, artRect, 16);
                    }

                    if (i == 0)
                    {
                        Rectangle heartBadge = new Rectangle(artRect.Right - 32, artRect.Bottom - 32, 26, 26);
                        using (SolidBrush hb = new SolidBrush(Color.FromArgb(220, accentColor)))
                        {
                            g.FillEllipse(hb, heartBadge);
                        }
                        DrawHeartIcon(g, Color.White, heartBadge.X + 13f, heartBadge.Y + 13f, true);
                    }

                    using (Font fPt = new Font("Segoe UI", 9.8f, FontStyle.Bold))
                    using (Font fPs = new Font("Segoe UI", 8.5f, FontStyle.Regular))
                    using (SolidBrush sb = new SolidBrush(Color.FromArgb(185, 180, 210)))
                    {
                        g.DrawString(pl.Name, fPt, Brushes.White, new RectangleF(cx + 2, curY + plArtSz + 6, plArtSz - 24, 19), sfLeftEllipsis);
                        g.DrawString("\u2022\u2022\u2022", fontSmallBold, sb, cx + plArtSz - 22, curY + plArtSz + 6);
                        g.DrawString(plCountLabels[i % plCountLabels.Length], fPs, sb, new RectangleF(cx + 2, curY + plArtSz + 24, plArtSz - 4, 17), sfLeftEllipsis);
                    }

                    Rectangle plDotHit = new Rectangle(cx + plArtSz - 28, curY + plArtSz + 2, 28, 24);
                    homeHitZones.Add(new HomeHitZone(plDotHit, "open_playlist_3dot", null, hKey + "_dot", i.ToString()));
                    Rectangle fullPlHit = new Rectangle(cx, curY, plArtSz, plRowH);
