            curY += plRowH + 18;

            if (curY + 30 >= vp.Y && curY <= vp.Bottom)
            {
                FillRoundRect(g, new SolidBrush(accentColor), new Rectangle(padX, curY + 4, 5, 20), 2);
                using (Font fSec = new Font("Segoe UI", 13.5f, FontStyle.Bold))
                {
                    g.DrawString(activeTab == 2 ? "Liked Tracks" : "Recently Played & Added", fSec, Brushes.White, padX + 12, curY);
                }
                g.DrawString("See All  \u203A", fontSmallBold, Brushes.White, padX + contentW - 64, curY + 6);
            }
            curY += 34;

            List<SongItem> tracksToShow = new List<SongItem>();
            if (activeTab == 2)
            {
                foreach (SongItem s in catalog) { if (likedIds.Contains(s.Id)) tracksToShow.Add(s); }
                foreach (SongItem s in recentlyPlayedSongs) { if (likedIds.Contains(s.Id) && !ContainsSongByTitleOrId(tracksToShow, s)) tracksToShow.Add(s); }
                if (tracksToShow.Count == 0) tracksToShow.AddRange(displaySongs);
            }
            else
            {
                foreach (SongItem s in recentlyPlayedSongs) { if (!ContainsSongByTitleOrId(tracksToShow, s)) tracksToShow.Add(s); }
                foreach (SongItem s in catalog) { if (!ContainsSongByTitleOrId(tracksToShow, s)) tracksToShow.Add(s); }
            }

            int rowH = 56;
            for (int i = 0; i < tracksToShow.Count; i++)
            {
                if (curY + rowH >= vp.Y && curY <= vp.Bottom)
                {
                    SongItem s = tracksToShow[i];
                    PaintInteractiveSongRow(g, s, new Rectangle(padX, curY, contentW, rowH), curBgCard, "lib_row_" + i, sfCenter, sfLeftEllipsis);
                }
                curY += rowH + 6;
            }

            totalHomeContentHeight = (curY + scrollOffset) - vp.Y + 24;
            g.Clip = oldClip;
            DrawCustomScrollbar(g, vp, totalHomeContentHeight);
        }

