        private void LoadUserProfilePhotoFromDisk(string path)
        {
            if (string.IsNullOrEmpty(path) || !File.Exists(path)) return;
            try
            {
                byte[] bytes = File.ReadAllBytes(path);
                using (MemoryStream ms = new MemoryStream(bytes))
                using (Image rawImg = Image.FromStream(ms))
                {
                    Bitmap cropped = new Bitmap(256, 256, PixelFormat.Format32bppPArgb);
                    using (Graphics g = Graphics.FromImage(cropped))
                    {
                        g.SmoothingMode = SmoothingMode.AntiAlias;
                        g.InterpolationMode = InterpolationMode.HighQualityBicubic;
                        int minSide = Math.Min(rawImg.Width, rawImg.Height);
                        int sx = (rawImg.Width - minSide) / 2;
                        int sy = (rawImg.Height - minSide) / 2;
                        g.DrawImage(rawImg, new Rectangle(0, 0, 256, 256), new Rectangle(sx, sy, minSide, minSide), GraphicsUnit.Pixel);
                    }
                    if (userProfileAvatarBmp != null)
                    {
                        try { userProfileAvatarBmp.Dispose(); } catch { }
                    }
                    userProfileAvatarBmp = cropped;
                }
            }
            catch { }
        }

        private void SelectUserProfilePhotoFromPc()
        {
            try
            {
                using (OpenFileDialog ofd = new OpenFileDialog())
                {
                    ofd.Title = "Select Your Leo Music Profile Photo from PC/Laptop";
                    ofd.Filter = "Image Files (*.png;*.jpg;*.jpeg;*.bmp;*.gif;*.webp)|*.png;*.jpg;*.jpeg;*.bmp;*.gif;*.webp|All Files (*.*)|*.*";
                    if (ofd.ShowDialog(this) == DialogResult.OK && !string.IsNullOrEmpty(ofd.FileName) && File.Exists(ofd.FileName))
                    {
                        string savedPhotoDest = Path.Combine(leoLocalDataRoot, "user_profile_photo.png");
                        LoadUserProfilePhotoFromDisk(ofd.FileName);
                        if (userProfileAvatarBmp != null)
                        {
                            try
                            {
                                userProfileAvatarBmp.Save(savedPhotoDest, ImageFormat.Png);
                                userProfilePhotoPath = savedPhotoDest;
                            }
                            catch
                            {
                                userProfilePhotoPath = ofd.FileName;
                            }
                        }
                        SavePersistentSettings();
                        ShowToast("\u2726 Profile Photo Updated from PC!");
                        this.Invalidate();
                    }
                }
            }
            catch { }
        }

        private void DrawUserProfileAvatar(Graphics g, Rectangle rect, int radius)
        {
            if (userProfileAvatarBmp != null)
            {
                using (GraphicsPath cp = GetRoundRectPath(rect, radius))
                {
                    Region oldClip = g.Clip;
                    g.SetClip(cp, CombineMode.Intersect);
                    g.DrawImage(userProfileAvatarBmp, rect);
                    g.Clip = oldClip;
                }
                return;
            }
            SongItem avSong = currentSong ?? (catalog.Count > 0 ? catalog[0] : null);
            if (avSong != null)
            {
                DrawStaticAlbumArt(g, avSong.ThumbUrl, rect, radius);
            }
        }

        private void SpeakVoiceTextAsync(string textToSpeak)
        {
            if (!voiceWelcomeEnabled || string.IsNullOrEmpty(textToSpeak)) return;
            ThreadPool.QueueUserWorkItem(_ =>
            {
                try
                {
                    Type sapiType = Type.GetTypeFromProgID("SAPI.SpVoice");
                    if (sapiType != null)
                    {
                        object spVoice = Activator.CreateInstance(sapiType);
                        sapiType.InvokeMember("Volume", BindingFlags.SetProperty, null, spVoice, new object[] { 92 });
                        sapiType.InvokeMember("Rate", BindingFlags.SetProperty, null, spVoice, new object[] { 0 });
                        sapiType.InvokeMember("Speak", BindingFlags.InvokeMethod, null, spVoice, new object[] { textToSpeak, 0 });
                    }
                }
                catch { }
            });
        }

