                trayContextMenu.Items.Add("Open Siri / Google AI PC Agent", null, (s, ev) => { RestoreFromBackgroundAgentMode(); OpenAiAgentPanel(); });
                trayContextMenu.Items.Add("Float Circular Agent Orb on Desktop", null, (s, ev) => { ToggleAgentFloatingDesktopMode(); });
                trayContextMenu.Items.Add("Play / Pause Music", null, (s, ev) => { TogglePlayPause(); });
                trayContextMenu.Items.Add("Next Track", null, (s, ev) => { NextTrack(); });
                trayContextMenu.Items.Add("Exit Leo Music", null, (s, ev) => { SavePersistentSettings(); Application.Exit(); });

                trayNotifyIcon = new NotifyIcon();
                trayNotifyIcon.Text = "Leo Music Studio & AI PC Agent (v" + CURRENT_APP_VERSION + ")";
                trayNotifyIcon.Icon = customAppIcon ?? SystemIcons.Application;
                trayNotifyIcon.ContextMenuStrip = trayContextMenu;
                trayNotifyIcon.Visible = true;
                trayNotifyIcon.DoubleClick += (s, ev) => { RestoreFromBackgroundAgentMode(); };
            }
            catch { }
