        private void OnAgentCommandBoxKeyDown(object sender, KeyEventArgs e)
        {
            if (e.KeyCode == Keys.Enter)
            {
                e.SuppressKeyPress = true;
                string cmd = (agentCommandBox.Text ?? "").Trim();
                if (!string.IsNullOrEmpty(cmd))
                {
                    agentCommandBox.Text = "";
                    ExecuteAgentMultiTaskCommand(cmd);
                }
            }
            else if (e.KeyCode == Keys.Escape)
            {
                e.SuppressKeyPress = true;
                UnfocusAgentCommandBox();
            }
        }

        private void FocusAgentCommandBox(int x, int y, int w)
        {
            if (agentCommandBox == null) return;
            isEditingAgentPrompt = true;
            agentCommandBox.Location = new Point(x, y);
            agentCommandBox.Size = new Size(Math.Max(120, w), 22);
            agentCommandBox.Visible = true;
            agentCommandBox.BringToFront();
            agentCommandBox.Focus();
            this.Invalidate();
        }

        private void UnfocusAgentCommandBox()
        {
            isEditingAgentPrompt = false;
            if (agentCommandBox != null && agentCommandBox.Visible)
            {
                agentCommandBox.Visible = false;
            }
            this.ActiveControl = null;
            this.Focus();
            this.Invalidate();
        }

