        private void UpdateWindowRoundedRegion(int radius)
        {
            try
            {
                using (GraphicsPath gp = new GraphicsPath())
                {
                    if (Math.Abs(this.Width - this.Height) <= 4 && radius >= this.Width / 2 - 4)
                    {
                        gp.AddEllipse(1, 1, this.Width - 2, this.Height - 2);
                    }
                    else
                    {
                        using (GraphicsPath rr = GetRoundRectPath(new Rectangle(0, 0, this.Width, this.Height), radius))
                        {
                            gp.AddPath(rr, false);
                        }
                    }
                    ReplaceWindowRegionSafely(new Region(gp));
                }
            }
            catch { }
        }

        private void ToggleAgentFloatingDesktopMode()
        {
            if (!isAgentFloatingDesktopMode)
            {
                UnfocusSearchInput();
                UnfocusAgentCommandBox();
                isAgentPanelOpen = false;
                if (!isMiniPlayerMode && !isDynamicBarMode)
                {
                    if (this.WindowState == FormWindowState.Maximized) this.WindowState = FormWindowState.Normal;
                    savedDesktopSize = this.Size;
                    savedDesktopLocation = this.Location;
                }
                isMiniPlayerMode = false;
                isDynamicBarMode = false;
                isAgentFloatingDesktopMode = true;
                isAgentDesktopExpanded = false;
                this.TopMost = true;
                Rectangle screen = Screen.FromControl(this).WorkingArea;

                // v10.6.1 Fix: Reset MinimumSize BEFORE shrinking to 88x88 so WinForms never clamps to 980x640!
                this.MinimumSize = new Size(88, 88);
                this.Size = new Size(88, 88);
                this.Location = new Point(screen.Right - 106, screen.Bottom - 110);
                UpdateWindowRoundedRegion(44);
                EnforceAlwaysOnTopOverlayZOrder();
                ShowToast("\u2726 Floating Desktop AI Orb Active (Click Orb to Expand \u2022 Drag to Move)");
                SpeakVoiceTextAsync("Desktop AI orb active");
            }
            else
            {
                RestoreFromBackgroundAgentMode();
            }
            this.Invalidate();
        }

        private void RestoreFromBackgroundAgentMode()
        {
            if (this.WindowState == FormWindowState.Minimized)
            {
                this.WindowState = FormWindowState.Normal;
            }
            if (isAgentFloatingDesktopMode)
            {
                isAgentFloatingDesktopMode = false;
                isAgentDesktopExpanded = false;
                UnfocusAgentCommandBox();
                this.TopMost = false;
                try { if (this.IsHandleCreated) SetWindowPos(this.Handle, HWND_NOTOPMOST, 0, 0, 0, 0, SWP_NOMOVE | SWP_NOSIZE | SWP_NOACTIVATE | SWP_SHOWWINDOW); } catch { }
                ReplaceWindowRegionSafely(null);
                this.MinimumSize = new Size(980, 640);
                this.Size = (savedDesktopSize.Width >= 980 && savedDesktopSize.Height >= 640) ? savedDesktopSize : new Size(1220, 770);
                this.Location = savedDesktopLocation;
            }
            this.Show();
            this.Activate();
            this.Invalidate();
        }

        private void ToggleAgentDesktopExpanded()
        {
            if (!isAgentFloatingDesktopMode) return;
            isAgentDesktopExpanded = !isAgentDesktopExpanded;
            Rectangle screen = Screen.FromControl(this).WorkingArea;
            if (isAgentDesktopExpanded)
            {
                int newW = 490;
                int newH = 310;
                int nx = Math.Max(screen.Left + 12, Math.Min(screen.Right - newW - 12, this.Location.X - (newW - 88)));
                int ny = Math.Max(screen.Top + 12, Math.Min(screen.Bottom - newH - 12, this.Location.Y - (newH - 88)));
                this.MinimumSize = new Size(newW, newH);
                this.Size = new Size(newW, newH);
                this.Location = new Point(nx, ny);
                UpdateWindowRoundedRegion(22);
                EnforceAlwaysOnTopOverlayZOrder();
                FocusAgentCommandBox(24, 72, newW - 136);
            }
            else
            {
                UnfocusAgentCommandBox();
                int nx = Math.Max(screen.Left + 12, Math.Min(screen.Right - 100, this.Location.X + (this.Width - 88)));
                int ny = Math.Max(screen.Top + 12, Math.Min(screen.Bottom - 100, this.Location.Y + (this.Height - 88)));
                this.MinimumSize = new Size(88, 88);
                this.Size = new Size(88, 88);
                this.Location = new Point(nx, ny);
                UpdateWindowRoundedRegion(44);
                EnforceAlwaysOnTopOverlayZOrder();
            }
            this.Invalidate();
        }

        private int ComputeLevenshteinDistance(string s, string t)
        {
            if (string.IsNullOrEmpty(s)) return string.IsNullOrEmpty(t) ? 0 : t.Length;
            if (string.IsNullOrEmpty(t)) return s.Length;
            int n = s.Length;
            int m = t.Length;
            int[,] d = new int[n + 1, m + 1];
            for (int i = 0; i <= n; i++) d[i, 0] = i;
            for (int j = 0; j <= m; j++) d[0, j] = j;
            for (int i = 1; i <= n; i++)
            {
                for (int j = 1; j <= m; j++)
                {
                    int cost = (char.ToLowerInvariant(s[i - 1]) == char.ToLowerInvariant(t[j - 1])) ? 0 : 1;
                    d[i, j] = Math.Min(Math.Min(d[i - 1, j] + 1, d[i, j - 1] + 1), d[i - 1, j - 1] + cost);
                }
            }
            return d[n, m];
        }

        private string GetConsonantSkeleton(string word)
        {
            if (string.IsNullOrEmpty(word)) return "";
            StringBuilder sb = new StringBuilder();
            char prev = '\0';
            foreach (char raw in word.ToLowerInvariant())
            {
                if (!char.IsLetterOrDigit(raw)) continue;
                bool isVowel = (raw == 'a' || raw == 'e' || raw == 'i' || raw == 'o' || raw == 'u');
                if (!isVowel || sb.Length == 0)
                {
                    if (raw != prev)
                    {
                        sb.Append(raw);
                        prev = raw;
                    }
                }
            }
            return sb.ToString();
        }

        private string SmartAutoCorrectAgentCommand(string rawInput)
        {
            if (string.IsNullOrEmpty(rawInput)) return "";
            string s = rawInput.Trim();
            s = Regex.Replace(s, @"\b(?:what's\s+up|whats\s+up|what\s+sap|watch\s+app|whats\s+app|whtsp|watsap|whatsp|wtsp|whasapp|whatsap|whtsapp|wapp)\b", "whatsapp", RegexOptions.IgnoreCase);
            s = Regex.Replace(s, @"\b(?:chat\s+g\s*p\s*t|chad\s+g\s*p\s*t|check\s+g\s*p\s*t|chat\s+gpt|chtgpt|chatgtp|cgpt|chagpt|chatgp|cahtgpt)\b", "chatgpt", RegexOptions.IgnoreCase);
            s = Regex.Replace(s, @"\b(?:you\s+tube|u\s+tube|utube|youtub|yotube|yuotube|yutube|yt)\b", "youtube", RegexOptions.IgnoreCase);
            s = Regex.Replace(s, @"\b(?:note\s+pad|notpad|ntpad|noetpad|notepd|npad)\b", "notepad", RegexOptions.IgnoreCase);
            s = Regex.Replace(s, @"\b(?:ad\s+nte|add\s+nte|ad\s+note|wrt\s+nte|write\s+nte)\b", "add note", RegexOptions.IgnoreCase);
            s = Regex.Replace(s, @"\b(?:cross\s+fade|crosfade|cfade|crsfade|crossfd|xfade)\b", "crossfade", RegexOptions.IgnoreCase);
            s = Regex.Replace(s, @"\b(?:three\s+d|3\s+d)\b", "3d", RegexOptions.IgnoreCase);
            s = Regex.Replace(s, @"\b(?:a\s*i\s*d\s*j|hey\s+d\s*j)\b", "ai dj", RegexOptions.IgnoreCase);
            s = Regex.Replace(s, @"\b(?:screen\s+shot|scrnshot|screnshot|screensht|ss|captur)\b", "screenshot", RegexOptions.IgnoreCase);

            Dictionary<string, string> tokenMap = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            foreach (string a in new string[] { "paly", "plai", "ply", "pla", "palyy", "pllay", "py", "palyed", "bajao", "chalao" }) tokenMap[a] = "play";
            foreach (string a in new string[] { "paus", "puse", "ps", "pasue", "stpo", "stp", "roko" }) tokenMap[a] = "pause";
            foreach (string a in new string[] { "nxt", "nex", "nxet", "skp", "sikp" }) tokenMap[a] = "next";
            foreach (string a in new string[] { "prv", "perv", "previus", "bck" }) tokenMap[a] = "previous";
            foreach (string a in new string[] { "opn", "opne", "oepn", "openn", "lanch", "lnch", "launc", "kholo" }) tokenMap[a] = "open";
            foreach (string a in new string[] { "msg", "mesage", "mssg", "msge", "messge", "snd", "sned", "bhejo" }) tokenMap[a] = "message";
            foreach (string a in new string[] { "nte", "noet", "notee" }) tokenMap[a] = "note";
            foreach (string a in new string[] { "calc", "calclator", "calcu", "calcultr", "clac", "calculater" }) tokenMap[a] = "calculator";
            foreach (string a in new string[] { "volm", "vlume", "vlm", "volum", "vol", "awaz" }) tokenMap[a] = "volume";
            foreach (string a in new string[] { "dwnld", "downlod", "dnld", "dwld", "dwnload", "dwn" }) tokenMap[a] = "download";
            foreach (string a in new string[] { "countery", "cuntry", "cntry", "countri", "contry" }) tokenMap[a] = "country";
            foreach (string a in new string[] { "serch", "srch", "sarch", "searh", "fnd" }) tokenMap[a] = "search";
            foreach (string a in new string[] { "setings", "sttings", "seting" }) tokenMap[a] = "settings";
            foreach (string a in new string[] { "equlizer", "equliser", "eqlzr" }) tokenMap[a] = "equalizer";
            foreach (string a in new string[] { "lyrcs", "lrics", "lyric" }) tokenMap[a] = "lyrics";

            string[] canonicalCmds = new string[] {
                "play", "pause", "next", "previous", "open", "whatsapp", "message",
                "youtube", "chatgpt", "note", "notepad", "calculator", "screenshot",
                "volume", "download", "crossfade", "country", "search", "settings", "equalizer", "lyrics"
            };

            string[] words = s.Split(new char[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
            for (int i = 0; i < words.Length; i++)
            {
                string clean = words[i].Trim(',', '.', '!', '?');
                string low = clean.ToLowerInvariant();
                if (tokenMap.ContainsKey(low))
                {
                    words[i] = tokenMap[low];
                    continue;
                }
                bool isCmdPos = (i == 0 || i == 1 || (i > 0 && (words[i - 1].Equals("and", StringComparison.OrdinalIgnoreCase) || words[i - 1].Equals("open", StringComparison.OrdinalIgnoreCase))));
                if (isCmdPos && low.Length >= 3)
                {
                    string best = null;
                    int bestD = 99;
                    string skel = GetConsonantSkeleton(low);
                    foreach (string cand in canonicalCmds)
                    {
                        int d = ComputeLevenshteinDistance(low, cand);
                        int maxD = cand.Length <= 4 ? 1 : 2;
                        if (d <= maxD && d < bestD)
                        {
                            bestD = d;
                            best = cand;
                        }
                        else if (low.Length >= 3 && cand.StartsWith(low, StringComparison.OrdinalIgnoreCase) && cand.Length - low.Length <= 4)
                        {
                            if (best == null) best = cand;
                        }
                        else if (skel.Length >= 3 && skel == GetConsonantSkeleton(cand))
                        {
                            if (best == null) best = cand;
                        }
                    }
                    if (best != null) words[i] = best;
                }
            }
            return string.Join(" ", words);
        }

        private SongItem FindBestFuzzySongMatch(string rawQuery)
        {
            if (string.IsNullOrEmpty(rawQuery) || catalog.Count == 0) return null;
            string q = Regex.Replace(rawQuery.Trim(), @"^(?:song|music|track|audio|please|now)\s+", "", RegexOptions.IgnoreCase).Trim().ToLowerInvariant();
            if (string.IsNullOrEmpty(q)) return currentSong ?? catalog[0];

            SongItem bestSong = null;
            double bestScore = -1.0;
            string qSkel = GetConsonantSkeleton(q);
            string[] qWords = q.Split(new char[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);

            foreach (SongItem s in catalog)
            {
                string tClean = CleanSongDisplayTitle(s.Title).ToLowerInvariant();
                string aClean = GetPrimaryArtistName(s.Artist).ToLowerInvariant();
                string full = tClean + " " + aClean;

                double score = 0.0;
                if (tClean == q) score += 130.0;
                else if (tClean.StartsWith(q)) score += 100.0;
                else if (tClean.Contains(q)) score += 85.0;
                else if (aClean.Contains(q)) score += 75.0;

                string[] targetWords = full.Split(new char[] { ' ', '-', '(', ')' }, StringSplitOptions.RemoveEmptyEntries);
                foreach (string qw in qWords)
                {
                    if (qw.Length < 2) continue;
                    string qwSkel = GetConsonantSkeleton(qw);
                    foreach (string tw in targetWords)
                    {
                        if (tw == qw) score += 48.0;
                        else if (tw.StartsWith(qw) && qw.Length >= 2) score += 40.0;
                        else if (qw.Length >= 3 && GetConsonantSkeleton(tw) == qwSkel) score += 36.0;
                        else if (qw.Length >= 3 && GetConsonantSkeleton(tw).StartsWith(qwSkel)) score += 30.0;
                        else
                        {
                            int dist = ComputeLevenshteinDistance(qw, tw);
                            if (dist == 1 && tw.Length >= 4) score += 32.0;
                            else if (dist == 2 && tw.Length >= 5) score += 24.0;
                            else if (tw.Length > qw.Length && ComputeLevenshteinDistance(qw, tw.Substring(0, qw.Length)) <= 1) score += 26.0;
                        }
                    }
                }

                string titleSkel = GetConsonantSkeleton(tClean.Replace(" ", ""));
                if (qSkel.Length >= 3 && (titleSkel == qSkel || titleSkel.StartsWith(qSkel)))
                {
                    score += 42.0;
                }
                int fullDist = ComputeLevenshteinDistance(q, tClean);
                if (fullDist <= 2) score += 52.0;
                else if (fullDist <= 3 && tClean.Length >= 6) score += 34.0;

                if (score > bestScore)
                {
                    bestScore = score;
                    bestSong = s;
                }
            }
            return bestScore >= 22.0 ? bestSong : null;
        }

        private string NormalizeSpokenAgentTranscript(string rawText)
        {
            if (string.IsNullOrEmpty(rawText)) return "";
            return SmartAutoCorrectAgentCommand(rawText);
        }

        private void StartAgentVoiceDictationAsync()
        {
            if (isAgentListeningVoice) return;
            isAgentListeningVoice = true;
            agentStatusSubtitle = "\u25C9 Listening Now (High-Accuracy Command + Voice Mode)... Speak clearly into your mic!";
            this.Invalidate();

            // Gather top song titles from catalog & downloads so SpeechRecognitionEngine recognizes song names with 99% accuracy!
            List<string> songPhrases = new List<string>();
            for (int i = 0; i < Math.Min(28, catalog.Count); i++)
            {
                string st = CleanSongDisplayTitle(catalog[i].Title).Replace("'", "").Replace("\"", "").Trim();
                if (st.Length >= 3 && st.Length <= 32)
                {
                    songPhrases.Add("play " + st);
                    songPhrases.Add("play song " + st);
                    songPhrases.Add("open youtube and play " + st);
                }
            }

            Thread voiceThread = new Thread(() =>
            {
                string recognized = "";
                try
                {
                    string psFile = Path.Combine(leoLocalDataRoot, "leo_voice_recognizer.ps1");
                    StringBuilder ps = new StringBuilder();
                    ps.AppendLine("Add-Type -AssemblyName System.Speech");
                    ps.AppendLine("$ErrorActionPreference = 'SilentlyContinue'");
                    ps.AppendLine("$r = New-Object System.Speech.Recognition.SpeechRecognitionEngine");
                    ps.AppendLine("$r.SetInputToDefaultAudioDevice()");
                    ps.AppendLine("$c = New-Object System.Speech.Recognition.Choices");
                    string[] baseCmds = new string[]
                    {
                        "open whatsapp", "open whatsapp and message hello", "open youtube", "open chatgpt",
                        "open calculator", "open notepad", "open chrome", "open brave", "open edge", "open explorer",
                        "open camera", "open task manager", "open settings", "open downloads", "open lyrics", "open equalizer",
                        "open calculator and open notepad", "add note meeting at 5 pm", "add note call client",
                        "play music", "pause music", "pause", "resume music", "resume", "stop music",
                        "next song", "next track", "previous song", "previous track",
                        "volume up", "volume down", "volume 50", "volume 80", "volume 100", "volume 120", "mute", "unmute",
                        "download song", "download this song", "enable 3d audio", "start ai dj",
                        "crossfade off", "crossfade 3", "crossfade 5", "mini player", "dynamic bar",
                        "take screenshot", "check pc status", "check battery", "what time is it", "what song is playing",
                        "country india", "country united states", "country united kingdom", "country canada"
                    };
                    foreach (string bc in baseCmds)
                    {
                        ps.AppendLine("$c.Add('" + bc + "')");
                    }
                    foreach (string sp in songPhrases)
                    {
                        ps.AppendLine("$c.Add('" + sp + "')");
                    }
                    ps.AppendLine("$gb = New-Object System.Speech.Recognition.GrammarBuilder($c)");
                    ps.AppendLine("$cmdGrammar = New-Object System.Speech.Recognition.Grammar($gb)");
                    ps.AppendLine("$cmdGrammar.Priority = 127");
                    ps.AppendLine("$cmdGrammar.Weight = 1.0");
                    ps.AppendLine("$r.LoadGrammar($cmdGrammar)");
                    ps.AppendLine("$dictGrammar = New-Object System.Speech.Recognition.DictationGrammar");
                    ps.AppendLine("$dictGrammar.Priority = 1");
                    ps.AppendLine("$dictGrammar.Weight = 0.45");
                    ps.AppendLine("$r.LoadGrammar($dictGrammar)");
                    ps.AppendLine("$r.InitialSilenceTimeout = [TimeSpan]::FromSeconds(5.0)");
                    ps.AppendLine("$r.BabbleTimeout = [TimeSpan]::FromSeconds(4.0)");
                    ps.AppendLine("$r.EndSilenceTimeout = [TimeSpan]::FromSeconds(1.1)");
                    ps.AppendLine("$res = $r.Recognize([TimeSpan]::FromSeconds(7.0))");
                    ps.AppendLine("if ($res -and $res.Text) { Write-Output ($res.Confidence.ToString('0.00') + '|' + $res.Text) }");
                    File.WriteAllText(psFile, ps.ToString(), Encoding.UTF8);

                    ProcessStartInfo psi = new ProcessStartInfo("powershell.exe");
                    psi.Arguments = "-NoProfile -ExecutionPolicy Bypass -File \"" + psFile + "\"";
                    psi.CreateNoWindow = true;
                    psi.UseShellExecute = false;
                    psi.RedirectStandardOutput = true;
                    using (Process p = Process.Start(psi))
                    {
                        recognized = (p.StandardOutput.ReadToEnd() ?? "").Trim();
                        p.WaitForExit(8000);
                    }
                }
                catch { }

                this.BeginInvoke((MethodInvoker)delegate
                {
                    isAgentListeningVoice = false;
                    if (!string.IsNullOrEmpty(recognized))
                    {
                        double conf = 0.85;
                        string rawTxt = recognized;
                        int barIdx = recognized.IndexOf('|');
                        if (barIdx > 0)
                        {
                            double.TryParse(recognized.Substring(0, barIdx), NumberStyles.Any, CultureInfo.InvariantCulture, out conf);
                            rawTxt = recognized.Substring(barIdx + 1).Trim();
                        }
                        string cleaned = NormalizeSpokenAgentTranscript(rawTxt);
                        if (agentCommandBox != null) agentCommandBox.Text = cleaned;
                        ExecuteAgentMultiTaskCommand(cleaned);
                    }
                    else
                    {
                        agentStatusSubtitle = "No speech detected \u2014 click 'Voice Mic' and speak clearly, or type your command below.";
                    }
                    this.Invalidate();
                });
            });
            voiceThread.IsBackground = true;
            voiceThread.Start();
        }

        private string GetPcSystemHealthSummary()
        {
            try
            {
                int batPct = 100;
                bool charging = true;
                try
                {
                    PowerStatus ps = SystemInformation.PowerStatus;
                    if (ps != null && ps.BatteryLifePercent >= 0f && ps.BatteryLifePercent <= 1.0f)
                    {
                        batPct = (int)Math.Round(ps.BatteryLifePercent * 100f);
                    }
                    charging = (ps != null && ps.PowerLineStatus == PowerLineStatus.Online);
                }
                catch { }
                long ramMb = 64;
                try { ramMb = Process.GetCurrentProcess().WorkingSet64 / (1024 * 1024); } catch { }
                string remStr = (agentReminderSecondsLeft > 0) ? ("  \u2022  Timer: " + FormatSec(agentReminderSecondsLeft)) : "";
                return "Battery: " + batPct + "%" + (charging ? " (AC)" : "") + "  \u2022  RAM: " + ramMb + " MB  \u2022  Offline Downloads: " + downloadedSongs.Count + remStr;
            }
            catch { return "System Online  \u2022  Offline Downloads: " + downloadedSongs.Count; }
        }

        private void CapturePcScreenshotViaAgent()
        {
            try
            {
                string shotDir = Path.Combine(leoLocalDataRoot, "Screenshots");
                if (!Directory.Exists(shotDir)) Directory.CreateDirectory(shotDir);
                string fileName = "Leo_Screenshot_" + DateTime.Now.ToString("yyyyMMdd_HHmmss") + ".png";
                string fullPath = Path.Combine(shotDir, fileName);
                string deskPath = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory), fileName);

                Rectangle bounds = Screen.PrimaryScreen.Bounds;
                using (Bitmap bmp = new Bitmap(bounds.Width, bounds.Height, PixelFormat.Format32bppArgb))
                {
                    using (Graphics g = Graphics.FromImage(bmp))
                    {
                        g.CopyFromScreen(bounds.X, bounds.Y, 0, 0, bounds.Size, CopyPixelOperation.SourceCopy);
                    }
                    bmp.Save(fullPath, ImageFormat.Png);
                    try { bmp.Save(deskPath, ImageFormat.Png); } catch { }
                }
                try { Process.Start(new ProcessStartInfo(fullPath) { UseShellExecute = true }); } catch { }
                LogAgentStep("\u2714 Captured Full-Screen PC Screenshot: " + fileName + " (Saved to Desktop & Local Folder)");
            }
            catch { }
        }

        private bool IsWhatsAppDesktopInstalled()
        {
            try
            {
                using (RegistryKey rk = Registry.ClassesRoot.OpenSubKey("whatsapp"))
                {
                    if (rk != null) return true;
                }
                string localWa = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "WhatsApp", "WhatsApp.exe");
                if (File.Exists(localWa)) return true;
                string winApps = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "Microsoft", "WindowsApps", "WhatsApp.exe");
                if (File.Exists(winApps)) return true;
            }
            catch { }
            return false;
        }

        private void LaunchWhatsAppWithMessageOrFallbackBrowser(string messageText, string recipient)
        {
            string fullText = messageText ?? "";
            string phoneDigits = "";
            if (!string.IsNullOrEmpty(recipient))
            {
                string onlyDigits = Regex.Replace(recipient, "[^0-9]", "");
                if (onlyDigits.Length >= 8) phoneDigits = onlyDigits;
                else if (string.IsNullOrEmpty(fullText)) fullText = "Hi " + recipient;
            }

            bool hasDesktopApp = IsWhatsAppDesktopInstalled();
            try
            {
                if (hasDesktopApp)
                {
                    string uri = "whatsapp://send?";
                    if (!string.IsNullOrEmpty(phoneDigits)) uri += "phone=" + phoneDigits + "&";
                    if (!string.IsNullOrEmpty(fullText)) uri += "text=" + Uri.EscapeDataString(fullText);
                    Process.Start(new ProcessStartInfo(uri) { UseShellExecute = true });
                    LogAgentStep("\u2714 WhatsApp Desktop App launched" + (string.IsNullOrEmpty(fullText) ? "" : (" with message: \"" + fullText + "\"")) + (string.IsNullOrEmpty(recipient) ? "" : (" to " + recipient)));
                    return;
                }
            }
            catch { }

            // Automatic Browser Fallback when WhatsApp Desktop App is not installed!
            try
            {
                string webUrl = "https://web.whatsapp.com/";
                if (!string.IsNullOrEmpty(fullText) || !string.IsNullOrEmpty(phoneDigits))
                {
                    webUrl = "https://web.whatsapp.com/send?";
                    if (!string.IsNullOrEmpty(phoneDigits)) webUrl += "phone=" + phoneDigits + "&";
                    if (!string.IsNullOrEmpty(fullText)) webUrl += "text=" + Uri.EscapeDataString(fullText);
                }
                Process.Start(new ProcessStartInfo(webUrl) { UseShellExecute = true });
                LogAgentStep("\u2714 WhatsApp App not installed \u2014 Opened WhatsApp Web in Browser" + (string.IsNullOrEmpty(fullText) ? "" : (" with message: \"" + fullText + "\"")));
            }
            catch { }
        }

        private void LaunchYoutubeSearchAndAutoPlay(string query, bool autoPlayVideo)
        {
            string cleanQ = (query ?? "").Trim();
            if (string.IsNullOrEmpty(cleanQ))
            {
                try { Process.Start(new ProcessStartInfo("https://www.youtube.com") { UseShellExecute = true }); } catch { }
                LogAgentStep("\u2714 Opened YouTube in Browser");
                return;
            }

            if (autoPlayVideo && isPlaying)
            {
                this.BeginInvoke((MethodInvoker)delegate
                {
                    if (isPlaying) TogglePlayPause();
                });
            }

            ThreadPool.QueueUserWorkItem(_ =>
            {
                string targetUrl = "https://www.youtube.com/results?search_query=" + Uri.EscapeDataString(cleanQ);
                if (autoPlayVideo)
                {
                    try
                    {
                        using (WebClient wc = new WebClient())
                        {
                            wc.Encoding = Encoding.UTF8;
                            wc.Headers.Add("User-Agent", "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/122.0 Safari/537.36");
                            string html = wc.DownloadString(targetUrl);
                            Match m = Regex.Match(html ?? "", "\"videoId\":\"([a-zA-Z0-9_-]{11})\"");
                            if (m.Success)
                            {
                                targetUrl = "https://www.youtube.com/watch?v=" + m.Groups[1].Value + "&autoplay=1";
                            }
                        }
                    }
                    catch { }
                }
                try
                {
                    Process.Start(new ProcessStartInfo(targetUrl) { UseShellExecute = true });
                }
                catch { }
            });
            LogAgentStep("\u2714 YouTube " + (autoPlayVideo ? "Auto-Playing: \"" : "Searching: \"") + cleanQ + "\" in Browser");
        }

        private void SaveAgentNoteAndShow(string noteContent, bool openNotepadWindow)
        {
            string cleanNote = (noteContent ?? "").Trim();
            if (string.IsNullOrEmpty(cleanNote)) cleanNote = "Quick Reminder from Leo AI Agent";
            string stamped = "[" + DateTime.Now.ToString("yyyy-MM-dd HH:mm") + "] " + cleanNote;
            agentSavedNotes.Insert(0, stamped);
            try
            {
                File.AppendAllText(localNotesFilePath, stamped + Environment.NewLine, Encoding.UTF8);
                string deskNote = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory), "Leo_Agent_Notes.txt");
                File.AppendAllText(deskNote, stamped + Environment.NewLine, Encoding.UTF8);
                if (openNotepadWindow)
                {
                    Process.Start("notepad.exe", localNotesFilePath);
                }
            }
            catch { }
            LogAgentStep("\u2714 Saved Note: \"" + cleanNote + "\" (Leo_Agent_Notes.txt)");
        }

        private void LogAgentStep(string stepText)
        {
            this.BeginInvoke((MethodInvoker)delegate
            {
                agentExecutionLogs.Insert(0, stepText);
                if (agentExecutionLogs.Count > 24) agentExecutionLogs.RemoveAt(agentExecutionLogs.Count - 1);
                agentStatusSubtitle = stepText;
                ShowToast(stepText);
                this.Invalidate();
            });
        }

        private List<string> SplitCompoundAgentCommands(string rawInput)
        {
            List<string> result = new List<string>();
            if (string.IsNullOrEmpty(rawInput)) return result;

            string norm = NormalizeSpokenAgentTranscript(rawInput);
            norm = Regex.Replace(norm, @"open\s+whatsapp\s+(?:app\s+)?and\s+(message|send|text|write)\b", "open whatsapp $1", RegexOptions.IgnoreCase);
            norm = Regex.Replace(norm, @"open\s+youtube\s+and\s+search\s+(.+?)\s+and\s+play(?:\s+on\s+youtube)?", "play on youtube $1", RegexOptions.IgnoreCase);
            norm = Regex.Replace(norm, @"open\s+youtube\s+and\s+(play|search)\b", "youtube $1", RegexOptions.IgnoreCase);
            norm = Regex.Replace(norm, @"open\s+chatgpt\s+and\s+(ask|search|write|prompt)\b", "chatgpt $1", RegexOptions.IgnoreCase);
            norm = Regex.Replace(norm, @"open\s+notepad\s+and\s+(?:add\s+note|write\s+note|write|type)\b", "notepad note", RegexOptions.IgnoreCase);

            string pattern = @"\s*(?:;|\bthen\b|\band\s+(?=(?:open|launch|start|play|pause|resume|stop|next|prev|previous|skip|volume|set\s+volume|mute|unmute|add\s+note|write\s+note|note|message|send|chatgpt|ask\s+chatgpt|youtube|search|download|like|country|change\s+country|enable|disable|turn\s+on|turn\s+off|crossfade|mini|dynamic\s+bar|bar|fullscreen|lyrics|equalizer|settings|shuffle|repeat|take\s+screenshot|screenshot|check|remind|timer)\b))\s*";
            string[] parts = Regex.Split(norm, pattern, RegexOptions.IgnoreCase);
            foreach (string p in parts)
            {
                string trimmed = (p ?? "").Trim();
                if (!string.IsNullOrEmpty(trimmed)) result.Add(trimmed);
            }
            return result;
        }

        private void ExecuteAgentMultiTaskCommand(string rawCommand)
        {
            if (string.IsNullOrEmpty(rawCommand)) return;
            List<string> tasks = SplitCompoundAgentCommands(rawCommand);
            if (tasks.Count == 0) return;

            isAgentBusyExecuting = true;
            agentStatusSubtitle = "Executing " + tasks.Count + (tasks.Count == 1 ? " task..." : " multi-tasks in sequence...");
            this.Invalidate();

            Thread runner = new Thread(() =>
            {
                List<string> spokenSummary = new List<string>();
                for (int i = 0; i < tasks.Count; i++)
                {
                    string task = tasks[i].Trim();
                    string lower = task.ToLowerInvariant();

                    try
                    {
                        // 1. WHATSAPP APP / WEB MESSAGE AUTOMATION
                        if (lower.Contains("whatsapp") || lower.StartsWith("message ") || lower.StartsWith("send message "))
                        {
                            string msg = "";
                            string toWhom = "";
                            Match mTo = Regex.Match(task, @"(?:message|send|text|write)\s+(.+?)\s+to\s+(.+)$", RegexOptions.IgnoreCase);
                            if (mTo.Success)
                            {
                                msg = mTo.Groups[1].Value.Trim().Trim('"', '\'');
                                toWhom = mTo.Groups[2].Value.Trim().Trim('"', '\'');
                            }
                            else
                            {
                                Match mMsgOnly = Regex.Match(task, @"(?:message|send|text|write)\s+(.+)$", RegexOptions.IgnoreCase);
                                if (mMsgOnly.Success) msg = mMsgOnly.Groups[1].Value.Trim().Trim('"', '\'');
                            }
                            LaunchWhatsAppWithMessageOrFallbackBrowser(msg, toWhom);
                            spokenSummary.Add("Opened WhatsApp");
                        }
                        // 2. NOTES / NOTEPAD AUTOMATION
                        else if (lower.StartsWith("add note") || lower.StartsWith("write note") || lower.StartsWith("notepad note") || lower.StartsWith("note "))
                        {
                            string noteTxt = Regex.Replace(task, @"^(?:notepad\s+note|add\s+note|write\s+note|note)\s*:?\s*", "", RegexOptions.IgnoreCase).Trim();
                            SaveAgentNoteAndShow(noteTxt, true);
                            spokenSummary.Add("Saved note");
                        }
                        // 3. SMART REMINDER / TIMER ("remind me in 5 minutes to ...")
                        else if (lower.StartsWith("remind") || lower.StartsWith("set timer") || lower.StartsWith("timer "))
                        {
                            Match mMin = Regex.Match(lower, @"(\d+)\s*(?:min|minute|minutes|sec|second|seconds)");
                            int secs = 300;
                            if (mMin.Success)
                            {
                                int val = 5;
                                int.TryParse(mMin.Groups[1].Value, out val);
                                secs = lower.Contains("sec") ? Math.Max(5, val) : Math.Max(1, val) * 60;
                            }
                            string rText = Regex.Replace(task, @"^(?:remind\s+me\s+(?:in\s+\d+\s+\w+\s+)?(?:to\s+)?|set\s+timer\s+(?:for\s+\d+\s+\w+\s+)?|timer\s+\d+\s*\w*\s*)", "", RegexOptions.IgnoreCase).Trim();
                            if (string.IsNullOrEmpty(rText)) rText = "Scheduled Studio Reminder";
                            agentReminderSecondsLeft = secs;
                            agentReminderText = rText;
                            LogAgentStep("\u2714 Timer Set (" + FormatSec(secs) + "): \"" + rText + "\"");
                            spokenSummary.Add("Reminder set for " + (secs >= 60 ? ((secs / 60) + " minutes") : (secs + " seconds")));
                        }
                        // 4. SCREENSHOT CAPTURE
                        else if (lower.Contains("screenshot") || lower.Contains("capture screen"))
                        {
                            this.BeginInvoke((MethodInvoker)delegate { CapturePcScreenshotViaAgent(); });
                            spokenSummary.Add("Screenshot saved");
                        }
                        // 5. PC BATTERY & SYSTEM HEALTH CHECK
                        else if (lower.Contains("battery") || lower.Contains("pc status") || lower.Contains("system status") || lower.Contains("pc health"))
                        {
                            string health = GetPcSystemHealthSummary();
                            LogAgentStep("\u2714 PC Health: " + health);
                            spokenSummary.Add(health.Replace("\u2022", ","));
                        }
                        // 6. CHATGPT AUTOMATION
                        else if (lower.Contains("chatgpt"))
                        {
                            string prompt = Regex.Replace(task, @"^(?:open\s+chatgpt|chatgpt|ask\s+chatgpt)\s*(?:and\s+ask|ask|for|about|:)?\s*", "", RegexOptions.IgnoreCase).Trim();
                            string url = string.IsNullOrEmpty(prompt)
                                ? "https://chatgpt.com/"
                                : ("https://chatgpt.com/?q=" + Uri.EscapeDataString(prompt));
                            Process.Start(new ProcessStartInfo(url) { UseShellExecute = true });
                            LogAgentStep("\u2714 Opened ChatGPT" + (string.IsNullOrEmpty(prompt) ? "" : (" with prompt: \"" + prompt + "\"")));
                            spokenSummary.Add("Opened ChatGPT");
                        }
                        // 7. YOUTUBE SEARCH & AUTO-PLAY AUTOMATION
                        else if (lower.Contains("youtube"))
                        {
                            bool wantPlay = lower.Contains("play");
                            string ytQuery = Regex.Replace(task, @"^(?:play\s+on\s+youtube|open\s+youtube|youtube\s+play|youtube\s+search|youtube|search\s+youtube|play)\s*", "", RegexOptions.IgnoreCase);
                            ytQuery = Regex.Replace(ytQuery, @"\s*(?:and\s+play\s+on\s+youtube|on\s+youtube|in\s+youtube)$", "", RegexOptions.IgnoreCase).Trim();
                            if (!string.IsNullOrEmpty(ytQuery) && lower.Contains("play")) wantPlay = true;
                            LaunchYoutubeSearchAndAutoPlay(ytQuery, wantPlay);
                            spokenSummary.Add(wantPlay ? ("Playing " + ytQuery + " on YouTube") : "Opened YouTube");
                        }
                        // 8. PLAY SONG IN LEO MUSIC STUDIO
                        else if (lower.StartsWith("play song") || (lower.StartsWith("play ") && !lower.Contains("youtube") && lower != "play" && lower != "play music"))
                        {
                            string songQ = Regex.Replace(task, @"^(?:play\s+song|play\s+music|play\s+track|play)\s+", "", RegexOptions.IgnoreCase).Trim();
                            SongItem preMatch = FindBestFuzzySongMatch(songQ);
                            if (preMatch != null) songQ = CleanSongDisplayTitle(preMatch.Title);
                            if (!string.IsNullOrEmpty(songQ))
                            {
                                SongItem bestLocal = FindBestFuzzySongMatch(songQ);
                                if (bestLocal != null)
                                {
                                    SongItem toPlay = bestLocal;
                                    this.BeginInvoke((MethodInvoker)delegate { PlaySong(toPlay, false); });
                                    LogAgentStep("\u2714 Playing in Leo Music: " + toPlay.Title + " \u2022 " + toPlay.Artist);
                                    spokenSummary.Add("Playing " + CleanSongDisplayTitle(toPlay.Title));
                                }
                                else
                                {
                                    try
                                    {
                                        string apiUrl = "https://www.jiosaavn.com/api.php?__call=search.getResults&_format=json&n=8&p=1&_marker=0&ctx=android&q=" + Uri.EscapeDataString(songQ);
                                        using (WebClient wc = new WebClient())
                                        {
                                            wc.Encoding = Encoding.UTF8;
                                            wc.Headers.Add("User-Agent", "Mozilla/5.0");
                                            string json = wc.DownloadString(apiUrl);
                                            List<SongItem> found = ParseOfficialJioSaavnJson(json);
                                            if (found != null && found.Count > 0)
                                            {
                                                SongItem topHit = found[0];
                                                this.BeginInvoke((MethodInvoker)delegate
                                                {
                                                    if (!ContainsSongByTitleOrId(catalog, topHit)) catalog.Insert(0, topHit);
                                                    PlaySong(topHit, false);
                                                });
                                                LogAgentStep("\u2714 Playing in Leo Music: " + topHit.Title + " \u2022 " + topHit.Artist);
                                                spokenSummary.Add("Playing " + CleanSongDisplayTitle(topHit.Title));
                                            }
                                        }
                                    }
                                    catch { }
                                }
                            }
                        }
                        // 9. LEO MUSIC APP CONTROLS
                        else if (lower == "pause" || lower == "stop" || lower == "pause music" || lower == "stop music")
                        {
                            this.BeginInvoke((MethodInvoker)delegate { if (isPlaying) TogglePlayPause(); });
                            LogAgentStep("\u2714 Paused Leo Music Playback");
                            spokenSummary.Add("Music paused");
                        }
                        else if (lower == "play" || lower == "resume" || lower == "resume music" || lower == "play music")
                        {
                            this.BeginInvoke((MethodInvoker)delegate { if (!isPlaying) TogglePlayPause(); });
                            LogAgentStep("\u2714 Resumed Leo Music Playback");
                            spokenSummary.Add("Music playing");
                        }
                        else if (lower.Contains("next") || lower == "skip")
                        {
                            this.BeginInvoke((MethodInvoker)delegate { NextTrack(); });
                            LogAgentStep("\u2714 Skipped to Next Track");
                            spokenSummary.Add("Next track");
                        }
                        else if (lower.Contains("prev") || lower.Contains("previous"))
                        {
                            this.BeginInvoke((MethodInvoker)delegate { PrevTrack(); });
                            LogAgentStep("\u2714 Returned to Previous Track");
                            spokenSummary.Add("Previous track");
                        }
                        else if (lower.Contains("volume") || lower == "mute" || lower == "unmute")
                        {
                            if (lower == "mute")
                            {
                                this.BeginInvoke((MethodInvoker)delegate { if (!isMuted) ToggleMute(); });
                                LogAgentStep("\u2714 Muted Leo Music Audio");
                            }
                            else if (lower == "unmute")
                            {
                                this.BeginInvoke((MethodInvoker)delegate { if (isMuted) ToggleMute(); });
                                LogAgentStep("\u2714 Unmuted Leo Music Audio");
                            }
                            else
                            {
                                Match mv = Regex.Match(lower, @"(\d+)");
                                int targetV = volumePercent + (lower.Contains("down") ? -15 : 15);
                                if (mv.Success) int.TryParse(mv.Groups[1].Value, out targetV);
                                targetV = Math.Max(0, Math.Min(150, targetV));
                                this.BeginInvoke((MethodInvoker)delegate { SetVolume(targetV); });
                                LogAgentStep("\u2714 Volume Set to " + targetV + "%");
                                spokenSummary.Add("Volume " + targetV + " percent");
                            }
                        }
                        else if (lower.Contains("download"))
                        {
                            if (lower.Contains("open"))
                            {
                                this.BeginInvoke((MethodInvoker)delegate
                                {
                                    activeTab = 3;
                                    isFullPlayerExpanded = false;
                                    isAgentPanelOpen = false;
                                    UnfocusAgentCommandBox();
                                    FilterDisplaySongs();
                                    this.Invalidate();
                                });
                                LogAgentStep("\u2714 Opened Offline Downloads Tab (" + downloadedSongs.Count + " Songs)");
                            }
                            else
                            {
                                this.BeginInvoke((MethodInvoker)delegate { DownloadSongDirectly(currentSong); });
                                LogAgentStep("\u2714 Downloading Current Song to Local Folder");
                            }
                            spokenSummary.Add("Downloads updated");
                        }
                        else if (lower.Contains("crossfade"))
                        {
                            if (lower.Contains("off") || lower.Contains("disable"))
                            {
                                this.BeginInvoke((MethodInvoker)delegate
                                {
                                    crossfadeEnabled = false;
                                    StopCrossfadeDeckBImmediately();
                                    SavePersistentSettings();
                                    this.Invalidate();
                                });
                                LogAgentStep("\u2714 Crossfade Turned Off");
                                spokenSummary.Add("Crossfade off");
                            }
                            else
                            {
                                Match mc = Regex.Match(lower, @"(\d+)");
                                int cfSec = crossfadeSeconds;
                                if (mc.Success) int.TryParse(mc.Groups[1].Value, out cfSec);
                                cfSec = Math.Max(1, Math.Min(12, cfSec));
                                this.BeginInvoke((MethodInvoker)delegate
                                {
                                    crossfadeSeconds = cfSec;
                                    crossfadeEnabled = true;
                                    SavePersistentSettings();
                                    this.Invalidate();
                                });
                                LogAgentStep("\u2714 Crossfade Enabled (" + cfSec + "s Overlap)");
                                spokenSummary.Add("Crossfade " + cfSec + " seconds");
                            }
                        }
                        else if (lower.Contains("country"))
                        {
                            foreach (string cName in availableCountries)
                            {
                                if (lower.Contains(cName.ToLowerInvariant()))
                                {
                                    string targetC = cName;
                                    this.BeginInvoke((MethodInvoker)delegate
                                    {
                                        selectedCountry = targetC;
                                        RebuildHomepageAndQueueForCountryAndLanguages(true);
                                        SavePersistentSettings();
                                        this.Invalidate();
                                    });
                                    LogAgentStep("\u2714 Switched Country to " + targetC);
                                    spokenSummary.Add("Switched country to " + targetC);
                                    break;
                                }
                            }
                        }
                        else if (lower.Contains("ai dj") || lower.Contains("smart mix"))
                        {
                            this.BeginInvoke((MethodInvoker)delegate { StartSmartAiDjAutoPilotMix(); });
                            LogAgentStep("\u2714 Started Smart AI DJ Mix");
                            spokenSummary.Add("Started AI DJ Mix");
                        }
                        else if (lower.Contains("3d"))
                        {
                            this.BeginInvoke((MethodInvoker)delegate { CycleHeadphone3DMode(); });
                            LogAgentStep("\u2714 Cycled 3D Headphone Stage");
                            spokenSummary.Add("3D audio updated");
                        }
                        else if (lower.Contains("lyrics"))
                        {
                            this.BeginInvoke((MethodInvoker)delegate
                            {
                                isAgentPanelOpen = false;
                                UnfocusAgentCommandBox();
                                isFullPlayerExpanded = true;
                                fullViewSubMode = 2;
                                this.Invalidate();
                            });
                            LogAgentStep("\u2714 Opened Full-Screen YouLy+ Synced Lyrics");
                            spokenSummary.Add("Opened lyrics");
                        }
                        else if (lower.Contains("equalizer") || lower.Contains("settings"))
                        {
                            this.BeginInvoke((MethodInvoker)delegate
                            {
                                isAgentPanelOpen = false;
                                UnfocusAgentCommandBox();
                                isFullPlayerExpanded = false;
                                activeTab = 4;
                                activeSettingsSubPage = lower.Contains("equalizer") ? 1 : 0;
                                this.Invalidate();
                            });
                            LogAgentStep("\u2714 Opened Studio Settings & Equalizer");
                            spokenSummary.Add("Opened settings");
                        }
                        else if (lower.Contains("mini"))
                        {
                            this.BeginInvoke((MethodInvoker)delegate { ToggleMiniPlayerMode(); });
                            LogAgentStep("\u2714 Toggled Mini-Player Mode");
                        }
                        else if (lower.Contains("dynamic bar") || lower == "bar")
                        {
                            this.BeginInvoke((MethodInvoker)delegate { ToggleDynamicBarMode(); });
                            LogAgentStep("\u2714 Toggled Dynamic Bar Overlay");
                        }
                        // 10. SMART CONVERSATIONAL & PC APP LAUNCHER
                        else
                        {
                            ExecuteSmartIntentOrPcApp(task, spokenSummary);
                        }
                    }
                    catch { }

                    if (i + 1 < tasks.Count) Thread.Sleep(350);
                }

                this.BeginInvoke((MethodInvoker)delegate
                {
                    isAgentBusyExecuting = false;
                    this.Invalidate();
                });

                if (spokenSummary.Count > 0)
                {
                    SpeakVoiceTextAsync(string.Join(", ", spokenSummary.ToArray()));
                }
            });
            runner.IsBackground = true;
            runner.Start();
        }

        private void ExecuteSmartIntentOrPcApp(string rawTask, List<string> spokenSummary)
        {
            string q = (rawTask ?? "").Trim();
            string lower = q.ToLowerInvariant();
            bool hasExplicitLaunchVerb = Regex.IsMatch(lower, @"^(?:open|launch|start|run|search|google)\b");
            string appTarget = Regex.Replace(q, @"^(?:open|launch|start|run)\s+", "", RegexOptions.IgnoreCase).Trim();
            string appLower = appTarget.ToLowerInvariant();

            try
            {
                // A. Conversational AI Questions (Time, Current Song, Greeting, Identity)
                if (lower.Contains("what time") || lower == "time")
                {
                    string tStr = DateTime.Now.ToString("h:mm tt");
                    LogAgentStep("\u2726 Current Time: " + tStr + " (" + DateTime.Now.ToString("dddd, MMM d") + ")");
                    spokenSummary.Add("It is " + tStr);
                    return;
                }
                if (lower.Contains("what song") || lower.Contains("which song") || lower.Contains("playing now"))
                {
                    string sInfo = currentSong != null ? (CleanSongDisplayTitle(currentSong.Title) + " by " + GetPrimaryArtistName(currentSong.Artist)) : "No song playing";
                    LogAgentStep("\u2726 Now Playing: " + sInfo);
                    spokenSummary.Add("Now playing " + sInfo);
                    return;
                }
                if (lower == "hello" || lower == "hi" || lower.Contains("who are you") || lower.Contains("how are you"))
                {
                    string reply = "Hello " + userName + "! I am Leo AI Assistant. Ask me to open apps, send WhatsApp messages, play songs, or control your PC.";
                    LogAgentStep("\u2726 " + reply);
                    spokenSummary.Add(reply);
                    return;
                }

                // B. Known PC Applications & Web Destinations
                if (appLower.Contains("calculator") || appLower == "calc")
                {
                    Process.Start("calc.exe");
                    LogAgentStep("\u2714 Launched Windows Calculator");
                    spokenSummary.Add("Opened Calculator");
                    return;
                }
                if (appLower.Contains("notepad"))
                {
                    Process.Start("notepad.exe");
                    LogAgentStep("\u2714 Launched Windows Notepad");
                    spokenSummary.Add("Opened Notepad");
                    return;
                }
                if (appLower.Contains("paint"))
                {
                    Process.Start("mspaint.exe");
                    LogAgentStep("\u2714 Launched Microsoft Paint");
                    spokenSummary.Add("Opened Paint");
                    return;
                }
                if (appLower.Contains("explorer") || appLower.Contains("files") || appLower.Contains("my computer"))
                {
                    Process.Start("explorer.exe", downloadsFolder);
                    LogAgentStep("\u2714 Opened Windows File Explorer");
                    spokenSummary.Add("Opened File Explorer");
                    return;
                }
                if (appLower.Contains("task manager"))
                {
                    Process.Start("taskmgr.exe");
                    LogAgentStep("\u2714 Launched Windows Task Manager");
                    spokenSummary.Add("Opened Task Manager");
                    return;
                }
                if (appLower == "cmd" || appLower.Contains("command prompt") || appLower.Contains("terminal"))
                {
                    Process.Start("cmd.exe");
                    LogAgentStep("\u2714 Launched Windows Command Prompt");
                    spokenSummary.Add("Opened Command Prompt");
                    return;
                }
                if (appLower.Contains("camera"))
                {
                    Process.Start(new ProcessStartInfo("microsoft.windows.camera:") { UseShellExecute = true });
                    LogAgentStep("\u2714 Launched Windows Camera");
                    spokenSummary.Add("Opened Camera");
                    return;
                }
                if (appLower.Contains("pc settings") || appLower.Contains("windows settings"))
                {
                    Process.Start(new ProcessStartInfo("ms-settings:") { UseShellExecute = true });
                    LogAgentStep("\u2714 Opened Windows System Settings");
                    spokenSummary.Add("Opened Windows Settings");
                    return;
                }
                if (appLower.Contains("chrome"))
                {
                    try { Process.Start(new ProcessStartInfo("chrome.exe") { UseShellExecute = true }); }
                    catch { Process.Start(new ProcessStartInfo("https://www.google.com") { UseShellExecute = true }); }
                    LogAgentStep("\u2714 Opened Google Chrome / Browser");
                    spokenSummary.Add("Opened Chrome");
                    return;
                }
                if (appLower.Contains("brave"))
                {
                    try { Process.Start(new ProcessStartInfo("brave.exe") { UseShellExecute = true }); }
                    catch { Process.Start(new ProcessStartInfo("https://search.brave.com") { UseShellExecute = true }); }
                    LogAgentStep("\u2714 Opened Brave Browser");
                    spokenSummary.Add("Opened Brave");
                    return;
                }
                if (appLower.Contains("edge"))
                {
                    Process.Start(new ProcessStartInfo("microsoft-edge:https://www.bing.com") { UseShellExecute = true });
                    LogAgentStep("\u2714 Opened Microsoft Edge");
                    spokenSummary.Add("Opened Edge");
                    return;
                }
                if (appLower.Contains("gmail") || appLower.Contains("mail"))
                {
                    Process.Start(new ProcessStartInfo("https://mail.google.com") { UseShellExecute = true });
                    LogAgentStep("\u2714 Opened Gmail in Browser");
                    spokenSummary.Add("Opened Gmail");
                    return;
                }
                if (appLower.Contains("instagram"))
                {
                    Process.Start(new ProcessStartInfo("https://www.instagram.com") { UseShellExecute = true });
                    LogAgentStep("\u2714 Opened Instagram in Browser");
                    spokenSummary.Add("Opened Instagram");
                    return;
                }
                if (appLower.Contains("telegram"))
                {
                    Process.Start(new ProcessStartInfo("https://web.telegram.org") { UseShellExecute = true });
                    LogAgentStep("\u2714 Opened Telegram Web in Browser");
                    spokenSummary.Add("Opened Telegram");
                    return;
                }
                if (appLower.Contains("github"))
                {
                    Process.Start(new ProcessStartInfo("https://github.com") { UseShellExecute = true });
                    LogAgentStep("\u2714 Opened GitHub in Browser");
                    spokenSummary.Add("Opened GitHub");
                    return;
                }
                if (lower.StartsWith("search google") || lower.StartsWith("google "))
                {
                    string gq = Regex.Replace(q, @"^(?:search\s+google\s+for|search\s+google|google)\s+", "", RegexOptions.IgnoreCase).Trim();
                    Process.Start(new ProcessStartInfo("https://www.google.com/search?q=" + Uri.EscapeDataString(gq)) { UseShellExecute = true });
                    LogAgentStep("\u2714 Google Search: \"" + gq + "\"");
                    spokenSummary.Add("Searched Google for " + gq);
                    return;
                }
                if (appLower.StartsWith("http://") || appLower.StartsWith("https://") || appLower.Contains(".com") || appLower.Contains(".org") || appLower.Contains(".in"))
                {
                    string url = appLower.StartsWith("http") ? appTarget : ("https://" + appTarget);
                    Process.Start(new ProcessStartInfo(url) { UseShellExecute = true });
                    LogAgentStep("\u2714 Opened Website: " + url);
                    spokenSummary.Add("Opened website");
                    return;
                }

                // C. High-Smart Fuzzy & Half-Word Song Match (even when user types half or wrong song name directly)
                SongItem fuzzyMatchedSong = FindBestFuzzySongMatch(appTarget);
                if (fuzzyMatchedSong != null && !hasExplicitLaunchVerb)
                {
                    SongItem matchedSong = fuzzyMatchedSong;
                    this.BeginInvoke((MethodInvoker)delegate { PlaySong(matchedSong, false); });
                    LogAgentStep("\u2714 Smart Fuzzy Match \u2014 Playing: " + matchedSong.Title + " \u2022 " + matchedSong.Artist);
                    spokenSummary.Add("Playing " + CleanSongDisplayTitle(matchedSong.Title));
                    return;
                }

                // D. Only launch unknown app/browser fallback if the user EXPLICITLY said "open ...", "launch ...", "start ...", or "search ..."
                // This prevents random background mic noise (like "But who don't have") from opening unwanted browser tabs!
                if (hasExplicitLaunchVerb)
                {
                    try
                    {
                        Process.Start(new ProcessStartInfo(appTarget) { UseShellExecute = true });
                        LogAgentStep("\u2714 Launched on PC: " + appTarget);
                        spokenSummary.Add("Opened " + appTarget);
                    }
                    catch
                    {
                        string fallbackWeb = "https://www.google.com/search?q=" + Uri.EscapeDataString(appTarget);
                        Process.Start(new ProcessStartInfo(fallbackWeb) { UseShellExecute = true });
                        LogAgentStep("\u2714 App \"" + appTarget + "\" not installed locally \u2014 Opened in Browser");
                        spokenSummary.Add("Opened " + appTarget + " in browser");
                    }
                }
                else
                {
                    LogAgentStep("\u25C9 Heard: \"" + q + "\" \u2014 Say 'open [app]', 'play [song]', 'add note [text]', or click Run to search.");
                }
            }
            catch { }
        }

        private void PaintSiriGoogleAssistantOrb(Graphics g, Rectangle orbRect, bool isActiveOrListening, StringFormat sfCenter)
        {
            if (orbRect.Width <= 8 || orbRect.Height <= 8) return;
            SmoothingMode prevSm = g.SmoothingMode;
            g.SmoothingMode = SmoothingMode.AntiAlias;

            float cx = orbRect.X + orbRect.Width / 2f;
            float cy = orbRect.Y + orbRect.Height / 2f;
            float rad = Math.Min(orbRect.Width, orbRect.Height) / 2f;
            float angleDeg = (agentOrbPhase * 52f) % 360f;

            // Subtle ambient outer glow
            float pulse = (float)Math.Sin(agentOrbPhase * 2.2f) * (isActiveOrListening ? 3.5f : 1.8f);
            Color glowCol = isActiveOrListening ? Color.FromArgb(62, 0, 235, 145) : Color.FromArgb(46, 0, 225, 255);
            using (SolidBrush gb = new SolidBrush(glowCol))
            {
                g.FillEllipse(gb, orbRect.X - 3f - pulse, orbRect.Y - 3f - pulse, orbRect.Width + 6f + pulse * 2f, orbRect.Height + 6f + pulse * 2f);
            }

            // Deep Obsidian Sphere Core
            using (LinearGradientBrush coreB = new LinearGradientBrush(
                orbRect,
                Color.FromArgb(250, 18, 22, 34),
                Color.FromArgb(254, 9, 12, 20),
                LinearGradientMode.ForwardDiagonal))
            {
                g.FillEllipse(coreB, orbRect);
            }

            Rectangle ringRect = new Rectangle(orbRect.X + 2, orbRect.Y + 2, orbRect.Width - 4, orbRect.Height - 4);
            int style = Math.Max(0, Math.Min(3, aiOrbStyleIdx));

            if (style == 0)
            {
                // DESIGN 0: SIRI SILK RING (Glowing multi-stop cyan/magenta/violet neon ring + silk arcs + center sparkle)
                using (LinearGradientBrush rg = new LinearGradientBrush(orbRect, Color.FromArgb(0, 235, 255), Color.FromArgb(245, 65, 255), angleDeg))
                using (Pen rp = new Pen(rg, 3.0f))
                {
                    g.DrawEllipse(rp, ringRect);
                }
                Rectangle innerArc = new Rectangle(orbRect.X + 6, orbRect.Y + 6, Math.Max(8, orbRect.Width - 12), Math.Max(8, orbRect.Height - 12));
                using (Pen ap = new Pen(Color.FromArgb(185, 80, 245, 255), 1.8f))
                {
                    g.DrawArc(ap, innerArc, angleDeg, 125f);
                    g.DrawArc(ap, innerArc, angleDeg + 180f, 125f);
                }
                using (Font fSym = new Font("Segoe UI", Math.Max(8.5f, rad * 0.52f), FontStyle.Bold))
                using (SolidBrush sb = new SolidBrush(isActiveOrListening ? Color.FromArgb(50, 250, 165) : Color.White))
                {
                    g.DrawString("\u2726", fSym, sb, orbRect, sfCenter);
                }
            }
            else if (style == 1)
            {
                // DESIGN 1: GOOGLE HALO (4 smooth 90-degree colored arc segments around a dark crystal core)
                Color[] gCols = new Color[]
                {
                    Color.FromArgb(255, 66, 133, 244),
                    Color.FromArgb(255, 234, 67, 53),
                    Color.FromArgb(255, 251, 188, 5),
                    Color.FromArgb(255, 52, 168, 83)
                };
                for (int i = 0; i < 4; i++)
                {
                    using (Pen segP = new Pen(gCols[i], 3.2f))
                    {
                        segP.StartCap = LineCap.Round;
                        segP.EndCap = LineCap.Round;
                        g.DrawArc(segP, ringRect, angleDeg + i * 90f, 70f);
                    }
                }
                using (Font fAi = new Font("Segoe UI", Math.Max(7.5f, rad * 0.40f), FontStyle.Bold))
                {
                    g.DrawString("AI", fAi, Brushes.White, orbRect, sfCenter);
                }
            }
            else if (style == 2)
            {
                // DESIGN 2: CYBER NEON PULSE (Concentric glowing neon ring + live 5-bar equalizer inside)
                using (Pen pOut = new Pen(Color.FromArgb(230, 0, 235, 255), 2.4f))
                {
                    g.DrawEllipse(pOut, ringRect);
                }
                int bars = 5;
                int totalW = Math.Max(14, (int)(orbRect.Width * 0.48f));
                int sp = totalW / bars;
                int sx = (int)cx - totalW / 2 + 2;
                for (int b = 0; b < bars; b++)
                {
                    float wv = (float)Math.Abs(Math.Sin(agentOrbPhase * 2.8f + b * 0.85f));
                    int bh = Math.Max(4, (int)(rad * 0.76f * (0.35f + 0.65f * wv)));
                    Rectangle br = new Rectangle(sx + b * sp, (int)cy - bh / 2, Math.Max(2, sp - 2), bh);
                    using (SolidBrush bb = new SolidBrush(b % 2 == 0 ? Color.FromArgb(0, 230, 255) : Color.FromArgb(195, 90, 255)))
                    {
                        g.FillRectangle(bb, br);
                    }
                }
            }
            else
            {
                // DESIGN 3: MINIMAL GLASS GEM (Smoked-crystal circle with theme accent rim & ✦ AI emblem)
                using (Pen rimP = new Pen(Color.FromArgb(230, accentColor), 2.5f))
                {
                    g.DrawEllipse(rimP, ringRect);
                }
                using (Font fGem = new Font("Segoe UI", Math.Max(7.2f, rad * 0.38f), FontStyle.Bold))
                using (SolidBrush sb = new SolidBrush(accentColor))
                {
                    g.DrawString("\u2726 AI", fGem, sb, orbRect, sfCenter);
                }
            }

            g.SmoothingMode = prevSm;
        }

        private void PaintFloatingDesktopAgentWidget(Graphics g, int w, int h, StringFormat sfCenter, StringFormat sfLeftEllipsis)
        {
            g.Clear(Color.FromArgb(255, 9, 11, 17));
            if (!isAgentDesktopExpanded)
            {
                Rectangle orbR = new Rectangle(6, 6, w - 12, h - 12);
                PaintSiriGoogleAssistantOrb(g, orbR, isAgentListeningVoice || isAgentBusyExecuting, sfCenter);
                using (Font fTiny = new Font("Segoe UI", 7.2f, FontStyle.Bold))
                using (SolidBrush badgeB = new SolidBrush(Color.FromArgb(210, 8, 10, 18)))
                {
                    Rectangle pill = new Rectangle(w / 2 - 18, h - 20, 36, 15);
                    FillRoundRect(g, badgeB, pill, 7);
                    g.DrawString("LEO AI", fTiny, Brushes.White, pill, sfCenter);
                }
                return;
            }

            // Expanded 490x310 Desktop AI & Music Control Hub
            Rectangle outer = new Rectangle(1, 1, w - 3, h - 3);
            using (LinearGradientBrush bg = new LinearGradientBrush(outer, Color.FromArgb(252, 16, 18, 28), Color.FromArgb(254, 10, 11, 18), LinearGradientMode.Vertical))
            using (Pen rim = new Pen(Color.FromArgb(145, 0, 242, 254), 1.4f))
            {
                FillRoundRect(g, bg, outer, 22);
                DrawRoundRect(g, rim, outer, 22);
            }

            Rectangle miniOrb = new Rectangle(14, 12, 44, 44);
            PaintSiriGoogleAssistantOrb(g, miniOrb, isAgentListeningVoice || isAgentBusyExecuting, sfCenter);

            using (Font fHdr = new Font("Segoe UI", 10.2f, FontStyle.Bold))
            using (SolidBrush subB = new SolidBrush(Color.FromArgb(195, 210, 220, 235)))
            {
                g.DrawString("Leo AI Desktop Agent", fHdr, Brushes.White, new RectangleF(66, 12, w - 230, 20), sfLeftEllipsis);
                g.DrawString(agentStatusSubtitle, fontSmallBold, subB, new RectangleF(66, 33, w - 230, 18), sfLeftEllipsis);
            }

            Rectangle btnMic  = new Rectangle(w - 156, 14, 44, 28);
            Rectangle btnShot = new Rectangle(w - 108, 14, 42, 28);
            Rectangle btnFull = new Rectangle(w - 62,  14, 32, 28);
            Rectangle btnMin  = new Rectangle(w - 26,  14, 18, 28);
            using (SolidBrush mb = new SolidBrush(isAgentListeningVoice ? Color.FromArgb(234, 67, 53) : Color.FromArgb(55, 66, 133, 244)))
            using (SolidBrush sb = new SolidBrush(Color.FromArgb(40, 255, 255, 255)))
            using (SolidBrush fb = new SolidBrush(accentColor))
            using (SolidBrush cb = new SolidBrush(Color.FromArgb(35, 255, 255, 255)))
            {
                FillRoundRect(g, mb, btnMic, 8);
                FillRoundRect(g, sb, btnShot, 8);
                FillRoundRect(g, fb, btnFull, 8);
                FillRoundRect(g, cb, btnMin, 8);
            }
            g.DrawString("Mic", fontSmallBold, Brushes.White, btnMic, sfCenter);
            g.DrawString("Shot", fontSmallBold, Brushes.White, btnShot, sfCenter);
            g.DrawString("App", fontSmallBold, Brushes.White, btnFull, sfCenter);
            g.DrawString("\u2013", fontSmallBold, Brushes.White, btnMin, sfCenter);

            Rectangle inputPill = new Rectangle(16, 66, w - 106, 34);
            using (SolidBrush ib = new SolidBrush(Color.FromArgb(24, 26, 38)))
            using (Pen ip = new Pen(Color.FromArgb(130, 0, 242, 254), 1.2f))
            {
                FillRoundRect(g, ib, inputPill, 10);
                DrawRoundRect(g, ip, inputPill, 10);
            }

            Rectangle runBtn = new Rectangle(w - 84, 66, 68, 34);
            using (SolidBrush rb = new SolidBrush(accentColor))
            {
                FillRoundRect(g, rb, runBtn, 10);
            }
            g.DrawString("\u25B6 Run", fontSmallBold, Brushes.White, runBtn, sfCenter);

            string[] quickChips = new string[] { "WhatsApp", "Add Note", "ChatGPT", "YouTube", "Multi-Task", "PC Status" };
            int chipW = (w - 32 - 5 * 6) / 6;
            for (int i = 0; i < quickChips.Length; i++)
            {
                Rectangle cr = new Rectangle(16 + i * (chipW + 6), 108, chipW, 24);
                using (SolidBrush cb = new SolidBrush(Color.FromArgb(36, 255, 255, 255)))
                using (Pen cp = new Pen(Color.FromArgb(45, 255, 255, 255), 1f))
                {
                    FillRoundRect(g, cb, cr, 8);
                    DrawRoundRect(g, cp, cr, 8);
                }
                g.DrawString(quickChips[i], fontSmallBold, Brushes.White, cr, sfCenter);
            }

            int logY = 140;
            using (SolidBrush lb = new SolidBrush(Color.FromArgb(205, 220, 228, 240)))
            {
                for (int i = 0; i < Math.Min(4, agentExecutionLogs.Count); i++)
                {
                    g.DrawString(agentExecutionLogs[i], fontSmallBold, lb, new RectangleF(18, logY + i * 22, w - 36, 19), sfLeftEllipsis);
                }
