                    g.DrawString(GetPrimaryArtistName(currentSong.Artist), fontSmallBold, sb, new RectangleF(miniBar.X + 52, miniBar.Y + 24, miniBar.Width - 190, 16), sfLeftEllipsis);
                }
            }
            int mCy = miniBar.Y + 24;
            Rectangle prevW = new Rectangle(miniBar.Right - 118, mCy - 12, 24, 24);
            Rectangle playW = new Rectangle(miniBar.Right - 86,  mCy - 14, 28, 28);
            Rectangle nextW = new Rectangle(miniBar.Right - 50,  mCy - 12, 24, 24);
            using (SolidBrush ab = new SolidBrush(accentColor))
            {
                g.FillEllipse(ab, playW);
            }
            DrawSkipPrevIcon(g, Brushes.White, prevW.X + 12f, mCy);
            if (isPlaying) DrawPauseBars(g, Brushes.White, playW.X + 14f, mCy, 2.8f, 9f, 3f);
            else DrawPlayTriangle(g, Brushes.White, playW.X + 14f, mCy, 6.5f);
            DrawSkipNextIcon(g, Brushes.White, nextW.X + 12f, mCy);
        }

        private void PaintAiAgentCommandOverlay(Graphics g, int w, int h, float anim, StringFormat sfCenter, StringFormat sfLeftEllipsis)
        {
            // Deep High-Contrast Backdrop Scrim so Homepage text/cards ("Roots") never bleed through!
            using (SolidBrush scrim = new SolidBrush(Color.FromArgb((int)(238 * anim), 4, 5, 10)))
            {
                g.FillRectangle(scrim, 0, 0, w, h);
            }

            int mw = Math.Min(880, w - 56);
            int mh = Math.Min(568, h - 48);
            int mx = (w - mw) / 2;
            int my = (h - mh) / 2;
            Rectangle modal = new Rectangle(mx, my, mw, mh);

            // Opaque Deep Obsidian-Crystal Modal Card (Zero background bleed-through)
            using (SolidBrush shB = new SolidBrush(Color.FromArgb(140, 0, 0, 0)))
            {
                FillRoundRect(g, shB, new Rectangle(modal.X + 2, modal.Y + 6, modal.Width, modal.Height), 22);
            }
            using (LinearGradientBrush cardGrad = new LinearGradientBrush(
                new Rectangle(modal.X, modal.Y - 1, modal.Width, modal.Height + 2),
                Color.FromArgb(252, 16, 18, 28),
                Color.FromArgb(254, 10, 11, 18),
                LinearGradientMode.Vertical))
            using (Pen cardRim = new Pen(Color.FromArgb(145, 0, 242, 254), 1.4f))
            {
                FillRoundRect(g, cardGrad, modal, 22);
                DrawRoundRect(g, cardRim, modal, 22);
            }

            // Top Siri + Google Assistant Animated Circular Orb (`mx + 22, my + 16, 62x62`)
            Rectangle centerOrb = new Rectangle(mx + 22, my + 16, 62, 62);
            PaintSiriGoogleAssistantOrb(g, centerOrb, isAgentListeningVoice || isAgentBusyExecuting, sfCenter);

            // Top-Right Controls (`my + 20`) — Positioned with generous width & zero overlap with title!
            Rectangle micBtn   = new Rectangle(modal.Right - 348, my + 20, 92, 30);
            Rectangle ttsBtn   = new Rectangle(modal.Right - 250, my + 20, 82, 30);
            Rectangle floatBtn = new Rectangle(modal.Right - 162, my + 20, 110, 30);
            Rectangle closeBtn = new Rectangle(modal.Right - 44,  my + 20, 28, 30);

            int titleMaxW = Math.Max(180, micBtn.X - (mx + 98) - 12);
            using (Font fTitle = new Font("Segoe UI", 13.5f, FontStyle.Bold))
            using (SolidBrush subB = new SolidBrush(Color.FromArgb(210, 220, 228, 242)))
            using (SolidBrush sysB = new SolidBrush(Color.FromArgb(190, 0, 230, 118)))
            {
                g.DrawString("Leo AI Assistant  \u2022  Siri & Google PC Agent", fTitle, Brushes.White, new RectangleF(mx + 96, my + 14, titleMaxW, 24), sfLeftEllipsis);
                g.DrawString(agentStatusSubtitle, fontSmallBold, subB, new RectangleF(mx + 96, my + 40, titleMaxW, 19), sfLeftEllipsis);
                g.DrawString("\u25C9 " + GetPcSystemHealthSummary(), fontSmallBold, sysB, new RectangleF(mx + 96, my + 60, modal.Width - 118, 18), sfLeftEllipsis);
            }

            using (SolidBrush bMic = new SolidBrush(isAgentListeningVoice ? Color.FromArgb(234, 67, 53) : Color.FromArgb(65, 66, 133, 244)))
            using (SolidBrush bTts = new SolidBrush(voiceWelcomeEnabled ? Color.FromArgb(52, 0, 230, 118) : Color.FromArgb(36, 255, 255, 255)))
            using (SolidBrush bFlt = new SolidBrush(Color.FromArgb(65, accentColor.R, accentColor.G, accentColor.B)))
            using (SolidBrush bCls = new SolidBrush(Color.FromArgb(40, 255, 255, 255)))
            using (Pen pMic = new Pen(isAgentListeningVoice ? Color.White : Color.FromArgb(140, 66, 133, 244), 1f))
            {
                FillRoundRect(g, bMic, micBtn, 10);
                DrawRoundRect(g, pMic, micBtn, 10);
                FillRoundRect(g, bTts, ttsBtn, 10);
                FillRoundRect(g, bFlt, floatBtn, 10);
                FillRoundRect(g, bCls, closeBtn, 10);
            }
            g.DrawString(isAgentListeningVoice ? "\u25C9 Speak Now" : "\u25C9 Voice Mic", fontSmallBold, Brushes.White, micBtn, sfCenter);
            g.DrawString("Voice: " + (voiceWelcomeEnabled ? "ON" : "OFF"), fontSmallBold, Brushes.White, ttsBtn, sfCenter);
            g.DrawString("\u25C9 Float Widget", fontSmallBold, Brushes.White, floatBtn, sfCenter);
            g.DrawString("\u2715", fontSmallBold, Brushes.White, closeBtn, sfCenter);

            // Command Input Bar (`my + 114`)
            using (SolidBrush hintB = new SolidBrush(Color.FromArgb(195, 0, 242, 254)))
            {
                g.DrawString("SINGLE OR MULTI-TASK COMMAND  \u2022  Chain tasks with 'and' (WhatsApp, Notes, ChatGPT, YouTube Auto-Play, PC Apps & Leo Music):",
                    fontSmallBold, hintB, new RectangleF(mx + 24, my + 90, mw - 48, 19), sfLeftEllipsis);
            }

            Rectangle inputRect = new Rectangle(mx + 24, my + 114, mw - 184, 42);
            using (SolidBrush ib = new SolidBrush(Color.FromArgb(24, 27, 38)))
            using (Pen ip = new Pen(Color.FromArgb(155, 0, 242, 254), 1.4f))
            {
                FillRoundRect(g, ib, inputRect, 12);
                DrawRoundRect(g, ip, inputRect, 12);
            }
            if (!isEditingAgentPrompt && (agentCommandBox == null || string.IsNullOrEmpty(agentCommandBox.Text)))
            {
                using (SolidBrush phB = new SolidBrush(Color.FromArgb(140, 195, 205, 220)))
                {
                    g.DrawString("Type or speak command (e.g. open whatsapp and message hello to aman and play song starboy)...",
                        fontSubReg, phB, new RectangleF(inputRect.X + 14, inputRect.Y + 10, inputRect.Width - 28, 22), sfLeftEllipsis);
                }
            }

            Rectangle runCmdBtn = new Rectangle(inputRect.Right + 12, my + 114, 124, 42);
            using (SolidBrush rb = new SolidBrush(accentColor))
            {
                FillRoundRect(g, rb, runCmdBtn, 12);
            }
            g.DrawString("\u25B6 Run Task(s)", fontTitleBold, Brushes.White, runCmdBtn, sfCenter);

            // 12 Smart Single & Multi-Task Preset Chips (`3 rows of 4 at my + 168`) — Clean, non-truncated labels!
            string[] presetTitles = new string[]
            {
                "\u2726 WhatsApp Message",
                "\u2726 Add Note & Notepad",
                "\u2726 Ask ChatGPT",
                "\u2726 YouTube Auto-Play",
                "\u26A1 4-in-1 Multi-Task",
                "\u266B Play Song in Leo",
                "\u266B 3D + Vol 110% + Fade",
                "\u25C9 Calculator & Notepad",
                "\u25C9 Take PC Screenshot",
                "\u25C9 Check PC Battery/RAM",
                "\u25C9 Set 5-Min Reminder",
                "\u25C9 Open Local Downloads"
            };
            int pCols = 4;
            int pGap = 10;
            int pW = (mw - 48 - (pCols - 1) * pGap) / pCols;
            int pH = 32;
            for (int i = 0; i < presetTitles.Length; i++)
            {
                int r = i / pCols;
                int c = i % pCols;
                Rectangle pr = new Rectangle(mx + 24 + c * (pW + pGap), my + 168 + r * (pH + 7), pW, pH);
                using (SolidBrush pb = new SolidBrush(i == 4 ? Color.FromArgb(62, 0, 242, 254) : Color.FromArgb(34, 40, 56)))
                using (Pen pp = new Pen(i == 4 ? Color.FromArgb(145, 0, 242, 254) : Color.FromArgb(52, 255, 255, 255), 1f))
                {
                    FillRoundRect(g, pb, pr, 9);
                    DrawRoundRect(g, pp, pr, 9);
                }
                g.DrawString(presetTitles[i], fontSmallBold, Brushes.White, pr, sfCenter);
            }

            // Live Execution Log & Saved Notes Box (`my + 292`)
            Rectangle logCard = new Rectangle(mx + 24, my + 292, mw - 48, mh - 310);
            using (SolidBrush lb = new SolidBrush(Color.FromArgb(215, 11, 13, 20)))
            using (Pen lp = new Pen(Color.FromArgb(45, 255, 255, 255), 1f))
            {
                FillRoundRect(g, lb, logCard, 14);
                DrawRoundRect(g, lp, logCard, 14);
            }
            using (SolidBrush hdrB = new SolidBrush(Color.FromArgb(200, 0, 242, 254)))
            {
                g.DrawString("LIVE MULTI-TASK AGENT EXECUTION LOG & SAVED NOTES", fontSmallBold, hdrB, logCard.X + 16, logCard.Y + 11);
            }
            int maxLogs = Math.Min(8, (logCard.Height - 38) / 23);
            using (SolidBrush txtB = new SolidBrush(Color.FromArgb(230, 238, 242, 250)))
            {
                for (int i = 0; i < Math.Min(maxLogs, agentExecutionLogs.Count); i++)
                {
                    g.DrawString(agentExecutionLogs[i], fontSubReg, txtB, new RectangleF(logCard.X + 16, logCard.Y + 34 + i * 23, logCard.Width - 32, 21), sfLeftEllipsis);
                }
            }
        }

        private void ToggleAbLoopMarker()
        {
            if (abLoopStartSec < 0)
            {
                abLoopStartSec = currentPosSec;
                abLoopEndSec = -1.0;
                ShowToast("A-B Loop: Point A set at " + FormatSec((int)abLoopStartSec) + " (Click again to set B)");
            }
            else if (abLoopEndSec < 0 && currentPosSec > abLoopStartSec + 1.0)
            {
                abLoopEndSec = currentPosSec;
                ShowToast("\u21BB A-B Seamless Loop Active: " + FormatSec((int)abLoopStartSec) + " \u2192 " + FormatSec((int)abLoopEndSec));
            }
            else
            {
                abLoopStartSec = -1.0;
                abLoopEndSec = -1.0;
                ShowToast("A-B Loop Cleared");
            }
            this.Invalidate();
        }

        private void CycleHomeEffectStyle()
        {
            homeEffectStyleIdx = (homeEffectStyleIdx + 1) % homeEffectStyleNames.Length;
            SavePersistentSettings();
            ShowToast("\u2726 Spatial Environment: " + homeEffectStyleNames[homeEffectStyleIdx]);
            this.Invalidate();
        }

        private void DrawSpatialSectionHeader(Graphics g, int x, int y, string titleText, string pillTag)
        {
            // Glowing 3D Spatial Orb Marker + Bold Section Title + Subtle Spatial Tag
            Rectangle orb = new Rectangle(x, y + 4, 10, 18);
            using (LinearGradientBrush ob = new LinearGradientBrush(orb, accentColor, Color.FromArgb(0, 235, 255), LinearGradientMode.Vertical))
            {
                FillRoundRect(g, ob, orb, 5);
            }
            using (Font fSecTitle = new Font("Segoe UI", 13.5f, FontStyle.Bold))
            {
                g.DrawString(titleText, fSecTitle, Brushes.White, x + 16, y);
            }
            if (!string.IsNullOrEmpty(pillTag))
            {
                int titleW = (int)g.MeasureString(titleText, new Font("Segoe UI", 13.5f, FontStyle.Bold)).Width;
                Rectangle tagR = new Rectangle(x + 24 + titleW, y + 3, Math.Max(64, pillTag.Length * 6 + 18), 20);
                using (SolidBrush tb = new SolidBrush(Color.FromArgb(40, accentColor.R, accentColor.G, accentColor.B)))
                using (Pen tp = new Pen(Color.FromArgb(95, accentColor), 1f))
                {
                    FillRoundRect(g, tb, tagR, 10);
                    DrawRoundRect(g, tp, tagR, 10);
                }
                using (Font fTiny = new Font("Segoe UI", 7.2f, FontStyle.Bold))
                using (SolidBrush txtB = new SolidBrush(Color.FromArgb(225, 240, 255)))
                {
                    StringFormat sfc = new StringFormat() { Alignment = StringAlignment.Center, LineAlignment = StringAlignment.Center };
                    g.DrawString(pillTag, fTiny, txtB, tagR, sfc);
                }
            }
        }

        // v10.6.4 3D SPATIAL GLASS PEDESTAL SONG CARD (VisionOS Floating Tile + Specular Rim + Reflection Glow)
        private void DrawLuxurySquareSongCard(Graphics g, SongItem s, int cardX, int curY, int artSz, int rowTotalH, string hKey, string badgeText, Color badgeAccent, StringFormat sfCenter, StringFormat sfLeftEllipsis)
        {
            if (s == null) return;
            bool isHov = (currentHoveredBtnKey == hKey);
            bool isCur = (currentSong != null && currentSong.Id == s.Id);
            float scale = GetButtonScale(hKey);

            int liftY = isHov ? -4 : 0;
            Rectangle artBox = ScaleRectCentered(new Rectangle(cardX, curY + liftY, artSz, artSz), scale);

            // Deep drop shadow + neon hover glow beneath card
            using (SolidBrush shB = new SolidBrush(Color.FromArgb(isHov ? 145 : 105, 3, 2, 10)))
            {
                FillRoundRect(g, shB, new Rectangle(artBox.X + 2, artBox.Y + 6, artBox.Width, artBox.Height), 16);
            }
            if (isCur || isHov)
            {
                using (Pen glowRim = new Pen(Color.FromArgb(isCur ? 165 : 115, accentColor.R, accentColor.G, accentColor.B), 3.2f))
                {
                    DrawRoundRect(g, glowRim, new Rectangle(artBox.X - 1, artBox.Y - 1, artBox.Width + 2, artBox.Height + 2), 17);
                }
            }

            string thumbToDraw = (s.Id == "sc_hanuman" && hKey.StartsWith("rec_card_")) ? "local://hanuman_mountain" : s.ThumbUrl;
            DrawStaticAlbumArt(g, thumbToDraw, artBox, 16);

            using (Pen borderP = new Pen(isCur ? Color.FromArgb(255, 225, 175, 255) : (isHov ? Color.FromArgb(235, 215, 165, 255) : Color.FromArgb(115, 195, 150, 255)), isCur ? 2.2f : 1.25f))
            {
                DrawRoundRect(g, borderP, artBox, 16);
            }

            // Vivid Glowing Play Badge in bottom-right corner
            Rectangle playBadge = new Rectangle(artBox.Right - 30, artBox.Bottom - 30, 24, 24);
            using (SolidBrush pb = new SolidBrush((isCur && isPlaying) || isHov ? accentColor : Color.FromArgb(215, 24, 16, 48)))
            using (Pen pp = new Pen(Color.FromArgb(215, 235, 195, 255), 1.2f))
            {
                g.FillEllipse(pb, playBadge);
                g.DrawEllipse(pp, playBadge);
            }
            if (isCur && isPlaying)
            {
                DrawPauseBars(g, Brushes.White, playBadge.X + 12f, playBadge.Y + 12f, 2.2f, 8.5f, 2.8f);
            }
            else
            {
                DrawPlayTriangle(g, Brushes.White, playBadge.X + 13f, playBadge.Y + 12f, 5.0f);
            }

            // Top-right 3-Dot (`•••`) Quick Action Badge
            Rectangle sqDotRect = new Rectangle(artBox.Right - 28, artBox.Y + 6, 22, 20);
            if (isHov || isCur)
            {
                using (SolidBrush db = new SolidBrush(Color.FromArgb(205, 18, 12, 38)))
                {
                    FillRoundRect(g, db, sqDotRect, 8);
                }
                g.DrawString("\u2022\u2022\u2022", fontSmallBold, Brushes.White, sqDotRect, sfCenter);
            }

            using (Font fCardT = new Font("Segoe UI", 9.5f, FontStyle.Bold))
            using (Font fCardA = new Font("Segoe UI", 8.4f, FontStyle.Regular))
            using (SolidBrush tb = new SolidBrush(isCur ? Color.FromArgb(235, 195, 255) : Color.White))
            using (SolidBrush ab = new SolidBrush(Color.FromArgb(215, 208, 238)))
            {
                g.DrawString(FormatMinimalCardTitle(s.Title), fCardT, tb, new RectangleF(cardX + 1, curY + liftY + artSz + 6, artSz - 2, 18), sfLeftEllipsis);
                g.DrawString(GetPrimaryArtistName(s.Artist), fCardA, ab, new RectangleF(cardX + 1, curY + liftY + artSz + 24, artSz - 2, 16), sfLeftEllipsis);
            }

            homeHitZones.Add(new HomeHitZone(sqDotRect, "open_song_3dot", s, hKey + "_dot"));
            Rectangle fullCardHit = new Rectangle(cardX - 2, curY - 2, artSz + 4, rowTotalH + 4);
            homeHitZones.Add(new HomeHitZone(fullCardHit, "play_song", s, hKey));
        }

        private void EnsureHomeDashboardShelvesCached(string activeLang)
        {
            string topRecentId = (recentlyPlayedSongs.Count > 0 && recentlyPlayedSongs[0] != null) ? recentlyPlayedSongs[0].Id : "";
            string key = (selectedCountry ?? "") + "|" + activeLang + "|" + (selectedMood ?? "All") + "|" +
                         (currentSong != null ? currentSong.Id : "") + "|" + topRecentId + "|" +
                         trendingSongs.Count + "|" + recentlyPlayedSongs.Count + "|" + displaySongs.Count;
            if (cachedHomeShelvesKey == key && cachedHomeTrendingRow.Count > 0 && cachedHomeRecentRow.Count >= 6)
            {
                return;
            }
            cachedHomeShelvesKey = key;

            cachedHomeTrendingRow = GetFilteredTrendingForHome(activeLang, selectedMood);

            cachedHomeRecentRow.Clear();
            if (currentSong != null)
            {
                cachedHomeRecentRow.Add(currentSong);
            }
            foreach (SongItem s in recentlyPlayedSongs)
            {
                if (cachedHomeRecentRow.Count >= 6) break;
                if (!ContainsSongByTitleOrId(cachedHomeRecentRow, s))
                {
                    cachedHomeRecentRow.Add(s);
                }
            }
            string[] refIds = new string[] { "sc_hanuman", "sc_2khatole", "sc_patiala", "sc_dilemma", "sc_taushe", "sc_mangal" };
            if (!IsNonIndiaCountrySelected())
            {
                for (int i = 0; i < refIds.Length; i++)
                {
                    if (cachedHomeRecentRow.Count >= 6) break;
                    foreach (SongItem cs in catalog)
                    {
                        if (cs.Id == refIds[i] && !ContainsSongByTitleOrId(cachedHomeRecentRow, cs))
                        {
                            cachedHomeRecentRow.Add(cs);
                            break;
                        }
                    }
                }
            }
            foreach (SongItem s in cachedHomeTrendingRow)
            {
                if (cachedHomeRecentRow.Count >= 6) break;
                if (!ContainsSongByTitleOrId(cachedHomeRecentRow, s))
                {
                    cachedHomeRecentRow.Add(s);
                }
            }
            foreach (SongItem s in catalog)
            {
                if (cachedHomeRecentRow.Count >= 6) break;
                if (!ContainsSongByTitleOrId(cachedHomeRecentRow, s))
                {
                    cachedHomeRecentRow.Add(s);
                }
            }
        }

        // True High-DPI Vector + Neon Wave Category Card (Never stretched or blurry at any resolution!)
        private void DrawNeonCategoryCard(Graphics g, Rectangle rect, string title, int iconKind, Color waveColor, bool isHovered)
        {
            if (rect.Width <= 10 || rect.Height <= 10) return;

            // 1. Deep Drop Shadow
            Rectangle shadowR = new Rectangle(rect.X + 2, rect.Y + 6, rect.Width, rect.Height);
            using (SolidBrush shB = new SolidBrush(Color.FromArgb(isHovered ? 145 : 105, 3, 2, 10)))
            {
                FillRoundRect(g, shB, shadowR, 18);
            }

            // 2. Rich Color-Tinted Dark Glass Body
            Color cTop = (iconKind == 0) ? Color.FromArgb(235, 30, 18, 58)
                       : ((iconKind == 1) ? Color.FromArgb(235, 42, 26, 36)
                       : ((iconKind == 2) ? Color.FromArgb(235, 16, 30, 58)
                                          : Color.FromArgb(235, 14, 36, 44)));
            Color cBot = (iconKind == 0) ? Color.FromArgb(245, 18, 11, 38)
                       : ((iconKind == 1) ? Color.FromArgb(245, 28, 16, 22)
                       : ((iconKind == 2) ? Color.FromArgb(245, 10, 20, 40)
                                          : Color.FromArgb(245, 8, 24, 30)));

            using (LinearGradientBrush bodyB = new LinearGradientBrush(rect, cTop, cBot, LinearGradientMode.Vertical))
            {
                FillRoundRect(g, bodyB, rect, 18);
            }

            // 3. Vivid Multi-Layer Neon Wave Ribbon at the Bottom of the Card + Center Radial Spotlight
            Region oldClip = g.Clip;
            using (GraphicsPath cardClip = GetRoundRectPath(rect, 18))
            {
                g.SetClip(cardClip, CombineMode.Intersect);

                int cx = rect.X + rect.Width / 2;
                int icCy = rect.Y + rect.Height / 2 - 12;
                DrawSoftMeshOrb(g, cx, icCy, 54, Color.FromArgb(isHovered ? 125 : 95, waveColor.R, waveColor.G, waveColor.B));
                DrawSoftMeshOrb(g, rect.Right - 36, rect.Bottom - 10, 78, Color.FromArgb(145, waveColor.R, waveColor.G, waveColor.B));

                using (GraphicsPath waveFillPath = new GraphicsPath())
                {
                    PointF p0 = new PointF(rect.X - 6, rect.Bottom - 8);
                    PointF p1 = new PointF(rect.X + rect.Width * 0.35f, rect.Bottom - 26);
                    PointF p2 = new PointF(rect.X + rect.Width * 0.68f, rect.Bottom + 4);
                    PointF p3 = new PointF(rect.Right + 6, rect.Bottom - 28);
                    waveFillPath.AddBezier(p0, p1, p2, p3);
                    waveFillPath.AddLine(new PointF(rect.Right + 6, rect.Bottom + 10), new PointF(rect.X - 6, rect.Bottom + 10));
                    waveFillPath.CloseFigure();

                    using (LinearGradientBrush wFill = new LinearGradientBrush(
                        new Rectangle(rect.X, rect.Bottom - 36, rect.Width, 44),
                        Color.FromArgb(195, waveColor.R, waveColor.G, waveColor.B),
                        Color.FromArgb(85, Math.Min(255, waveColor.R + 40), Math.Min(255, waveColor.G + 40), Math.Min(255, waveColor.B + 40)),
                        LinearGradientMode.Horizontal))
                    {
                        g.FillPath(wFill, waveFillPath);
                    }
                }

                using (GraphicsPath waveLine = new GraphicsPath())
                {
                    waveLine.AddBezier(
                        new PointF(rect.X - 4, rect.Bottom - 8),
                        new PointF(rect.X + rect.Width * 0.35f, rect.Bottom - 26),
                        new PointF(rect.X + rect.Width * 0.68f, rect.Bottom + 4),
                        new PointF(rect.Right + 4, rect.Bottom - 28));
                    using (Pen glowP = new Pen(Color.FromArgb(120, waveColor.R, waveColor.G, waveColor.B), 4.5f))
                    using (Pen coreP = new Pen(Color.FromArgb(245, Math.Min(255, waveColor.R + 55), Math.Min(255, waveColor.G + 55), Math.Min(255, waveColor.B + 55)), 2.0f))
                    {
                        g.DrawPath(glowP, waveLine);
                        g.DrawPath(coreP, waveLine);
                    }
                }

                // 4. Razor-Sharp Glowing Vector Icon in Center
                Color brightIconCol = Color.FromArgb(255, Math.Min(255, waveColor.R + 65), Math.Min(255, waveColor.G + 65), Math.Min(255, waveColor.B + 65));
                using (Pen glowIcPen = new Pen(Color.FromArgb(110, waveColor.R, waveColor.G, waveColor.B), 4.8f))
                using (Pen icPen = new Pen(brightIconCol, 2.5f))
                {
                    glowIcPen.StartCap = LineCap.Round; glowIcPen.EndCap = LineCap.Round; glowIcPen.LineJoin = LineJoin.Round;
                    icPen.StartCap = LineCap.Round; icPen.EndCap = LineCap.Round; icPen.LineJoin = LineJoin.Round;

                    if (iconKind == 0) // My Music: Play Triangle
                    {
                        PointF[] tri = new PointF[]
                        {
                            new PointF(cx - 9f, icCy - 12f),
                            new PointF(cx - 9f, icCy + 12f),
                            new PointF(cx + 12f, icCy)
                        };
                        g.DrawPolygon(glowIcPen, tri);
                        g.DrawPolygon(icPen, tri);
                    }
                    else if (iconKind == 1) // Trending: 3 Ascending Chart Bars
                    {
                        using (SolidBrush bb = new SolidBrush(brightIconCol))
                        {
                            FillRoundRect(g, bb, new Rectangle(cx - 12, icCy + 2, 5, 10), 2);
                            FillRoundRect(g, bb, new Rectangle(cx - 2,  icCy - 5, 5, 17), 2);
                            FillRoundRect(g, bb, new Rectangle(cx + 8,  icCy - 12, 5, 24), 2);
                        }
                    }
                    else if (iconKind == 2) // New Releases: 5-Point Star
                    {
                        PointF[] starPts = new PointF[10];
                        for (int k = 0; k < 10; k++)
                        {
                            double ang = -Math.PI / 2.0 + k * (Math.PI / 5.0);
                            float r = (k % 2 == 0) ? 13.5f : 5.8f;
                            starPts[k] = new PointF(cx + r * (float)Math.Cos(ang), icCy + r * (float)Math.Sin(ang));
                        }
                        g.DrawPolygon(glowIcPen, starPts);
                        g.DrawPolygon(icPen, starPts);
                    }
                    else // Genres: 2x2 Rounded Grid
                    {
                        DrawRoundRect(g, icPen, new Rectangle(cx - 12, icCy - 12, 10, 10), 3);
                        DrawRoundRect(g, icPen, new Rectangle(cx + 2,  icCy - 12, 10, 10), 3);
                        DrawRoundRect(g, icPen, new Rectangle(cx - 12, icCy + 2,  10, 10), 3);
                        DrawRoundRect(g, icPen, new Rectangle(cx + 2,  icCy + 2,  10, 10), 3);
                    }
                }

                // 5. Crisp White Category Title
                using (Font fCat = new Font("Segoe UI", 11.2f, FontStyle.Bold))
                {
                    StringFormat sfc = new StringFormat() { Alignment = StringAlignment.Center, LineAlignment = StringAlignment.Center };
                    g.DrawString(title, fCat, Brushes.White, new RectangleF(rect.X + 4, icCy + 18, rect.Width - 8, 24), sfc);
                }

                g.Clip = oldClip;
            }

            // 6. Luminous Colored Glass Rim
            bool isActGenre = (iconKind == 3 && activeGenreRadioIdx >= 0);
            using (Pen rimPen = new Pen(Color.FromArgb(isHovered || isActGenre ? 245 : 155, Math.Min(255, waveColor.R + 45), Math.Min(255, waveColor.G + 45), Math.Min(255, waveColor.B + 45)), isHovered || isActGenre ? 2.0f : 1.3f))
            {
                DrawRoundRect(g, rimPen, rect, 18);
            }

            if (isActGenre)
            {
                string gSub = genreRadioNames[activeGenreRadioIdx].Split(' ')[0];
                Rectangle tagR = new Rectangle(rect.Right - 68, rect.Y + 8, 60, 18);
                using (SolidBrush tb = new SolidBrush(Color.FromArgb(220, 10, 24, 28)))
                {
                    FillRoundRect(g, tb, tagR, 9);
                }
                g.DrawString("\u25B6 " + gSub, new Font("Segoe UI", 7.0f, FontStyle.Bold), Brushes.White, tagR, new StringFormat() { Alignment = StringAlignment.Center, LineAlignment = StringAlignment.Center });
            }
        }

        private void PaintScrollableHomeDashboard(Graphics g, Rectangle vp, Color curBgCard, StringFormat sfCenter, StringFormat sfLeftEllipsis)
        {
            Region prevClip = g.Clip;
            g.SetClip(vp);

            int padX = vp.X + 18;
            int contentW = vp.Width - 32;
            int curY = vp.Y + 6 - scrollOffset;

            string activeLang = GetActiveFilterLanguageName();
            EnsureHomeDashboardShelvesCached(activeLang);

            List<SongItem> curTrending = cachedHomeTrendingRow;
            List<SongItem> recentRowSongs = cachedHomeRecentRow;
            SongItem heroSong = currentSong ?? ((curTrending.Count > 0) ? curTrending[0] : catalog[0]);

            int heroH = 212;
            if (curY + heroH >= vp.Y && curY <= vp.Bottom)
            {
                using (Font fEye = new Font("Segoe UI", 8.8f, FontStyle.Bold))
                using (SolidBrush eyeB = new SolidBrush(Color.FromArgb(230, 215, 245)))
                {
                    g.DrawString("W E L C O M E   B A C K", fEye, eyeB, padX + 4, curY + 8);
                }

                using (Font fHeroBold = new Font("Segoe UI", 29f, FontStyle.Bold))
                using (Font fHeroItalic = new Font("Segoe UI", 29f, FontStyle.Bold | FontStyle.Italic))
                using (LinearGradientBrush purpGrad = new LinearGradientBrush(
                    new Rectangle(padX, curY + 26, 390, 98),
                    Color.FromArgb(255, 208, 142, 255),
                    Color.FromArgb(255, 248, 165, 255),
                    LinearGradientMode.Horizontal))
                {
                    g.DrawString("Listen", fHeroBold, Brushes.White, padX, curY + 25);
                    g.DrawString("Without", fHeroItalic, purpGrad, padX + 126, curY + 25);
                    g.DrawString("Limits", fHeroItalic, purpGrad, padX, curY + 68);
                }

                using (Font fHeroSub = new Font("Segoe UI", 10.4f, FontStyle.Regular))
                using (SolidBrush subB = new SolidBrush(Color.FromArgb(235, 228, 250)))
                {
                    g.DrawString("Your Music  \u2022  Your Mood  \u2022  Anytime", fHeroSub, subB, padX + 4, curY + 122);
                }

                int btnY = curY + 154;
                Rectangle startBtn = ScaleRectCentered(new Rectangle(padX + 2, btnY, 166, 42), GetButtonScale("hero_play"));
                // Vivid outer neon bloom around [ ▶ Start Listening ]
                for (int gl = 2; gl >= 1; gl--)
                {
                    Rectangle glR = new Rectangle(startBtn.X - gl * 3, startBtn.Y - gl * 3, startBtn.Width + gl * 6, startBtn.Height + gl * 6);
                    using (SolidBrush gb = new SolidBrush(Color.FromArgb(28 * (3 - gl), 192, 108, 255)))
                    {
                        FillRoundRect(g, gb, glR, 21 + gl * 3);
                    }
                }
                using (LinearGradientBrush pb = new LinearGradientBrush(
                    startBtn,
                    Color.FromArgb(255, Math.Min(255, accentColor.R + 36), Math.Min(255, accentColor.G + 22), (int)accentColor.B),
                    Color.FromArgb(255, Math.Max(0, accentColor.R - 32), Math.Max(0, accentColor.G - 24), Math.Max(0, accentColor.B - 10)),
                    LinearGradientMode.Horizontal))
                using (Pen pr = new Pen(Color.FromArgb(245, 240, 210, 255), 1.5f))
                {
                    FillRoundRect(g, pb, startBtn, 21);
                    DrawRoundRect(g, pr, startBtn, 21);
                }
                if (isPlaying)
                {
                    DrawPauseBars(g, Brushes.White, startBtn.X + 28f, startBtn.Y + 21f, 2.8f, 10f, 3.4f);
                }
                else
                {
                    DrawPlayTriangle(g, Brushes.White, startBtn.X + 28f, startBtn.Y + 21f, 6.5f);
                }
                using (Font fStart = new Font("Segoe UI", 10.2f, FontStyle.Bold))
                {
                    g.DrawString(isPlaying ? "Listening Now" : "Start Listening", fStart, Brushes.White, startBtn.X + 42, startBtn.Y + 11);
                }
                homeHitZones.Add(new HomeHitZone(startBtn, "toggle_hero_play", heroSong, "hero_play"));

                Rectangle shufPill = ScaleRectCentered(new Rectangle(startBtn.Right + 12, btnY, 54, 42), GetButtonScale("hero_shuf"));
                DrawGlassCard(g, shufPill, 21, curBgCard, isShuffle, currentHoveredBtnKey == "hero_shuf");
                DrawShuffleVectorIcon(g, Color.White, shufPill.X + 27f, shufPill.Y + 21f);
                homeHitZones.Add(new HomeHitZone(shufPill, "shuffle_all_home", null, "hero_shuf"));

                Rectangle homeUpdPill = ScaleRectCentered(new Rectangle(shufPill.Right + 10, btnY + 4, 114, 34), GetButtonScale("home_upd_btn"));
                DrawGlassCard(g, homeUpdPill, 17, curBgCard, false, currentHoveredBtnKey == "home_upd_btn");
                g.DrawString("\u21BB Check Update", fontSmallBold, Brushes.White, homeUpdPill, sfCenter);
                homeHitZones.Add(new HomeHitZone(homeUpdPill, "check_updates_home", null, "home_upd_btn"));

                Rectangle homeCntPill = ScaleRectCentered(new Rectangle(homeUpdPill.Right + 8, btnY + 4, 98, 34), GetButtonScale("home_cnt_btn"));
                DrawGlassCard(g, homeCntPill, 17, curBgCard, false, currentHoveredBtnKey == "home_cnt_btn");
                string cShort = string.IsNullOrEmpty(selectedCountry) ? "Global" : (selectedCountry.Length > 8 ? selectedCountry.Substring(0, 7) + "." : selectedCountry);
                g.DrawString("\u25C9 " + cShort, fontSmallBold, Brushes.White, homeCntPill, sfCenter);
                homeHitZones.Add(new HomeHitZone(homeCntPill, "open_lang_home", null, "home_cnt_btn"));
            }
            curY += heroH + 8;

            // 4 Electric Neon Category Cards (`My Music`, `Trending`, `New Releases`, `Genres`)
            int catH = 104;
            int catGap = 14;
            int catW = (contentW - 3 * catGap) / 4;
            if (curY + catH >= vp.Y && curY <= vp.Bottom)
            {
                string[] catNames = new string[] { "My Music", "Trending", "New Releases", "Genres" };
                Color[] catCols = new Color[]
                {
                    Color.FromArgb(178, 92, 255),
                    Color.FromArgb(250, 165, 55),
                    Color.FromArgb(45, 195, 255),
                    Color.FromArgb(42, 218, 185)
                };
                string[] catActions = new string[]
                {
                    "play_cat_mymusic",
                    "play_cat_trending",
                    "play_cat_newreleases",
                    "play_cat_genres"
                };

                for (int i = 0; i < 4; i++)
                {
                    int cx = padX + i * (catW + catGap);
                    string hKey = "cat_card_" + i;
                    Rectangle cRect = ScaleRectCentered(new Rectangle(cx, curY, catW, catH), GetButtonScale(hKey));
                    DrawNeonCategoryCard(g, cRect, catNames[i], i, catCols[i], currentHoveredBtnKey == hKey);
                    homeHitZones.Add(new HomeHitZone(cRect, catActions[i], null, hKey));
                }
            }
            curY += catH + 22;

            if (curY + 32 >= vp.Y && curY <= vp.Bottom)
            {
                FillRoundRect(g, new SolidBrush(Color.FromArgb(255, 195, 125, 255)), new Rectangle(padX, curY + 4, 5, 20), 2);
                using (Font fSec = new Font("Segoe UI", 14.0f, FontStyle.Bold))
                {
                    g.DrawString("Recently Played", fSec, Brushes.White, padX + 14, curY);
                }
                Rectangle seeAllRect = new Rectangle(padX + contentW - 68, curY + 2, 68, 24);
                g.DrawString("See All  \u203A", fontSmallBold, new SolidBrush(Color.FromArgb(225, 215, 245)), seeAllRect, sfCenter);
                homeHitZones.Add(new HomeHitZone(seeAllRect, "open_library_tab", null, "see_all_rec"));
            }
            curY += 34;

            int numRecCards = 6;
            int recGap = 14;
            int recCardW = (contentW - (numRecCards - 1) * recGap) / numRecCards;
            int recArtSz = Math.Max(88, Math.Min(128, recCardW));
            int recRowH = recArtSz + 44;

            if (curY + recRowH >= vp.Y && curY <= vp.Bottom)
            {
                for (int i = 0; i < numRecCards && i < recentRowSongs.Count; i++)
                {
                    SongItem rs = recentRowSongs[i];
                    int cx = padX + i * (recCardW + recGap);
                    DrawLuxurySquareSongCard(g, rs, cx, curY, recArtSz, recRowH, "rec_card_" + i, "RECENT", accentColor, sfCenter, sfLeftEllipsis);
                }
            }
            curY += recRowH + 22;

            if (curY + 32 >= vp.Y && curY <= vp.Bottom)
            {
                FillRoundRect(g, new SolidBrush(Color.FromArgb(255, 195, 125, 255)), new Rectangle(padX, curY + 4, 5, 20), 2);
                using (Font fSec = new Font("Segoe UI", 14.0f, FontStyle.Bold))
                {
                    g.DrawString("Trending in " + selectedCountry, fSec, Brushes.White, padX + 14, curY);
                }
                Rectangle refPill = new Rectangle(padX + contentW - 86, curY, 86, 26);
                DrawGlassCard(g, refPill, 13, curBgCard, false, false);
                g.DrawString("\u21BB Refresh", fontSmallBold, Brushes.White, refPill, sfCenter);
                homeHitZones.Add(new HomeHitZone(refPill, "refresh_trending", null, "ref_tr_btn"));
            }
            curY += 34;

            if (curY + recRowH >= vp.Y && curY <= vp.Bottom)
            {
                for (int i = 0; i < numRecCards && i < curTrending.Count; i++)
                {
                    SongItem ts = curTrending[i];
                    int cx = padX + i * (recCardW + recGap);
                    DrawLuxurySquareSongCard(g, ts, cx, curY, recArtSz, recRowH, "tr_card_" + i, "TOP #" + (i + 1), accentColor, sfCenter, sfLeftEllipsis);
                }
            }
            curY += recRowH + 20;

            if (curY + 30 >= vp.Y && curY <= vp.Bottom)
            {
                FillRoundRect(g, new SolidBrush(Color.FromArgb(255, 195, 125, 255)), new Rectangle(padX, curY + 4, 5, 20), 2);
                using (Font fSec = new Font("Segoe UI", 14.0f, FontStyle.Bold))
                {
                    string allHdr = activeGenreRadioIdx >= 0 ? ("Genre Radio: " + genreRadioNames[activeGenreRadioIdx]) : "All Studio Tracks";
                    g.DrawString(allHdr, fSec, Brushes.White, padX + 14, curY);
                }
            }
            curY += 34;

            int rowH = 56;
            int maxRows = Math.Min(16, displaySongs.Count);
            for (int i = 0; i < maxRows; i++)
            {
                if (curY + rowH >= vp.Y && curY <= vp.Bottom)
                {
                    SongItem s = displaySongs[i];
                    PaintInteractiveSongRow(g, s, new Rectangle(padX, curY, contentW, rowH), curBgCard, "home_row_" + i, sfCenter, sfLeftEllipsis);
                }
                curY += rowH + 6;
            }

            totalHomeContentHeight = (curY + scrollOffset) - vp.Y + 24;
            g.Clip = prevClip;
            DrawCustomScrollbar(g, vp, totalHomeContentHeight);
        }

        private void PaintPlaylistsStudioScreen(Graphics g, int centerX, int centerW, int mainH, Color curBgCard, StringFormat sfCenter, StringFormat sfLeftEllipsis)
        {
            playlistStageHitZones.Clear();
            homeHitZones.Clear();
            topFilterHitZones.Clear();
            PaintCosmicTopBar(g, this.ClientSize.Width, sfCenter, sfLeftEllipsis);

            int padX = centerX + 26;
            int contentW = centerW - 52;

            if (userPlaylists.Count == 0) InitDefaultPlaylists();
            if (selectedPlaylistIdx < 0 || selectedPlaylistIdx >= userPlaylists.Count) selectedPlaylistIdx = 0;

            using (Font fHead = new Font("Segoe UI", 16f, FontStyle.Bold))
            using (SolidBrush wb = new SolidBrush(textWhite))
            using (SolidBrush sb = new SolidBrush(textSub))
            {
                g.DrawString("Playlists & Smart Mood Collections", fHead, wb, padX, 66);
                g.DrawString("Click any playlist card to open, or click \u2022\u2022\u2022 on any playlist or song for full studio actions.", fontSubReg, sb, padX, 94);
            }

            if (isCreatingPlaylistInput)
            {
                Rectangle inputBg = new Rectangle(padX + contentW - 300, 68, 196, 32);
                using (SolidBrush ib = new SolidBrush(Color.FromArgb(24, 18, 46)))
                using (Pen ip = new Pen(accentColor, 1.4f))
                {
                    FillRoundRect(g, ib, inputBg, 10);
                    DrawRoundRect(g, ip, inputBg, 10);
                }
                Rectangle savePlBtn = new Rectangle(padX + contentW - 98, 68, 98, 32);
                FillRoundRect(g, new SolidBrush(accentColor), savePlBtn, 10);
                g.DrawString("Save Playlist", fontSmallBold, Brushes.White, savePlBtn, sfCenter);
                playlistStageHitZones.Add(new HomeHitZone(savePlBtn, "confirm_create_playlist", null, "save_pl_btn", ""));
            }
            else
            {
                Rectangle createPlBtn = ScaleRectCentered(new Rectangle(padX + contentW - 152, 68, 152, 34), GetButtonScale("create_pl_btn"));
                FillRoundRect(g, new SolidBrush(accentColor), createPlBtn, 17);
                g.DrawString("+ Create Playlist", fontSmallBold, Brushes.White, createPlBtn, sfCenter);
                playlistStageHitZones.Add(new HomeHitZone(createPlBtn, "start_create_playlist", null, "create_pl_btn", ""));
            }

            int plCardY = 120;
            int plCardH = 76;
            int numPl = Math.Min(6, userPlaylists.Count);
            int plGap = 10;
            int plCardW = (contentW - (Math.Max(2, numPl) - 1) * plGap) / Math.Max(2, numPl);
            string[] plCoverUris = new string[] { "local://pl_favorites", "local://pl_chill", "local://pl_workout", "local://pl_hindi", "local://pl_lofi", "local://pl_latenight" };

            for (int i = 0; i < userPlaylists.Count && i < 6; i++)
            {
                UserPlaylistItem pl = userPlaylists[i];
                bool isSel = (selectedPlaylistIdx == i);
                string hKey = "pl_card_" + i;
                Rectangle pRect = ScaleRectCentered(new Rectangle(padX + i * (plCardW + plGap), plCardY, plCardW, plCardH), GetButtonScale(hKey));

                DrawGlassCard(g, pRect, 16, curBgCard, isSel, currentHoveredBtnKey == hKey);
                string covUri = (pl.Songs.Count > 0 && !string.IsNullOrEmpty(pl.Songs[0].ThumbUrl)) ? pl.Songs[0].ThumbUrl : plCoverUris[i % plCoverUris.Length];
                DrawStaticAlbumArt(g, covUri, new Rectangle(pRect.X + 10, pRect.Y + 11, 54, 54), 11);

                int tw = Math.Max(40, pRect.Width - 102);
                g.DrawString(pl.Name, fontTitleBold, Brushes.White, new RectangleF(pRect.X + 70, pRect.Y + 14, tw, 22), sfLeftEllipsis);
                string subInfo = pl.IsLeoAutoMood ? ("Auto: " + selectedMood) : (pl.Songs.Count + " Songs");
                g.DrawString(subInfo, fontSubReg, Brushes.LightGray, new RectangleF(pRect.X + 70, pRect.Y + 38, tw, 18), sfLeftEllipsis);

                Rectangle dotBtn = new Rectangle(pRect.Right - 32, pRect.Y + 8, 26, 24);
                using (SolidBrush db = new SolidBrush(Color.FromArgb(95, 165, 125, 245)))
                {
                    FillRoundRect(g, db, dotBtn, 8);
                }
                g.DrawString("\u2022\u2022\u2022", fontSmallBold, Brushes.White, dotBtn, sfCenter);

                playlistStageHitZones.Add(new HomeHitZone(dotBtn, "open_playlist_3dot", null, hKey + "_dot", i.ToString()));
                playlistStageHitZones.Add(new HomeHitZone(pRect, "select_playlist_idx", null, hKey, i.ToString()));
            }

            UserPlaylistItem activePl = userPlaylists[selectedPlaylistIdx];
            int bannerY = 206;
            Rectangle bannerRect = new Rectangle(padX, bannerY, contentW, 58);
            DrawGlassCard(g, bannerRect, 16, curBgCard, true, false);

            using (Font fPlTitle = new Font("Segoe UI", 12f, FontStyle.Bold))
            {
                g.DrawString(activePl.Name + "  (" + activePl.Songs.Count + " Tracks)", fPlTitle, Brushes.White, bannerRect.X + 16, bannerRect.Y + 8);
                g.DrawString(activePl.Subtitle, fontSubReg, Brushes.LightGray, bannerRect.X + 16, bannerRect.Y + 32);
            }

            if (activePl.IsLeoAutoMood)
            {
                int mx = bannerRect.Right - 535;
                if (mx > bannerRect.X + 220)
                {
                    for (int mIdx = 0; mIdx < moods.Length; mIdx++)
                    {
                        string mName = moods[mIdx];
                        int mw = (int)g.MeasureString(mName, fontSmallBold).Width + 14;
                        Rectangle mr = new Rectangle(mx, bannerRect.Y + 17, mw, 24);
                        bool isActM = string.Equals(selectedMood, mName, StringComparison.OrdinalIgnoreCase);
                        FillRoundRect(g, new SolidBrush(isActM ? accentColor : Color.FromArgb(80, 26, 20, 48)), mr, 12);
                        g.DrawString(mName, fontSmallBold, Brushes.White, mr, sfCenter);
                        playlistStageHitZones.Add(new HomeHitZone(mr, "leo_playlist_mood", null, "leo_m_" + mIdx, mName));
                        mx += mw + 4;
                    }
                }
            }
            else if (selectedPlaylistIdx >= 1 && userPlaylists.Count > 1)
            {
                Rectangle delPlBtn = new Rectangle(bannerRect.Right - 256, bannerRect.Y + 14, 92, 30);
                FillRoundRect(g, new SolidBrush(Color.FromArgb(95, 225, 65, 85)), delPlBtn, 14);
                g.DrawString("Delete List", fontSmallBold, Brushes.White, delPlBtn, sfCenter);
                playlistStageHitZones.Add(new HomeHitZone(delPlBtn, "delete_custom_playlist", null, "del_pl", ""));
            }

            Rectangle bannerDotBtn = new Rectangle(bannerRect.Right - 154, bannerRect.Y + 14, 36, 30);
            DrawGlassCard(g, bannerDotBtn, 12, curBgCard, false, false);
            g.DrawString("\u2022\u2022\u2022", fontSmallBold, Brushes.White, bannerDotBtn, sfCenter);
            playlistStageHitZones.Add(new HomeHitZone(bannerDotBtn, "open_playlist_3dot", null, "banner_pl_dot", selectedPlaylistIdx.ToString()));

            Rectangle playAllPlBtn = ScaleRectCentered(new Rectangle(bannerRect.Right - 110, bannerRect.Y + 14, 98, 30), GetButtonScale("play_active_pl"));
            FillRoundRect(g, new SolidBrush(accentColor), playAllPlBtn, 15);
            g.DrawString("\u25B6 Play All", fontSmallBold, Brushes.White, playAllPlBtn, sfCenter);
            playlistStageHitZones.Add(new HomeHitZone(playAllPlBtn, "play_active_playlist", null, "play_active_pl", ""));

            int vpTop = 274;
            Rectangle vp = new Rectangle(centerX, vpTop, centerW, mainH - vpTop - 8);
            int rowH = 58;
            totalHomeContentHeight = activePl.Songs.Count * (rowH + 6) + 24;

            Region oldClip = g.Clip;
            g.SetClip(vp);
            for (int i = 0; i < activePl.Songs.Count; i++)
            {
                int ry = vpTop + 4 + i * (rowH + 6) - scrollOffset;
                if (ry + rowH < vpTop || ry > vp.Bottom) continue;
                SongItem s = activePl.Songs[i];
                PaintInteractiveSongRow(g, s, new Rectangle(padX, ry, contentW, rowH), curBgCard, "pl_row_" + i, sfCenter, sfLeftEllipsis);
            }
            g.Clip = oldClip;
            DrawCustomScrollbar(g, vp, totalHomeContentHeight);
        }

        private void PaintInteractiveSongRow(Graphics g, SongItem s, Rectangle baseRowRect, Color curBgCard, string hoverKey, StringFormat sfCenter, StringFormat sfLeftEllipsis)
        {
            bool isCur = (currentSong != null && currentSong.Id == s.Id);
            bool isHov = (currentHoveredBtnKey == hoverKey);
            Rectangle rowRect = isHov ? ScaleRectCentered(baseRowRect, 1.004f) : baseRowRect;

            DrawGlassCard(g, rowRect, 16, curBgCard, isCur, isHov);
            if (isCur || isHov)
            {
                using (SolidBrush barB = new SolidBrush(isCur ? accentColor : Color.FromArgb(185, 205, 145, 255)))
                {
                    FillRoundRect(g, barB, new Rectangle(rowRect.X + 4, rowRect.Y + 14, 3, rowRect.Height - 28), 2);
                }
            }

            Rectangle thumbRect = new Rectangle(rowRect.X + 11, rowRect.Y + 8, 42, 42);
            DrawStaticAlbumArt(g, s.ThumbUrl, thumbRect, 11);

            using (SolidBrush wb = new SolidBrush(isCur ? Color.FromArgb(230, 190, 255) : textWhite))
            using (SolidBrush subB = new SolidBrush(textSub))
            {
                int textMaxW = Math.Max(100, rowRect.Width - 325);
                g.DrawString(s.Title, fontTitleBold, wb, new RectangleF(rowRect.X + 60, rowRect.Y + 8, textMaxW, 22), sfLeftEllipsis);
                string cInfo = !string.IsNullOrEmpty(s.CountryTag) ? s.CountryTag.Split(',')[0] : (s.Language ?? "Studio");
                g.DrawString(s.Artist + "  \u2022  " + s.Mood + "  \u2022  " + cInfo, fontSubReg, subB, new RectangleF(rowRect.X + 60, rowRect.Y + 29, textMaxW, 20), sfLeftEllipsis);
            }

            using (SolidBrush mb = new SolidBrush(textMuted))
            {
                g.DrawString(FormatSec(s.Duration), fontSubReg, mb, rowRect.Right - 252, rowRect.Y + 20);
            }

            Color actPillBg = Color.FromArgb(isHov ? 52 : 28, 175, 135, 255);
            Color actPillRim = Color.FromArgb(isHov ? 110 : 55, 205, 165, 255);

            Rectangle addPlBtn = new Rectangle(rowRect.Right - 204, rowRect.Y + 14, 32, 30);
            using (SolidBrush plb = new SolidBrush(actPillBg))
            using (Pen plp = new Pen(actPillRim, 1f))
            {
                FillRoundRect(g, plb, addPlBtn, 8);
                DrawRoundRect(g, plp, addPlBtn, 8);
            }
            bool isCustomPlView = (activeTab == 5 && selectedPlaylistIdx >= 1);
            g.DrawString(isCustomPlView ? "\u2715" : "+\u266B", fontSmallBold, Brushes.White, addPlBtn, sfCenter);

            Rectangle addQBtn = new Rectangle(rowRect.Right - 166, rowRect.Y + 14, 30, 30);
            using (SolidBrush qb = new SolidBrush(actPillBg))
            using (Pen qp = new Pen(actPillRim, 1f))
            {
                FillRoundRect(g, qb, addQBtn, 8);
                DrawRoundRect(g, qp, addQBtn, 8);
            }
            DrawPlusQueueIcon(g, textSub, addQBtn.X + 15f, addQBtn.Y + 15f);

            Rectangle likeBtn = new Rectangle(rowRect.Right - 130, rowRect.Y + 14, 32, 30);
            bool liked = likedIds.Contains(s.Id);
            DrawHeartIcon(g, liked ? accentColor : textMuted, likeBtn.X + 16f, likeBtn.Y + 15f, liked);

            Rectangle dlBtn = new Rectangle(rowRect.Right - 92, rowRect.Y + 14, 38, 30);
            bool isDlThis = (downloadingSongId == s.Id);
            using (SolidBrush dlb = new SolidBrush(isDlThis ? accentColor : actPillBg))
            using (Pen dlp = new Pen(actPillRim, 1f))
            {
                FillRoundRect(g, dlb, dlBtn, 8);
                if (!isDlThis) DrawRoundRect(g, dlp, dlBtn, 8);
            }
            if (isDlThis) g.DrawString(downloadProgress + "%", fontSmallBold, Brushes.White, dlBtn, sfCenter);
            else DrawDownloadArrow(g, accentColor, dlBtn.X + dlBtn.Width / 2f, dlBtn.Y + dlBtn.Height / 2f);

            Rectangle dotBtn = new Rectangle(rowRect.Right - 46, rowRect.Y + 14, 34, 30);
            using (SolidBrush db = new SolidBrush(actPillBg))
            using (Pen dp = new Pen(actPillRim, 1f))
            {
                FillRoundRect(g, db, dotBtn, 8);
                DrawRoundRect(g, dp, dotBtn, 8);
            }
            g.DrawString("\u2022\u2022\u2022", fontSmallBold, Brushes.White, dotBtn, sfCenter);

            homeHitZones.Add(new HomeHitZone(dotBtn, "open_song_3dot", s, hoverKey + "_dot"));
            homeHitZones.Add(new HomeHitZone(dlBtn, "download_song", s, hoverKey));
            homeHitZones.Add(new HomeHitZone(likeBtn, "like_song", s, hoverKey));
            homeHitZones.Add(new HomeHitZone(addQBtn, "queue_song", s, hoverKey));
            homeHitZones.Add(new HomeHitZone(addPlBtn, isCustomPlView ? "remove_playlist_song" : "add_playlist_song", s, hoverKey));
            homeHitZones.Add(new HomeHitZone(rowRect, "play_song", s, hoverKey));
        }

        private void DrawCustomScrollbar(Graphics g, Rectangle vp, int contentHeight)
        {
            if (contentHeight <= vp.Height + 10) return;
            int trackX = vp.Right - 10;
            int trackY = vp.Y + 6;
            int trackH = vp.Height - 12;

            float ratio = (float)vp.Height / contentHeight;
            int thumbH = Math.Max(32, (int)(trackH * ratio));
            int maxScroll = Math.Max(1, contentHeight - vp.Height);
            float scrollFrac = Math.Max(0f, Math.Min(1f, (float)scrollOffset / maxScroll));
            int thumbY = trackY + (int)((trackH - thumbH) * scrollFrac);

            using (SolidBrush trB = new SolidBrush(Color.FromArgb(25, 255, 255, 255)))
            using (SolidBrush thB = new SolidBrush(Color.FromArgb(145, accentColor)))
            {
                FillRoundRect(g, trB, new Rectangle(trackX, trackY, 5, trackH), 2);
                FillRoundRect(g, thB, new Rectangle(trackX, thumbY, 5, thumbH), 2);
            }
        }

        // =========================================================================
        // v10.4.3 MULTI-PAGE TABBED SETTINGS STUDIO
        // Replaces the single crowded settings page with 5 spacious, organized tabs:
        //   0: [ Account & Profile ]   — Studio Profile, Listening Stats, 14 Languages & Stream Quality
        //   1: [ Player & Audio EQ ]   — 5-Band Hardware EQ, 3 DSP Sliders, Crossfade, Speed & Sleep Timer
        //   2: [ Lyrics & Dyn Bar ]    — BetterLyrics 2.0 (8 Visual Controls), Dynamic Bar & Mini-Player Shapes
        //   3: [ Theme & Background ]  — Multi-Image Song Background Slideshow (ON/OFF, Style, Fade, Speed, Preview),
        //                                3D Glass, Dynamic Lighting, 6 3D Art Styles & 9 Theme Palettes
        //   4: [ System & Updates ]    — 60Hz+/120Hz Engine, Audio Cache Manager, GitHub OTA Updater & Discord
        // =========================================================================

        private void DrawPurpleToggleSwitch(Graphics g, Rectangle rect, bool isOn)
        {
            using (LinearGradientBrush bgB = new LinearGradientBrush(
                rect,
                isOn ? Color.FromArgb(255, Math.Min(255, accentColor.R + 25), Math.Min(255, accentColor.G + 15), (int)accentColor.B) : Color.FromArgb(180, 38, 32, 62),
                isOn ? accentColor : Color.FromArgb(180, 28, 22, 48),
                LinearGradientMode.Horizontal))
            using (Pen rimP = new Pen(isOn ? Color.FromArgb(220, 235, 195, 255) : Color.FromArgb(90, 165, 145, 215), 1f))
            {
                FillRoundRect(g, bgB, rect, rect.Height / 2);
                DrawRoundRect(g, rimP, rect, rect.Height / 2);
            }
            int d = rect.Height - 6;
            int kx = isOn ? (rect.Right - d - 3) : (rect.X + 3);
            g.FillEllipse(Brushes.White, kx, rect.Y + 3, d, d);
        }

        private void DrawSettingsSubNavIcon(Graphics g, int idx, float cx, float cy, Color col)
        {
            using (Pen p = new Pen(col, 1.6f))
            {
                p.StartCap = LineCap.Round;
                p.EndCap = LineCap.Round;
                if (idx == 0) DrawSidebarNavIcon(g, 6, cx, cy, col);
                else if (idx == 1)
                {
                    PointF[] tri = new PointF[] { new PointF(cx - 4.5f, cy - 5.5f), new PointF(cx - 4.5f, cy + 5.5f), new PointF(cx + 5.5f, cy) };
                    g.DrawPolygon(p, tri);
                }
                else if (idx == 2) DrawSpeakerVectorIcon(g, col, cx, cy, false);
                else if (idx == 3) DrawDownloadArrow(g, col, cx, cy);
                else if (idx == 4) DrawSidebarNavIcon(g, 2, cx, cy, col);
                else if (idx == 5)
                {
                    g.DrawLine(p, cx - 5f, cy + 5f, cx + 5f, cy - 5f);
                    g.DrawEllipse(p, cx - 6f, cy + 1f, 5f, 5f);
                }
                else if (idx == 6)
                {
                    g.DrawRectangle(p, cx - 6.5f, cy - 4.5f, 13f, 9f);
                    g.DrawLine(p, cx - 3.5f, cy + 1.5f, cx + 3.5f, cy + 1.5f);
                }
                else if (idx == 7)
                {
                    g.DrawEllipse(p, cx - 3.5f, cy - 6.0f, 7f, 7f);
                    g.DrawArc(p, cx - 6.0f, cy + 1.5f, 12f, 8f, 180f, 180f);
                }
                else
                {
                    g.DrawEllipse(p, cx - 6.0f, cy - 6.0f, 12f, 12f);
                    g.DrawLine(p, cx, cy - 1.0f, cx, cy + 3.5f);
                    g.FillEllipse(new SolidBrush(col), cx - 1.0f, cy - 4.0f, 2.0f, 2.0f);
                }
            }
        }

        // 4 Visually Distinct Background Style Preview Thumbnails:
        // 0 = Cosmic Mountain Aurora (Violet/Pink), 1 = Golden Sunset Peaks (Gold/Crimson), 2 = Cyber Neon Grid (Cyan/Magenta), 3 = Emerald Night Forest (Green/Teal)
        private void DrawBgStylePreviewThumb(Graphics g, Rectangle rect, int styleIdx, bool isSelected)
        {
            Color cTop = (styleIdx == 0) ? Color.FromArgb(255, 36, 16, 78)
                       : ((styleIdx == 1) ? Color.FromArgb(255, 92, 26, 48)
                       : ((styleIdx == 2) ? Color.FromArgb(255, 10, 32, 68)
                                           : Color.FromArgb(255, 8, 46, 42)));
            Color cBot = (styleIdx == 0) ? Color.FromArgb(255, 16, 10, 34)
                       : ((styleIdx == 1) ? Color.FromArgb(255, 235, 125, 58)
                       : ((styleIdx == 2) ? Color.FromArgb(255, 24, 12, 48)
                                           : Color.FromArgb(255, 10, 22, 26)));

            using (LinearGradientBrush bgB = new LinearGradientBrush(rect, cTop, cBot, LinearGradientMode.Vertical))
            {
                FillRoundRect(g, bgB, rect, 12);
            }

            Region prev = g.Clip;
            g.SetClip(rect);
            if (styleIdx == 0) // Cosmic Mountain Aurora
            {
                using (Pen wp = new Pen(Color.FromArgb(235, 225, 145, 255), 2.4f))
                {
                    g.DrawBezier(wp,
                        new PointF(rect.X + 8, rect.Bottom - 8),
                        new PointF(rect.X + rect.Width * 0.35f, rect.Y + 14),
                        new PointF(rect.X + rect.Width * 0.68f, rect.Y + 8),
                        new PointF(rect.Right - 4, rect.Y + 4));
                }
                PointF[] mtn = new PointF[]
                {
                    new PointF(rect.X + 12, rect.Bottom),
                    new PointF(rect.X + 42, rect.Y + 24),
                    new PointF(rect.X + 68, rect.Y + 14),
                    new PointF(rect.Right, rect.Bottom)
                };
                g.FillPolygon(new SolidBrush(Color.FromArgb(215, 48, 28, 92)), mtn);
            }
            else if (styleIdx == 1) // Golden Sunset Peaks
            {
                g.FillEllipse(new SolidBrush(Color.FromArgb(235, 255, 220, 95)), rect.X + rect.Width / 2 - 12, rect.Y + 8, 24, 24);
                PointF[] mtn = new PointF[]
                {
                    new PointF(rect.X, rect.Bottom),
                    new PointF(rect.X + 26, rect.Y + 22),
                    new PointF(rect.X + 52, rect.Y + 32),
                    new PointF(rect.X + 76, rect.Y + 18),
                    new PointF(rect.Right, rect.Bottom)
                };
                g.FillPolygon(new SolidBrush(Color.FromArgb(225, 42, 16, 36)), mtn);
            }
            else if (styleIdx == 2) // Cyber Neon Grid
            {
                int hy = rect.Y + rect.Height / 2;
                using (Pen hp = new Pen(Color.FromArgb(220, 236, 72, 153), 1.8f))
                using (Pen gp = new Pen(Color.FromArgb(160, 6, 215, 255), 1.1f))
                {
                    g.DrawLine(hp, rect.X, hy, rect.Right, hy);
                    int vx = rect.X + rect.Width / 2;
                    for (int i = -3; i <= 3; i++) g.DrawLine(gp, vx + i * 6, hy, vx + i * 22, rect.Bottom);
                    g.DrawLine(gp, rect.X, hy + 8, rect.Right, hy + 8);
                    g.DrawLine(gp, rect.X, hy + 16, rect.Right, hy + 16);
                }
            }
            else // Emerald Night Forest
            {
                using (Pen ap = new Pen(Color.FromArgb(210, 52, 245, 168), 3.2f))
                {
                    g.DrawBezier(ap,
                        new PointF(rect.X + 4, rect.Y + 22),
                        new PointF(rect.X + 34, rect.Y + 6),
                        new PointF(rect.X + 64, rect.Y + 26),
                        new PointF(rect.Right - 4, rect.Y + 10));
                }
                for (int tx = rect.X + 12; tx < rect.Right - 8; tx += 16)
                {
                    PointF[] tri = new PointF[] { new PointF(tx, rect.Y + 22), new PointF(tx - 7, rect.Bottom), new PointF(tx + 7, rect.Bottom) };
                    g.FillPolygon(new SolidBrush(Color.FromArgb(235, 6, 14, 18)), tri);
                }
            }
            g.Clip = prev;

            using (Pen rimP = new Pen(isSelected ? Color.FromArgb(245, 215, 155, 255) : Color.FromArgb(85, 185, 155, 245), isSelected ? 2.0f : 1.0f))
            {
                DrawRoundRect(g, rimP, rect, 12);
            }

            string[] shortNames = new string[] { "Aurora", "Sunset", "Cyber Grid", "Forest" };
            using (Font fTiny = new Font("Segoe UI", 6.8f, FontStyle.Bold))
            {
                g.DrawString(shortNames[styleIdx % 4], fTiny, Brushes.White, rect.X + 6, rect.Bottom - 15);
            }

            if (isSelected)
            {
                Rectangle chk = new Rectangle(rect.Right - 20, rect.Bottom - 20, 16, 16);
                using (SolidBrush cb = new SolidBrush(accentColor))
                {
                    g.FillEllipse(cb, chk);
                }
                StringFormat sfc = new StringFormat() { Alignment = StringAlignment.Center, LineAlignment = StringAlignment.Center };
                g.DrawString("\u2713", new Font("Segoe UI", 7.0f, FontStyle.Bold), Brushes.White, chk, sfc);
            }
        }

        private void PaintSettingsAndEqualizerScreen(Graphics g, int centerX, int centerW, int mainH, Color curBgCard, StringFormat sfCenter, StringFormat sfLeftEllipsis)
        {
            topFilterHitZones.Clear();
            int w = this.ClientSize.Width;
            PaintCosmicTopBar(g, w, sfCenter, sfLeftEllipsis);

            int padX = centerX + 20;
            int contentW = centerW - 36;

            Rectangle gearCircle = new Rectangle(padX + 4, 68, 48, 48);
            using (SolidBrush gb = new SolidBrush(Color.FromArgb(75, accentColor.R, accentColor.G, accentColor.B)))
            using (Pen gp = new Pen(Color.FromArgb(165, 215, 165, 255), 1.4f))
            {
                g.FillEllipse(gb, gearCircle);
                g.DrawEllipse(gp, gearCircle);
            }
            DrawSidebarNavIcon(g, 6, gearCircle.X + 24f, gearCircle.Y + 24f, Color.FromArgb(235, 195, 255));

            using (Font fHead = new Font("Segoe UI", 22f, FontStyle.Bold))
            using (Font fSub = new Font("Segoe UI", 10.0f, FontStyle.Regular))
            using (SolidBrush sb = new SolidBrush(Color.FromArgb(205, 198, 225)))
            {
                g.DrawString("Settings", fHead, Brushes.White, padX + 64, 62);
                g.DrawString("Customize your music experience", fSub, sb, padX + 66, 100);
            }

            int subSideW = 212;
            int panelTopY = 132;
            int panelH = mainH - panelTopY - 14;
            Rectangle subSideCard = new Rectangle(padX, panelTopY, subSideW, panelH);
            DrawGlassCard(g, subSideCard, 22, curBgCard, false, false);

            for (int i = 0; i < settingsSubPageNames.Length; i++)
            {
                Rectangle itemR = new Rectangle(subSideCard.X + 12, subSideCard.Y + 14 + i * 44, subSideCard.Width - 24, 38);
                bool isSel = (activeSettingsSubPage == i);
                if (isSel)
                {
                    using (LinearGradientBrush selB = new LinearGradientBrush(
                        itemR,
                        Color.FromArgb(240, Math.Min(255, accentColor.R + 20), Math.Min(255, accentColor.G + 15), (int)accentColor.B),
                        Color.FromArgb(215, Math.Max(0, accentColor.R - 45), Math.Max(0, accentColor.G - 35), Math.Max(0, accentColor.B - 20)),
                        LinearGradientMode.Horizontal))
                    {
                        FillRoundRect(g, selB, itemR, 14);
                    }
                    using (Pen rp = new Pen(Color.FromArgb(215, 235, 195, 255), 1.1f))
                    {
                        DrawRoundRect(g, rp, itemR, 14);
                    }
                }
                Color icCol = isSel ? Color.White : Color.FromArgb(205, 200, 225);
                DrawSettingsSubNavIcon(g, i, itemR.X + 20f, itemR.Y + 19f, icCol);
                using (Font fNav = new Font("Segoe UI", 9.8f, isSel ? FontStyle.Bold : FontStyle.Regular))
                using (SolidBrush tb = new SolidBrush(icCol))
                {
                    g.DrawString(settingsSubPageNames[i], fNav, tb, itemR.X + 42, itemR.Y + 9);
                }
            }

            int rightAreaX = subSideCard.Right + 18;
            int rightAreaW = Math.Max(360, contentW - subSideW - 18);

            // =================================================================
            // PAGE 0: GENERAL (Matches Screenshot 3 1:1 + Song Images Toggle!)
            // =================================================================
            if (activeSettingsSubPage == 0)
            {
                int genH = Math.Min(264, (panelH - 16) / 2);
                Rectangle genCard = new Rectangle(rightAreaX, panelTopY, rightAreaW, genH);
                DrawGlassCard(g, genCard, 22, curBgCard, true, false);

                Rectangle genIconCircle = new Rectangle(genCard.X + 20, genCard.Y + 16, 34, 34);
                using (Pen gp = new Pen(Color.FromArgb(215, 165, 255), 1.8f))
                {
                    g.DrawEllipse(gp, genIconCircle);
                    g.DrawEllipse(gp, genIconCircle.X + 10, genIconCircle.Y + 10, 14, 14);
                }
                using (Font fCardHdr = new Font("Segoe UI", 13.5f, FontStyle.Bold))
                using (SolidBrush sb = new SolidBrush(Color.FromArgb(195, 190, 220)))
                {
                    g.DrawString("General", fCardHdr, Brushes.White, genCard.X + 66, genCard.Y + 12);
                    g.DrawString("Basic settings for LEO Music", fontSubReg, sb, genCard.X + 66, genCard.Y + 35);
                }

                string[] genRowTitles = new string[] { "Language", "Startup Behavior", "Minimize to System Tray", "Auto Check for Updates" };
                string[] genRowSubs = new string[]
                {
                    "Choose your preferred language",
                    "What should happen when LEO Music starts?",
                    "Keep LEO Music running in the background",
                    "Get the latest features and improvements"
                };

                int rowStartY = genCard.Y + 62;
                int rowStepH = (genH - 68) / 4;
                for (int r = 0; r < 4; r++)
                {
                    int ry = rowStartY + r * rowStepH;
                    if (r > 0)
                    {
                        using (Pen sepP = new Pen(Color.FromArgb(28, 205, 185, 255), 1f))
                        {
                            g.DrawLine(sepP, genCard.X + 20, ry - 2, genCard.Right - 20, ry - 2);
                        }
                    }

                    float icx = genCard.X + 36f;
                    float icy = ry + rowStepH / 2f;
                    using (Pen ip = new Pen(Color.FromArgb(215, 210, 235), 1.6f))
                    {
                        if (r == 0)
                        {
                            g.DrawEllipse(ip, icx - 8f, icy - 8f, 16f, 16f);
                            g.DrawEllipse(ip, icx - 4f, icy - 8f, 8f, 16f);
                            g.DrawLine(ip, icx - 8f, icy, icx + 8f, icy);
                        }
                        else if (r == 1)
                        {
                            g.DrawArc(ip, icx - 7f, icy - 6f, 14f, 14f, -60f, 300f);
                            g.DrawLine(ip, icx, icy - 8f, icx, icy);
                        }
                        else if (r == 2)
                        {
                            g.DrawRectangle(ip, icx - 8f, icy - 6f, 16f, 11f);
                            g.DrawLine(ip, icx - 4f, icy + 8f, icx + 4f, icy + 8f);
                        }
                        else
                        {
                            DrawRepeatVectorIcon(g, Color.FromArgb(215, 210, 235), icx, icy);
                        }
                    }

                    using (Font fRt = new Font("Segoe UI", 10.0f, FontStyle.Bold))
                    using (Font fRs = new Font("Segoe UI", 8.5f, FontStyle.Regular))
                    using (SolidBrush sb = new SolidBrush(Color.FromArgb(185, 180, 210)))
                    {
                        g.DrawString(genRowTitles[r], fRt, Brushes.White, genCard.X + 66, ry + 4);
                        g.DrawString(genRowSubs[r], fRs, sb, genCard.X + 66, ry + 23);
                    }

                    if (r == 0)
                    {
                        Rectangle dropPill = new Rectangle(genCard.Right - 166, ry + (rowStepH - 30) / 2, 142, 30);
                        DrawGlassCard(g, dropPill, 15, curBgCard, false, false);
                        string langTxt = (activeLanguageFilterName == "All Languages") ? "English" : activeLanguageFilterName;
                        g.DrawString(langTxt + "   \u2304", fontSmallBold, Brushes.White, dropPill, sfCenter);
                    }
                    else if (r == 1)
                    {
                        Rectangle dropPill = new Rectangle(genCard.Right - 166, ry + (rowStepH - 30) / 2, 142, 30);
                        DrawGlassCard(g, dropPill, 15, curBgCard, false, false);
                        g.DrawString(startupBehaviorNames[startupBehaviorIdx] + "   \u2304", fontSmallBold, Brushes.White, dropPill, sfCenter);
                    }
                    else if (r == 2)
                    {
                        Rectangle togR = new Rectangle(genCard.Right - 68, ry + (rowStepH - 24) / 2, 44, 24);
                        DrawPurpleToggleSwitch(g, togR, minimizeToTrayEnabled);
                    }
                    else
                    {
                        Rectangle chkNowBtn = new Rectangle(genCard.Right - 166, ry + (rowStepH - 26) / 2, 88, 26);
                        DrawGlassCard(g, chkNowBtn, 13, curBgCard, false, false);
                        g.DrawString("\u21BB Check Now", fontSmallBold, Brushes.White, chkNowBtn, sfCenter);

                        Rectangle togR = new Rectangle(genCard.Right - 68, ry + (rowStepH - 24) / 2, 44, 24);
                        DrawPurpleToggleSwitch(g, togR, autoCheckUpdatesEnabled);
                    }
                }

                int appTopY = genCard.Bottom + 16;
                int appH = Math.Max(220, panelH - genH - 16);
                Rectangle appCard = new Rectangle(rightAreaX, appTopY, rightAreaW, appH);
                DrawGlassCard(g, appCard, 22, curBgCard, false, false);

                Rectangle palCircle = new Rectangle(appCard.X + 20, appCard.Y + 16, 34, 34);
                using (Pen pp = new Pen(Color.FromArgb(215, 165, 255), 1.8f))
                {
                    g.DrawEllipse(pp, palCircle);
                    g.FillEllipse(new SolidBrush(accentColor), palCircle.X + 9, palCircle.Y + 9, 6, 6);
                    g.FillEllipse(Brushes.Cyan, palCircle.X + 18, palCircle.Y + 11, 5, 5);
                    g.FillEllipse(Brushes.Orange, palCircle.X + 13, palCircle.Y + 19, 5, 5);
                }
                using (Font fCardHdr = new Font("Segoe UI", 13.5f, FontStyle.Bold))
                using (SolidBrush sb = new SolidBrush(Color.FromArgb(195, 190, 220)))
                {
                    g.DrawString("Appearance", fCardHdr, Brushes.White, appCard.X + 66, appCard.Y + 12);
                    g.DrawString("Personalize the look and feel", fontSubReg, sb, appCard.X + 66, appCard.Y + 35);
                }

                // Song Images in Background Toggle Pill right in Appearance Card Header!
                Rectangle songBgPill = new Rectangle(appCard.Right - 216, appCard.Y + 16, 196, 30);
                DrawGlassCard(g, songBgPill, 15, curBgCard, songBgImageEnabled, false);
                g.DrawString("Song Art Background: " + (songBgImageEnabled ? "ON" : "OFF"), fontSmallBold, Brushes.White, new RectangleF(songBgPill.X + 10, songBgPill.Y + 5, 140, 20), sfLeftEllipsis);
                DrawPurpleToggleSwitch(g, new Rectangle(songBgPill.Right - 42, songBgPill.Y + 5, 36, 20), songBgImageEnabled);

                int aRow1Y = appCard.Y + 64;
                int aRow2Y = appCard.Y + 116;
                int aRow3Y = appCard.Y + 168;

                using (Pen sepP = new Pen(Color.FromArgb(28, 205, 185, 255), 1f))
                {
                    g.DrawLine(sepP, appCard.X + 20, aRow1Y - 4, appCard.Right - 20, aRow1Y - 4);
                    g.DrawLine(sepP, appCard.X + 20, aRow2Y - 4, appCard.Right - 20, aRow2Y - 4);
                    g.DrawLine(sepP, appCard.X + 20, aRow3Y - 4, appCard.Right - 20, aRow3Y - 4);
                }

                using (Font fRt = new Font("Segoe UI", 10.0f, FontStyle.Bold))
                using (Font fRs = new Font("Segoe UI", 8.5f, FontStyle.Regular))
                using (SolidBrush sb = new SolidBrush(Color.FromArgb(185, 180, 210)))
                using (Pen ip = new Pen(Color.FromArgb(215, 210, 235), 1.6f))
                {
                    g.DrawArc(ip, appCard.X + 28, aRow1Y + 8, 16, 16, 40, 260);
                    g.DrawString("Theme", fRt, Brushes.White, appCard.X + 66, aRow1Y + 2);
                    g.DrawString("Choose your preferred theme", fRs, sb, appCard.X + 66, aRow1Y + 22);

                    string[] thModes = new string[] { "\u25A3 System", "\u2600 Light", "\uD83C\uDF19 Dark", "\u24B6 Auto" };
                    int tmStartX = appCard.Right - 364;
                    for (int ti = 0; ti < 4; ti++)
                    {
                        Rectangle tmR = new Rectangle(tmStartX + ti * 86, aRow1Y + 6, 80, 30);
                        bool isActTm = (appearanceThemeModeIdx == ti);
                        if (isActTm)
                        {
                            using (LinearGradientBrush tb = new LinearGradientBrush(tmR, Color.FromArgb(245, accentColor), Color.FromArgb(215, 92, 42, 185), LinearGradientMode.Horizontal))
                            {
                                FillRoundRect(g, tb, tmR, 15);
                            }
                        }
                        else
                        {
                            DrawGlassCard(g, tmR, 15, curBgCard, false, false);
                        }
                        g.DrawString(thModes[ti], fontSmallBold, Brushes.White, tmR, sfCenter);
                    }

                    PointF[] dropPts = new PointF[]
                    {
                        new PointF(appCard.X + 36, aRow2Y + 6),
                        new PointF(appCard.X + 29, aRow2Y + 18),
                        new PointF(appCard.X + 36, aRow2Y + 24),
                        new PointF(appCard.X + 43, aRow2Y + 18)
                    };
                    g.DrawClosedCurve(ip, dropPts);
                    g.DrawString("Accent Color", fRt, Brushes.White, appCard.X + 66, aRow2Y + 2);
                    g.DrawString("Set the accent color for the app", fRs, sb, appCard.X + 66, aRow2Y + 22);

                    int colStartX = appCard.Right - 244;
                    for (int ci = 0; ci < Math.Min(6, themes.Count); ci++)
                    {
                        Rectangle cCircle = new Rectangle(colStartX + ci * 38, aRow2Y + 8, 26, 26);
                        Color cCol = themes[ci].Accent;
                        using (SolidBrush cb = new SolidBrush(cCol))
                        {
                            g.FillEllipse(cb, cCircle);
                        }
                        if (activeThemeIdx == ci)
                        {
                            using (Pen outRing = new Pen(Color.White, 2.0f))
                            {
                                g.DrawEllipse(outRing, cCircle.X - 3, cCircle.Y - 3, cCircle.Width + 6, cCircle.Height + 6);
                            }
                            g.FillEllipse(Brushes.White, cCircle.X + 9, cCircle.Y + 9, 8, 8);
                        }
                    }

                    g.DrawRectangle(ip, appCard.X + 28, aRow3Y + 10, 16, 12);
                    g.DrawString("Background Style", fRt, Brushes.White, appCard.X + 66, aRow3Y + 4);
                    g.DrawString("4 distinct cosmic environments", fRs, sb, appCard.X + 66, aRow3Y + 24);

                    int bgThumbW = 96;
                    int bgThumbH = 46;
                    int bgGap = 10;
                    int bgStartX = appCard.Right - (4 * bgThumbW + 3 * bgGap) - 20;
                    for (int bi = 0; bi < 4; bi++)
                    {
                        Rectangle bRect = new Rectangle(bgStartX + bi * (bgThumbW + bgGap), aRow3Y + 2, bgThumbW, bgThumbH);
                        DrawBgStylePreviewThumb(g, bRect, bi, homeEffectStyleIdx == bi);
                    }
                }
                return;
            }

            Rectangle subPageCard = new Rectangle(rightAreaX, panelTopY, rightAreaW, panelH);
            DrawGlassCard(g, subPageCard, 22, curBgCard, true, false);

            int sx = subPageCard.X + 24;
            int sy = subPageCard.Y + 20;
            int sw = subPageCard.Width - 48;

            // =================================================================
            // PAGE 1: PLAYBACK, TRANSITIONS & MULTI-LYRICS STUDIO CUSTOMIZATION
            // =================================================================
            if (activeSettingsSubPage == 1)
            {
                using (Font fSec = new Font("Segoe UI", 14.5f, FontStyle.Bold))
                {
                    g.DrawString("Playback, Transitions & Multi-Lyrics Studio", fSec, Brushes.White, sx, sy - 4);
                    g.DrawString("Configure crossfade, speed, gapless audio, and customize BetterLyrics 2.0 (" + currentLyricMatchScore + "% Sync Accuracy)", fontSubReg, Brushes.LightGray, sx, sy + 20);
                }

                string[,] pbRows = new string[,]
                {
                    { "Smooth Crossfade Overlap", "Seamless dual-deck transition (" + (crossfadeEnabled ? (crossfadeSeconds + "s") : "Off") + ")", crossfadeEnabled ? (crossfadeSeconds + "s ON") : "OFF" },
                    { "Gapless & Skip Silence", "Eliminate silence between tracks", gaplessPlayback ? "ON" : "OFF" },
                    { "Playback Speed & Pitch", "Real-time tempo & Slowed+Reverb", playbackSpeedNames[playbackSpeedIdx] },
                    { "Auto-Mix Smart Queue", "Generate similar artist & country queue", autoMixEnabled ? "ON" : "OFF" },
                    { "Windows Notification Center", "Show Now Playing banner on song play", windowsNotificationEnabled ? "ON" : "OFF" },
                    { "Studio Sleep Timer", "Auto-pause playback after countdown", sleepTimerMinutes == 0 ? "Off" : (sleepTimerMinutes + " Mins") }
                };

                int colW = (sw - 12) / 2;
                int pStartY = sy + 48;
                for (int i = 0; i < 6; i++)
                {
                    int r = i / 2;
                    int c = i % 2;
                    Rectangle rr = new Rectangle(sx + c * (colW + 12), pStartY + r * 48, colW, 42);
                    DrawGlassCard(g, rr, 12, curBgCard, false, false);
                    g.DrawString(pbRows[i, 0], fontSmallBold, Brushes.White, rr.X + 12, rr.Y + 5);
                    g.DrawString(pbRows[i, 1], fontSubReg, Brushes.LightGray, rr.X + 12, rr.Y + 22);
                    Rectangle pill = new Rectangle(rr.Right - 96, rr.Y + 8, 86, 26);
                    bool isAct = pbRows[i, 2].Contains("ON") || (i == 2 && playbackSpeedIdx != 0) || (i == 5 && sleepTimerMinutes > 0);
                    FillRoundRect(g, new SolidBrush(isAct ? accentColor : Color.FromArgb(65, 145, 115, 225)), pill, 13);
                    g.DrawString(pbRows[i, 2], fontSmallBold, Brushes.White, pill, sfCenter);
                }

                int lyrHdrY = pStartY + 3 * 48 + 10;
                using (Font fLyrH = new Font("Segoe UI", 12.5f, FontStyle.Bold))
                {
                    g.DrawString("Multi-Lyrics & BetterLyrics 2.0 Studio Customization (\u2713 " + Math.Max(90, currentLyricMatchScore) + "% Sync Accuracy):", fLyrH, new SolidBrush(Color.FromArgb(225, 185, 255)), sx, lyrHdrY);
                }

                string[] lyrBtns = new string[]
                {
                    "\u21C4 Lyrics Engine: " + lyricsProviderNames[activeLyricsProviderIdx],
                    "Stage Style: " + lyricStageStyleNames[lyricStageStyleIdx],
                    "Syllable Glow: " + lyricGlowModeNames[lyricGlowModeIdx],
                    "Lyrics Font: " + lyricFontStyleNames[lyricFontStyleIdx],
                    "Lyrics Size: " + lyricTextSizeNames[lyricTextSizeIdx],
                    "Background Watermark: " + lyricBgArtModeNames[lyricBgArtModeIdx],
                    "Highlight Capsule: " + (fullLyricsScriptToggle ? "ON" : "Standard"),
                    "\u26F6 Open Full-Screen Lyrics Studio"
                };
                int lbTop = lyrHdrY + 28;
                for (int i = 0; i < 8; i++)
                {
                    int r = i / 2;
                    int c = i % 2;
                    Rectangle lr = new Rectangle(sx + c * (colW + 12), lbTop + r * 42, colW, 36);
                    DrawGlassCard(g, lr, 12, curBgCard, i == 0 || i == 7, false);
                    g.DrawString(lyrBtns[i], fontSmallBold, Brushes.White, lr, sfCenter);
                }
            }
            // =================================================================
            // PAGE 2: DEDICATED AUDIO & 5-BAND HARDWARE EQUALIZER (Distinct from Playback!)
            // =================================================================
            else if (activeSettingsSubPage == 2)
            {
                using (Font fSec = new Font("Segoe UI", 15f, FontStyle.Bold))
                {
                    g.DrawString("Audio Engine, 5-Band Equalizer & 3D Spatial Stage", fSec, Brushes.White, sx, sy);
                }
                DrawPurpleToggleSwitch(g, new Rectangle(sx + sw - 52, sy + 2, 46, 24), eqEnabled);

                int pY = sy + 40;
                int pW = (sw - 8 * 6) / 9;
                for (int i = 0; i < eqPresetNames.Length; i++)
                {
                    Rectangle pr = new Rectangle(sx + i * (pW + 6), pY, pW, 28);
                    bool act = string.Equals(activeEqPreset, eqPresetNames[i], StringComparison.OrdinalIgnoreCase);
                    DrawGlassCard(g, pr, 14, curBgCard, act, false);
                    g.DrawString(eqPresetNames[i], fontSmallBold, Brushes.White, pr, sfCenter);
                }

                int slTop = pY + 46;
                int slH = 140;
                int bandSpacing = sw / 6;
                for (int b = 0; b < 5; b++)
                {
                    int bx = sx + 48 + b * bandSpacing;
                    Rectangle track = new Rectangle(bx - 3, slTop, 6, slH);
                    FillRoundRect(g, new SolidBrush(Color.FromArgb(55, 255, 255, 255)), track, 3);
                    float norm = (eqBands[b] + 12f) / 24f;
                    int fillH = (int)(norm * slH);
                    int fillY = slTop + slH - fillH;
                    FillRoundRect(g, new SolidBrush(accentColor), new Rectangle(bx - 3, fillY, 6, Math.Max(4, fillH)), 3);
                    g.FillEllipse(Brushes.White, bx - 8, fillY - 8, 16, 16);
                    g.DrawString((eqBands[b] >= 0 ? "+" : "") + eqBands[b].ToString("0.0") + "dB", fontSmallBold, Brushes.White, new RectangleF(bx - 32, slTop - 22, 64, 18), sfCenter);
                    g.DrawString(eqBandLabels[b], fontSmallBold, Brushes.LightGray, new RectangleF(bx - 32, slTop + slH + 8, 64, 18), sfCenter);
                }

                int cfgY = slTop + slH + 42;
                string[] cfgLabels = new string[]
                {
                    "Bass Boost: " + bassBoostPct + "%",
                    "3D Virtualizer: " + virtualizerPct + "%",
                    "Volume Overdrive: " + (volumeOverdriveAllowed ? "150% ON" : "100% Std"),
                    "3D Stage: " + headphone3DShortNames[headphone3DModeIdx],
                    "Pin-Drop: " + pinDropDetailShortNames[pinDropDetailLevelIdx],
                    "DAC: " + dacOutputShortNames[dacOutputModeIdx]
                };
                int cW = (sw - 2 * 10) / 3;
                for (int i = 0; i < 6; i++)
                {
                    int r = i / 3;
                    int c = i % 3;
                    Rectangle cr = new Rectangle(sx + c * (cW + 10), cfgY + r * 44, cW, 36);
                    DrawGlassCard(g, cr, 14, curBgCard, true, false);
                    g.DrawString(cfgLabels[i], fontSmallBold, Brushes.White, cr, sfCenter);
                }
            }
            // =================================================================
            // PAGE 3: DEDICATED DOWNLOADS & STORAGE MANAGER (Distinct from Library!)
            // =================================================================
            else if (activeSettingsSubPage == 3)
            {
                using (Font fSec = new Font("Segoe UI", 15f, FontStyle.Bold))
                {
                    g.DrawString("Offline Downloads & Local Storage Manager", fSec, Brushes.White, sx, sy);
                    g.DrawString("Local Folder: " + downloadsFolder + "  \u2022  " + downloadedSongs.Count + " Offline Tracks Saved", fontSubReg, Brushes.LightGray, sx, sy + 28);
                }

                string[] dlBtns = new string[]
                {
                    "+ Import MP3 / M4A Songs from PC",
                    "\u21BB Scan & Restore Local Downloads",
                    "\uD83D\uDCC2 Open Downloads Folder in Explorer",
                    "Download Quality: " + activeStreamQuality,
                    "\uD83D\uDDD1 Clear Temp Audio Cache (" + GetAudioCacheSizeText() + ")",
                    "\u2713 Go to Downloads Screen"
                };
                int bW = (sw - 12) / 2;
                for (int i = 0; i < 6; i++)
                {
                    int r = i / 2;
                    int c = i % 2;
                    Rectangle br = new Rectangle(sx + c * (bW + 12), sy + 72 + r * 54, bW, 44);
                    DrawGlassCard(g, br, 16, curBgCard, i == 0 || i == 5, false);
                    g.DrawString(dlBtns[i], fontTitleBold, Brushes.White, br, sfCenter);
                }
            }
            // =================================================================
            // PAGE 4: DEDICATED LIBRARY, 14 COUNTRIES & 14 LANGUAGES (Distinct from Downloads!)
            // =================================================================
            else if (activeSettingsSubPage == 4)
            {
                using (Font fSec = new Font("Segoe UI", 15f, FontStyle.Bold))
                {
                    g.DrawString("Library, Active Country & Music Languages", fSec, Brushes.White, sx, sy);
                    g.DrawString("Active Country: " + selectedCountry + "  \u2022  Click any country below to switch charts, recommendations & smart queue", fontSubReg, Brushes.LightGray, sx, sy + 28);
                }

                int cCols = 7;
                int cGap = 8;
                int cW = (sw - (cCols - 1) * cGap) / cCols;
                int cH = 36;
                for (int i = 0; i < availableCountries.Length; i++)
                {
                    int r = i / cCols;
                    int c = i % cCols;
                    Rectangle cr = new Rectangle(sx + c * (cW + cGap), sy + 64 + r * (cH + 8), cW, cH);
                    bool isActC = string.Equals(selectedCountry, availableCountries[i], StringComparison.OrdinalIgnoreCase);
                    DrawGlassCard(g, cr, 12, curBgCard, isActC, false);
                    g.DrawString(availableCountries[i], fontSmallBold, Brushes.White, cr, sfCenter);
                }

                int lTop = sy + 164;
                g.DrawString("Library Preferences & Multi-Language Selector:", fontTitleBold, Brushes.White, sx, lTop);

                string[] libBtns = new string[]
                {
                    "\uD83C\uDF10 Open Full 14-Language Selector Modal",
                    "Default Library Sort: " + librarySortNames[librarySortIdx],
                    "Default Library View: " + (isGridViewMode ? "Grid Cards (\u229E)" : "Compact List (\u2630)"),
                    "YouLyPlus Smart Auto-Recommend: " + (youLyPlusAutoRecommend ? "ON" : "OFF")
                };
                int bW = (sw - 12) / 2;
                for (int i = 0; i < 4; i++)
                {
                    int r = i / 2;
                    int c = i % 2;
                    Rectangle br = new Rectangle(sx + c * (bW + 12), lTop + 32 + r * 52, bW, 42);
                    DrawGlassCard(g, br, 16, curBgCard, i == 0, false);
                    g.DrawString(libBtns[i], fontTitleBold, Brushes.White, br, sfCenter);
                }
            }
            // =================================================================
            // PAGE 5: DEDICATED APPEARANCE, SONG IMAGES ON/OFF & 4 BACKGROUNDS
            // =================================================================
            else if (activeSettingsSubPage == 5)
            {
                using (Font fSec = new Font("Segoe UI", 15f, FontStyle.Bold))
                {
                    g.DrawString("Appearance, Song Cover Backgrounds & 4 Environments", fSec, Brushes.White, sx, sy);
                    g.DrawString("Toggle live song cover art in the background, or choose from 4 distinct cosmic environments", fontSubReg, Brushes.LightGray, sx, sy + 28);
                }

                // Row A: Song Images in Background ON/OFF + Slideshow Transition Mode
                Rectangle songBgRow = new Rectangle(sx, sy + 64, sw, 54);
                DrawGlassCard(g, songBgRow, 16, curBgCard, songBgImageEnabled, false);
                g.DrawString("Show Playing Song Cover Art in Background", fontTitleBold, Brushes.White, songBgRow.X + 18, songBgRow.Y + 8);
                g.DrawString("Renders the current song's artwork & artist gallery as an atmospheric cinema backdrop", fontSubReg, Brushes.LightGray, songBgRow.X + 18, songBgRow.Y + 29);
                DrawPurpleToggleSwitch(g, new Rectangle(songBgRow.Right - 64, songBgRow.Y + 15, 46, 24), songBgImageEnabled);

                // Row B: 4 Large Distinct Background Style Cards
                int bgY = sy + 132;
                g.DrawString("Choose Background Environment Style (4 Distinct Worlds):", fontTitleBold, Brushes.White, sx, bgY);
                int cardGap = 12;
                int cardW = (sw - 3 * cardGap) / 4;
                int cardH = 88;
                for (int bi = 0; bi < 4; bi++)
                {
                    Rectangle bRect = new Rectangle(sx + bi * (cardW + cardGap), bgY + 28, cardW, cardH);
                    DrawBgStylePreviewThumb(g, bRect, bi, homeEffectStyleIdx == bi);
                }

                // Row C: 6 Accent Colors + 3D Curved Glass + OLED Pure Black
                int acY = bgY + 132;
                g.DrawString("Accent Color Palette:", fontTitleBold, Brushes.White, sx, acY + 4);
                for (int ci = 0; ci < Math.Min(6, themes.Count); ci++)
                {
                    Rectangle cCircle = new Rectangle(sx + 180 + ci * 44, acY, 30, 30);
                    using (SolidBrush cb = new SolidBrush(themes[ci].Accent)) { g.FillEllipse(cb, cCircle); }
                    if (activeThemeIdx == ci)
                    {
                        using (Pen outRing = new Pen(Color.White, 2.0f)) { g.DrawEllipse(outRing, cCircle.X - 3, cCircle.Y - 3, 36, 36); }
                        g.FillEllipse(Brushes.White, cCircle.X + 10, cCircle.Y + 10, 10, 10);
                    }
                }

                int togY = acY + 42;
                int bW = (sw - 12) / 2;
                Rectangle artDesBtn = new Rectangle(sx, togY, bW, 38);
                Rectangle bumpBtn   = new Rectangle(sx + bW + 12, togY, bW, 38);
                Rectangle glassBtn  = new Rectangle(sx, togY + 44, bW, 38);
                Rectangle oledBtn   = new Rectangle(sx + bW + 12, togY + 44, bW, 38);
                DrawGlassCard(g, artDesBtn, 14, curBgCard, true, false);
                DrawGlassCard(g, bumpBtn, 14, curBgCard, beatBumpEnabled, false);
                DrawGlassCard(g, glassBtn, 14, curBgCard, curved3DGlassEnabled, false);
                DrawGlassCard(g, oledBtn, 14, curBgCard, oledPureBlack, false);
                g.DrawString("\u2726 Full Player Art: " + fullArtDesignNames[fullArtDesignIdx], fontSmallBold, Brushes.White, artDesBtn, sfCenter);
                g.DrawString("Beat-Reactive Image Bump-Up: " + (beatBumpEnabled ? "ON" : "OFF"), fontSmallBold, Brushes.White, bumpBtn, sfCenter);
                g.DrawString("3D Curved Specular Glass: " + (curved3DGlassEnabled ? "ON" : "OFF"), fontSmallBold, Brushes.White, glassBtn, sfCenter);
                g.DrawString("OLED Pure Black Mode: " + (oledPureBlack ? "ON" : "OFF"), fontSmallBold, Brushes.White, oledBtn, sfCenter);
            }
            // =================================================================
            // PAGE 6: SHORTCUTS
            // =================================================================
            else if (activeSettingsSubPage == 6)
            {
                using (Font fSec = new Font("Segoe UI", 15f, FontStyle.Bold))
                {
                    g.DrawString("Keyboard Shortcuts", fSec, Brushes.White, sx, sy);
                }
                string[,] keys = new string[,]
                {
                    { "Focus Global Search Bar", "Ctrl + K" },
                    { "Play / Pause Track", "Space" },
                    { "Seek Forward / Backward 5s", "Left / Right Arrow" },
                    { "Volume Up / Down 5%", "Up / Down Arrow" },
                    { "Next / Previous Track", "N / P" },
                    { "Toggle Full-Screen Lyrics View", "F" },
                    { "Like / Favorite Current Track", "L" },
                    { "Download Current Track Offline", "D" }
                };
                for (int i = 0; i < keys.GetLength(0); i++)
                {
                    int ry = sy + 42 + i * 42;
                    Rectangle kr = new Rectangle(sx, ry, sw, 36);
                    DrawGlassCard(g, kr, 12, curBgCard, false, false);
                    g.DrawString(keys[i, 0], fontTitleBold, Brushes.White, kr.X + 16, kr.Y + 7);
                    Rectangle badge = new Rectangle(kr.Right - 148, kr.Y + 5, 134, 26);
                    FillRoundRect(g, new SolidBrush(Color.FromArgb(75, accentColor)), badge, 10);
                    g.DrawString(keys[i, 1], fontSmallBold, Brushes.White, badge, sfCenter);
                }
            }
            // =================================================================
            // PAGE 7: ACCOUNT
            // =================================================================
            else if (activeSettingsSubPage == 7)
            {
                using (Font fSec = new Font("Segoe UI", 15f, FontStyle.Bold))
                {
                    g.DrawString("Account & Studio Profile", fSec, Brushes.White, sx, sy);
                }
                Rectangle avRect = new Rectangle(sx, sy + 42, 84, 84);
                DrawUserProfileAvatar(g, avRect, 42);
                using (Pen avP = new Pen(accentColor, 2.0f)) { g.DrawEllipse(avP, avRect); }

                using (Font fName = new Font("Segoe UI", 16f, FontStyle.Bold))
                {
                    g.DrawString(userName, fName, Brushes.White, sx + 104, sy + 48);
                    g.DrawString("Country: " + selectedCountry + "  \u2022  Listening Time: " + (totalListeningSeconds / 60) + " mins", fontSubReg, Brushes.LightGray, sx + 106, sy + 82);
                }

                string[] accBtns = new string[]
                {
                    "+ Upload Profile Photo from PC",
                    "\u270E Edit Profile Name (" + userName + ")",
                    "Startup Voice Welcome: " + (voiceWelcomeEnabled ? "ON" : "OFF"),
                    "\u25C9 Select Country & Languages"
                };
                int bW = (sw - 12) / 2;
                for (int i = 0; i < 4; i++)
                {
                    int r = i / 2;
                    int c = i % 2;
                    Rectangle br = new Rectangle(sx + c * (bW + 12), sy + 148 + r * 52, bW, 42);
                    DrawGlassCard(g, br, 16, curBgCard, i == 0, false);
                    g.DrawString(accBtns[i], fontTitleBold, Brushes.White, br, sfCenter);
                }
            }
            // =================================================================
            // PAGE 8: ABOUT
            // =================================================================
            else
            {
                using (Font fSec = new Font("Segoe UI", 15f, FontStyle.Bold))
                {
                    g.DrawString("About LEO Music Studio v" + CURRENT_APP_VERSION + " & Auto-Updater", fSec, Brushes.White, sx, sy);
                }
                g.DrawString(latestUpdateTitle, fontTitleBold, new SolidBrush(Color.FromArgb(215, 165, 255)), sx, sy + 36);

                Rectangle notesR = new Rectangle(sx, sy + 68, sw, 140);
                DrawGlassCard(g, notesR, 16, curBgCard, false, false);
                string[] nLines = (latestUpdateNotes ?? "").Split(new char[] { '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries);
                for (int i = 0; i < nLines.Length; i++)
                {
                    g.DrawString(nLines[i], fontSubReg, Brushes.White, sx + 16, notesR.Y + 14 + i * 26);
                }

                Rectangle chkBtn = new Rectangle(sx, notesR.Bottom + 20, 220, 42);
                Rectangle popBtn = new Rectangle(sx + 234, notesR.Bottom + 20, 220, 42);
                DrawGlassCard(g, chkBtn, 16, curBgCard, true, false);
                DrawGlassCard(g, popBtn, 16, curBgCard, false, false);
                g.DrawString(isCheckingUpdate ? "Checking..." : "\u21BB Check for Updates Now", fontTitleBold, Brushes.White, chkBtn, sfCenter);
                g.DrawString("View Update Center Popup", fontTitleBold, Brushes.White, popBtn, sfCenter);
            }
        }

        private void PaintDockedAiSidePanelContent(Graphics g, Rectangle box, StringFormat sfCenter, StringFormat sfLeftEllipsis)
        {
            int x = box.X + 4;
            int w = box.Width - 8;
            int y = box.Y + 2;

            // 1. Clean Orb + Controls Header Card
            Rectangle hdrCard = new Rectangle(x, y, w, 74);
            using (SolidBrush hb = new SolidBrush(Color.FromArgb(210, 18, 22, 34)))
            using (Pen hp = new Pen(Color.FromArgb(85, 0, 235, 255), 1f))
            {
                FillRoundRect(g, hb, hdrCard, 12);
                DrawRoundRect(g, hp, hdrCard, 12);
            }

            Rectangle orbR = new Rectangle(hdrCard.X + 8, hdrCard.Y + 11, 48, 48);
            PaintSiriGoogleAssistantOrb(g, orbR, isAgentListeningVoice || isAgentBusyExecuting, sfCenter);

            using (Font fHdr = new Font("Segoe UI", 9.5f, FontStyle.Bold))
            using (SolidBrush subB = new SolidBrush(isAgentListeningVoice ? Color.FromArgb(60, 245, 155) : Color.FromArgb(180, 195, 215)))
            {
                g.DrawString("Leo Smart AI Side Panel", fHdr, Brushes.White, new RectangleF(hdrCard.X + 64, hdrCard.Y + 8, hdrCard.Width - 70, 18), sfLeftEllipsis);
                g.DrawString(agentStatusSubtitle, fontSmallBold, subB, new RectangleF(hdrCard.X + 64, hdrCard.Y + 26, hdrCard.Width - 70, 16), sfLeftEllipsis);
            }

            // 3 Compact Header Action Pills: [ 🎤 Mic ] [ ✦ Circle ] [ Float ]
            int pY = hdrCard.Y + 46;
            Rectangle micBtn   = new Rectangle(hdrCard.X + 64, pY, 64, 22);
            Rectangle styleBtn = new Rectangle(micBtn.Right + 5, pY, 72, 22);
            Rectangle floatBtn = new Rectangle(styleBtn.Right + 5, pY, 60, 22);
            using (SolidBrush bMic = new SolidBrush(isAgentListeningVoice ? Color.FromArgb(234, 67, 53) : Color.FromArgb(55, 66, 133, 244)))
            using (SolidBrush bSty = new SolidBrush(Color.FromArgb(45, 0, 225, 255)))
            using (SolidBrush bFlt = new SolidBrush(Color.FromArgb(45, accentColor.R, accentColor.G, accentColor.B)))
            {
                FillRoundRect(g, bMic, micBtn, 8);
                FillRoundRect(g, bSty, styleBtn, 8);
                FillRoundRect(g, bFlt, floatBtn, 8);
            }
            g.DrawString(isAgentListeningVoice ? "Speak" : "\u25C9 Mic", fontSmallBold, Brushes.White, micBtn, sfCenter);
            g.DrawString("\u2726 Circle", fontSmallBold, Brushes.White, styleBtn, sfCenter);
            g.DrawString("Float PC", fontSmallBold, Brushes.White, floatBtn, sfCenter);

            y += 82;

            // 2. Smart Typo-Tolerant Input Bar + [ ▶ Run ]
            using (SolidBrush lblB = new SolidBrush(Color.FromArgb(0, 230, 255)))
            {
                g.DrawString("HIGH-SMART TYPO AI (Try 'paly strby', 'opn whtsp'):", fontSmallBold, lblB, x + 2, y);
            }
            y += 18;

            Rectangle inputRect = new Rectangle(x, y, w - 64, 34);
            Rectangle runBtn = new Rectangle(inputRect.Right + 6, y, 58, 34);
            using (SolidBrush ib = new SolidBrush(Color.FromArgb(22, 24, 34)))
            using (Pen ip = new Pen(Color.FromArgb(145, 0, 235, 255), 1.2f))
            {
                FillRoundRect(g, ib, inputRect, 10);
                DrawRoundRect(g, ip, inputRect, 10);
            }
            if (isEditingAgentPrompt && agentCommandBox != null)
            {
                Point targetPt = new Point(inputRect.X + 8, inputRect.Y + 6);
                if (agentCommandBox.Location != targetPt || agentCommandBox.Width != inputRect.Width - 16)
                {
                    agentCommandBox.Location = targetPt;
                    agentCommandBox.Size = new Size(Math.Max(100, inputRect.Width - 16), 22);
                }
            }
            else if (agentCommandBox == null || string.IsNullOrEmpty(agentCommandBox.Text))
            {
                using (SolidBrush phB = new SolidBrush(Color.FromArgb(140, 185, 198, 215)))
                {
                    g.DrawString("Type command (even half/wrong spelling)...", fontSmallBold, phB, new RectangleF(inputRect.X + 8, inputRect.Y + 8, inputRect.Width - 14, 18), sfLeftEllipsis);
                }
            }

            using (SolidBrush rb = new SolidBrush(accentColor))
            {
                FillRoundRect(g, rb, runBtn, 10);
            }
            g.DrawString("\u25B6 Run", fontSmallBold, Brushes.White, runBtn, sfCenter);
            y += 40;

            if (!string.IsNullOrEmpty(agentSmartTypoHint))
            {
                using (SolidBrush hb = new SolidBrush(Color.FromArgb(120, 240, 255)))
                {
                    g.DrawString(agentSmartTypoHint, fontSmallBold, hb, new RectangleF(x + 2, y, w - 4, 17), sfLeftEllipsis);
                }
                y += 20;
            }

            // 3. 8 Clean 2-Column Quick Action Chips
            string[] chipTitles = new string[]
            {
                "\u2726 WhatsApp Msg",
                "\u2726 Add Note",
                "\u2726 Ask ChatGPT",
                "\u2726 YouTube Play",
                "\u26A1 4-in-1 Combo",
                "\u266B Typo Play Demo",
                "\u266B 3D + Vol 115%",
                "\u25C9 Screenshot"
            };
            int colW = (w - 8) / 2;
            int chipH = 26;
            for (int i = 0; i < 8; i++)
            {
                int c = i % 2;
                int r = i / 2;
                Rectangle cr = new Rectangle(x + c * (colW + 8), y + r * (chipH + 6), colW, chipH);
                using (SolidBrush cb = new SolidBrush((i == 4 || i == 5) ? Color.FromArgb(48, 0, 230, 255) : Color.FromArgb(30, 35, 50)))
                using (Pen cp = new Pen((i == 4 || i == 5) ? Color.FromArgb(135, 0, 230, 255) : Color.FromArgb(45, 255, 255, 255), 1f))
                {
                    FillRoundRect(g, cb, cr, 8);
                    DrawRoundRect(g, cp, cr, 8);
                }
                g.DrawString(chipTitles[i], fontSmallBold, Brushes.White, cr, sfCenter);
            }
            y += 4 * (chipH + 6) + 6;

            // 4. Live Multi-Task Execution Log & Saved Notes Box
            int logH = Math.Max(64, box.Bottom - y - 4);
            Rectangle logCard = new Rectangle(x, y, w, logH);
            using (SolidBrush lb = new SolidBrush(Color.FromArgb(195, 11, 13, 20)))
            using (Pen lp = new Pen(Color.FromArgb(40, 255, 255, 255), 1f))
            {
                FillRoundRect(g, lb, logCard, 12);
                DrawRoundRect(g, lp, logCard, 12);
            }
            using (SolidBrush hdrB = new SolidBrush(Color.FromArgb(195, 0, 235, 255)))
            {
                g.DrawString("LIVE SMART AI LOG & NOTES", fontSmallBold, hdrB, logCard.X + 10, logCard.Y + 7);
            }
            int ly = logCard.Y + 26;
            using (SolidBrush txtB = new SolidBrush(Color.FromArgb(225, 235, 245)))
            {
                for (int i = 0; i < agentExecutionLogs.Count; i++)
                {
                    if (ly + 18 > logCard.Bottom - 4) break;
                    g.DrawString(agentExecutionLogs[i], fontSmallBold, txtB, new RectangleF(logCard.X + 10, ly, logCard.Width - 18, 17), sfLeftEllipsis);
                    ly += 19;
                }
            }
        }

        private void PaintRightDockedPanel(Graphics g, int rightX, int rightW, int mainH, Color curBgSide, Color curBgCard, StringFormat sfCenter, StringFormat sfLeftEllipsis)
        {
            if (currentSong == null) return;

            Rectangle cardRect = new Rectangle(rightX + 4, 68, rightW - 18, mainH - 76);
            DrawGlassCard(g, cardRect, 26, curBgSide, true, false);

            using (Pen topGlow = new Pen(Color.FromArgb(245, 230, 185, 255), 2.4f))
            {
                g.DrawLine(topGlow, cardRect.Right - 145, cardRect.Y, cardRect.Right - 24, cardRect.Y);
                g.DrawLine(topGlow, cardRect.X + 24, cardRect.Bottom, cardRect.X + 145, cardRect.Bottom);
            }

            Rectangle segBar = new Rectangle(cardRect.X + 14, cardRect.Y + 12, cardRect.Width - 28, 30);
            using (SolidBrush sbBg = new SolidBrush(Color.FromArgb(180, 14, 10, 28)))
            using (Pen sbRim = new Pen(Color.FromArgb(85, 195, 150, 255), 1f))
            {
                FillRoundRect(g, sbBg, segBar, 15);
                DrawRoundRect(g, sbRim, segBar, 15);
            }
            string[] sideTabs = new string[] { "\u266B Player", "\u2630 Queue", "\u2630 Lyrics" };
            int stW = (segBar.Width - 6) / 3;
            for (int ti = 0; ti < 3; ti++)
            {
                Rectangle tr = new Rectangle(segBar.X + 3 + ti * stW, segBar.Y + 3, stW - 2, 24);
                bool isSel = (rightPanelMode == ti);
                if (isSel)
                {
                    FillRoundRect(g, new SolidBrush(accentColor), tr, 12);
                }
                g.DrawString(sideTabs[ti], fontSmallBold, Brushes.White, tr, sfCenter);
            }

            if (rightPanelMode == 1 || rightPanelMode == 2)
            {
                Rectangle listBox = new Rectangle(cardRect.X + 8, cardRect.Y + 48, cardRect.Width - 16, cardRect.Height - 102);
                if (rightPanelMode == 2)
                {
                    PaintBetterLyricsCanvas(g, listBox, false, sfCenter);
                }
                else
                {
                    Region prevRightClip = g.Clip;
                    g.SetClip(listBox);
                    int qRowH = 52;
                    int qTotalH = queueSongs.Count * (qRowH + 5) + 8;
                    int maxQ = Math.Max(0, qTotalH - listBox.Height);
                    if (queueScrollOffset > maxQ) queueScrollOffset = maxQ;

                    for (int i = 0; i < queueSongs.Count; i++)
                    {
                        int qy = listBox.Y + 2 + i * (qRowH + 5) - queueScrollOffset;
                        if (qy + qRowH < listBox.Y - 2 || qy > listBox.Bottom + 2) continue;
                        SongItem qs = queueSongs[i];
                        bool isPlayingThis = (currentSong != null && currentSong.Id == qs.Id);
                        Rectangle qRowRect = new Rectangle(listBox.X + 4, qy, listBox.Width - 12, qRowH);
                        DrawGlassCard(g, qRowRect, 12, curBgCard, isPlayingThis, hoveredQueueIndex == i);
                        DrawStaticAlbumArt(g, qs.ThumbUrl, new Rectangle(qRowRect.X + 8, qRowRect.Y + 6, 40, 40), 8);
                        g.DrawString(FormatMinimalCardTitle(qs.Title), fontSmallBold, isPlayingThis ? new SolidBrush(Color.FromArgb(230, 190, 255)) : Brushes.White, new RectangleF(qRowRect.X + 54, qRowRect.Y + 8, qRowRect.Width - 62, 18), sfLeftEllipsis);
                        g.DrawString(GetPrimaryArtistName(qs.Artist), fontSubReg, Brushes.LightGray, new RectangleF(qRowRect.X + 54, qRowRect.Y + 26, qRowRect.Width - 62, 16), sfLeftEllipsis);
                    }
                    g.Clip = prevRightClip;
                }

                int mCy = cardRect.Bottom - 28;
                int mMidX = cardRect.X + cardRect.Width / 2;
                DrawSkipPrevIcon(g, Brushes.White, mMidX - 54f, mCy);
                DrawGlowingNeonPlayButton(g, new Rectangle(mMidX - 18, mCy - 18, 36, 36), isPlaying);
                DrawSkipNextIcon(g, Brushes.White, mMidX + 54f, mCy);
                return;
            }

            int artPad = 24;
            int artSz = Math.Min(cardRect.Width - artPad * 2, Math.Max(155, cardRect.Height - 275));
            int artX = cardRect.X + (cardRect.Width - artSz) / 2;
            int artY = cardRect.Y + 50;
            Rectangle baseArtRect = new Rectangle(artX, artY, artSz, artSz);
            Rectangle artRect = beatBumpEnabled ? ScaleRectCentered(baseArtRect, beatBumpScale) : baseArtRect;

            DrawStaticAlbumArt(g, currentSong.ThumbUrl, artRect, 20);
            using (Pen artRim = new Pen(Color.FromArgb(165, 235, 205, 255), 1.4f))
            {
                DrawRoundRect(g, artRim, artRect, 20);
            }

            int metaY = baseArtRect.Bottom + 14;
            using (Font fRtTitle = new Font("Segoe UI", 12.2f, FontStyle.Bold))
            using (Font fRtArtist = new Font("Segoe UI", 9.4f, FontStyle.Regular))
            using (SolidBrush subB = new SolidBrush(Color.FromArgb(215, 208, 238)))
            {
                g.DrawString(FormatMinimalCardTitle(currentSong.Title), fRtTitle, Brushes.White, new RectangleF(cardRect.X + 20, metaY, cardRect.Width - 94, 24), sfLeftEllipsis);
                g.DrawString(GetPrimaryArtistName(currentSong.Artist), fRtArtist, subB, new RectangleF(cardRect.X + 20, metaY + 23, cardRect.Width - 94, 19), sfLeftEllipsis);
            }

            bool isLiked = likedIds.Contains(currentSong.Id);
            DrawHeartIcon(g, isLiked ? accentColor : Color.FromArgb(235, 230, 250), cardRect.Right - 54f, metaY + 18f, isLiked);
            g.DrawString("\u2022\u2022\u2022", fontSmallBold, Brushes.White, cardRect.Right - 32, metaY + 10);

            int waveCy = metaY + 62;
            int numBars = 27;
            int barSpacing = 7;
            int totalWaveW = numBars * barSpacing;
            int waveStartX = cardRect.X + (cardRect.Width - totalWaveW) / 2;
            float[] baseHeights = new float[]
            {
                3f, 5f, 8f, 12f, 7f, 15f, 10f, 18f, 9f, 14f, 20f, 11f, 16f, 24f,
                15f, 11f, 21f, 13f, 9f, 17f, 10f, 14f, 7f, 11f, 6f, 4f, 3f
            };
            for (int b = 0; b < numBars; b++)
            {
                float animMod = isPlaying ? (0.65f + 0.55f * (float)Math.Abs(Math.Sin(wavePhase * 1.6f + b * 0.45f))) : 0.85f;
                int bh = Math.Max(3, (int)(baseHeights[b] * animMod));
                int bx = waveStartX + b * barSpacing;
                Color barCol = (b % 3 == 0) ? Color.FromArgb(245, 225, 165, 255) : accentColor;
                using (SolidBrush wb = new SolidBrush(barCol))
                {
                    FillRoundRect(g, wb, new Rectangle(bx, waveCy - bh / 2, 2, bh), 1);
                }
            }

            int seekY = waveCy + 30;
            int seekX = cardRect.X + 22;
            int seekW = cardRect.Width - 44;
            float frac = (float)Math.Max(0.0, Math.Min(1.0, smoothPosSec / Math.Max(1.0, currentDurSec)));
            int actSeekX = seekX + (int)(seekW * frac);

            using (Pen trP = new Pen(Color.FromArgb(75, 255, 255, 255), 3.4f))
            {
                trP.StartCap = LineCap.Round;
                trP.EndCap = LineCap.Round;
                g.DrawLine(trP, seekX, seekY, seekX + seekW, seekY);
            }
            if (actSeekX > seekX + 2)
            {
                using (Pen acP = new Pen(accentColor, 3.8f))
                {
                    acP.StartCap = LineCap.Round;
                    acP.EndCap = LineCap.Round;
                    g.DrawLine(acP, seekX, seekY, actSeekX, seekY);
                }
            }
            using (SolidBrush glowK = new SolidBrush(Color.FromArgb(110, accentColor)))
            {
                g.FillEllipse(glowK, actSeekX - 9, seekY - 9, 18, 18);
                g.FillEllipse(Brushes.White, actSeekX - 5, seekY - 5, 10, 10);
            }

            using (Font fTime = new Font("Segoe UI", 8.4f, FontStyle.Regular))
            using (SolidBrush tb = new SolidBrush(Color.FromArgb(215, 210, 235)))
            {
                g.DrawString(FormatSec((int)currentPosSec), fTime, tb, seekX, seekY + 10);
                SizeF durSz = g.MeasureString(FormatSec((int)currentDurSec), fTime);
                g.DrawString(FormatSec((int)currentDurSec), fTime, tb, seekX + seekW - durSz.Width, seekY + 10);
            }

            int ctrlCy = cardRect.Bottom - 36;
            int ctrlMidX = cardRect.X + cardRect.Width / 2;

            DrawRepeatVectorIcon(g, isRepeatOne ? accentColor : Color.FromArgb(225, 220, 245), ctrlMidX - 96f, ctrlCy);
            DrawSkipPrevIcon(g, Brushes.White, ctrlMidX - 48f, ctrlCy);

            Rectangle rtPlayRect = ScaleRectCentered(new Rectangle(ctrlMidX - 23, ctrlCy - 23, 46, 46), GetButtonScale("play"));
            DrawGlowingNeonPlayButton(g, rtPlayRect, isPlaying);

            DrawSkipNextIcon(g, Brushes.White, ctrlMidX + 48f, ctrlCy);
            DrawShuffleVectorIcon(g, isShuffle ? accentColor : Color.FromArgb(225, 220, 245), ctrlMidX + 96f, ctrlCy);
        }

        private void DrawFullStageCustomAlbumArtwork(Graphics g, Rectangle baseArtRect)
        {
            Rectangle bigArtRect = beatBumpEnabled ? ScaleRectCentered(baseArtRect, beatBumpScale) : baseArtRect;
            float cx = bigArtRect.X + bigArtRect.Width / 2f;
            float cy = bigArtRect.Y + bigArtRect.Height / 2f;

            if (isPlaying || fullArtDesignIdx == 1 || fullArtDesignIdx == 4)
            {
                for (int r = 3; r >= 1; r--)
                {
                    int exp = (int)(r * 12 * beatBumpScale);
                    Rectangle haloR = new Rectangle(bigArtRect.X - exp, bigArtRect.Y - exp, bigArtRect.Width + exp * 2, bigArtRect.Height + exp * 2);
                    using (SolidBrush hb = new SolidBrush(Color.FromArgb(18 * (4 - r), accentColor.R, accentColor.G, accentColor.B)))
                    {
                        if (fullArtDesignIdx == 2 || fullArtDesignIdx == 1 || fullArtDesignIdx == 4) g.FillEllipse(hb, haloR);
                        else FillRoundRect(g, hb, haloR, 28 + exp);
                    }
                }
            }

            if (fullArtDesignIdx == 0)
            {
                int vinylDiam = bigArtRect.Width - 22;
                Rectangle vinylRect = new Rectangle(bigArtRect.Right - vinylDiam / 2 - 20, bigArtRect.Y + 11, vinylDiam, vinylDiam);
                using (LinearGradientBrush vBase = new LinearGradientBrush(
                    vinylRect,
                    Color.FromArgb(252, 26, 18, 44),
                    Color.FromArgb(255, 8, 6, 14),
                    35f + (isPlaying ? (vinylAngle % 360f) * 0.2f : 0f)))
                {
                    g.FillEllipse(vBase, vinylRect);
                }
                using (Pen vRim = new Pen(Color.FromArgb(190, 205, 165, 255), 1.6f))
                {
                    g.DrawEllipse(vRim, vinylRect);
                    for (int gr = 12; gr < vinylDiam / 2 - 16; gr += 9)
                    {
                        int aGr = (gr % 18 == 0) ? 95 : 45;
                        using (Pen vGroove = new Pen(Color.FromArgb(aGr, 195, 140, 255), 1.1f))
                        {
                            g.DrawEllipse(vGroove, vinylRect.X + gr, vinylRect.Y + gr, vinylRect.Width - gr * 2, vinylRect.Height - gr * 2);
                        }
                    }
                }
                using (SolidBrush shB = new SolidBrush(Color.FromArgb(145, 4, 2, 10)))
                {
                    FillRoundRect(g, shB, new Rectangle(bigArtRect.X + 4, bigArtRect.Y + 8, bigArtRect.Width, bigArtRect.Height), 24);
                }
                DrawStaticAlbumArt(g, currentSong.ThumbUrl, bigArtRect, 24);
                using (Pen artRim = new Pen(Color.FromArgb(175, 235, 205, 255), 1.6f))
                {
                    DrawRoundRect(g, artRim, bigArtRect, 24);
                }
            }
            else if (fullArtDesignIdx == 1 || fullArtDesignIdx == 4)
            {
                int numSpokes = 48;
                float baseR = bigArtRect.Width / 2f + 8f;
                for (int i = 0; i < numSpokes; i++)
                {
                    double ang = (i / (double)numSpokes) * Math.PI * 2.0 + (vinylAngle * 0.01);
                    float barLen = isPlaying ? (8f + 22f * (float)Math.Abs(Math.Sin(wavePhase * 1.8f + i * 0.45f))) : 6f;
                    float x1 = cx + baseR * (float)Math.Cos(ang);
                    float y1 = cy + baseR * (float)Math.Sin(ang);
                    float x2 = cx + (baseR + barLen) * (float)Math.Cos(ang);
                    float y2 = cy + (baseR + barLen) * (float)Math.Sin(ang);
                    Color sc = (i % 2 == 0) ? accentColor : Color.FromArgb(235, 225, 165, 255);
                    using (Pen sp = new Pen(sc, 3.0f))
                    {
                        sp.StartCap = LineCap.Round;
                        sp.EndCap = LineCap.Round;
                        g.DrawLine(sp, x1, y1, x2, y2);
                    }
                }
                DrawStaticAlbumArt(g, currentSong.ThumbUrl, bigArtRect, bigArtRect.Width / 2);
                using (Pen rim = new Pen(Color.FromArgb(225, 235, 195, 255), 2.2f))
                {
                    g.DrawEllipse(rim, bigArtRect);
                }
            }
            else if (fullArtDesignIdx == 2)
            {
                using (LinearGradientBrush vBase = new LinearGradientBrush(
                    bigArtRect,
                    Color.FromArgb(255, 28, 18, 48),
                    Color.FromArgb(255, 8, 6, 16),
                    vinylAngle))
                {
                    g.FillEllipse(vBase, bigArtRect);
                }
                for (int gr = 10; gr < bigArtRect.Width / 2 - 42; gr += 8)
                {
                    using (Pen gp = new Pen(Color.FromArgb((gr % 16 == 0) ? 105 : 48, 205, 155, 255), 1.1f))
                    {
                        g.DrawEllipse(gp, bigArtRect.X + gr, bigArtRect.Y + gr, bigArtRect.Width - gr * 2, bigArtRect.Height - gr * 2);
                    }
                }
                int innerSz = (int)(bigArtRect.Width * 0.56f);
                Rectangle innerArt = new Rectangle((int)cx - innerSz / 2, (int)cy - innerSz / 2, innerSz, innerSz);
                DrawStaticAlbumArt(g, currentSong.ThumbUrl, innerArt, innerSz / 2);
                using (Pen ip = new Pen(accentColor, 2.0f)) { g.DrawEllipse(ip, innerArt); }
                g.FillEllipse(new SolidBrush(Color.FromArgb(255, 12, 9, 24)), cx - 9, cy - 9, 18, 18);
                g.DrawEllipse(new Pen(Color.White, 1.5f), cx - 9, cy - 9, 18, 18);
            }
            else
            {
                Rectangle outerPrism = new Rectangle(bigArtRect.X - 12, bigArtRect.Y - 12, bigArtRect.Width + 24, bigArtRect.Height + 24);
                DrawGlassCard(g, outerPrism, 32, Color.FromArgb(32, 22, 58), true, true);
                DrawStaticAlbumArt(g, currentSong.ThumbUrl, bigArtRect, 24);
                using (Pen rp = new Pen(Color.FromArgb(215, 235, 200, 255), 1.8f))
                {
                    DrawRoundRect(g, rp, bigArtRect, 24);
                }
            }
        }

        private void PaintFullNowPlayingPanel(Graphics g, int w, int h, float animAlpha, StringFormat sfCenter, StringFormat sfLeftEllipsis)
        {
            using (SolidBrush solidBase = new SolidBrush(Color.FromArgb(255, 10, 8, 20)))
            {
                g.FillRectangle(solidBase, 0, 0, w, h);
            }

            if (songBgImageEnabled)
            {
                PaintAtmosphericSongBackdrop(g, w, h, 1.15f);
            }
            PaintLiveMeshAuroraBackdrop(g, w, h);
            PaintSpatialEnvironmentBackdrop(g, w, h);

            using (Pen backP = new Pen(Color.FromArgb(235, 235, 230, 255), 2.2f))
            {
                backP.StartCap = LineCap.Round;
                backP.EndCap = LineCap.Round;
                g.DrawLine(backP, 34f, 22f, 27f, 29f);
                g.DrawLine(backP, 27f, 29f, 34f, 36f);
            }
            DrawBrandMusicNoteLogo(g, 58, 17);

            string[] viewModeShort = new string[] { "Only Art", "Split Stage", "Full Lyrics", "Concert 3D" };
            fullArtDesignPillRect = new Rectangle(w - 432, 16, 176, 30);
            fullViewModePillRect  = new Rectangle(w - 246, 16, 134, 30);
            DrawGlassCard(g, fullArtDesignPillRect, 15, bgCard, false, false);
            DrawGlassCard(g, fullViewModePillRect, 15, bgCard, true, false);
            g.DrawString("\u2726 Art: " + fullArtDesignNames[fullArtDesignIdx].Split(' ')[0] + " " + fullArtDesignNames[fullArtDesignIdx].Split(' ')[1], fontSmallBold, Brushes.White, fullArtDesignPillRect, sfCenter);
            g.DrawString("\u25EB View: " + viewModeShort[Math.Max(0, Math.Min(3, fullViewSubMode))], fontSmallBold, Brushes.White, fullViewModePillRect, sfCenter);

            Rectangle leftActionPill = new Rectangle(32, 136, 54, 304);
            if (fullViewSubMode != 2)
            {
                DrawGlassCard(g, leftActionPill, 27, Color.FromArgb(24, 18, 46), false, false);
                float pillCx = leftActionPill.X + 27f;
                int[] iconYs = new int[] { 168, 226, 284, 342, 400 };
                bool isCurLiked = (currentSong != null && likedIds.Contains(currentSong.Id));
                DrawHeartIcon(g, isCurLiked ? accentColor : Color.FromArgb(235, 230, 250), pillCx, iconYs[0], isCurLiked);
                DrawPlusQueueIcon(g, Color.FromArgb(225, 220, 240), pillCx, iconYs[1]);
                DrawDownloadArrow(g, Color.FromArgb(225, 220, 240), pillCx, iconYs[2]);
                using (Pen shP = new Pen(Color.FromArgb(225, 220, 240), 1.7f))
                {
                    float sy = iconYs[3];
                    g.DrawEllipse(shP, pillCx + 2f, sy - 7f, 5f, 5f);
                    g.DrawEllipse(shP, pillCx - 7f, sy - 2.5f, 5f, 5f);
                    g.DrawEllipse(shP, pillCx + 2f, sy + 2f, 5f, 5f);
                    g.DrawLine(shP, pillCx - 2f, sy - 1f, pillCx + 2.5f, sy - 4f);
                    g.DrawLine(shP, pillCx - 2f, sy + 1f, pillCx + 2.5f, sy + 4f);
                }
                g.DrawString("\u2022\u2022\u2022", fontTitleBold, Brushes.White, new RectangleF(leftActionPill.X, iconYs[4] - 12, leftActionPill.Width, 24), sfCenter);
            }

            if (fullViewSubMode == 2)
            {
                Rectangle fullLyrBox = new Rectangle(64, 58, w - 128, h - 134);
                DrawGlassCard(g, fullLyrBox, 26, bgCard, false, false);
                PaintBetterLyricsCanvas(g, new Rectangle(fullLyrBox.X + 16, fullLyrBox.Y + 14, fullLyrBox.Width - 32, fullLyrBox.Height - 28), true, sfCenter);

                Rectangle botPod = new Rectangle(w / 2 - 280, h - 64, 560, 48);
                DrawGlassCard(g, botPod, 24, Color.FromArgb(22, 16, 44), true, false);
                DrawStaticAlbumArt(g, currentSong.ThumbUrl, new Rectangle(botPod.X + 10, botPod.Y + 6, 36, 36), 9);
                g.DrawString(FormatMinimalCardTitle(currentSong.Title), fontSmallBold, Brushes.White, new RectangleF(botPod.X + 54, botPod.Y + 8, 175, 18), sfLeftEllipsis);
                g.DrawString(GetPrimaryArtistName(currentSong.Artist), fontSubReg, Brushes.LightGray, new RectangleF(botPod.X + 54, botPod.Y + 24, 175, 16), sfLeftEllipsis);
                int bMid = botPod.X + 340;
                int bCy = botPod.Y + 24;
                DrawSkipPrevIcon(g, Brushes.White, bMid - 48f, bCy);
                DrawGlowingNeonPlayButton(g, new Rectangle(bMid - 18, bCy - 18, 36, 36), isPlaying);
                DrawSkipNextIcon(g, Brushes.White, bMid + 48f, bCy);

                Rectangle exitPill = new Rectangle(botPod.Right - 122, botPod.Y + 10, 110, 28);
                FillRoundRect(g, new SolidBrush(Color.FromArgb(90, accentColor)), exitPill, 14);
                g.DrawString("\u2715 Split View", fontSmallBold, Brushes.White, exitPill, sfCenter);

                if (fullThreeDotMenuAnim > 0.01f) PaintFullThreeDotPopupMenu(g, w, h, fullThreeDotMenuAnim, sfCenter, sfLeftEllipsis);
                return;
            }

            if (fullViewSubMode == 3)
            {
                Rectangle concertCard = new Rectangle(106, 66, w - 138, h - 140);
                DrawGlassCard(g, concertCard, 26, Color.FromArgb(18, 12, 38), true, false);

                int cMidX = concertCard.X + concertCard.Width / 2;
                int artSzC = Math.Min(196, concertCard.Height / 3 + 24);
                Rectangle cArt = new Rectangle(cMidX - artSzC / 2, concertCard.Y + 26, artSzC, artSzC);
                DrawFullStageCustomAlbumArtwork(g, cArt);

                using (Font fCt = new Font("Segoe UI", 18f, FontStyle.Bold))
                {
                    g.DrawString(FormatMinimalCardTitle(currentSong.Title) + "  \u2022  " + GetPrimaryArtistName(currentSong.Artist), fCt, Brushes.White, new RectangleF(concertCard.X + 20, cArt.Bottom + 14, concertCard.Width - 40, 30), sfCenter);
                }

                int numSpec = 48;
                int specW = Math.Min(concertCard.Width - 80, 760);
                int specStartX = cMidX - specW / 2;
                int specBaseY = cArt.Bottom + 115;
                int barStep = specW / numSpec;
                for (int b = 0; b < numSpec; b++)
                {
                    float distCenter = 1.0f - Math.Abs(b - numSpec / 2f) / (numSpec / 2f);
                    float waveH = isPlaying ? (0.25f + 0.75f * (float)Math.Abs(Math.Sin(wavePhase * 1.9f + b * 0.32f))) : 0.2f;
                    int bh = Math.Max(6, (int)((20f + 78f * distCenter) * waveH * beatBumpScale));
                    int bx = specStartX + b * barStep;
                    Color bc = (b % 3 == 0) ? Color.FromArgb(240, 225, 165, 255) : ((b % 2 == 0) ? accentColor : Color.FromArgb(220, 56, 189, 248));
                    using (SolidBrush sb = new SolidBrush(bc))
                    {
                        FillRoundRect(g, sb, new Rectangle(bx, specBaseY - bh / 2, Math.Max(3, barStep - 3), bh), 2);
                    }
                }

                EnsureSyncedLyricsParsed(currentSong);
                if (currentSong.SyncedLines != null && currentSong.SyncedLines.Count > 0)
                {
                    double syncClock = Math.Max(0.0, smoothPosSec + lyricSyncOffsetSec + 0.04);
                    int actL = 0;
                    for (int i = 0; i < currentSong.SyncedLines.Count; i++)
                    {
                        if (syncClock >= currentSong.SyncedLines[i].StartSec) actL = i;
                    }
                    string curLine = FormatLyricTextForActiveProvider(currentSong.SyncedLines[actL].Text);
                    Rectangle lyrBanner = new Rectangle(cMidX - 340, concertCard.Bottom - 68, 680, 48);
                    DrawGlassCard(g, lyrBanner, 24, bgCard, true, false);
                    using (Font fKar = new Font("Segoe UI", 14f, FontStyle.Bold))
                    {
                        g.DrawString(curLine, fKar, Brushes.White, lyrBanner, sfCenter);
                    }
                }

                int ctrlCyC = h - 38;
                DrawRepeatVectorIcon(g, isRepeatOne ? accentColor : Color.White, cMidX - 148f, ctrlCyC);
                DrawSkipPrevIcon(g, Brushes.White, cMidX - 78f, ctrlCyC);
                DrawGlowingNeonPlayButton(g, ScaleRectCentered(new Rectangle(cMidX - 26, ctrlCyC - 26, 52, 52), GetButtonScale("play")), isPlaying);
                DrawSkipNextIcon(g, Brushes.White, cMidX + 78f, ctrlCyC);
                DrawShuffleVectorIcon(g, isShuffle ? accentColor : Color.White, cMidX + 148f, ctrlCyC);

                if (fullThreeDotMenuAnim > 0.01f) PaintFullThreeDotPopupMenu(g, w, h, fullThreeDotMenuAnim, sfCenter, sfLeftEllipsis);
                return;
            }

            int rightCardW = (fullViewSubMode == 0) ? 0 : Math.Min(476, Math.Max(390, (int)(w * 0.40f)));
            int rightCardX = (fullViewSubMode == 0) ? (w - 20) : (w - rightCardW - 28);
            Rectangle rightCard = new Rectangle(rightCardX, 66, rightCardW, h - 92);

            if (fullViewSubMode == 1)
            {
                DrawGlassCard(g, rightCard, 26, Color.FromArgb(22, 16, 44), false, false);

                Rectangle segBar = new Rectangle(rightCard.X + 20, rightCard.Y + 18, rightCard.Width - 40, 42);
                using (SolidBrush sbBg = new SolidBrush(Color.FromArgb(165, 14, 10, 28)))
                using (Pen sbRim = new Pen(Color.FromArgb(65, 185, 145, 255), 1f))
                {
                    FillRoundRect(g, sbBg, segBar, 21);
                    DrawRoundRect(g, sbRim, segBar, 21);
                }

                string[] rTabs = new string[] { "\u266B  Now Playing", "\u2630  Lyrics", "\u2630  Queue" };
                int rTabW = (segBar.Width - 8) / 3;
                for (int ti = 0; ti < 3; ti++)
                {
                    Rectangle tr = new Rectangle(segBar.X + 4 + ti * rTabW, segBar.Y + 4, rTabW - 2, 34);
                    bool isSel = (fullRightCardTabIdx == ti);
                    if (isSel)
                    {
                        using (LinearGradientBrush tb = new LinearGradientBrush(
                            tr,
                            Color.FromArgb(245, Math.Min(255, accentColor.R + 22), Math.Min(255, accentColor.G + 15), (int)accentColor.B),
                            Color.FromArgb(225, Math.Max(0, accentColor.R - 38), Math.Max(0, accentColor.G - 28), Math.Max(0, accentColor.B - 15)),
                            LinearGradientMode.Horizontal))
                        using (Pen tp = new Pen(Color.FromArgb(215, 235, 195, 255), 1.1f))
                        {
                            FillRoundRect(g, tb, tr, 17);
                            DrawRoundRect(g, tp, tr, 17);
                        }
                    }
                    g.DrawString(rTabs[ti], fontSmallBold, Brushes.White, tr, sfCenter);
                }

                Rectangle footerPill = new Rectangle(rightCard.X + 20, rightCard.Bottom - 62, rightCard.Width - 40, 44);
                using (SolidBrush fbBg = new SolidBrush(Color.FromArgb(165, 14, 10, 28)))
                using (Pen fbRim = new Pen(Color.FromArgb(65, 185, 145, 255), 1f))
                {
                    FillRoundRect(g, fbBg, footerPill, 22);
                    DrawRoundRect(g, fbRim, footerPill, 22);
                }
                g.DrawString("Aa", fontTitleBold, Brushes.White, footerPill.X + 14, footerPill.Y + 12);
                Rectangle lyrTogRect = new Rectangle(footerPill.X + 42, footerPill.Y + 10, 42, 24);
                DrawPurpleToggleSwitch(g, lyrTogRect, fullLyricsScriptToggle);

                Rectangle multiLyrBtn = new Rectangle(footerPill.X + 92, footerPill.Y + 9, 108, 26);
                DrawGlassCard(g, multiLyrBtn, 13, bgCard, true, false);
                g.DrawString("\u21C4 " + lyricsProviderNames[activeLyricsProviderIdx], fontSmallBold, Brushes.White, multiLyrBtn, sfCenter);

                Rectangle reSyncBtn = new Rectangle(footerPill.X + 206, footerPill.Y + 9, 72, 26);
                DrawGlassCard(g, reSyncBtn, 13, bgCard, false, false);
                g.DrawString(isLoadingBetterLyrics ? "Sync.." : "\u21BB Sync", fontSmallBold, Brushes.White, reSyncBtn, sfCenter);

                DrawFullscreenCornersIcon(g, Color.FromArgb(215, 210, 235), footerPill.Right - 88f, footerPill.Y + 22f);
                g.DrawString("Full Lyrics", fontSmallBold, Brushes.White, footerPill.Right - 72, footerPill.Y + 14);

                Rectangle rightInner = new Rectangle(rightCard.X + 16, segBar.Bottom + 12, rightCard.Width - 32, footerPill.Y - segBar.Bottom - 24);

                if (fullRightCardTabIdx == 2)
                {
                    Region prevClipQ = g.Clip;
                    g.SetClip(rightInner);
                    int qRowH = 56;
                    int qTotalH = queueSongs.Count * (qRowH + 6) + 12;
                    int maxQ = Math.Max(0, qTotalH - rightInner.Height);
                    if (queueScrollOffset > maxQ) queueScrollOffset = maxQ;
                    if (targetQueueScrollOffset > maxQ) targetQueueScrollOffset = maxQ;

                    for (int i = 0; i < queueSongs.Count; i++)
                    {
                        int qy = rightInner.Y + 4 + i * (qRowH + 6) - queueScrollOffset;
                        if (qy + qRowH < rightInner.Y - 2 || qy > rightInner.Bottom + 2) continue;
                        SongItem qs = queueSongs[i];
                        bool isPlayQ = (currentSong != null && currentSong.Id == qs.Id);
                        Rectangle qr = new Rectangle(rightInner.X + 4, qy, rightInner.Width - 16, qRowH);
                        DrawGlassCard(g, qr, 14, bgCard, isPlayQ, hoveredQueueIndex == i);
                        DrawStaticAlbumArt(g, qs.ThumbUrl, new Rectangle(qr.X + 8, qr.Y + 7, 42, 42), 8);
                        g.DrawString(FormatMinimalCardTitle(qs.Title), fontTitleBold, isPlayQ ? new SolidBrush(Color.FromArgb(225, 185, 255)) : Brushes.White, new RectangleF(qr.X + 58, qr.Y + 8, qr.Width - 110, 20), sfLeftEllipsis);
                        g.DrawString(GetPrimaryArtistName(qs.Artist), fontSubReg, Brushes.LightGray, new RectangleF(qr.X + 58, qr.Y + 29, qr.Width - 110, 18), sfLeftEllipsis);
                        g.DrawString(FormatSec(qs.Duration), fontSmallBold, Brushes.LightGray, qr.Right - 44, qr.Y + 19);
                    }
                    g.Clip = prevClipQ;

                    if (qTotalH > rightInner.Height + 8)
                    {
                        int sbX = rightInner.Right - 6;
                        int sbY = rightInner.Y + 4;
                        int sbH = rightInner.Height - 8;
                        int thH = Math.Max(28, (int)((float)rightInner.Height / qTotalH * sbH));
                        int thY = sbY + (int)((sbH - thH) * ((float)queueScrollOffset / Math.Max(1, maxQ)));
                        FillRoundRect(g, new SolidBrush(Color.FromArgb(35, 255, 255, 255)), new Rectangle(sbX, sbY, 4, sbH), 2);
                        FillRoundRect(g, new SolidBrush(accentColor), new Rectangle(sbX, thY, 4, thH), 2);
                    }
                }
                else if (fullRightCardTabIdx == 0)
                {
                    int vBars = 24;
                    int vStep = (rightInner.Width - 40) / vBars;
                    DrawEqResponsiveVisualizer(g, rightInner.X + 24, rightInner.Y + 95, vBars, vStep, 5.0f, 34f);

                    string[] infoRows = new string[]
                    {
                        "Track: " + currentSong.Title,
                        "Artist: " + currentSong.Artist,
                        "Bitrate & DAC: 320 kbps Master \u2022 " + dacOutputShortNames[dacOutputModeIdx],
                        "Spatial 3D Stage: " + headphone3DShortNames[headphone3DModeIdx],
                        "Lyrics Engine: " + lyricsProviderNames[activeLyricsProviderIdx] + " (" + currentLyricMatchScore + "% Acc)",
                        "Equalizer Preset: " + (eqEnabled ? activeEqPreset : "Flat Studio"),
                        "Art Design: " + fullArtDesignNames[fullArtDesignIdx]
                    };
                    for (int i = 0; i < infoRows.Length; i++)
                    {
                        Rectangle ir = new Rectangle(rightInner.X + 8, rightInner.Y + 120 + i * 38, rightInner.Width - 16, 32);
                        DrawGlassCard(g, ir, 10, bgCard, i == 0, false);
                        g.DrawString(infoRows[i], fontSmallBold, Brushes.White, new RectangleF(ir.X + 12, ir.Y + 6, ir.Width - 24, 20), sfLeftEllipsis);
                    }
                }
                else // Live Synced Lyrics Tab (`fullRightCardTabIdx == 1`) with Glowing Accuracy % Badge & Micro-Sync Bar!
                {
                    EnsureSyncedLyricsParsed(currentSong);
                    activeLyricHitRects.Clear();
                    activeLyricHitTimes.Clear();

                    List<LyricLine> lines = currentSong.SyncedLines;
                    bool isExactLrc = (lines != null && lines.Count > 0 && lines[0].IsExactLrcTimestamp) || currentLyricsAreExactLrc;
                    int dispAcc = Math.Max(88, Math.Min(99, currentLyricMatchScore > 0 ? currentLyricMatchScore : (isExactLrc ? 99 : 92)));

                    // Top Accuracy % & Micro-Sync Bar inside Split-View Lyrics Card
                    Rectangle accBar = new Rectangle(rightInner.X + 8, rightInner.Y, rightInner.Width - 16, 26);
                    Color accCol = isExactLrc ? Color.FromArgb(34, 197, 94) : Color.FromArgb(168, 85, 247);
                    Rectangle accPill = new Rectangle(accBar.X, accBar.Y, accBar.Width - 124, 24);
                    using (SolidBrush ab = new SolidBrush(Color.FromArgb(55, accCol.R, accCol.G, accCol.B)))
                    using (Pen ap = new Pen(Color.FromArgb(175, accCol.R, accCol.G, accCol.B), 1f))
                    {
                        FillRoundRect(g, ab, accPill, 12);
                        DrawRoundRect(g, ap, accPill, 12);
                    }
                    using (SolidBrush atb = new SolidBrush(isExactLrc ? Color.FromArgb(145, 255, 190) : Color.FromArgb(235, 200, 255)))
                    {
                        g.DrawString("\u2713 " + dispAcc + "% Sync Accuracy \u2022 " + (isExactLrc ? "Exact LRC" : "Smart Sync"), fontSmallBold, atb, accPill, sfCenter);
                    }

                    splitLyrMinusBtnRect = new Rectangle(accBar.Right - 116, accBar.Y, 36, 24);
                    splitLyrResetBtnRect = new Rectangle(accBar.Right - 76,  accBar.Y, 36, 24);
                    splitLyrPlusBtnRect  = new Rectangle(accBar.Right - 36,  accBar.Y, 36, 24);
                    DrawGlassCard(g, splitLyrMinusBtnRect, 8, bgCard, false, false);
                    DrawGlassCard(g, splitLyrResetBtnRect, 8, bgCard, lyricSyncOffsetSec != 0, false);
                    DrawGlassCard(g, splitLyrPlusBtnRect,  8, bgCard, false, false);
                    g.DrawString("-0.2", fontSmallBold, Brushes.White, splitLyrMinusBtnRect, sfCenter);
                    g.DrawString(lyricSyncOffsetSec == 0 ? "0s" : lyricSyncOffsetSec.ToString("+0.0;-0.0"), fontSmallBold, Brushes.White, splitLyrResetBtnRect, sfCenter);
                    g.DrawString("+0.2", fontSmallBold, Brushes.White, splitLyrPlusBtnRect, sfCenter);

                    Rectangle lyrViewport = new Rectangle(rightInner.X, rightInner.Y + 32, rightInner.Width, rightInner.Height - 32);

                    if (lines != null && lines.Count > 0)
                    {
                        double syncClock = Math.Max(0.0, smoothPosSec + lyricSyncOffsetSec + 0.04);
                        int activeIdx = 0;
                        for (int i = 0; i < lines.Count; i++)
                        {
                            if (syncClock >= lines[i].StartSec && syncClock <= lines[i].EndSec) { activeIdx = i; break; }
                            if (syncClock >= lines[i].StartSec) activeIdx = i;
                        }
                        if (currentSong.Id == "sc_hanuman" && !isPlaying && activeIdx < 3 && lines.Count > 3)
                        {
                            activeIdx = 3;
                        }

                        Region oldClipL = g.Clip;
                        g.SetClip(lyrViewport);

                        int centerLineY = lyrViewport.Y + lyrViewport.Height / 2 - 24;
                        int lineStep = 44;
                        StringFormat sfWrapCenter = new StringFormat();
                        sfWrapCenter.Alignment = StringAlignment.Center;
                        sfWrapCenter.LineAlignment = StringAlignment.Center;
                        sfWrapCenter.Trimming = StringTrimming.EllipsisWord;

                        for (int i = 0; i < lines.Count; i++)
                        {
                            int dist = i - activeIdx;
                            if (Math.Abs(dist) > 6) continue;

                            int ly = centerLineY + dist * lineStep;
                            if (dist > 0) ly += 10;

                            Rectangle lineRect = new Rectangle(lyrViewport.X + 6, ly, lyrViewport.Width - 12, (dist == 0) ? 48 : 38);
                            if (lineRect.Bottom < lyrViewport.Y || lineRect.Y > lyrViewport.Bottom) continue;

                            activeLyricHitRects.Add(lineRect);
                            activeLyricHitTimes.Add(lines[i].StartSec);
                            string dispTxt = FormatLyricTextForActiveProvider(lines[i].Text);

                            if (dist == 0 && fullLyricsScriptToggle)
                            {
                                using (LinearGradientBrush capB = new LinearGradientBrush(
                                    lineRect,
                                    Color.FromArgb(235, 102, 48, 198),
                                    Color.FromArgb(245, 152, 74, 245),
                                    LinearGradientMode.Horizontal))
                                using (Pen capP = new Pen(Color.FromArgb(240, 235, 195, 255), 1.4f))
                                {
                                    FillRoundRect(g, capB, lineRect, 14);
                                    DrawRoundRect(g, capP, lineRect, 14);
                                }

                                int eqX = lineRect.X + 14;
                                int eqCy = lineRect.Y + 24;
                                for (int b = 0; b < 3; b++)
                                {
                                    float mod = isPlaying ? (0.6f + 0.6f * (float)Math.Abs(Math.Sin(wavePhase * 1.8f + b * 1.1f))) : 1.0f;
                                    int hBar = Math.Max(5, (int)((b == 1 ? 15 : 9) * mod));
                                    FillRoundRect(g, new SolidBrush(Color.FromArgb(245, 235, 200, 255)), new Rectangle(eqX + b * 5, eqCy - hBar / 2, 3, hBar), 1);
                                }

                                Rectangle textR = new Rectangle(lineRect.X + 34, lineRect.Y + 2, lineRect.Width - 44, lineRect.Height - 4);
                                using (Font fActLyr = new Font("Segoe UI", 12.2f, FontStyle.Bold))
                                {
                                    g.DrawString(dispTxt, fActLyr, Brushes.White, textR, sfWrapCenter);
                                }
                            }
                            else
                            {
                                int alpha = (dist == 0) ? 255 : Math.Max(65, 235 - Math.Abs(dist) * 34);
                                float fSz = (i == 0 || dist == 0) ? 12.2f : 11.0f;
                                using (Font fIdleLyr = new Font("Segoe UI", fSz, (i == 0 || dist == 0) ? FontStyle.Bold : FontStyle.Regular))
                                using (SolidBrush lb = new SolidBrush(Color.FromArgb(alpha, 235, 230, 250)))
                                {
                                    g.DrawString(dispTxt, fIdleLyr, lb, lineRect, sfWrapCenter);
                                }
                            }
                        }
                        g.Clip = oldClipL;
                    }
                }
            }

            int stageLeftX = leftActionPill.Right + 20;
            int stageRightX = (fullViewSubMode == 0) ? (w - 40) : (rightCard.X - 20);
            int stageW = Math.Max(320, stageRightX - stageLeftX);
            int stageCx = stageLeftX + stageW / 2 - ((fullViewSubMode == 0 && fullArtDesignIdx != 0) ? 0 : 18);

            int artSz = Math.Min((fullViewSubMode == 0) ? 320 : 286, Math.Max(205, h - 350));
            int artX = stageCx - artSz / 2;
            int artY = 76;
            Rectangle bigArtRect = new Rectangle(artX, artY, artSz, artSz);

            DrawFullStageCustomAlbumArtwork(g, bigArtRect);

            int titleY = bigArtRect.Bottom + 18;
            int centerMidX = stageLeftX + stageW / 2;
            using (Font fFullTitle = new Font("Segoe UI", 20f, FontStyle.Bold))
            {
                g.DrawString(FormatMinimalCardTitle(currentSong.Title), fFullTitle, Brushes.White, new RectangleF(stageLeftX, titleY, stageW, 34), sfCenter);
            }

            int subY = titleY + 36;
            string artistStr = GetPrimaryArtistName(currentSong.Artist);
            using (Font fFullArtist = new Font("Segoe UI", 11.0f, FontStyle.Regular))
            using (SolidBrush artSubB = new SolidBrush(Color.FromArgb(215, 210, 235)))
            {
                SizeF aSz = g.MeasureString(artistStr, fFullArtist);
                int totalSubW = (int)aSz.Width + 74;
                int subStartX = centerMidX - totalSubW / 2;
                g.DrawString(artistStr, fFullArtist, artSubB, subStartX, subY + 1);

                Rectangle kbpsBadge = new Rectangle(subStartX + (int)aSz.Width + 8, subY, 64, 22);
                using (SolidBrush kb = new SolidBrush(Color.FromArgb(85, accentColor.R, accentColor.G, accentColor.B)))
                using (Pen kp = new Pen(Color.FromArgb(185, 215, 165, 255), 1f))
                {
                    FillRoundRect(g, kb, kbpsBadge, 11);
                    DrawRoundRect(g, kp, kbpsBadge, 11);
                }
                using (Font fKb = new Font("Segoe UI", 8.0f, FontStyle.Bold))
                using (SolidBrush kt = new SolidBrush(Color.FromArgb(235, 205, 255)))
                {
                    g.DrawString("320 kbps", fKb, kt, kbpsBadge, sfCenter);
                }
            }

            int sliderY = subY + 42;
            int sliderW = Math.Min((fullViewSubMode == 0) ? 460 : 360, stageW - 110);
            int sliderX = centerMidX - sliderW / 2;
            float frac = (float)Math.Max(0.0, Math.Min(1.0, smoothPosSec / Math.Max(1.0, currentDurSec)));
            int activeX = sliderX + (int)(sliderW * frac);

            using (Pen trackPen = new Pen(Color.FromArgb(75, 255, 255, 255), 4.0f))
            {
                trackPen.StartCap = LineCap.Round;
                trackPen.EndCap = LineCap.Round;
                g.DrawLine(trackPen, sliderX, sliderY, sliderX + sliderW, sliderY);
            }
            if (activeX > sliderX + 2)
            {
                using (Pen actPen = new Pen(accentColor, 4.2f))
                {
                    actPen.StartCap = LineCap.Round;
                    actPen.EndCap = LineCap.Round;
                    g.DrawLine(actPen, sliderX, sliderY, activeX, sliderY);
                }
            }
            using (SolidBrush thGlow = new SolidBrush(Color.FromArgb(110, accentColor)))
            {
                g.FillEllipse(thGlow, activeX - 10, sliderY - 10, 20, 20);
                g.FillEllipse(Brushes.White, activeX - 6, sliderY - 6, 12, 12);
            }

            using (Font fTime = new Font("Segoe UI", 9.0f, FontStyle.Regular))
            using (SolidBrush timeB = new SolidBrush(Color.FromArgb(220, 215, 240)))
            {
                g.DrawString(FormatSec((int)currentPosSec), fTime, timeB, sliderX - 42, sliderY - 8);
                g.DrawString(FormatSec((int)currentDurSec), fTime, timeB, sliderX + sliderW + 12, sliderY - 8);
            }

            int ctrlCy = sliderY + 56;
            DrawRepeatVectorIcon(g, isRepeatOne ? accentColor : Color.FromArgb(225, 220, 240), centerMidX - 148f, ctrlCy);
            DrawSkipPrevIcon(g, Brushes.White, centerMidX - 78f, ctrlCy);

            Rectangle bigNeonPlayRect = ScaleRectCentered(new Rectangle(centerMidX - 33, ctrlCy - 33, 66, 66), GetButtonScale("play"));
            DrawGlowingNeonPlayButton(g, bigNeonPlayRect, isPlaying);

            DrawSkipNextIcon(g, Brushes.White, centerMidX + 78f, ctrlCy);
            DrawShuffleVectorIcon(g, isShuffle ? accentColor : Color.FromArgb(225, 220, 240), centerMidX + 148f, ctrlCy);

            int botBarY = h - 46;
            int fpVolBarX = 82;
            int fpVolBarW = 148;
            DrawSpeakerVectorIcon(g, Color.FromArgb(225, 220, 240), fpVolBarX - 22f, botBarY, isMuted || volumePercent == 0);

            int maxFpVol = volumeOverdriveAllowed ? 150 : 100;
            using (Pen vp = new Pen(Color.FromArgb(65, 255, 255, 255), 3.6f))
            {
                vp.StartCap = LineCap.Round;
                vp.EndCap = LineCap.Round;
                g.DrawLine(vp, fpVolBarX, botBarY, fpVolBarX + fpVolBarW, botBarY);
            }
            int fpActVolW = isMuted ? 0 : Math.Min(fpVolBarW, (int)(fpVolBarW * (volumePercent / (double)maxFpVol)));
            if (fpActVolW > 2)
            {
                using (Pen avp = new Pen(accentColor, 3.8f))
                {
                    avp.StartCap = LineCap.Round;
                    avp.EndCap = LineCap.Round;
                    g.DrawLine(avp, fpVolBarX, botBarY, fpVolBarX + fpActVolW, botBarY);
                }
            }
            g.FillEllipse(Brushes.White, fpVolBarX + fpActVolW - 6, botBarY - 6, 12, 12);

            int sqBtnX = stageRightX - 154;
            for (int bi = 0; bi < 3; bi++)
            {
                Rectangle sqR = new Rectangle(sqBtnX + bi * 50, botBarY - 17, 42, 34);
                DrawGlassCard(g, sqR, 12, bgCard, false, false);
                float bcx = sqR.X + 21f;
                float bcy = sqR.Y + 17f;
                using (Pen bp = new Pen(Color.FromArgb(225, 220, 240), 1.5f))
                {
                    if (bi == 0)
                    {
                        g.DrawLine(bp, bcx - 7f, bcy - 4f, bcx + 7f, bcy - 4f);
                        g.DrawLine(bp, bcx - 7f, bcy + 4f, bcx + 7f, bcy + 4f);
                        g.FillEllipse(Brushes.White, bcx - 3f, bcy - 6.5f, 5f, 5f);
                        g.FillEllipse(Brushes.White, bcx + 1f, bcy + 1.5f, 5f, 5f);
                    }
                    else if (bi == 1)
                    {
                        g.DrawRectangle(bp, bcx - 7f, bcy - 6f, 14f, 11f);
                        g.DrawArc(bp, bcx - 4f, bcy + 1f, 8f, 6f, 180f, 180f);
                    }
                    else
                    {
                        g.DrawLine(bp, bcx - 5f, bcy + 5f, bcx + 5f, bcy - 5f);
                        g.DrawLine(bp, bcx + 1f, bcy - 5f, bcx + 5f, bcy - 5f);
                        g.DrawLine(bp, bcx + 5f, bcy - 1f, bcx + 5f, bcy - 5f);
                        g.DrawLine(bp, bcx - 5f, bcy + 1f, bcx - 5f, bcy + 5f);
                        g.DrawLine(bp, bcx - 1f, bcy + 5f, bcx - 5f, bcy + 5f);
                    }
                }
            }

            if (fullThreeDotMenuAnim > 0.01f)
            {
                PaintFullThreeDotPopupMenu(g, w, h, fullThreeDotMenuAnim, sfCenter, sfLeftEllipsis);
            }
        }

        private void PaintFullThreeDotPopupMenu(Graphics g, int w, int h, float anim, StringFormat sfCenter, StringFormat sfLeftEllipsis)
        {
            int popW = 284;
            int popH = 382;
            int popX = 100;
            int popY = 120;
            Rectangle popRect = new Rectangle(popX, popY, popW, popH);

            DrawGlassCard(g, popRect, 18, bgCard, true, false);
            g.DrawString("FULL PANEL VIEW & STUDIO OPTIONS", fontSmallBold, new SolidBrush(accentColor), popRect.X + 16, popRect.Y + 12);

            string[] itemLabels = new string[]
            {
                "Playing + Lyrics (Split View)",
                "Only Playing (Pure Art Stage)",
                "Only Lyrics (Full Screen)",
                "Concert 3D Visualizer Stage",
                "Art Design: " + fullArtDesignNames[fullArtDesignIdx],
                "Beat Image Bump: " + (beatBumpEnabled ? "ON" : "OFF"),
                "Cycle Background Style  \u2726",
                "Open Audio EQ & Settings",
                "Download 320kbps Track"
            };
            int rowStart = popRect.Y + 36;
            Point relM = this.PointToClient(Cursor.Position);
            for (int i = 0; i < itemLabels.Length; i++)
            {
                Rectangle itemR = new Rectangle(popRect.X + 10, rowStart + i * 37, popRect.Width - 20, 33);
                bool isSel = (i == 0 && fullViewSubMode == 1) || (i == 1 && fullViewSubMode == 0) || (i == 2 && fullViewSubMode == 2) || (i == 3 && fullViewSubMode == 3) || itemR.Contains(relM);
                DrawGlassCard(g, itemR, 10, bgCard, isSel, itemR.Contains(relM));
                g.DrawString(itemLabels[i], fontSubReg, Brushes.White, new RectangleF(itemR.X + 14, itemR.Y + 5, itemR.Width - 24, 22), sfLeftEllipsis);
            }
        }

        private void PaintBottomPlayerBar(Graphics g, int w, int h, int playerH, StringFormat sfCenter, StringFormat sfLeftEllipsis)
        {
            Rectangle dockRect = new Rectangle(204, h - 76, w - 218, 64);
            DrawGlassCard(g, dockRect, 22, Color.FromArgb(20, 14, 38), true, false);

            using (Pen topNeon = new Pen(Color.FromArgb(195, 215, 165, 255), 1.8f))
            {
                g.DrawLine(topNeon, dockRect.X + dockRect.Width / 3, dockRect.Y, dockRect.Right - dockRect.Width / 4, dockRect.Y);
                g.DrawLine(topNeon, dockRect.X + 60, dockRect.Bottom, dockRect.Right - 40, dockRect.Bottom);
            }

            if (currentSong != null)
            {
                DrawStaticAlbumArt(g, currentSong.ThumbUrl, new Rectangle(dockRect.X + 14, dockRect.Y + 9, 46, 46), 10);
                using (Font fBt = new Font("Segoe UI", 10.2f, FontStyle.Bold))
                using (Font fBa = new Font("Segoe UI", 8.6f, FontStyle.Regular))
                using (SolidBrush sb = new SolidBrush(Color.FromArgb(195, 190, 220)))
                {
                    g.DrawString(FormatMinimalCardTitle(currentSong.Title), fBt, Brushes.White, new RectangleF(dockRect.X + 70, dockRect.Y + 12, 165, 20), sfLeftEllipsis);
                    g.DrawString(GetPrimaryArtistName(currentSong.Artist), fBa, sb, new RectangleF(dockRect.X + 70, dockRect.Y + 33, 165, 18), sfLeftEllipsis);
                }

                bool isLiked = likedIds.Contains(currentSong.Id);
                DrawHeartIcon(g, isLiked ? accentColor : Color.FromArgb(225, 220, 245), dockRect.X + 252f, dockRect.Y + 32f, isLiked);
            }

            int transCx = dockRect.X + (int)(dockRect.Width * 0.42f);
            float btnCy = dockRect.Y + 32f;

            DrawShuffleVectorIcon(g, isShuffle ? accentColor : Color.FromArgb(215, 210, 235), transCx - 102f, btnCy);
            DrawSkipPrevIcon(g, Brushes.White, transCx - 52f, btnCy);

            Rectangle playCircle = ScaleRectCentered(new Rectangle(transCx - 21, (int)btnCy - 21, 42, 42), GetButtonScale("play"));
            DrawGlowingNeonPlayButton(g, playCircle, isPlaying);

            DrawSkipNextIcon(g, Brushes.White, transCx + 52f, btnCy);
            DrawRepeatVectorIcon(g, isRepeatOne ? accentColor : Color.FromArgb(215, 210, 235), transCx + 102f, btnCy);

            int timeX = transCx + 144;
            using (Font fTime = new Font("Segoe UI", 8.8f, FontStyle.Regular))
            using (SolidBrush tb = new SolidBrush(Color.FromArgb(215, 210, 235)))
            {
                string timeTxt = FormatSec((int)currentPosSec) + " / " + FormatSec((int)currentDurSec);
                g.DrawString(timeTxt, fTime, tb, timeX, btnCy - 8f);
            }

            int seekX = timeX + 78;
            int seekW = Math.Max(70, Math.Min(130, dockRect.Right - seekX - 210));
            if (seekW > 40)
            {
                float sFrac = (float)Math.Max(0.0, Math.Min(1.0, smoothPosSec / Math.Max(1.0, currentDurSec)));
                int sActW = (int)(seekW * sFrac);
                using (Pen trP = new Pen(Color.FromArgb(65, 255, 255, 255), 3.2f))
                {
                    trP.StartCap = LineCap.Round;
                    trP.EndCap = LineCap.Round;
                    g.DrawLine(trP, seekX, btnCy, seekX + seekW, btnCy);
                }
                if (sActW > 2)
                {
                    using (Pen acP = new Pen(accentColor, 3.5f))
                    {
                        acP.StartCap = LineCap.Round;
                        acP.EndCap = LineCap.Round;
                        g.DrawLine(acP, seekX, btnCy, seekX + sActW, btnCy);
                    }
                }
                g.FillEllipse(Brushes.White, seekX + sActW - 5, btnCy - 5f, 10f, 10f);
            }

            int volBarX = dockRect.Right - 148;
            int volBarW = 86;
            DrawSpeakerVectorIcon(g, isVolumeControllerPopupOpen ? accentColor : Color.FromArgb(225, 220, 240), volBarX - 18f, btnCy, isMuted || volumePercent == 0);

            int maxDockVol = volumeOverdriveAllowed ? 150 : 100;
            using (Pen vp = new Pen(Color.FromArgb(65, 255, 255, 255), 3.2f))
            {
                vp.StartCap = LineCap.Round;
                vp.EndCap = LineCap.Round;
                g.DrawLine(vp, volBarX, btnCy, volBarX + volBarW, btnCy);
            }
            int actVolW = isMuted ? 0 : Math.Min(volBarW, (int)(volBarW * (volumePercent / (double)maxDockVol)));
            if (actVolW > 2)
            {
                using (Pen avp = new Pen(accentColor, 3.5f))
                {
                    avp.StartCap = LineCap.Round;
                    avp.EndCap = LineCap.Round;
                    g.DrawLine(avp, volBarX, btnCy, volBarX + actVolW, btnCy);
                }
            }
            g.FillEllipse(Brushes.White, volBarX + actVolW - 5, btnCy - 5f, 10f, 10f);

            DrawQueueListIcon(g, Color.FromArgb(225, 220, 240), dockRect.Right - 32f, btnCy);
        }

        private Rectangle GetBackendHubPopupRect(int w, int h)
        {
            int popW = 460;
            int popH = 386;
            int popX = (w - popW) / 2;
