        private void PaintStudioVolumeControllerPopup(Graphics g, int w, int h, float anim, StringFormat sfCenter, StringFormat sfLeftEllipsis)
        {
            Rectangle popRect = GetVolumeControllerPopupRect(w, h);
            int slideOffset = (int)((1.0f - anim) * 18f);
            Rectangle r = new Rectangle(popRect.X, popRect.Y + slideOffset, popRect.Width, popRect.Height);

            // Deep shadow + 3D Curved Glass card
            using (SolidBrush shB = new SolidBrush(Color.FromArgb((int)(165 * anim), 0, 0, 0)))
            {
                FillRoundRect(g, shB, new Rectangle(r.X - 4, r.Y + 6, r.Width + 8, r.Height + 8), 22);
            }
            using (SolidBrush bgB = new SolidBrush(Color.FromArgb((int)(246 * anim), 16, 14, 22)))
            using (Pen rimP = new Pen(Color.FromArgb((int)(185 * anim), accentColor), 1.5f))
            {
                FillRoundRect(g, bgB, r, 20);
                DrawRoundRect(g, rimP, r, 20);
            }

            // Top specular 3D glass highlight
            Rectangle domeR = new Rectangle(r.X + 12, r.Y + 3, r.Width - 24, 22);
            using (LinearGradientBrush domeB = new LinearGradientBrush(domeR, Color.FromArgb((int)(42 * anim), 255, 255, 255), Color.FromArgb(0, 255, 255, 255), LinearGradientMode.Vertical))
            {
                FillRoundRect(g, domeB, domeR, 10);
            }

            using (SolidBrush ab = new SolidBrush(accentColor))
            using (SolidBrush wb = new SolidBrush(Color.White))
            using (SolidBrush sb = new SolidBrush(textSub))
            {
                g.DrawString("\u266B STUDIO VOLUME & SMOOTHNESS", fontSmallBold, ab, r.X + 16, r.Y + 14);
                string badgeTxt = isMuted ? "MUTED" : (volumePercent > 100 ? (volumePercent + "% BOOST \u26A1") : (volumePercent + "% STUDIO"));
                Color badgeCol = volumePercent > 100 ? Color.FromArgb(255, 255, 200, 55) : Color.White;
                using (SolidBrush bCol = new SolidBrush(badgeCol))
                {
                    g.DrawString(badgeTxt, fontTitleBold, bCol, r.Right - 118, r.Y + 12);
                }

                // 1. Interactive 0% - 150% Overdrive Volume Slider Bar (`r.Y + 46`)
                int slX = r.X + 18;
                int slW = r.Width - 36;
                int slY = r.Y + 50;
                int maxV = volumeOverdriveAllowed ? 150 : 100;

                using (Pen trkP = new Pen(Color.FromArgb(65, 255, 255, 255), 6.0f))
                {
                    trkP.StartCap = LineCap.Round;
                    trkP.EndCap = LineCap.Round;
                    g.DrawLine(trkP, slX, slY, slX + slW, slY);
                }

                // 100% Unity Marker tick
                int unityX = slX + (int)(slW * (100.0 / maxV));
                using (Pen uPen = new Pen(Color.FromArgb(140, 255, 255, 255), 1.5f))
                {
                    g.DrawLine(uPen, unityX, slY - 7, unityX, slY + 7);
                }

                int fillW = isMuted ? 0 : Math.Min(slW, (int)(slW * (volumePercent / (double)maxV)));
                if (fillW > 2)
                {
                    Color fillC = (volumePercent > 100) ? Color.FromArgb(255, 255, 190, 40) : accentColor;
                    using (Pen actP = new Pen(fillC, 6.2f))
                    {
                        actP.StartCap = LineCap.Round;
                        actP.EndCap = LineCap.Round;
                        g.DrawLine(actP, slX, slY, slX + fillW, slY);
                    }
                }
                g.FillEllipse(Brushes.White, slX + fillW - 7, slY - 7, 14, 14);

                using (Font fTiny = new Font("Segoe UI", 7.4f, FontStyle.Regular))
                {
                    g.DrawString("0%", fTiny, sb, slX, slY + 9);
                    g.DrawString("100% Unity", fTiny, sb, unityX - 24, slY + 9);
                    g.DrawString(volumeOverdriveAllowed ? "150% Boost" : "100% Max", fTiny, sb, slX + slW - 52, slY + 9);
                }

                // 2. Fine Step Buttons Row (`r.Y + 80`): [-5%] [-1%] [Mute] [+1%] [+5%]
                string[] stepLabels = new string[] { "-5%", "-1%", isMuted ? "Unmute" : "Mute", "+1%", "+5%" };
                int stGap = 6;
                int stW = (slW - 4 * stGap) / 5;
                for (int i = 0; i < 5; i++)
                {
                    Rectangle sr = new Rectangle(slX + i * (stW + stGap), r.Y + 80, stW, 26);
                    bool isMuteBtn = (i == 2 && isMuted);
                    using (SolidBrush b = new SolidBrush(isMuteBtn ? accentColor : Color.FromArgb(34, 38, 54)))
                    using (Pen p = new Pen(Color.FromArgb(80, accentColor), 1f))
                    {
                        FillRoundRect(g, b, sr, 8);
                        DrawRoundRect(g, p, sr, 8);
                    }
                    g.DrawString(stepLabels[i], fontSmallBold, Brushes.White, sr, sfCenter);
                }

                // 3. 6 One-Click Studio Volume Presets (`r.Y + 114`): [20%] [50%] [75%] [85%] [100%] [135%\u26A1]
                int[] presetVols = new int[] { 20, 50, 75, 85, 100, 135 };
                string[] presetNames = new string[] { "20%", "50%", "75%", "85%", "100%", "135%\u26A1" };
                int prW = (slW - 5 * 5) / 6;
                for (int i = 0; i < 6; i++)
                {
                    Rectangle pr = new Rectangle(slX + i * (prW + 5), r.Y + 114, prW, 25);
                    bool actP = (!isMuted && Math.Abs(volumePercent - presetVols[i]) <= 2);
                    using (SolidBrush b = new SolidBrush(actP ? accentColor : Color.FromArgb(26, 30, 44)))
                    {
                        FillRoundRect(g, b, pr, 7);
                    }
                    g.DrawString(presetNames[i], fontSmallBold, Brushes.White, pr, sfCenter);
                }

                // 4. Stereo Balance L / Center / R Control (`r.Y + 148`)
                string balStr = (manualStereoBalance == 0) ? "Center (0)" : (manualStereoBalance < 0 ? ("Left " + Math.Abs(manualStereoBalance) + "%") : ("Right " + manualStereoBalance + "%"));
                g.DrawString("Stereo Balance: " + balStr, fontSmallBold, wb, slX, r.Y + 148);
                string[] balBtns = new string[] { "L -25%", "Center 0", "R +25%" };
                int bBtnW = (slW - 12) / 3;
                for (int i = 0; i < 3; i++)
                {
                    Rectangle br = new Rectangle(slX + i * (bBtnW + 6), r.Y + 168, bBtnW, 24);
                    bool actB = (i == 0 && manualStereoBalance < -5) || (i == 1 && Math.Abs(manualStereoBalance) <= 5) || (i == 2 && manualStereoBalance > 5);
                    using (SolidBrush b = new SolidBrush(actB ? Color.FromArgb(75, accentColor) : Color.FromArgb(28, 32, 46)))
                    using (Pen p = new Pen(actB ? accentColor : Color.FromArgb(50, 255, 255, 255), 1f))
                    {
                        FillRoundRect(g, b, br, 7);
                        DrawRoundRect(g, p, br, 7);
                    }
                    g.DrawString(balBtns[i], fontSmallBold, Brushes.White, br, sfCenter);
                }

                // 5. 3D Headphone, Pin-Drop Detailing & Smoothness Quick Toggles (`r.Y + 202`)
                string[] smoothToggles = new string[]
                {
                    "\u266B 3D Headphone: " + headphone3DShortNames[headphone3DModeIdx],
                    "\u2726 24-Bit Pin-Drop Detail: " + pinDropDetailShortNames[pinDropDetailLevelIdx],
                    "Smart Auto-Volume Leveler (Normalize): " + (autoVolumeNormalizeEnabled ? "ON" : "OFF"),
                    "Smooth 180ms Micro-Fade & Pre-Buffer: " + (smoothMicroFadeEnabled ? "ON" : "OFF")
                };
                bool[] smoothStates = new bool[] { (headphone3DModeIdx != 4), pinDropClarityEnabled, autoVolumeNormalizeEnabled, smoothMicroFadeEnabled };

                for (int i = 0; i < 4; i++)
                {
                    Rectangle tr = new Rectangle(slX, r.Y + 202 + i * 36, slW, 31);
                    bool stOn = smoothStates[i];
                    using (SolidBrush b = new SolidBrush(stOn ? Color.FromArgb(42, accentColor.R, accentColor.G, accentColor.B) : Color.FromArgb(24, 28, 40)))
                    using (Pen p = new Pen(stOn ? Color.FromArgb(145, accentColor) : Color.FromArgb(45, 255, 255, 255), 1f))
                    {
                        FillRoundRect(g, b, tr, 9);
                        DrawRoundRect(g, p, tr, 9);
                    }
                    g.DrawString(smoothToggles[i], fontSmallBold, stOn ? Brushes.White : sb, new RectangleF(tr.X + 12, tr.Y + 4, tr.Width - 56, 22), sfLeftEllipsis);
                    DrawToggleSwitch(g, new Rectangle(tr.Right - 44, tr.Y + 6, 34, 18), stOn);
                }
            }
        }

        private void DrawStaticAlbumArt(Graphics g, string url, Rectangle rect, int radius)
        {
            if (rect.Width <= 4 || rect.Height <= 4) return;
            string jpgUrl = (url ?? "").Replace(".webp", ".jpg");
            Image img = null;
            lock (imageCache)
            {
                if (imageCache.ContainsKey(jpgUrl)) img = imageCache[jpgUrl];
            }
            if (img == null && !string.IsNullOrEmpty(jpgUrl))
            {
                PrefetchSingleThumbnail(jpgUrl);
            }

            // v10.4.4 ZERO-LAG THUMBNAIL CACHE: Pre-bake exact-sized rounded-corner Format32bppPArgb bitmaps in RAM!
            // Eliminates 18x per-frame 500x500 -> card downscaling and SetClip(GraphicsPath) overhead during scrolling!
            if (uiTurboCacheEnabled && img != null && rect.Width <= 380 && rect.Height <= 380)
            {
                string cacheKey = jpgUrl + "_" + rect.Width + "x" + rect.Height + "_r" + radius;
                Bitmap baked = null;
                lock (cachedSizedThumbnails)
                {
                    if (cachedSizedThumbnails.ContainsKey(cacheKey))
                    {
                        baked = cachedSizedThumbnails[cacheKey];
                    }
                    else
                    {
                        try
                        {
                            if (cachedSizedThumbnails.Count > 180) cachedSizedThumbnails.Clear();
                            baked = new Bitmap(rect.Width, rect.Height, System.Drawing.Imaging.PixelFormat.Format32bppPArgb);
                            using (Graphics bg = Graphics.FromImage(baked))
                            {
                                bg.SmoothingMode = SmoothingMode.AntiAlias;
                                bg.InterpolationMode = InterpolationMode.Bilinear;
                                Rectangle localR = new Rectangle(0, 0, rect.Width, rect.Height);
                                using (GraphicsPath cp = GetRoundRectPath(localR, radius))
                                {
                                    bg.SetClip(cp);
                                    bg.DrawImage(img, localR);
                                }
                            }
                            cachedSizedThumbnails[cacheKey] = baked;
                        }
                        catch { baked = null; }
                    }
                }
                if (baked != null)
                {
                    g.DrawImageUnscaled(baked, rect.X, rect.Y);
                    return;
                }
            }

            using (GraphicsPath clipPath = GetRoundRectPath(rect, radius))
            {
                Region prevClip = g.Clip;
                g.SetClip(clipPath, CombineMode.Intersect);
                if (img != null)
                {
                    g.DrawImage(img, rect);
                }
                else
                {
                    int h = Math.Abs((jpgUrl ?? "leo").GetHashCode());
                    Color c1 = Color.FromArgb(255, 28 + (h % 45), 32 + ((h / 7) % 40), 52 + ((h / 13) % 55));
                    Color c2 = Color.FromArgb(255, Math.Min(255, accentColor.R / 3 + 18), Math.Min(255, accentColor.G / 3 + 18), Math.Min(255, accentColor.B / 3 + 28));
                    using (LinearGradientBrush lg = new LinearGradientBrush(rect, c1, c2, LinearGradientMode.ForwardDiagonal))
                    {
                        g.FillRectangle(lg, rect);
                    }
                    using (SolidBrush nb = new SolidBrush(Color.FromArgb(140, accentColor)))
                    using (StringFormat sfc = new StringFormat() { Alignment = StringAlignment.Center, LineAlignment = StringAlignment.Center })
                    {
                        g.DrawString("\u266B", fontTitleBold, nb, rect, sfc);
                    }
                }
                g.Clip = prevClip;
            }
        }

        private void DrawAnimatedStudioArtwork(Graphics g, string url, Rectangle rect, int shapeMode)
        {
            string jpgUrl = (url ?? "").Replace(".webp", ".jpg");
            Image img = null;
            lock (imageCache)
            {
                if (imageCache.ContainsKey(jpgUrl)) img = imageCache[jpgUrl];
            }
            if (img == null && !string.IsNullOrEmpty(jpgUrl)) PrefetchSingleThumbnail(jpgUrl);

            float cx = rect.X + rect.Width / 2f;
            float cy = rect.Y + rect.Height / 2f;
            float halfW = rect.Width / 2f;
            double rotRad = (vinylAngle * Math.PI) / 180.0;

            if (shapeMode == 0 || shapeMode == 1)
            {
                float pulseR = halfW * (0.94f + 0.05f * (float)Math.Sin(wavePhase * 1.6f));
                using (Pen haloPen = new Pen(Color.FromArgb(45, accentColor), 3.5f))
                {
                    g.DrawEllipse(haloPen, cx - pulseR, cy - pulseR, pulseR * 2f, pulseR * 2f);
                }
            }

            GraphicsPath clipPath = new GraphicsPath();
            int numPts = 180;
            PointF[] pts = new PointF[numPts + 1];

            for (int i = 0; i <= numPts; i++)
            {
                double theta = (i / (double)numPts) * Math.PI * 2.0;
                float r = halfW * 0.86f;

                if (shapeMode == 0)
                {
                    float baseR = halfW * 0.78f;
                    float q1 = (float)Math.Sin(12.0 * theta + wavePhase * 1.4) * (baseR * 0.035f);
                    float q2 = (float)Math.Cos(6.0 * (theta - rotRad)) * (baseR * 0.045f);
                    r = baseR + q1 + q2;
                }
                else if (shapeMode == 1)
                {
                    float baseR = halfW * 0.80f;
                    float star = (float)Math.Abs(Math.Cos(4.0 * (theta - rotRad * 0.8))) * (baseR * 0.12f);
                    float harmonic = (float)Math.Sin(8.0 * (theta + rotRad * 1.2)) * (baseR * 0.05f);
                    r = baseR + star + harmonic;
                }
                else if (shapeMode == 2)
                {
                    float w8 = (float)(0.5 + 0.5 * Math.Sin(morphPhase));
                    float w4 = (float)(0.5 + 0.5 * Math.Cos(morphPhase * 0.72));
                    float w6 = (float)(0.5 + 0.5 * Math.Sin(morphPhase * 0.45 + 1.2));
                    float baseR = halfW * 0.85f;
                    r = baseR
                        + (float)Math.Cos(8.0 * (theta - rotRad)) * (baseR * 0.11f * w8)
                        + (float)Math.Cos(4.0 * (theta + rotRad * 0.6)) * (baseR * 0.08f * w4)
                        + (float)Math.Sin(6.0 * (theta - rotRad * 0.8)) * (baseR * 0.06f * w6);
                }
                else if (shapeMode == 3)
                {
                    float baseR = halfW * 0.87f;
                    float breathe = 0.115f + 0.025f * (float)Math.Sin(morphPhase * 1.4f);
                    r = baseR + baseR * breathe * (float)Math.Cos(8.0 * (theta - rotRad));
                }
                else if (shapeMode == 4)
                {
                    r = halfW * 0.94f;
                }
                else
                {
                    float baseR = halfW * 0.89f;
                    r = baseR + baseR * 0.065f * (float)Math.Cos(4.0 * (theta - rotRad * 0.7));
                }

                pts[i] = new PointF(cx + r * (float)Math.Cos(theta), cy + r * (float)Math.Sin(theta));
            }
            clipPath.AddPolygon(pts);

            Region prevClip = g.Clip;
            g.SetClip(clipPath, CombineMode.Intersect);

            if (img != null)
            {
                GraphicsState state = g.Save();
                float imgRot = (shapeMode == 4) ? vinylAngle : (vinylAngle * 0.38f);
                g.TranslateTransform(cx, cy);
                g.RotateTransform(imgRot);
                g.TranslateTransform(-cx, -cy);

                int pad = (int)(rect.Width * 0.16f);
                Rectangle rotRect = new Rectangle(rect.X - pad, rect.Y - pad, rect.Width + pad * 2, rect.Height + pad * 2);
                g.DrawImage(img, rotRect);
                g.Restore(state);
            }
            else
            {
                using (SolidBrush b = new SolidBrush(Color.FromArgb(30, 34, 48)))
                {
                    g.FillRectangle(b, rect);
                }
            }

            if (shapeMode == 4)
            {
                using (Pen groovePen = new Pen(Color.FromArgb(45, 255, 255, 255), 1f))
                {
                    int g1 = (int)(rect.Width * 0.72f);
                    int g2 = (int)(rect.Width * 0.52f);
                    g.DrawEllipse(groovePen, cx - g1 / 2f, cy - g1 / 2f, g1, g1);
                    g.DrawEllipse(groovePen, cx - g2 / 2f, cy - g2 / 2f, g2, g2);
                }
                int holeSz = rect.Width / 5;
                RectangleF holeR = new RectangleF(cx - holeSz / 2f, cy - holeSz / 2f, holeSz, holeSz);
                using (SolidBrush hb = new SolidBrush(bgMain))
                using (Pen hp = new Pen(accentColor, 2.2f))
                {
                    g.FillEllipse(hb, holeR);
                    g.DrawEllipse(hp, holeR);
                }
            }

            g.Clip = prevClip;

            using (Pen glowPen = new Pen(Color.FromArgb(170, accentColor), 2.0f))
            {
                g.DrawPath(glowPen, clipPath);
            }
            clipPath.Dispose();

            if (shapeMode == 0)
            {
                float ringRx = halfW * 0.96f;
                float ringRy = halfW * 0.36f;
                float[] tiltAngles = new float[] { vinylAngle * 1.15f, -vinylAngle * 0.95f + 60f, vinylAngle * 0.65f + 120f };

                for (int rIdx = 0; rIdx < 3; rIdx++)
                {
                    GraphicsState gs = g.Save();
                    g.TranslateTransform(cx, cy);
                    g.RotateTransform(tiltAngles[rIdx]);

                    Color ringCol = (rIdx == 0)
                        ? Color.FromArgb(150, accentColor)
                        : ((rIdx == 1) ? Color.FromArgb(120, 0, 229, 255) : Color.FromArgb(115, 255, 255, 255));
                    using (Pen rp = new Pen(ringCol, 1.6f))
                    {
                        g.DrawEllipse(rp, -ringRx, -ringRy, ringRx * 2f, ringRy * 2f);
                    }

                    double orbAngle = wavePhase * (1.8 + rIdx * 0.45) + rIdx * 2.1;
                    float px = ringRx * (float)Math.Cos(orbAngle);
                    float py = ringRy * (float)Math.Sin(orbAngle);
                    using (SolidBrush haloB = new SolidBrush(Color.FromArgb(90, accentColor)))
                    {
                        g.FillEllipse(haloB, px - 7f, py - 7f, 14f, 14f);
                    }
                    g.FillEllipse(Brushes.White, px - 3.5f, py - 3.5f, 7f, 7f);
                    g.Restore(gs);
                }
            }
            else if (shapeMode == 1)
            {
                int vertices = 8;
                PointF[] outerStar = new PointF[vertices];
                PointF[] innerStar = new PointF[vertices];
                float rOut = halfW * 0.96f;
                float rIn = halfW * 0.82f;
                for (int k = 0; k < vertices; k++)
                {
                    double a1 = (k / (double)vertices) * Math.PI * 2.0 + rotRad * 1.3;
                    double a2 = (k / (double)vertices) * Math.PI * 2.0 - rotRad * 1.1 + (Math.PI / vertices);
                    outerStar[k] = new PointF(cx + rOut * (float)Math.Cos(a1), cy + rOut * (float)Math.Sin(a1));
                    innerStar[k] = new PointF(cx + rIn * (float)Math.Cos(a2), cy + rIn * (float)Math.Sin(a2));
                }
                using (Pen pLattice = new Pen(Color.FromArgb(115, accentColor), 1.3f))
                using (Pen pRay = new Pen(Color.FromArgb(80, 255, 255, 255), 1.0f))
                {
                    g.DrawPolygon(pLattice, outerStar);
                    for (int k = 0; k < vertices; k++)
                    {
                        g.DrawLine(pRay, outerStar[k], innerStar[k]);
                        g.DrawLine(pRay, outerStar[k], innerStar[(k + 1) % vertices]);
                        g.FillEllipse(Brushes.White, outerStar[k].X - 2.5f, outerStar[k].Y - 2.5f, 5f, 5f);
                    }
                }
            }
        }

        // =========================================================================
        // v10.4.3 MOUSE HIT-TESTING & INTERACTION ENGINE
        // =========================================================================

        protected override void OnMouseDown(MouseEventArgs e)
        {
            base.OnMouseDown(e);
            clickRipplePt = e.Location;
            clickRippleAnim = 1.0f;
            int w = this.ClientSize.Width;
            int h = this.ClientSize.Height;
            int sidebarW = 198;
            int rightW = Math.Max(0, (int)Math.Round(rightPanelWidthAnim));
            int playerH = 82;
            int mainH = h - playerH;
            int centerX = sidebarW;
            int centerW = Math.Max(320, w - sidebarW - rightW);
            int rightX = w - rightW;

            if (isUniversalDotMenuOpen && HandleUniversalThreeDotPopupClick(e.Location)) return;

            // Handle Share Song Smart Link Modal Clicks first if open
            if (isShareModalOpen)
            {
                int mw = 500, mh = 320;
                int mx = (w - mw) / 2;
                int my = (h - mh) / 2;
                int btnY = my + mh - 62;
                Rectangle btnCopy = new Rectangle(mx + 24, btnY, 146, 40);
                Rectangle btnWa   = new Rectangle(mx + 180, btnY, 156, 40);
                Rectangle btnTest = new Rectangle(mx + 346, btnY, 74, 40);
                Rectangle btnClose = new Rectangle(mx + 428, btnY, 48, 40);

                if (btnCopy.Contains(e.Location))
                {
                    CopyShareTrackCardToClipboard();
                    ShowToast("\u2713 Smart Share Link Copied to Clipboard!");
                    return;
                }
                if (btnWa.Contains(e.Location) && currentSong != null)
                {
                    string waMsg = "Listen to \"" + CleanSongDisplayTitle(currentSong.Title) + "\" by " + GetPrimaryArtistName(currentSong.Artist) +
                        " on Leo Music!\n\nOpen in Leo Music or Download App:\n" + lastGeneratedSmartShareUrl + "\n\nDirect App Link: " + lastGeneratedDeepLinkUri;
                    LaunchWhatsAppWithMessageOrFallbackBrowser(waMsg, "");
                    isShareModalOpen = false;
                    this.Invalidate();
                    return;
                }
                if (btnTest.Contains(e.Location))
                {
                    string htmlPath = Path.Combine(leoLocalDataRoot, "Leo_Shared_Song_Launcher.html");
                    if (File.Exists(htmlPath))
                    {
                        try { Process.Start(htmlPath); } catch { }
                    }
                    isShareModalOpen = false;
                    this.Invalidate();
                    return;
                }
                if (btnClose.Contains(e.Location) || !new Rectangle(mx, my, mw, mh).Contains(e.Location))
                {
                    isShareModalOpen = false;
                    this.Invalidate();
                    return;
                }
                return;
            }

            if (isLanguageSetupScreenOpen)
            {
                int mw = Math.Min(820, w - 64);
                int mh = Math.Min(560, h - 64);
                int mx = (w - mw) / 2;
                int my = (h - mh) / 2;

                Rectangle nameEditPill = new Rectangle(mx + 24, my + 84, 240, 32);
                if (nameEditPill.Contains(e.Location))
                {
                    ShowUserNameBox(nameEditPill.X + 8, nameEditPill.Y + 5, nameEditPill.Width - 16);
                    return;
                }
                else if (isEditingUserName)
                {
                    CommitUserNameBoxEdit();
                }

                Rectangle welcomePhotoBtn = new Rectangle(mx + 272, my + 84, 132, 32);
                if (welcomePhotoBtn.Contains(e.Location))
                {
                    SelectUserProfilePhotoFromPc();
                    return;
                }

                int cCols = 7;
                int cGap = 8;
                int cW = (mw - 48 - (cCols - 1) * cGap) / cCols;
                int cH = 30;
                for (int i = 0; i < availableCountries.Length; i++)
                {
                    int r = i / cCols;
                    int c = i % cCols;
                    Rectangle cr = new Rectangle(mx + 24 + c * (cW + cGap), my + 124 + r * (cH + 6), cW, cH);
                    if (cr.Contains(e.Location))
                    {
                        selectedCountry = availableCountries[i];
                        hasCompletedCountrySetup = true;
                        RebuildHomepageAndQueueForCountryAndLanguages(true);
                        SavePersistentSettings();
                        ShowToast("\u25C9 Country Set: " + selectedCountry);
                        this.Invalidate();
                        return;
                    }
                }

                int gridTop = my + 202;
                int cols = 7;
                int cardGap = 10;
                int cardW = (mw - 48 - (cols - 1) * cardGap) / cols;
                int cardH = 68;
                for (int i = 0; i < availableLanguages.Count; i++)
                {
                    int r = i / cols;
                    int c = i % cols;
                    Rectangle cardRect = new Rectangle(mx + 24 + c * (cardW + cardGap), gridTop + r * (cardH + 12), cardW, cardH);
                    if (cardRect.Contains(e.Location))
                    {
                        string langName = availableLanguages[i].Name;
                        if (userSelectedLanguages.Contains(langName))
                        {
                            if (userSelectedLanguages.Count > 1) userSelectedLanguages.Remove(langName);
                        }
                        else
                        {
                            userSelectedLanguages.Add(langName);
                        }
                        RebuildHomepageAndQueueForCountryAndLanguages(false);
                        this.Invalidate();
                        return;
                    }
                }

                if (!langContinueBtnRect.IsEmpty && langContinueBtnRect.Contains(e.Location))
                {
                    if (isEditingUserName) CommitUserNameBoxEdit();
                    hasCompletedLanguageSetup = true;
                    hasCompletedCountrySetup = true;
                    isLanguageSetupScreenOpen = false;
                    RebuildHomepageAndQueueForCountryAndLanguages(true);
                    SavePersistentSettings();
                    ShowToast("\u2726 Saved Profile (" + userName + " \u2022 " + selectedCountry + ")");
                    this.Invalidate();
                    return;
                }
                return;
            }

            if (isDynamicBarMode)
            {
                if (!isDynamicBarExpanded)
                {
                    if (e.X >= w - 40 || e.Clicks >= 2) { ToggleDynamicBarExpanded(); return; }
                    if (e.X <= 30) { TogglePlayPause(); return; }
                    isDraggingWindow = true;
                    dragStartPoint = e.Location;
                    return;
                }
                else
                {
                    Rectangle btnFull = new Rectangle(w - 44, 10, 36, 20);
                    if (btnFull.Contains(e.Location)) { ToggleDynamicBarMode(); return; }
                    int cyPod = 74;
                    if (new Rectangle(14, cyPod - 11, 22, 22).Contains(e.Location)) { PrevTrack(); return; }
                    if (new Rectangle(40, cyPod - 13, 26, 26).Contains(e.Location)) { TogglePlayPause(); return; }
                    if (new Rectangle(70, cyPod - 11, 22, 22).Contains(e.Location)) { NextTrack(); return; }
                    isDraggingWindow = true;
                    dragStartPoint = e.Location;
                    return;
                }
            }

            if (isMiniPlayerMode)
            {
                int rightMargin = (miniPlayerStyleIdx == 1) ? 24 : 14;
                Rectangle expandDesktopBtn = new Rectangle(w - rightMargin - 64, 12, 64, 24);
                if (expandDesktopBtn.Contains(e.Location)) { ToggleMiniPlayerMode(); return; }
                int artLeft = (miniPlayerStyleIdx == 1) ? 22 : 14;
                int tLeft = artLeft + 100;
                int cy = 96;
                if (new Rectangle(tLeft, cy - 13, 26, 26).Contains(e.Location)) { PrevTrack(); return; }
                if (new Rectangle(tLeft + 34, cy - 16, 32, 32).Contains(e.Location)) { TogglePlayPause(); return; }
                if (new Rectangle(tLeft + 74, cy - 13, 26, 26).Contains(e.Location)) { NextTrack(); return; }
                isDraggingWindow = true;
                dragStartPoint = e.Location;
                return;
            }

            if (isUpdatePopupOpen)
            {
                int mw = 520, mh = 360;
                int mx = (w - mw) / 2;
                int my = (h - mh) / 2;

                if (updateInstallBtnRect.Contains(e.Location))
                {
                    TriggerButtonBounce("upd_install");
                    PerformOneClickSelfUpdate();
                    return;
                }
                if (!updateEditUrlBtnRect.IsEmpty && updateEditUrlBtnRect.Contains(e.Location))
                {
                    CheckForAppUpdatesAsync(true);
                    return;
                }
                if (updateLaterBtnRect.Contains(e.Location))
                {
                    TriggerButtonBounce("upd_later");
                    isUpdatePopupOpen = false;
                    this.Invalidate();
                    return;
                }

                Rectangle modalRect = new Rectangle(mx, my, mw, mh);
                if (!modalRect.Contains(e.Location))
                {
                    isUpdatePopupOpen = false;
                    this.Invalidate();
                }
                return;
            }

            if (e.Y < 44 && e.X >= w - 108)
            {
                if (e.X >= w - 42)
                {
                    SavePersistentSettings();
                    Application.Exit();
                    return;
                }
                if (e.X >= w - 72 && e.X < w - 42)
                {
                    this.WindowState = (this.WindowState == FormWindowState.Maximized) ? FormWindowState.Normal : FormWindowState.Maximized;
                    return;
                }
                if (e.X >= w - 108 && e.X < w - 72) { this.WindowState = FormWindowState.Minimized; return; }
            }

            // -----------------------------------------------------------------
            // 1. FULL-SCREEN NOW PLAYING + LYRICS + QUEUE CLICKS
            // -----------------------------------------------------------------
            if (isFullPlayerExpanded)
            {
                if (new Rectangle(12, 10, 175, 44).Contains(e.Location))
                {
                    isFullThreeDotMenuOpen = false;
                    isFullPlayerExpanded = false;
                    this.Invalidate();
                    return;
                }

                if (!fullArtDesignPillRect.IsEmpty && fullArtDesignPillRect.Contains(e.Location))
                {
                    fullArtDesignIdx = (fullArtDesignIdx + 1) % fullArtDesignNames.Length;
                    SavePersistentSettings();
                    ShowToast("\u2726 Full Player Art Design: " + fullArtDesignNames[fullArtDesignIdx]);
                    this.Invalidate();
                    return;
                }
                if (!fullViewModePillRect.IsEmpty && fullViewModePillRect.Contains(e.Location))
                {
                    fullViewSubMode = (fullViewSubMode + 1) % 4;
                    SavePersistentSettings();
                    string[] vmNames = new string[] { "Only Playing (Pure Art Stage)", "Split Playing + Lyrics", "Full-Screen Multi-Lyrics", "Concert 3D Visualizer Stage" };
                    ShowToast("\u25EB Full View Mode: " + vmNames[fullViewSubMode]);
                    this.Invalidate();
                    return;
                }

                if (isFullThreeDotMenuOpen)
                {
                    Rectangle popRect = new Rectangle(100, 120, 284, 382);
                    if (popRect.Contains(e.Location))
                    {
                        int idx = (e.Y - (popRect.Y + 36)) / 37;
                        isFullThreeDotMenuOpen = false;
                        if (idx == 0) fullViewSubMode = 1;
                        else if (idx == 1) fullViewSubMode = 0;
                        else if (idx == 2) fullViewSubMode = 2;
                        else if (idx == 3) fullViewSubMode = 3;
                        else if (idx == 4) { fullArtDesignIdx = (fullArtDesignIdx + 1) % fullArtDesignNames.Length; ShowToast("\u2726 Art Design: " + fullArtDesignNames[fullArtDesignIdx]); }
                        else if (idx == 5) { beatBumpEnabled = !beatBumpEnabled; ShowToast("Beat-Reactive Image Bump-Up: " + (beatBumpEnabled ? "ON" : "OFF")); }
                        else if (idx == 6) CycleHomeEffectStyle();
                        else if (idx == 7) { isFullPlayerExpanded = false; activeTab = 4; activeSettingsSubPage = 2; this.Invalidate(); return; }
                        else if (idx == 8 && currentSong != null) DownloadSongDirectly(currentSong);
                        SavePersistentSettings();
                        this.Invalidate();
                        return;
                    }
                    isFullThreeDotMenuOpen = false;
                    this.Invalidate();
                    return;
                }

                if (fullViewSubMode == 2)
                {
                    if (!syncSwitchMatchBtnRect.IsEmpty && syncSwitchMatchBtnRect.Contains(e.Location)) { CycleLyricsProviderMode(); return; }
                    if (!syncBoxlessBtnRect.IsEmpty && syncBoxlessBtnRect.Contains(e.Location)) { CycleLyricStageStyle(); return; }
                    if (!syncGlowBtnRect.IsEmpty && syncGlowBtnRect.Contains(e.Location)) { CycleLyricGlowMode(); return; }
                    if (!syncFontBtnRect.IsEmpty && syncFontBtnRect.Contains(e.Location)) { CycleLyricFontStyle(); return; }
                    if (!syncSizeBtnRect.IsEmpty && syncSizeBtnRect.Contains(e.Location)) { CycleLyricTextSize(); return; }
                    if (!syncBgArtBtnRect.IsEmpty && syncBgArtBtnRect.Contains(e.Location)) { CycleLyricBgArtMode(); return; }
                    if (!syncCopyBtnRect.IsEmpty && syncCopyBtnRect.Contains(e.Location)) { CopyCurrentSongLyricsToClipboard(); return; }
                    if (!syncRefetchBtnRect.IsEmpty && syncRefetchBtnRect.Contains(e.Location) && currentSong != null)
                    {
                        lyricSyncOffsetSec = 0.0;
                        FetchBetterLyricsAsync(currentSong);
                        ShowToast("\u21BB Re-Syncing Live Lyrics for " + currentSong.Title + "...");
                        return;
                    }
                    if (!syncMinusBtnRect.IsEmpty && syncMinusBtnRect.Contains(e.Location))
                    {
                        AdjustSongLyricSyncOffset(-0.2);
                        return;
                    }
                    if (!syncResetBtnRect.IsEmpty && syncResetBtnRect.Contains(e.Location))
                    {
                        lyricSyncOffsetSec = 0.0;
                        ShowToast("Lyrics Sync Reset to 0.0s");
                        this.Invalidate();
                        return;
                    }
                    if (!syncPlusBtnRect.IsEmpty && syncPlusBtnRect.Contains(e.Location))
                    {
                        AdjustSongLyricSyncOffset(0.2);
                        return;
                    }

                    Rectangle botPod = new Rectangle(w / 2 - 280, h - 64, 560, 48);
                    if (botPod.Contains(e.Location))
                    {
                        int bMid = botPod.X + 340;
                        int bCy = botPod.Y + 24;
                        if (new Rectangle(bMid - 66, bCy - 18, 36, 36).Contains(e.Location)) { PrevTrack(); return; }
                        if (new Rectangle(bMid - 22, bCy - 22, 44, 44).Contains(e.Location)) { TogglePlayPause(); return; }
                        if (new Rectangle(bMid + 30, bCy - 18, 36, 36).Contains(e.Location)) { NextTrack(); return; }
                        if (new Rectangle(botPod.Right - 126, botPod.Y + 6, 118, 36).Contains(e.Location))
                        {
                            fullViewSubMode = 1;
                            this.Invalidate();
                            return;
                        }
                        return;
                    }

                    for (int i = 0; i < activeLyricHitRects.Count; i++)
                    {
                        if (activeLyricHitRects[i].Contains(e.Location))
                        {
                            SeekToAbsolute(activeLyricHitTimes[i]);
                            ShowToast("Synced to lyric (" + FormatSec((int)activeLyricHitTimes[i]) + ")");
                            return;
                        }
                    }
                    return;
                }

                Rectangle leftActionPill = new Rectangle(32, 136, 54, 304);
                if (leftActionPill.Contains(e.Location) && currentSong != null)
                {
                    int relY = e.Y - leftActionPill.Y;
                    int slot = relY / 60;
                    if (slot == 0)
                    {
                        if (likedIds.Contains(currentSong.Id)) likedIds.Remove(currentSong.Id);
                        else likedIds.Add(currentSong.Id);
                        SavePersistentSettings();
                        ShowToast(likedIds.Contains(currentSong.Id) ? "\u2665 Added to Favorites" : "Removed from Favorites");
                    }
                    else if (slot == 1) AddSongToActiveUserPlaylist(currentSong);
                    else if (slot == 2) DownloadSongDirectly(currentSong);
                    else if (slot == 3) CopyShareTrackCardToClipboard();
                    else isFullThreeDotMenuOpen = !isFullThreeDotMenuOpen;
                    this.Invalidate();
                    return;
                }

                if (fullViewSubMode == 3)
                {
                    int cMidX = 106 + (w - 138) / 2;
                    int ctrlCyC = h - 38;
                    if (new Rectangle(cMidX - 168, ctrlCyC - 20, 40, 40).Contains(e.Location)) { isRepeatOne = !isRepeatOne; SavePersistentSettings(); this.Invalidate(); return; }
                    if (new Rectangle(cMidX - 98, ctrlCyC - 22, 42, 42).Contains(e.Location)) { PrevTrack(); return; }
                    if (new Rectangle(cMidX - 30, ctrlCyC - 30, 60, 60).Contains(e.Location)) { TogglePlayPause(); return; }
                    if (new Rectangle(cMidX + 56, ctrlCyC - 22, 42, 42).Contains(e.Location)) { NextTrack(); return; }
                    if (new Rectangle(cMidX + 128, ctrlCyC - 20, 40, 40).Contains(e.Location)) { isShuffle = !isShuffle; SavePersistentSettings(); this.Invalidate(); return; }
                    return;
                }

                int rightCardW = (fullViewSubMode == 0) ? 0 : Math.Min(476, Math.Max(390, (int)(w * 0.40f)));
                int rightCardX = (fullViewSubMode == 0) ? (w - 20) : (w - rightCardW - 28);
                Rectangle rightCard = new Rectangle(rightCardX, 66, rightCardW, h - 92);
                if (fullViewSubMode == 1 && rightCard.Contains(e.Location))
                {
                    Rectangle segBar = new Rectangle(rightCard.X + 20, rightCard.Y + 18, rightCard.Width - 40, 42);
                    if (segBar.Contains(e.Location))
                    {
                        int rTabW = (segBar.Width - 8) / 3;
                        int clickedTab = Math.Max(0, Math.Min(2, (e.X - (segBar.X + 4)) / rTabW));
                        fullRightCardTabIdx = clickedTab;
                        this.Invalidate();
                        return;
                    }

                    Rectangle footerPill = new Rectangle(rightCard.X + 20, rightCard.Bottom - 62, rightCard.Width - 40, 44);
                    if (footerPill.Contains(e.Location))
                    {
                        if (e.X >= footerPill.Right - 108)
                        {
                            fullViewSubMode = 2;
                            ShowToast("Full-Screen Multi-Lyrics Studio Expanded");
                        }
                        else if (e.X >= footerPill.X + 90 && e.X <= footerPill.X + 202)
                        {
                            CycleLyricsProviderMode();
                        }
                        else if (e.X >= footerPill.X + 204 && e.X <= footerPill.X + 282 && currentSong != null)
                        {
                            lyricSyncOffsetSec = 0.0;
                            FetchBetterLyricsAsync(currentSong);
                            ShowToast("\u21BB Re-Syncing Live Lyrics for " + currentSong.Title + "...");
                        }
                        else
                        {
                            fullLyricsScriptToggle = !fullLyricsScriptToggle;
                            ShowToast("Lyrics Highlight Capsule: " + (fullLyricsScriptToggle ? "ON" : "Standard"));
                        }
                        this.Invalidate();
                        return;
                    }

                    if (fullRightCardTabIdx == 1)
                    {
                        if (!splitLyrMinusBtnRect.IsEmpty && splitLyrMinusBtnRect.Contains(e.Location)) { AdjustSongLyricSyncOffset(-0.2); return; }
                        if (!splitLyrResetBtnRect.IsEmpty && splitLyrResetBtnRect.Contains(e.Location)) { lyricSyncOffsetSec = 0.0; ShowToast("Lyrics Sync Reset to 0.0s"); this.Invalidate(); return; }
                        if (!splitLyrPlusBtnRect.IsEmpty && splitLyrPlusBtnRect.Contains(e.Location)) { AdjustSongLyricSyncOffset(0.2); return; }

                        for (int i = 0; i < activeLyricHitRects.Count; i++)
                        {
                            if (activeLyricHitRects[i].Contains(e.Location))
                            {
                                SeekToAbsolute(activeLyricHitTimes[i]);
                                ShowToast("Synced to lyric (" + FormatSec((int)activeLyricHitTimes[i]) + ")");
                                return;
                            }
                        }
                    }
                    else if (fullRightCardTabIdx == 2)
                    {
                        Rectangle rightInner = new Rectangle(rightCard.X + 16, segBar.Bottom + 12, rightCard.Width - 32, footerPill.Y - segBar.Bottom - 24);
                        int qRowH = 56;
                        for (int i = 0; i < queueSongs.Count; i++)
                        {
                            int qy = rightInner.Y + 4 + i * (qRowH + 6) - queueScrollOffset;
                            Rectangle qr = new Rectangle(rightInner.X + 4, qy, rightInner.Width - 16, qRowH);
                            if (qr.Contains(e.Location))
                            {
                                currentQueueIndex = i;
                                PlaySong(queueSongs[i], true);
                                return;
                            }
                        }
                    }
                    return;
                }

                int stageLeftX = leftActionPill.Right + 20;
                int stageRightX = (fullViewSubMode == 0) ? (w - 40) : (rightCard.X - 20);
                int stageW = Math.Max(320, stageRightX - stageLeftX);
                int centerMidX = stageLeftX + stageW / 2;
                int artSz = Math.Min((fullViewSubMode == 0) ? 320 : 286, Math.Max(205, h - 350));
                int titleY = 76 + artSz + 18;
                int subY = titleY + 36;
                int sliderY = subY + 42;
                int sliderW = Math.Min((fullViewSubMode == 0) ? 460 : 360, stageW - 110);
                int sliderX = centerMidX - sliderW / 2;

                if (new Rectangle(sliderX - 8, sliderY - 14, sliderW + 16, 28).Contains(e.Location))
                {
                    double frac = Math.Max(0.0, Math.Min(1.0, (double)(e.X - sliderX) / sliderW));
                    SeekToAbsolute(frac * currentDurSec);
                    return;
                }

                int ctrlCy = sliderY + 56;
                if (new Rectangle(centerMidX - 168, ctrlCy - 20, 40, 40).Contains(e.Location))
                {
                    isRepeatOne = !isRepeatOne;
                    SavePersistentSettings();
                    ShowToast(isRepeatOne ? "Repeat One On" : "Repeat Off");
                    this.Invalidate();
                    return;
                }
                if (new Rectangle(centerMidX - 98, ctrlCy - 22, 42, 42).Contains(e.Location)) { PrevTrack(); return; }
                if (new Rectangle(centerMidX - 36, ctrlCy - 36, 72, 72).Contains(e.Location)) { TogglePlayPause(); return; }
                if (new Rectangle(centerMidX + 56, ctrlCy - 22, 42, 42).Contains(e.Location)) { NextTrack(); return; }
                if (new Rectangle(centerMidX + 128, ctrlCy - 20, 40, 40).Contains(e.Location))
                {
                    isShuffle = !isShuffle;
                    SavePersistentSettings();
                    ShowToast(isShuffle ? "Shuffle On" : "Shuffle Off");
                    this.Invalidate();
                    return;
                }

                int botBarY = h - 46;
                int fpVolBarX = 82;
                int fpVolBarW = 148;
                int maxFpVol = volumeOverdriveAllowed ? 150 : 100;
                if (new Rectangle(fpVolBarX - 32, botBarY - 16, 26, 32).Contains(e.Location)) { ToggleMute(); return; }
                if (new Rectangle(fpVolBarX - 4, botBarY - 16, fpVolBarW + 8, 32).Contains(e.Location))
                {
                    int newV = (int)Math.Round(((double)(e.X - fpVolBarX) / fpVolBarW) * maxFpVol);
                    SetVolume(newV);
                    return;
                }

                int sqBtnX = stageRightX - 154;
                for (int bi = 0; bi < 3; bi++)
                {
                    Rectangle sqR = new Rectangle(sqBtnX + bi * 50, botBarY - 17, 42, 34);
                    if (sqR.Contains(e.Location))
                    {
                        if (bi == 0)
                        {
                            isFullPlayerExpanded = false;
                            activeTab = 4;
                            activeSettingsSubPage = 2;
                            this.Invalidate();
                        }
                        else if (bi == 1)
                        {
                            CycleHeadphone3DMode();
                        }
                        else
                        {
                            isFullPlayerExpanded = false;
                            this.Invalidate();
                        }
                        return;
                    }
                }

                if (e.Y < 48)
                {
                    isDraggingWindow = true;
                    dragStartPoint = e.Location;
                }
                return;
            }

            // -----------------------------------------------------------------
            // 2. BOTTOM FLOATING PURPLE PLAYER DOCK CLICKS
            // -----------------------------------------------------------------
            Rectangle dockRect = new Rectangle(204, h - 76, w - 218, 64);
            if (activeTab != 4 && dockRect.Contains(e.Location))
            {
                UnfocusSearchInput();
                int transCx = dockRect.X + (int)(dockRect.Width * 0.42f);
                int btnCy = dockRect.Y + 32;

                if (e.X >= dockRect.X + 8 && e.X <= dockRect.X + 232)
                {
                    TriggerButtonBounce("exp_bot");
                    isFullPlayerExpanded = true;
                    this.Invalidate();
                    return;
                }
                if (e.X >= dockRect.X + 233 && e.X <= dockRect.X + 272 && currentSong != null)
                {
                    if (likedIds.Contains(currentSong.Id)) likedIds.Remove(currentSong.Id);
                    else likedIds.Add(currentSong.Id);
                    SavePersistentSettings();
                    ShowToast(likedIds.Contains(currentSong.Id) ? "\u2665 Added to Favorites" : "Removed from Favorites");
                    this.Invalidate();
                    return;
                }

                if (new Rectangle(transCx - 120, btnCy - 16, 36, 32).Contains(e.Location))
                {
                    isShuffle = !isShuffle;
                    SavePersistentSettings();
                    ShowToast(isShuffle ? "Shuffle On" : "Shuffle Off");
                    this.Invalidate();
                    return;
                }
                if (new Rectangle(transCx - 70, btnCy - 16, 36, 32).Contains(e.Location)) { PrevTrack(); return; }
                if (new Rectangle(transCx - 24, btnCy - 24, 48, 48).Contains(e.Location)) { TogglePlayPause(); return; }
                if (new Rectangle(transCx + 34, btnCy - 16, 36, 32).Contains(e.Location)) { NextTrack(); return; }
                if (new Rectangle(transCx + 84, btnCy - 16, 36, 32).Contains(e.Location))
                {
                    isRepeatOne = !isRepeatOne;
                    SavePersistentSettings();
                    ShowToast(isRepeatOne ? "Repeat One On" : "Repeat Off");
                    this.Invalidate();
                    return;
                }

                int timeX = transCx + 144;
                int seekX = timeX + 78;
                int seekW = Math.Max(70, Math.Min(130, dockRect.Right - seekX - 210));
                if (seekW > 40 && new Rectangle(seekX - 4, btnCy - 14, seekW + 8, 28).Contains(e.Location))
                {
                    double frac = Math.Max(0.0, Math.Min(1.0, (double)(e.X - seekX) / seekW));
                    SeekToAbsolute(frac * currentDurSec);
                    return;
                }

                int volBarX = dockRect.Right - 148;
                int volBarW = 86;
                int maxDockVol = volumeOverdriveAllowed ? 150 : 100;
                if (new Rectangle(volBarX - 30, btnCy - 14, 24, 28).Contains(e.Location)) { ToggleMute(); return; }
                if (new Rectangle(volBarX - 4, btnCy - 14, volBarW + 8, 28).Contains(e.Location))
                {
                    int newV = (int)Math.Round(((double)(e.X - volBarX) / volBarW) * maxDockVol);
                    SetVolume(newV);
                    return;
                }
                if (new Rectangle(dockRect.Right - 48, btnCy - 16, 36, 32).Contains(e.Location))
                {
                    isFullPlayerExpanded = true;
                    fullRightCardTabIdx = 2;
                    this.Invalidate();
                    return;
                }
                return;
            }

            // -----------------------------------------------------------------
            // 3. LEFT SIDEBAR NAVIGATION CLICKS
            // -----------------------------------------------------------------
            if (e.X < sidebarW)
            {
                UnfocusSearchInput();
                HidePlaylistNameBox();

                int[] navTabIds = new int[] { 0, 1, 6, 5, 3, 2 };
                for (int i = 0; i < navTabIds.Length; i++)
                {
                    Rectangle navRect = new Rectangle(20, 82 + i * 44, sidebarW - 34, 38);
                    if (navRect.Contains(e.Location))
                    {
                        int tabId = navTabIds[i];
                        TriggerButtonBounce("nav_" + tabId);
                        activeTab = tabId;
                        tabFadeAnim = 0.2f;
                        targetScrollOffset = 0;
                        if (tabId == 0 || tabId == 6)
                        {
                            searchBox.Text = "";
                            searchQueryText = "";
                            liveSearchResults.Clear();
                            activeGenreRadioIdx = -1;
                        }
                        else if (tabId == 1)
                        {
                            FocusSearchInput();
                        }
                        else if (tabId == 5)
                        {
                            SyncLeoSmartPlaylistWithMood(false);
                        }
                        if (tabId != 4) FilterDisplaySongs();
                        else this.Invalidate();
                        return;
                    }
                }

                if (new Rectangle(20, 368, sidebarW - 34, 38).Contains(e.Location))
                {
                    activeTab = 5;
                    tabFadeAnim = 0.2f;
                    int padX = centerX + 26;
                    int contentW = centerW - 52;
                    ShowPlaylistNameBox(padX + contentW - 292, 31, 180);
                    this.Invalidate();
                    return;
                }

                if (new Rectangle(20, h - 62, sidebarW - 34, 38).Contains(e.Location))
                {
                    TriggerButtonBounce("nav_4");
                    activeTab = 4;
                    tabFadeAnim = 0.2f;
                    this.Invalidate();
                    return;
                }
                return;
            }

            // -----------------------------------------------------------------
            // 4. RIGHT DOCKED NOW-PLAYING CARD CLICKS ON HOMEPAGE
            // -----------------------------------------------------------------
            if (rightW > 40 && activeTab != 4 && e.X >= rightX && e.Y >= 64 && e.Y < mainH)
            {
                UnfocusSearchInput();
                Rectangle cardRect = new Rectangle(rightX + 4, 68, rightW - 18, mainH - 76);

                Rectangle segBar = new Rectangle(cardRect.X + 14, cardRect.Y + 12, cardRect.Width - 28, 30);
                if (segBar.Contains(e.Location))
                {
                    int stW = (segBar.Width - 6) / 3;
                    int clickedMode = Math.Max(0, Math.Min(2, (e.X - (segBar.X + 3)) / stW));
                    rightPanelMode = clickedMode;
                    SavePersistentSettings();
                    this.Invalidate();
                    return;
                }

                if (rightPanelMode == 1 || rightPanelMode == 2)
                {
                    int mCy = cardRect.Bottom - 28;
                    int mMidX = cardRect.X + cardRect.Width / 2;
                    if (new Rectangle(mMidX - 72, mCy - 16, 34, 32).Contains(e.Location)) { PrevTrack(); return; }
                    if (new Rectangle(mMidX - 20, mCy - 20, 40, 40).Contains(e.Location)) { TogglePlayPause(); return; }
                    if (new Rectangle(mMidX + 38, mCy - 16, 34, 32).Contains(e.Location)) { NextTrack(); return; }

                    Rectangle listBox = new Rectangle(cardRect.X + 8, cardRect.Y + 48, cardRect.Width - 16, cardRect.Height - 102);
                    if (rightPanelMode == 2)
                    {
                        if (!syncSwitchMatchBtnRect.IsEmpty && syncSwitchMatchBtnRect.Contains(e.Location)) { CycleLyricsProviderMode(); return; }
                        for (int i = 0; i < activeLyricHitRects.Count; i++)
                        {
                            if (activeLyricHitRects[i].Contains(e.Location))
                            {
                                SeekToAbsolute(activeLyricHitTimes[i]);
                                return;
                            }
                        }
                        return;
                    }
                    else
                    {
                        int qRowH = 52;
                        for (int i = 0; i < queueSongs.Count; i++)
                        {
                            int qy = listBox.Y + 2 + i * (qRowH + 5) - queueScrollOffset;
                            Rectangle qRowRect = new Rectangle(listBox.X + 4, qy, listBox.Width - 12, qRowH);
                            if (qRowRect.Contains(e.Location))
                            {
                                currentQueueIndex = i;
                                PlaySong(queueSongs[i], true);
                                return;
                            }
                        }
                        return;
                    }
                }

                int artPad = 24;
                int artSz = Math.Min(cardRect.Width - artPad * 2, Math.Max(155, cardRect.Height - 275));
                int artX = cardRect.X + (cardRect.Width - artSz) / 2;
                int artY = cardRect.Y + 50;
                Rectangle artRect = new Rectangle(artX, artY, artSz, artSz);

                if (artRect.Contains(e.Location))
                {
                    isFullPlayerExpanded = true;
                    this.Invalidate();
                    return;
                }

                int metaY = artRect.Bottom + 14;
                if (new Rectangle(cardRect.Right - 68, metaY, 34, 34).Contains(e.Location) && currentSong != null)
                {
                    if (likedIds.Contains(currentSong.Id)) likedIds.Remove(currentSong.Id);
                    else likedIds.Add(currentSong.Id);
                    SavePersistentSettings();
                    ShowToast(likedIds.Contains(currentSong.Id) ? "\u2665 Added to Favorites" : "Removed from Favorites");
                    this.Invalidate();
                    return;
                }
                if (new Rectangle(cardRect.Right - 34, metaY, 30, 34).Contains(e.Location) && currentSong != null)
                {
                    OpenUniversalThreeDotMenuForSong(currentSong, e.Location);
                    return;
                }

                int waveCy = metaY + 62;
                int seekY = waveCy + 30;
                int seekX = cardRect.X + 22;
                int seekW = cardRect.Width - 44;
                if (new Rectangle(seekX - 6, seekY - 14, seekW + 12, 28).Contains(e.Location))
                {
                    double frac = Math.Max(0.0, Math.Min(1.0, (double)(e.X - seekX) / seekW));
                    SeekToAbsolute(frac * currentDurSec);
                    return;
                }

                int ctrlCy = cardRect.Bottom - 36;
                int ctrlMidX = cardRect.X + cardRect.Width / 2;
                if (new Rectangle(ctrlMidX - 114, ctrlCy - 18, 36, 36).Contains(e.Location))
                {
                    isRepeatOne = !isRepeatOne;
                    SavePersistentSettings();
                    ShowToast(isRepeatOne ? "Repeat One On" : "Repeat Off");
                    this.Invalidate();
                    return;
                }
                if (new Rectangle(ctrlMidX - 66, ctrlCy - 18, 36, 36).Contains(e.Location)) { PrevTrack(); return; }
                if (new Rectangle(ctrlMidX - 25, ctrlCy - 25, 50, 50).Contains(e.Location)) { TogglePlayPause(); return; }
                if (new Rectangle(ctrlMidX + 30, ctrlCy - 18, 36, 36).Contains(e.Location)) { NextTrack(); return; }
                if (new Rectangle(ctrlMidX + 78, ctrlCy - 18, 36, 36).Contains(e.Location))
                {
                    isShuffle = !isShuffle;
                    SavePersistentSettings();
                    ShowToast(isShuffle ? "Shuffle On" : "Shuffle Off");
                    this.Invalidate();
                    return;
                }
                return;
            }

            // -----------------------------------------------------------------
            // 5. TOP SEARCH BAR (`[ Ctrl + K ]`) & TOP RIGHT BUTTONS
            // -----------------------------------------------------------------
            int searchW = Math.Min(520, Math.Max(280, w - 540));
            int searchX = Math.Max(214, (w - searchW) / 2 - 20);
            Rectangle searchPill = new Rectangle(searchX, 14, searchW, 40);
            if (searchPill.Contains(e.Location))
            {
                if (!string.IsNullOrEmpty(searchQueryText) && e.X >= searchPill.Right - 68)
                {
                    searchBox.Text = "";
                    searchQueryText = "";
                    liveSearchResults.Clear();
                    UnfocusSearchInput();
                    FilterDisplaySongs();
                    return;
                }
                FocusSearchInput();
                return;
            }
            else
            {
                UnfocusSearchInput();
            }

            for (int i = 0; i < topFilterHitZones.Count; i++)
            {
                HomeHitZone tfz = topFilterHitZones[i];
                if (tfz.Rect.Contains(e.Location))
                {
                    if (!string.IsNullOrEmpty(tfz.HoverKey)) TriggerButtonBounce(tfz.HoverKey);
                    if (tfz.Action == "select_mood_chip")
                    {
                        selectedMood = tfz.Payload;
                        FilterDisplaySongs();
                        return;
                    }
                    else if (tfz.Action == "open_account_settings")
                    {
                        if (e.Button == MouseButtons.Right) { SelectUserProfilePhotoFromPc(); return; }
                        activeTab = 4;
                        activeSettingsSubPage = 7;
                        tabFadeAnim = 0.2f;
                        this.Invalidate();
                        return;
                    }
                    else if (tfz.Action == "check_updates_top")
                    {
                        CheckForAppUpdatesAsync(true);
                        return;
                    }
                }
            }

            // -----------------------------------------------------------------
            // 6. SETTINGS TAB CLICKS (`activeTab == 4`)
            // -----------------------------------------------------------------
            if (activeTab == 4 && e.X >= centerX && e.Y >= 60)
            {
                HidePlaylistNameBox();
                HandleSettingsClick(e.Location, centerX, w - sidebarW, false);
                return;
            }

            // -----------------------------------------------------------------
            // 7. PLAYLISTS TAB CLICKS (`activeTab == 5`)
            // -----------------------------------------------------------------
            if (activeTab == 5 && e.X >= centerX && e.X < rightX)
            {
                for (int i = 0; i < playlistStageHitZones.Count; i++)
                {
                    HomeHitZone phz = playlistStageHitZones[i];
                    if (phz.Rect.Contains(e.Location))
                    {
                        if (phz.Action == "start_create_playlist")
                        {
                            int padX = centerX + 26;
                            int contentW = centerW - 52;
                            ShowPlaylistNameBox(padX + contentW - 292, 31, 180);
                            return;
                        }
                        else if (phz.Action == "confirm_create_playlist") { ConfirmCreateCustomPlaylist(); return; }
                        else if (phz.Action == "open_playlist_3dot")
                        {
                            int idx = 0;
                            int.TryParse(phz.Payload, out idx);
                            OpenUniversalThreeDotMenuForPlaylist(idx, e.Location);
                            return;
                        }
                        else if (phz.Action == "select_playlist_idx")
                        {
                            int idx = 0;
                            int.TryParse(phz.Payload, out idx);
                            selectedPlaylistIdx = idx;
                            targetScrollOffset = 0;
                            this.Invalidate();
                            return;
                        }
                        else if (phz.Action == "leo_playlist_mood")
                        {
                            selectedMood = phz.Payload;
                            SyncLeoSmartPlaylistWithMood(true);
                            FilterDisplaySongs();
                            this.Invalidate();
                            return;
                        }
                        else if (phz.Action == "play_active_playlist")
                        {
                            if (selectedPlaylistIdx >= 0 && selectedPlaylistIdx < userPlaylists.Count)
                                PlayEntirePlaylist(userPlaylists[selectedPlaylistIdx], false);
                            return;
                        }
                        else if (phz.Action == "delete_custom_playlist")
                        {
                            if (selectedPlaylistIdx >= 1 && selectedPlaylistIdx < userPlaylists.Count)
                            {
                                userPlaylists.RemoveAt(selectedPlaylistIdx);
                                selectedPlaylistIdx = 0;
                                SavePersistentSettings();
                                this.Invalidate();
                            }
                            return;
                        }
                    }
                }
            }

            // -----------------------------------------------------------------
            // 8. HOME, LIBRARY & DOWNLOADS STAGE HIT ZONES
            // -----------------------------------------------------------------
            if (e.X >= centerX && e.X < rightX && e.Y >= 60 && e.Y < mainH)
            {
                for (int i = 0; i < homeHitZones.Count; i++)
                {
                    HomeHitZone hz = homeHitZones[i];
                    if (hz.Rect.Contains(e.Location))
                    {
                        if (!string.IsNullOrEmpty(hz.HoverKey)) TriggerButtonBounce(hz.HoverKey);
                        if (hz.Action == "play_song" && hz.Song != null) { PlaySong(hz.Song, false); return; }
                        else if (hz.Action == "open_song_3dot" && hz.Song != null) { OpenUniversalThreeDotMenuForSong(hz.Song, e.Location); return; }
                        else if (hz.Action == "open_playlist_3dot")
                        {
                            int plIdx = 0;
                            int.TryParse(hz.Payload, out plIdx);
                            OpenUniversalThreeDotMenuForPlaylist(plIdx, e.Location);
                            return;
                        }
                        else if (hz.Action == "remove_playlist_song" && hz.Song != null)
                        {
                            if (selectedPlaylistIdx >= 1 && selectedPlaylistIdx < userPlaylists.Count)
                            {
                                UserPlaylistItem cpl = userPlaylists[selectedPlaylistIdx];
                                for (int ri = cpl.Songs.Count - 1; ri >= 0; ri--) { if (cpl.Songs[ri].Id == hz.Song.Id) cpl.Songs.RemoveAt(ri); }
                                SavePersistentSettings();
                                ShowToast("Removed from " + cpl.Name);
                                this.Invalidate();
                            }
                            return;
                        }
                        else if (hz.Action == "toggle_hero_play" && hz.Song != null)
                        {
                            if (currentSong != null && currentSong.Id == hz.Song.Id && !string.IsNullOrEmpty(activePlayTargetUrlOrFile)) TogglePlayPause();
                            else PlaySong(hz.Song, false);
                            return;
                        }
                        else if (hz.Action == "play_cat_mymusic") { PlayMyMusicCategoryNow(); return; }
                        else if (hz.Action == "play_cat_trending") { PlayTrendingCategoryNow(); return; }
                        else if (hz.Action == "play_cat_newreleases") { PlayNewReleasesCategoryNow(); return; }
                        else if (hz.Action == "play_cat_genres") { PlayNextGenreRadioNow(); return; }
                        else if (hz.Action == "shuffle_all_home")
                        {
                            isShuffle = true;
                            ShuffleCurrentQueueNow();
                            return;
                        }
                        else if (hz.Action == "check_updates_home")
                        {
                            CheckForAppUpdatesAsync(true);
                            return;
                        }
                        else if (hz.Action == "open_lang_home")
                        {
                            isLanguageSetupScreenOpen = true;
                            this.Invalidate();
                            return;
                        }
                        else if (hz.Action == "open_full_player")
                        {
                            isFullPlayerExpanded = true;
                            this.Invalidate();
                            return;
                        }
                        else if (hz.Action == "open_library_tab" || hz.Action == "lib_card_albums" || hz.Action == "lib_card_artists")
                        {
                            activeTab = 6;
                            tabFadeAnim = 0.2f;
                            targetScrollOffset = 0;
                            FilterDisplaySongs();
                            return;
                        }
                        else if (hz.Action == "lib_card_liked")
                        {
                            activeTab = 2;
                            tabFadeAnim = 0.2f;
                            targetScrollOffset = 0;
                            FilterDisplaySongs();
                            return;
                        }
                        else if (hz.Action == "lib_card_playlists")
                        {
                            activeTab = 5;
                            tabFadeAnim = 0.2f;
                            targetScrollOffset = 0;
                            this.Invalidate();
                            return;
                        }
                        else if (hz.Action == "open_playlist_from_lib")
                        {
                            int plIdx = 0;
                            int.TryParse(hz.Payload, out plIdx);
                            if (plIdx >= 0 && plIdx < userPlaylists.Count)
                            {
                                selectedPlaylistIdx = plIdx;
                                PlayEntirePlaylist(userPlaylists[plIdx], false);
                            }
                            return;
                        }
                        else if (hz.Action == "cycle_lib_sort")
                        {
                            librarySortIdx = (librarySortIdx + 1) % librarySortNames.Length;
                            ShowToast("Sorted by: " + librarySortNames[librarySortIdx]);
                            this.Invalidate();
                            return;
                        }
                        else if (hz.Action == "toggle_grid_list")
                        {
                            isGridViewMode = !isGridViewMode;
                            this.Invalidate();
                            return;
                        }
                        else if (hz.Action == "select_dl_tab")
                        {
                            int tIdx = 0;
                            int.TryParse(hz.Payload, out tIdx);
                            downloadsFilterTabIdx = tIdx;
                            this.Invalidate();
                            return;
                        }
                        else if (hz.Action == "focus_search_dl")
                        {
                            FocusSearchInput();
                            return;
                        }
                        else if (hz.Action == "import_local_songs")
                        {
                            ImportLocalAudioFilesFromPc();
                            return;
                        }
                        else if (hz.Action == "open_dl_folder_top")
                        {
                            try { Process.Start("explorer.exe", downloadsFolder); } catch { }
                            return;
                        }
                        else if (hz.Action == "refresh_trending")
                        {
                            ShowToast("\u21BB Refreshing " + selectedCountry + " Charts & New Releases...");
                            RebuildHomepageAndQueueForCountryAndLanguages(true);
                            return;
                        }
                        else if (hz.Action == "queue_song" && hz.Song != null) { AddToQueue(hz.Song); return; }
                        else if (hz.Action == "add_playlist_song" && hz.Song != null) { AddSongToActiveUserPlaylist(hz.Song); return; }
                        else if (hz.Action == "like_song" && hz.Song != null)
                        {
                            if (likedIds.Contains(hz.Song.Id)) likedIds.Remove(hz.Song.Id);
                            else likedIds.Add(hz.Song.Id);
                            SavePersistentSettings();
                            ShowToast(likedIds.Contains(hz.Song.Id) ? "\u2665 Added to Favorites" : "Removed from Favorites");
                            this.Invalidate();
                            return;
                        }
                        else if (hz.Action == "download_song" && hz.Song != null) { DownloadSongDirectly(hz.Song); return; }
                    }
                }
            }

            if (e.Y < 58)
            {
                isDraggingWindow = true;
                dragStartPoint = e.Location;
            }
        }

        private void HandleSettingsClick(Point pt, int centerX, int centerW, bool isDrag)
        {
            int padX = centerX + 20;
            int contentW = centerW - 36;
            int subSideW = 212;
            int panelTopY = 132;
            int panelH = this.ClientSize.Height - panelTopY - 14;
            Rectangle subSideCard = new Rectangle(padX, panelTopY, subSideW, panelH);

            if (!isDrag && subSideCard.Contains(pt))
            {
                for (int i = 0; i < settingsSubPageNames.Length; i++)
                {
                    Rectangle itemR = new Rectangle(subSideCard.X + 12, subSideCard.Y + 14 + i * 44, subSideCard.Width - 24, 38);
                    if (itemR.Contains(pt))
                    {
                        activeSettingsSubPage = i;
                        if (isEditingUserName) CommitUserNameBoxEdit();
                        this.Invalidate();
                        return;
                    }
                }
                return;
            }

            int rightAreaX = subSideCard.Right + 18;
            int rightAreaW = Math.Max(360, contentW - subSideW - 18);

            // Page 0: General + Appearance Card
            if (activeSettingsSubPage == 0)
            {
                if (isDrag) return;
                int genH = Math.Min(264, (panelH - 16) / 2);
                Rectangle genCard = new Rectangle(rightAreaX, panelTopY, rightAreaW, genH);
                int rowStartY = genCard.Y + 62;
                int rowStepH = (genH - 68) / 4;

                if (genCard.Contains(pt))
                {
                    int rIdx = (pt.Y - rowStartY) / Math.Max(1, rowStepH);
                    if (rIdx == 0) { isLanguageSetupScreenOpen = true; this.Invalidate(); }
                    else if (rIdx == 1)
                    {
                        startupBehaviorIdx = (startupBehaviorIdx + 1) % startupBehaviorNames.Length;
                        SavePersistentSettings();
                        ShowToast("Startup Behavior: " + startupBehaviorNames[startupBehaviorIdx]);
                        this.Invalidate();
                    }
                    else if (rIdx == 2)
                    {
                        minimizeToTrayEnabled = !minimizeToTrayEnabled;
                        SavePersistentSettings();
                        ShowToast("Minimize to System Tray: " + (minimizeToTrayEnabled ? "ON" : "OFF"));
                        this.Invalidate();
                    }
                    else if (rIdx >= 3)
                    {
                        Rectangle chkNowBtn = new Rectangle(genCard.Right - 166, rowStartY + 3 * rowStepH, 92, rowStepH);
                        if (chkNowBtn.Contains(pt)) CheckForAppUpdatesAsync(true);
                        else
                        {
                            autoCheckUpdatesEnabled = !autoCheckUpdatesEnabled;
                            SavePersistentSettings();
                            ShowToast("Auto Check for Updates on Startup: " + (autoCheckUpdatesEnabled ? "ON" : "OFF"));
                            this.Invalidate();
                        }
                    }
                    return;
                }

                int appTopY = genCard.Bottom + 16;
                int appH = Math.Max(220, panelH - genH - 16);
                Rectangle appCard = new Rectangle(rightAreaX, appTopY, rightAreaW, appH);
                if (appCard.Contains(pt))
                {
                    // Song Images in Background Toggle Pill in Appearance Card Header
                    if (new Rectangle(appCard.Right - 220, appCard.Y + 12, 204, 38).Contains(pt))
                    {
                        songBgImageEnabled = !songBgImageEnabled;
                        if (songBgImageEnabled && currentSong != null) RebuildCurrentSongBgSlideshow(currentSong, true);
                        SavePersistentSettings();
                        ShowToast("Song Cover Art Background: " + (songBgImageEnabled ? "ON" : "OFF"));
                        this.Invalidate();
                        return;
                    }

                    int aRow1Y = appCard.Y + 64;
                    int aRow2Y = appCard.Y + 116;
                    int aRow3Y = appCard.Y + 168;

                    int tmStartX = appCard.Right - 364;
                    for (int ti = 0; ti < 4; ti++)
                    {
                        Rectangle tmR = new Rectangle(tmStartX + ti * 86, aRow1Y + 4, 80, 34);
                        if (tmR.Contains(pt))
                        {
                            appearanceThemeModeIdx = ti;
                            oledPureBlack = (ti == 0);
                            this.Invalidate();
                            return;
                        }
                    }

                    int colStartX = appCard.Right - 244;
                    for (int ci = 0; ci < Math.Min(6, themes.Count); ci++)
                    {
                        Rectangle cCircle = new Rectangle(colStartX + ci * 38 - 4, aRow2Y + 4, 34, 34);
                        if (cCircle.Contains(pt))
                        {
                            activeThemeIdx = ci;
                            accentColor = themes[ci].Accent;
                            dynamicLightingEnabled = false;
                            SavePersistentSettings();
                            ShowToast("Accent Color: " + themes[ci].Name);
                            this.Invalidate();
                            return;
                        }
                    }

                    int bgThumbW = 96;
                    int bgThumbH = 46;
                    int bgGap = 10;
                    int bgStartX = appCard.Right - (4 * bgThumbW + 3 * bgGap) - 20;
                    for (int bi = 0; bi < 4; bi++)
                    {
                        Rectangle bRect = new Rectangle(bgStartX + bi * (bgThumbW + bgGap), aRow3Y, bgThumbW, bgThumbH + 4);
                        if (bRect.Contains(pt))
                        {
                            homeEffectStyleIdx = bi;
                            SavePersistentSettings();
                            ShowToast("Background Environment: " + homeEffectStyleNames[homeEffectStyleIdx]);
                            this.Invalidate();
                            return;
                        }
                    }
                }
                return;
            }

            int sx = rightAreaX + 24;
            int sy = panelTopY + 20;
            int sw = rightAreaW - 48;

            // Page 1: Playback, Transitions & Multi-Lyrics Studio Customization Clicks
            if (activeSettingsSubPage == 1)
            {
                int colW = (sw - 12) / 2;
                int pStartY = sy + 48;
                for (int i = 0; i < 6; i++)
                {
                    int r = i / 2;
                    int c = i % 2;
                    Rectangle rr = new Rectangle(sx + c * (colW + 12), pStartY + r * 48, colW, 42);
                    if (rr.Contains(pt))
                    {
                        if (i == 0)
                        {
                            if (!crossfadeEnabled) { crossfadeEnabled = true; crossfadeSeconds = 3; }
                            else if (crossfadeSeconds == 3) crossfadeSeconds = 6;
                            else if (crossfadeSeconds == 6) crossfadeSeconds = 10;
                            else crossfadeEnabled = false;
                            SavePersistentSettings();
                            ShowToast("Crossfade: " + (crossfadeEnabled ? (crossfadeSeconds + "s ON") : "OFF"));
                        }
                        else if (i == 1) { gaplessPlayback = !gaplessPlayback; skipSilence = gaplessPlayback; SavePersistentSettings(); ShowToast("Gapless & Skip Silence: " + (gaplessPlayback ? "ON" : "OFF")); }
                        else if (i == 2) CyclePlaybackSpeed();
                        else if (i == 3) { autoMixEnabled = !autoMixEnabled; SavePersistentSettings(); ShowToast("Auto-Mix Smart Queue: " + (autoMixEnabled ? "ON" : "OFF")); }
                        else if (i == 4) { windowsNotificationEnabled = !windowsNotificationEnabled; SavePersistentSettings(); ShowToast("Windows Notification Center Banner: " + (windowsNotificationEnabled ? "ON" : "OFF")); }
                        else if (i == 5)
                        {
                            int[] sMins = new int[] { 0, 15, 30, 60 };
                            int curIdx = Array.IndexOf(sMins, sleepTimerMinutes);
                            sleepTimerMinutes = sMins[(curIdx + 1) % sMins.Length];
                            sleepTimerSecondsLeft = sleepTimerMinutes * 60;
                            ShowToast("Sleep Timer: " + (sleepTimerMinutes == 0 ? "Off" : (sleepTimerMinutes + " Minutes")));
                        }
                        this.Invalidate();
                        return;
                    }
                }

                int lbTop = pStartY + 3 * 48 + 38;
                for (int i = 0; i < 8; i++)
                {
                    int r = i / 2;
                    int c = i % 2;
                    Rectangle lr = new Rectangle(sx + c * (colW + 12), lbTop + r * 42, colW, 36);
                    if (lr.Contains(pt))
                    {
                        if (i == 0) CycleLyricsProviderMode();
                        else if (i == 1) CycleLyricStageStyle();
                        else if (i == 2) CycleLyricGlowMode();
                        else if (i == 3) CycleLyricFontStyle();
                        else if (i == 4) CycleLyricTextSize();
                        else if (i == 5) CycleLyricBgArtMode();
                        else if (i == 6) { fullLyricsScriptToggle = !fullLyricsScriptToggle; SavePersistentSettings(); ShowToast("Lyrics Highlight Capsule: " + (fullLyricsScriptToggle ? "ON" : "Standard")); }
                        else if (i == 7) { isFullPlayerExpanded = true; fullViewSubMode = 2; }
                        this.Invalidate();
                        return;
                    }
                }
                return;
            }
            // Page 2: Dedicated Audio & 5-Band Hardware EQ Clicks
            if (activeSettingsSubPage == 2)
            {
                if (!isDrag && new Rectangle(sx + sw - 60, sy - 4, 60, 32).Contains(pt))
                {
                    eqEnabled = !eqEnabled;
                    ApplyEffectiveDspAndVolume();
                    SavePersistentSettings();
                    this.Invalidate();
                    return;
                }

                int pY = sy + 40;
                int pW = (sw - 8 * 6) / 9;
                if (!isDrag && pt.Y >= pY && pt.Y <= pY + 30)
                {
                    for (int i = 0; i < eqPresetNames.Length; i++)
                    {
                        Rectangle pr = new Rectangle(sx + i * (pW + 6), pY, pW, 28);
                        if (pr.Contains(pt))
                        {
                            ApplyEqPreset(eqPresetNames[i]);
                            return;
                        }
                    }
                }

                int slTop = pY + 46;
                int slH = 140;
                int bandSpacing = sw / 6;
                for (int b = 0; b < 5; b++)
                {
                    int bx = sx + 48 + b * bandSpacing;
                    if (pt.X >= bx - 22 && pt.X <= bx + 22 && pt.Y >= slTop - 10 && pt.Y <= slTop + slH + 10)
                    {
                        float norm = 1.0f - (float)(pt.Y - slTop) / slH;
                        norm = Math.Max(0f, Math.Min(1f, norm));
                        eqBands[b] = -12f + norm * 24f;
                        activeEqPreset = "Custom";
                        ApplyEffectiveDspAndVolume();
                        QueueSavePersistentSettings();
                        this.Invalidate();
                        return;
                    }
                }

                if (!isDrag)
                {
                    int cfgY = slTop + slH + 42;
                    int cW = (sw - 2 * 10) / 3;
                    for (int i = 0; i < 6; i++)
                    {
                        int r = i / 3;
                        int c = i % 3;
                        Rectangle cr = new Rectangle(sx + c * (cW + 10), cfgY + r * 44, cW, 36);
                        if (cr.Contains(pt))
                        {
                            if (i == 0) { bassBoostPct = (bassBoostPct + 20) % 120; ApplyEffectiveDspAndVolume(); ShowToast("Bass Boost: " + bassBoostPct + "%"); }
                            else if (i == 1) { virtualizerPct = (virtualizerPct + 25) % 125; ApplyEffectiveDspAndVolume(); ShowToast("3D Virtualizer: " + virtualizerPct + "%"); }
                            else if (i == 2) { volumeOverdriveAllowed = !volumeOverdriveAllowed; ShowToast("Volume Overdrive 150%: " + (volumeOverdriveAllowed ? "ON" : "100% Standard")); }
                            else if (i == 3) CycleHeadphone3DMode();
                            else if (i == 4) CyclePinDropDetailLevel();
                            else if (i == 5) CycleDacOutputMode();
                            SavePersistentSettings();
                            this.Invalidate();
                            return;
                        }
                    }
                }
                return;
            }

            if (isDrag) return;

            // Page 3: Dedicated Downloads Settings Clicks
            if (activeSettingsSubPage == 3)
            {
                int bW = (sw - 12) / 2;
                for (int i = 0; i < 6; i++)
                {
                    int r = i / 2;
                    int c = i % 2;
                    Rectangle br = new Rectangle(sx + c * (bW + 12), sy + 72 + r * 54, bW, 44);
                    if (br.Contains(pt))
                    {
                        if (i == 0) ImportLocalAudioFilesFromPc();
                        else if (i == 1) ScanAndRestoreLocalDownloads(true);
                        else if (i == 2) { try { Process.Start("explorer.exe", downloadsFolder); } catch { } }
                        else if (i == 3)
                        {
                            if (activeStreamQuality == "320kbps") SwitchLosslessStreamQualityLive("160kbps", "160kbps High");
                            else SwitchLosslessStreamQualityLive("320kbps", "320kbps Master");
                        }
                        else if (i == 4) ClearAudioCache();
                        else if (i == 5) { activeTab = 3; this.Invalidate(); }
                        return;
                    }
                }
                return;
            }

            // Page 4: Dedicated Library & 14 Countries Settings Clicks
            if (activeSettingsSubPage == 4)
            {
                int cCols = 7;
                int cGap = 8;
                int cW = (sw - (cCols - 1) * cGap) / cCols;
                int cH = 36;
                for (int i = 0; i < availableCountries.Length; i++)
                {
                    int r = i / cCols;
                    int c = i % cCols;
                    Rectangle cr = new Rectangle(sx + c * (cW + cGap), sy + 64 + r * (cH + 8), cW, cH);
                    if (cr.Contains(pt))
                    {
                        selectedCountry = availableCountries[i];
                        hasCompletedCountrySetup = true;
                        if (!string.Equals(selectedCountry, "India", StringComparison.OrdinalIgnoreCase))
                        {
                            userSelectedLanguages.Clear();
                            userSelectedLanguages.Add("English");
                        }
                        RebuildHomepageAndQueueForCountryAndLanguages(true);
                        SavePersistentSettings();
                        ShowToast("\u25C9 Active Country Switched to " + selectedCountry);
                        this.Invalidate();
                        return;
                    }
                }

                int lTop = sy + 164;
                int bW = (sw - 12) / 2;
                for (int i = 0; i < 4; i++)
                {
                    int r = i / 2;
                    int c = i % 2;
                    Rectangle br = new Rectangle(sx + c * (bW + 12), lTop + 32 + r * 52, bW, 42);
                    if (br.Contains(pt))
                    {
                        if (i == 0) { isLanguageSetupScreenOpen = true; this.Invalidate(); }
                        else if (i == 1) { librarySortIdx = (librarySortIdx + 1) % librarySortNames.Length; ShowToast("Default Sort: " + librarySortNames[librarySortIdx]); this.Invalidate(); }
                        else if (i == 2) { isGridViewMode = !isGridViewMode; this.Invalidate(); }
                        else if (i == 3) { youLyPlusAutoRecommend = !youLyPlusAutoRecommend; ShowToast("YouLyPlus Auto-Recommend: " + (youLyPlusAutoRecommend ? "ON" : "OFF")); this.Invalidate(); }
                        return;
                    }
                }
                return;
            }

            // Page 5: Dedicated Appearance, Song Images ON/OFF & 4 Background Styles Clicks
            if (activeSettingsSubPage == 5)
            {
                Rectangle songBgRow = new Rectangle(sx, sy + 64, sw, 54);
                if (songBgRow.Contains(pt))
                {
                    songBgImageEnabled = !songBgImageEnabled;
                    if (songBgImageEnabled && currentSong != null) RebuildCurrentSongBgSlideshow(currentSong, true);
                    SavePersistentSettings();
                    ShowToast("Song Cover Art in Background: " + (songBgImageEnabled ? "ON" : "OFF"));
                    this.Invalidate();
                    return;
                }

                int bgY = sy + 132;
                int cardGap = 12;
                int cardW = (sw - 3 * cardGap) / 4;
                int cardH = 88;
                for (int bi = 0; bi < 4; bi++)
                {
                    Rectangle bRect = new Rectangle(sx + bi * (cardW + cardGap), bgY + 28, cardW, cardH);
                    if (bRect.Contains(pt))
                    {
                        homeEffectStyleIdx = bi;
                        SavePersistentSettings();
                        ShowToast("Background Environment: " + homeEffectStyleNames[homeEffectStyleIdx]);
                        this.Invalidate();
                        return;
                    }
                }

                int acY = bgY + 132;
                for (int ci = 0; ci < Math.Min(6, themes.Count); ci++)
                {
                    Rectangle cCircle = new Rectangle(sx + 180 + ci * 44, acY, 34, 34);
                    if (cCircle.Contains(pt))
                    {
                        activeThemeIdx = ci;
                        accentColor = themes[ci].Accent;
                        dynamicLightingEnabled = false;
                        SavePersistentSettings();
                        ShowToast("Accent Color: " + themes[ci].Name);
                        this.Invalidate();
                        return;
                    }
                }

                int togY = acY + 42;
                int bW = (sw - 12) / 2;
                if (new Rectangle(sx, togY, bW, 38).Contains(pt))
                {
                    fullArtDesignIdx = (fullArtDesignIdx + 1) % fullArtDesignNames.Length;
                    SavePersistentSettings();
                    ShowToast("\u2726 Full Player Art Design: " + fullArtDesignNames[fullArtDesignIdx]);
                    this.Invalidate();
                    return;
                }
                if (new Rectangle(sx + bW + 12, togY, bW, 38).Contains(pt))
                {
                    beatBumpEnabled = !beatBumpEnabled;
                    SavePersistentSettings();
                    ShowToast("Beat-Reactive Image Bump-Up: " + (beatBumpEnabled ? "ON" : "OFF"));
                    this.Invalidate();
                    return;
                }
                if (new Rectangle(sx, togY + 44, bW, 38).Contains(pt))
                {
                    curved3DGlassEnabled = !curved3DGlassEnabled;
                    SavePersistentSettings();
                    this.Invalidate();
                    return;
                }
                if (new Rectangle(sx + bW + 12, togY + 44, bW, 38).Contains(pt))
                {
                    oledPureBlack = !oledPureBlack;
                    SavePersistentSettings();
                    this.Invalidate();
                    return;
                }
                return;
            }

            if (activeSettingsSubPage == 7)
            {
                if (new Rectangle(sx, sy + 42, 84, 84).Contains(pt))
                {
                    SelectUserProfilePhotoFromPc();
                    return;
                }
                int bW = (sw - 12) / 2;
                for (int i = 0; i < 4; i++)
                {
                    int r = i / 2;
                    int c = i % 2;
                    Rectangle br = new Rectangle(sx + c * (bW + 12), sy + 148 + r * 52, bW, 42);
                    if (br.Contains(pt))
                    {
                        if (i == 0) SelectUserProfilePhotoFromPc();
                        else if (i == 1) ShowUserNameBox(sx + 104, sy + 48, 220);
                        else if (i == 2)
                        {
                            voiceWelcomeEnabled = !voiceWelcomeEnabled;
                            SavePersistentSettings();
                            if (voiceWelcomeEnabled) SpeakVoiceTextAsync("Welcome " + userName + " to Leo Music");
                            this.Invalidate();
                        }
                        else if (i == 3) { isLanguageSetupScreenOpen = true; this.Invalidate(); }
                        return;
                    }
                }
                return;
            }

            if (activeSettingsSubPage == 8)
            {
                Rectangle chkBtn = new Rectangle(sx, sy + 228, 220, 42);
                Rectangle popBtn = new Rectangle(sx + 234, sy + 228, 220, 42);
                if (chkBtn.Contains(pt)) { CheckForAppUpdatesAsync(true); return; }
                if (popBtn.Contains(pt)) { isUpdatePopupOpen = true; this.Invalidate(); return; }
            }
        }

        protected override void OnMouseMove(MouseEventArgs e)
        {
            base.OnMouseMove(e);
            spatialMousePt = e.Location;
            int w = this.ClientSize.Width;
            int h = this.ClientSize.Height;
            int sidebarW = 198;
            int rightW = Math.Max(0, (int)Math.Round(rightPanelWidthAnim));
            int playerH = 82;
            int centerX = sidebarW;
            int centerW = Math.Max(320, w - sidebarW - rightW);
            int rightX = w - rightW;

            if (isDraggingWindow && e.Button == MouseButtons.Left)
            {
                this.Location = new Point(this.Left + e.X - dragStartPoint.X, this.Top + e.Y - dragStartPoint.Y);
                if (isDynamicBarMode) savedDynamicBarLocation = this.Location;
                return;
            }

            if (e.Button == MouseButtons.Left)
            {
                if (isFullPlayerExpanded && fullViewSubMode != 2 && fullViewSubMode != 3 && !isFullThreeDotMenuOpen)
                {
                    int rightCardW = Math.Min(476, Math.Max(390, (int)(w * 0.40f)));
                    int rightCardX = w - rightCardW - 28;
                    int stageLeftX = 32 + 54 + 20;
                    int stageRightX = rightCardX - 20;
                    int stageW = Math.Max(320, stageRightX - stageLeftX);
                    int centerMidX = stageLeftX + stageW / 2;
                    int artSz = Math.Min(286, Math.Max(205, h - 350));
                    int sliderY = 76 + artSz + 18 + 36 + 42;
                    int sliderW = Math.Min(360, stageW - 110);
                    int sliderX = centerMidX - sliderW / 2;

                    if (e.Y >= sliderY - 16 && e.Y <= sliderY + 16 && e.X >= sliderX - 8 && e.X <= sliderX + sliderW + 8)
                    {
                        double frac = Math.Max(0.0, Math.Min(1.0, (double)(e.X - sliderX) / sliderW));
                        SeekToAbsolute(frac * currentDurSec);
                        return;
                    }

                    int botBarY = h - 46;
                    int fpVolBarX = 82;
                    int fpVolBarW = 148;
                    int maxFpV = volumeOverdriveAllowed ? 150 : 100;
                    if (e.Y >= botBarY - 18 && e.Y <= botBarY + 18 && e.X >= fpVolBarX - 8 && e.X <= fpVolBarX + fpVolBarW + 8)
                    {
                        SetVolume((int)Math.Round(((double)(e.X - fpVolBarX) / fpVolBarW) * maxFpV));
                        return;
                    }
                }
                else if (!isFullPlayerExpanded && e.Y >= h - 76 && e.X >= 204 && activeTab != 4)
                {
                    Rectangle dockRect = new Rectangle(204, h - 76, w - 218, 64);
                    int volBarX = dockRect.Right - 148;
                    int volBarW = 86;
                    int maxDockV = volumeOverdriveAllowed ? 150 : 100;
                    if (e.X >= volBarX - 8 && e.X <= volBarX + volBarW + 8 && e.Y >= dockRect.Y + 14 && e.Y <= dockRect.Y + 50)
                    {
                        SetVolume((int)Math.Round(((double)(e.X - volBarX) / volBarW) * maxDockV));
                        return;
                    }
                }
                else if (!isFullPlayerExpanded && activeTab == 4 && e.X >= centerX)
                {
                    HandleSettingsClick(e.Location, centerX, w - sidebarW, true);
                    return;
                }
            }

            string newHovKey = "";
            hoveredNavIndex = -1;
            hoveredSongIndex = -1;
            hoveredQueueIndex = -1;
            hoveredQuickPlayIndex = -1;

            int mainH = h - playerH;

            if (isFullPlayerExpanded)
            {
                int rightCardW = Math.Min(476, Math.Max(390, (int)(w * 0.40f)));
                int rightCardX = w - rightCardW - 28;
                if (fullRightCardTabIdx == 2 && e.X >= rightCardX && e.Y >= 140 && e.Y < h - 100)
                {
                    int qIdx = (e.Y - 144 + queueScrollOffset) / 62;
                    if (qIdx >= 0 && qIdx < queueSongs.Count) hoveredQueueIndex = qIdx;
                }
                currentHoveredBtnKey = newHovKey;
                return;
            }

            if (e.X < sidebarW)
            {
                int[] navTabIds = new int[] { 0, 1, 6, 5, 3, 2 };
                for (int i = 0; i < navTabIds.Length; i++)
                {
                    Rectangle navRect = new Rectangle(20, 82 + i * 44, sidebarW - 34, 38);
                    if (navRect.Contains(e.Location))
                    {
                        hoveredNavIndex = i;
                        newHovKey = "nav_" + navTabIds[i];
                        break;
                    }
                }
            }
            else if (activeTab != 4 && e.X < rightX && e.Y < mainH)
            {
                if (activeTab == 5)
                {
                    for (int i = 0; i < playlistStageHitZones.Count; i++)
                    {
                        if (playlistStageHitZones[i].Rect.Contains(e.Location))
                        {
                            newHovKey = playlistStageHitZones[i].HoverKey;
                            break;
                        }
                    }
                }
                if (string.IsNullOrEmpty(newHovKey))
                {
                    for (int i = 0; i < homeHitZones.Count; i++)
                    {
                        if (homeHitZones[i].Rect.Contains(e.Location))
                        {
                            newHovKey = homeHitZones[i].HoverKey;
                            break;
                        }
                    }
                }
            }

            currentHoveredBtnKey = newHovKey;
        }

        protected override void OnMouseUp(MouseEventArgs e)
        {
            base.OnMouseUp(e);
            agentWidgetPotentialClick = false;
            isDraggingWindow = false;
        }

        protected override void OnMouseWheel(MouseEventArgs e)
        {
            base.OnMouseWheel(e);
            int w = this.ClientSize.Width;
            int h = this.ClientSize.Height;

            if (isVolumeControllerPopupOpen && GetVolumeControllerPopupRect(w, h).Contains(e.Location))
            {
                int step = (e.Delta > 0) ? 2 : -2;
                AdjustVolumeByStep(step);
                return;
            }

            // Fix: Support mouse-wheel scrolling in Full-Screen Queue AND Full-Screen Lyrics!
            if (isFullPlayerExpanded)
            {
                int rightCardW = Math.Min(476, Math.Max(390, (int)(w * 0.40f)));
                int rightCardX = w - rightCardW - 28;
                if (e.X >= rightCardX || fullViewSubMode == 2)
                {
                    if (fullRightCardTabIdx == 2 && fullViewSubMode != 2)
                    {
                        int qViewportH = Math.Max(180, h - 240);
                        int maxQScroll = Math.Max(0, queueSongs.Count * 62 - qViewportH);
                        targetQueueScrollOffset = Math.Max(0, Math.Min(maxQScroll, targetQueueScrollOffset - (int)(e.Delta * 0.65f)));
                        queueScrollOffset = targetQueueScrollOffset;
                        this.Invalidate();
                        return;
                    }
                    else if (fullRightCardTabIdx == 1 || fullViewSubMode == 2)
                    {
                        // Nudge lyric scroll or seek slightly when scrolling lyrics
                        double stepSec = (e.Delta > 0) ? -3.0 : 3.0;
                        SeekRelative(stepSec);
                        return;
                    }
                }
                if (e.Y >= h - 68)
                {
                    int step = (e.Delta > 0) ? 2 : -2;
                    AdjustVolumeByStep(step);
                    return;
                }
                return;
            }

            if (e.Y >= h - 78 && e.X >= 204 && activeTab != 4)
            {
                int step = (e.Delta > 0) ? 2 : -2;
                AdjustVolumeByStep(step);
                return;
            }

            int rightX = w - 315;
            if (e.X >= rightX && (rightPanelMode == 1 || rightPanelMode == 2) && isRightPanelVisible && activeTab != 4)
            {
                int maxQScroll = Math.Max(0, queueSongs.Count * 60 - (h - 220));
                targetQueueScrollOffset = Math.Max(0, Math.Min(maxQScroll, targetQueueScrollOffset - (int)(e.Delta * 0.65f)));
            }
            else if (activeTab != 4)
            {
                int vpH = Math.Max(200, h - 82 - 70);
                int maxScroll = Math.Max(0, totalHomeContentHeight - vpH);
                targetScrollOffset = Math.Max(0, Math.Min(maxScroll, targetScrollOffset - (int)(e.Delta * 0.65f)));
            }
            this.Invalidate();
        }

        private string FormatSec(int sec)
        {
            if (sec < 0) sec = 0;
            int m = sec / 60;
            int s = sec % 60;
            return m + ":" + (s < 10 ? "0" + s : s.ToString());
        }

        private GraphicsPath GetRoundRectPath(Rectangle r, int radius)
        {
            GraphicsPath path = new GraphicsPath();
            int d = Math.Max(2, radius * 2);
            path.AddArc(r.X, r.Y, d, d, 180, 90);
            path.AddArc(r.Right - d, r.Y, d, d, 270, 90);
            path.AddArc(r.Right - d, r.Bottom - d, d, d, 0, 90);
            path.AddArc(r.X, r.Bottom - d, d, d, 90, 90);
            path.CloseFigure();
            return path;
        }

        private void FillRoundRect(Graphics g, Brush b, Rectangle r, int radius)
        {
            using (GraphicsPath p = GetRoundRectPath(r, radius))
            {
                g.FillPath(b, p);
            }
        }

        private void DrawRoundRect(Graphics g, Pen pen, Rectangle r, int radius)
        {
            using (GraphicsPath p = GetRoundRectPath(r, radius))
            {
                g.DrawPath(pen, p);
            }
        }
    }

    static class Program
    {
        [STAThread]
        static void Main(string[] args)
        {
            ServicePointManager.SecurityProtocol = (SecurityProtocolType)3072;
            string localAppDir = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "LeoMusic");
            try { if (!Directory.Exists(localAppDir)) Directory.CreateDirectory(localAppDir); } catch { }

            EnsureDesktopLaunchers(localAppDir);

            if (args != null && args.Length > 0)
            {
                if (args[0] == "--install") return;
                // Handle leomusic://play?... deep-link protocol launch
                try
                {
                    string dataDir = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "Leo_Music_Local_Data");
                    if (!Directory.Exists(dataDir)) dataDir = Path.Combine(localAppDir, "Leo_Music_Local_Data");
                    if (!Directory.Exists(dataDir)) Directory.CreateDirectory(dataDir);
                    string cmdFile = Path.Combine(dataDir, "incoming_share.cmd");
                    File.WriteAllText(cmdFile, args[0], Encoding.UTF8);

                    // If an instance of LeoMusic.exe is already running, let it pick up incoming_share.cmd without opening a second window!
                    Process[] running = Process.GetProcessesByName("LeoMusic");
                    if (running != null && running.Length > 1)
                    {
                        return;
                    }
                }
                catch { }
            }

            Application.EnableVisualStyles();
            Application.SetCompatibleTextRenderingDefault(false);
            Application.Run(new LeoMainForm());
        }

        private static void EnsureDesktopLaunchers(string installDir)
        {
            try
            {
                string exePath = Assembly.GetExecutingAssembly().Location;
                string icoPath = Path.Combine(installDir, "leo_icon.ico");
                if (!File.Exists(icoPath))
                {
                    icoPath = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "leo_icon.ico");
                }

                string userProfile = Environment.GetFolderPath(Environment.SpecialFolder.UserProfile);
                string[] folders = new string[]
                {
                    Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),
                    Path.Combine(userProfile, "Desktop"),
                    Path.Combine(userProfile, @"OneDrive\Desktop"),
                    Environment.GetFolderPath(Environment.SpecialFolder.Programs)
                };

                Type shellType = Type.GetTypeFromProgID("WScript.Shell");
                object shell = Activator.CreateInstance(shellType);

                foreach (string dir in folders)
                {
                    if (!string.IsNullOrEmpty(dir) && Directory.Exists(dir))
                    {
                        try
                        {
                            string lnkPath = Path.Combine(dir, "Leo Music.lnk");
                            object shortcut = shellType.InvokeMember("CreateShortcut", BindingFlags.InvokeMethod, null, shell, new object[] { lnkPath });
                            Type scType = shortcut.GetType();
                            scType.InvokeMember("TargetPath", BindingFlags.SetProperty, null, shortcut, new object[] { exePath });
                            scType.InvokeMember("WorkingDirectory", BindingFlags.SetProperty, null, shortcut, new object[] { installDir });
                            if (File.Exists(icoPath))
                            {
                                scType.InvokeMember("IconLocation", BindingFlags.SetProperty, null, shortcut, new object[] { icoPath + ",0" });
                            }
                            else
                            {
                                scType.InvokeMember("IconLocation", BindingFlags.SetProperty, null, shortcut, new object[] { exePath + ",0" });
                            }
                            scType.InvokeMember("Description", BindingFlags.SetProperty, null, shortcut, new object[] { "Leo Music Studio" });
                            scType.InvokeMember("Save", BindingFlags.InvokeMethod, null, shortcut, null);
                        }
                        catch { }
                    }
                }
            }
            catch { }
        }
    }
}